export default [{"url": "https://hklandlaw.wordpress.com/2026/08/06/when-a-form-a-meets-a-prior-mortgage-estoppel-ancillary-relief-and-lis-pendens/", "title": "When a Form A Meets a Prior Mortgage: Estoppel, Ancillary Relief and Lis Pendens", "date": "2026-08-06", "type": "case-note", "topics": ["mortgages", "lis-pendens", "land-registration", "matrimonial-property", "estoppel"], "cases": [{"name": "Sun Hung Kai Credit Limited v Lam Lai Wah Lindy", "citation": "[2026] HKCFI 2686", "court": "CFI", "jurisdiction": "HK"}, {"name": "Ho Yau-kong v Ho Kwai-ying", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Join Win Holdings Ltd v City Target Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Si Tou Choi Kam v Wealth Credit Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Mo Ying v Brillex Development Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "WYM v LYM", "citation": "[2024] HKCA 499", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance (Cap 128) s.19", "Matrimonial Proceedings and Property Ordinance (Cap 192)"], "summary": "CFI vacated a wife's registered Form A: her ancillary relief claim could not outrank an earlier mortgage, reaching only surplus value after the security, and her failure to intervene in the possession action raised an estoppel by standing by."}, {"url": "https://hklandlaw.wordpress.com/2026/05/04/yim-tin-fook-v-yu-chor-lai-the-milmo-rule-and-overlong-sub-leases/", "title": "Yim Tin Fook v Yu Chor Lai: the Milmo rule and overlong sub-leases", "date": "2026-05-04", "type": "case-note", "topics": ["leases", "subleases", "assignment", "privity-of-estate", "landlord-and-tenant"], "cases": [{"name": "Yim Tin Fook v Yu Chor Lai", "citation": "[2026] HKCFA 17", "court": "CFA", "jurisdiction": "HK"}, {"name": "Milmo v Carreras", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Bruton v London & Quadrant Housing Trust", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "The CFA discarded Milmo's automatic conversion of an overlong sub-lease into an assignment of the grantor's estate: the grant stays contractually effective between the parties while its proprietary reach is capped at the grantor's interest, borrowing Bruton's contract/estate distinction."}, {"url": "https://hklandlaw.wordpress.com/2026/04/28/uksc-judgments-in-hong-kong-wong-chi-hung-v-lo-wing-pun/", "title": "UKSC judgments in Hong Kong: Wong Chi Hung v Lo Wing Pun", "date": "2026-04-28", "type": "case-note", "topics": ["precedent", "illegality", "unjust-enrichment", "basic-law", "comparative-law"], "cases": [{"name": "Wong Chi Hung v Lo Wing Pun", "citation": "[2026] HKCFA 14", "court": "CFA", "jurisdiction": "HK"}, {"name": "Patel v Mirza", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Monat Investment", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Fearn v Board of Trustees of the Tate Gallery", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Regency Villas", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Vauxhall Motors v Manchester Ship Canal", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Basic Law art.84"], "summary": "Uses a CFA judgment to examine the status of UKSC decisions in Hong Kong: persuasive only, since Basic Law article 84 gives no overseas authority special rank; local courts may depart where reasoning does not suit Hong Kong, though Patel v Mirza's illegality test was adopted."}, {"url": "https://hklandlaw.wordpress.com/2026/04/25/the-mechanical-priority-rule-in-grant-v-jackman-2026-ukpc-13/", "title": "The Mechanical Priority Rule in Grant v Jackman [2026] UKPC 13", "date": "2026-04-25", "type": "case-note", "topics": ["land-registration", "priority", "nemo-dat", "deeds-registration", "bona-fide-purchaser"], "cases": [{"name": "Grant v Jackman", "citation": "[2026] UKPC 13", "court": "UKPC", "jurisdiction": "other"}, {"name": "Yim Tin Fook v Yu Chor Lai", "citation": "[2026] HKCFA 17", "court": "CFA", "jurisdiction": "HK"}, {"name": "Warburton v Loveland", "citation": null, "court": null, "jurisdiction": "other"}, {"name": "Bushell v Bushell", "citation": null, "court": null, "jurisdiction": "other"}], "statutes": ["Registration of Deeds Act (Trinidad and Tobago) s.16(1)", "Registration of Deeds Act (Trinidad and Tobago) s.16(2)", "Land Registration Ordinance (Cap 128) s.3"], "summary": "Privy Council appeal from Trinidad holding that deeds-registration priority runs mechanically by order of registration: a first-registered voluntary deed defeated an earlier unregistered conveyance, good faith meaning absence of fraud rather than of notice. The note draws parallels with Hong Kong's ordinance."}, {"url": "https://hklandlaw.wordpress.com/2026/04/22/the-primacy-of-registration-nemo-dat-and-the-statutory-shield-in-yim-tin-fook-v-yu-chor-lai/", "title": "The Primacy of Registration: Nemo Dat and the Statutory Shield in Yim Tin Fook v Yu Chor Lai", "date": "2026-04-22", "type": "case-note", "topics": ["land-registration", "nemo-dat", "priority", "bona-fide-purchaser", "unregistered-instruments"], "cases": [{"name": "Yim Tin Fook v Yu Chor Lai", "citation": "[2026] HKCFA 17", "court": "CFA", "jurisdiction": "HK"}, {"name": "Chu Yam On v Li Tam Toi Hing", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Markfaith Investment Ltd v Chiap Hua Flashlights Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Milmo v Carreras", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Land Registration Ordinance (Cap 128) s.3(1)", "Land Registration Ordinance (Cap 128) s.3(2)", "Land Registration Ordinance (Cap 128) s.4"], "summary": "Examines the CFA's reading of LRO s.3(2): an unregistered instrument becomes void against a later bona fide purchaser for value, displacing nemo dat even where the later deed covers only subdivided lots, while s.4 strips notice of effect so the register alone governs."}, {"url": "https://hklandlaw.wordpress.com/2026/04/02/interim-injunctions-and-proprietary-estoppel-claims-preston-v-preston/", "title": "Interim injunctions and proprietary estoppel claims: Preston v Preston", "date": "2026-04-02", "type": "case-note", "topics": ["proprietary-estoppel", "interim-injunctions", "remedies", "possession"], "cases": [{"name": "Preston v Preston", "citation": "[2026] NICh 3", "court": "other", "jurisdiction": "other"}, {"name": "American Cyanamid Co v Ethicon Ltd", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Northern Ireland ruling applying American Cyanamid where occupiers raised proprietary estoppel against a possession-seeking estate: the legal owner's title weighed heavily at the interlocutory stage and damages could satisfy any estoppel equity, so interim control of the land followed the paper title."}, {"url": "https://hklandlaw.wordpress.com/2026/03/04/what-is-the-status-of-trusts-of-land-not-manifested-and-proved-in-writing-national-iranian-oil-company-v-crescent-gas-corporation/", "title": "What is the status of trusts of land not manifested and proved in writing? National Iranian Oil Company v Crescent Gas Corporation", "date": "2026-03-04", "type": "case-note", "topics": ["trusts-of-land", "formalities", "writing-requirements", "constructive-trusts", "insolvency"], "cases": [{"name": "National Iranian Oil Company v Crescent Gas Corporation Limited", "citation": "[2025] EWCA Civ 1211", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Khan v Khan", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Preston v Preston", "citation": null, "court": null, "jurisdiction": "other"}], "statutes": ["Law of Property Act 1925 s.53(1)(b)", "Conveyancing and Property Ordinance s.5(1)(b)", "Insolvency Act 1986 s.423"], "summary": "EWCA held an agent cannot supply the s.53(1)(b) signature, and without compliant writing a declared trust of land is treated as non-existent rather than merely unenforceable, though later writing validates it retrospectively; the transfer was an undervalue transaction. Hong Kong's CPO s.5(1)(b) parallel is noted."}, {"url": "https://hklandlaw.wordpress.com/2026/02/03/establishing-a-constructive-trust-without-detrimental-reliance-khan-v-khan/", "title": "Establishing a constructive trust without detrimental reliance: Khan v Khan", "date": "2026-02-03", "type": "case-note", "topics": ["constructive-trusts", "detrimental-reliance", "formalities", "family-property", "equity"], "cases": [{"name": "Khan v Khan", "citation": "[2025] EWCA Civ 1436", "court": "EWCA", "jurisdiction": "EN"}, {"name": "De Bruyne v De Bruyne", "citation": "[2010] EWCA Civ 519", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Rochefoucauld v Boustead", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Bannister v Bannister", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Archibald v Alexander", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925"], "summary": "EWCA upheld an acquisition constructive trust where title was taken on an agreement to hold for family members: no detrimental reliance is required, the agreement can be inferred from the whole course of dealing, and equity stops the transferee sheltering behind absent formalities."}, {"url": "https://hklandlaw.wordpress.com/2026/01/03/when-can-incorporated-owners-approve-an-apparent-breach-of-the-deed-of-mutual-covenant-or-waive-such-a-breach/", "title": "When can incorporated owners approve an apparent breach of the Deed of Mutual Covenant or waive such a breach?", "date": "2026-01-03", "type": "case-note", "topics": ["deed-of-mutual-covenant", "building-management", "incorporated-owners", "waiver", "common-parts"], "cases": [{"name": "Centre Chase Investment Limited v Castle Peak Building (IO)", "citation": "[2024] HKCA 1179", "court": "CA", "jurisdiction": "HK"}, {"name": "Incorporated Owners of Hoi Luen Industrial Centre", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Hollywood Shopping Centre Owners Committee Limited v IO of Wing Wah Building Mongkok Kowloon", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Freder Centre (IO) v Gringo Ltd", "citation": null, "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.18(1)(c)", "Building Management Ordinance s.34I", "Building Management Ordinance s.34C(2)"], "summary": "Surveys CA authority on incorporated owners sanctioning DMC breaches like external alterations: BMO s.34I prevails over contrary DMC terms through s.34C(2), approval or acquiescence can come after the event where the covenant is not absolute, but genuinely unlawful works cannot be approved."}, {"url": "https://hklandlaw.wordpress.com/2025/11/09/update-on-yim-tin-fook-v-yu-chor-lai-leave-to-appeal-granted/", "title": "Update on Yim Tin Fook v Yu Chor Lai: leave to appeal granted", "date": "2025-11-09", "type": "case-note", "topics": ["land-registration", "nemo-dat", "priority", "appeals"], "cases": [{"name": "Yim Tin Fook v Yu Chor Lai", "citation": "[2025] HKCA 816", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3(2)"], "summary": "Brief update: the Court of Appeal granted leave to appeal to the CFA in Yim Tin Fook, certifying questions on whether s.3(2) voids an unregistered assignment against a later registered good-faith purchaser, including where a gift intervenes or only part of the land is on-sold."}, {"url": "https://hklandlaw.wordpress.com/2025/11/07/section-32-of-the-land-registration-ordinance-and-the-nemo-dat-principle/", "title": "Section 3(2) of the Land Registration Ordinance and the nemo dat principle", "date": "2025-11-07", "type": "case-note", "topics": ["land-registration", "nemo-dat", "priority", "bona-fide-purchaser"], "cases": [{"name": "Yim Tin Fook v Yu Chor Lai", "citation": "[2025] HKCA 675", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3(2)"], "summary": "Note on the CA's ruling that LRO s.3(2) renders an unregistered assignment void against a later registered bona fide purchaser for value, overriding nemo dat: the court followed the statute's plain wording, penalising non-registration even though a gift sat between the competing transactions."}, {"url": "https://hklandlaw.wordpress.com/2025/10/01/lease-or-licence-ap-wireless-ii-uk-ltd-v-on-tower-uk-ltd/", "title": "Lease or licence? AP Wireless II (UK) Ltd v ON Tower (UK) Ltd", "date": "2025-10-01", "type": "case-note", "topics": ["leases", "licences", "certainty-of-term", "periodic-tenancies", "landlord-and-tenant"], "cases": [{"name": "AP Wireless II (UK) Ltd v ON Tower (UK) Ltd", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Say v Smith", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Lace v Chantler", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Berrisford v Mexfield Housing Co-operative Ltd", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Prudential Assurance Co Ltd v London Residuary Body", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "EWCA decision on telecom site agreements terminable at any time after a minimum period: the term was uncertain, so the court asked whether a contractual licence or an implied periodic tenancy best fitted the bargain, preferring salvage over voidness and renewing criticism of the certainty-of-term doctrine."}, {"url": "https://hklandlaw.wordpress.com/2025/09/02/is-the-front-door-of-a-flat-a-fixture/", "title": "Is the front door of a flat a fixture?", "date": "2025-09-02", "type": "case-note", "topics": ["fixtures", "chattels", "leases", "landlord-and-tenant", "covenants"], "cases": [{"name": "Marlborough Knightsbridge Management Ltd v Fivaz", "citation": "[2021] EWCA Civ 989", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Elitestone Ltd v Morris", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Boswell v Crucible Steel", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Explains the chattel, fixture, part-of-the-land triad through Fivaz: entrance doors installed at original construction are integral to the building rather than fixtures, so a lessee who replaced his flat's front doors without consent did not breach a covenant against removing landlord's fixtures."}, {"url": "https://hklandlaw.wordpress.com/2025/07/31/did-it-make-any-legal-difference-if-easements-were-wrongly-described-as-restrictive-covenants/", "title": "Did it make any legal difference if easements were wrongly described as restrictive covenants?", "date": "2025-07-31", "type": "case-note", "topics": ["easements", "restrictive-covenants", "recreational-rights", "land-registration"], "cases": [{"name": "Cayman Shores Development Ltd v The Proprietors, Strata Plan No 79 (Lion's Court)", "citation": "[2025] UKPC 27", "court": "UKPC", "jurisdiction": "other"}, {"name": "Re Ellenborough Park", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Regency Villas", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Registered Land Act (Cayman Islands)"], "summary": "Privy Council found rights to use resort recreational facilities satisfied the Ellenborough Park and Regency Villas easement criteria, and their misdescription and registration as restrictive agreements under the Cayman statute did not stop them running with the land: the intended attachment of benefit and burden governed."}, {"url": "https://hklandlaw.wordpress.com/2025/06/26/hybrid-transactions-and-the-etridge-code-waller-edwards-v-one-savings-bank-plc/", "title": "Hybrid transactions and the Etridge code: Waller-Edwards v One Savings Bank plc", "date": "2025-06-26", "type": "case-note", "topics": ["undue-influence", "mortgages", "surety-transactions", "etridge-protocol", "banking"], "cases": [{"name": "Waller-Edwards v One Savings Bank plc", "citation": "[2025] UKSC 22", "court": "UKSC", "jurisdiction": "EN"}, {"name": "CIBC Mortgages plc v Pitt", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Royal Bank of Scotland plc v Etridge (No 2)", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "UKSC ruled that a hybrid loan, partly joint and partly for one borrower's exclusive benefit, engages Etridge whenever that exclusive benefit exceeds de minimis: the lender must take the protocol steps to see the surety-like borrower independently advised, or the charge risks being set aside for undue influence."}, {"url": "https://hklandlaw.wordpress.com/2025/06/09/extent-of-fiduciary-duties-depend-on-the-relationship/", "title": "Extent of fiduciary duties depend on the relationship", "date": "2025-06-09", "type": "case-note", "topics": ["fiduciary-duties", "agency", "bank-accounts", "duty-to-account"], "cases": [{"name": "Jong Yat Kit v Li Mun Hok Steven", "citation": "[2025] HKCFI 1764", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "CFI held an authorised bank-account signatory acting purely on his father's instructions owed only narrow fiduciary duties, to follow those instructions and avoid unauthorised dealings, with no duty to probe their rationale; the reach of fiduciary obligation tracks the degree of control over the assets."}, {"url": "https://hklandlaw.wordpress.com/2025/04/28/presumption-of-equality-where-the-family-home-is-in-joint-names-chen-lily-v-yip-tsun-wah-alvan/", "title": "Presumption of equality where the family home is in joint names: Chen Lily v Yip Tsun Wah Alvan", "date": "2025-04-28", "type": "case-note", "topics": ["family-home", "joint-tenancy", "common-intention", "beneficial-ownership", "trusts"], "cases": [{"name": "Chen Lily v Yip Tsun Wah Alvan", "citation": null, "court": "CFI", "jurisdiction": "HK"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Hong Kong decision applying Stack v Dowden to a jointly held family home: absent an express declaration, a beneficial joint tenancy is presumed because couples are taken to pool assets in an enduring domestic venture, and unequal mortgage contributions alone do not displace equality on breakdown."}, {"url": "https://hklandlaw.wordpress.com/2025/04/16/assignment-completed-but-purchase-price-not-paid-does-the-purchaser-hold-the-property-on-trust-for-the-seller/", "title": "Assignment completed but purchase price not paid: does the purchaser hold the property on trust for the seller?", "date": "2025-04-16", "type": "case-note", "topics": ["resulting-trusts", "vendors-lien", "repudiatory-breach", "assignment", "purchase-price"], "cases": [{"name": "Ho Wai Kwong v Ho Kam Chui", "citation": "[2025] HKCA 174", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "CA rejected the argument that a purchaser who never paid holds the assigned property on trust for the seller: accepting a repudiatory breach discharges future obligations without unwinding completed transfers, so the unpaid vendor is left with a debt claim, not a resulting trust or revived beneficial interest."}, {"url": "https://hklandlaw.wordpress.com/2025/03/11/ownership-of-funds-in-a-joint-bank-account-poon-loi-tak-v-poon-loi-cheung-desmond/", "title": "Ownership of funds in a joint bank account: Poon Loi Tak v Poon Loi Cheung Desmond", "date": "2025-03-11", "type": "case-note", "topics": ["joint-bank-accounts", "resulting-trusts", "survivorship", "beneficial-ownership", "succession"], "cases": [{"name": "Poon Loi Tak v Poon Loi Cheung Desmond", "citation": "[2024] HKCA 796", "court": "CA", "jurisdiction": "HK"}, {"name": "Whitlock v Moree", "citation": "[2017] UKPC 44", "court": "UKPC", "jurisdiction": "other"}], "statutes": [], "summary": "CA resolved joint-account ownership by evidence of the deceased depositor's real gifting intention, giving bank-form joint tenancy and survivorship wording little weight, in contrast with Whitlock v Moree's contract-first approach; presumed resulting trust operates only where direct evidence of intent runs out."}, {"url": "https://hklandlaw.wordpress.com/2025/02/05/rights-of-way-acquired-by-long-user-ching-to-yuen-limited-v-pristine-villa-io/", "title": "Rights of way acquired by long user: Ching To Yuen Limited v Pristine Villa (IO)", "date": "2025-02-05", "type": "case-note", "topics": ["easements", "prescription", "lost-modern-grant", "rights-of-way", "nuisance"], "cases": [{"name": "Ching To Yuen Limited v Pristine Villa (IO)", "citation": "[2025] HKCFI 388", "court": "CFI", "jurisdiction": "HK"}, {"name": "Kong Sau Ching v Kong Pak Yan", "citation": "[2004] 1 HKC 119", "court": null, "jurisdiction": "HK"}, {"name": "Re Ellenborough Park", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Lee Kok Che v Royal Mortgage Limited", "citation": "[2023] HKCFI 648", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "CFI dispute over estate access ways: public rights of way need open use plainly asserted against the owner, while lost modern grant prescription needs 20 years' use without force, stealth or permission, so tolerated use fails; intensified use can extinguish an easement, and damaging entry sounded in nuisance."}, {"url": "https://hklandlaw.wordpress.com/2025/01/01/naming-rights-in-a-dmc-falcome-company-limited-v-zj300-io/", "title": "Naming rights in a DMC: Falcome Company Limited v ZJ300 (IO)", "date": "2025-01-01", "type": "case-note", "topics": ["deed-of-mutual-covenant", "naming-rights", "building-management", "incorporated-owners", "touch-and-concern"], "cases": [{"name": "Falcome Company Limited v ZJ300 (IO)", "citation": "[2024] HKCFI 2992", "court": "CFI", "jurisdiction": "HK"}, {"name": "Lamaya Limited v Supreme Honour Development Limited", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Pak Fah Yeow Investment (Hong Kong) Company Limited v Proper Invest Group Limited", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.18(2)"], "summary": "CFI held a DMC building-naming right is not proprietary and does not touch and concern land, so it cannot bind successors in title; naming belongs to the owners collectively, and BMO s.18(2) empowers incorporated owners to rename a building by duly passed resolution in the common interest."}, {"url": "https://hklandlaw.wordpress.com/2024/11/30/ouster-of-co-owner-and-adverse-possession-lin-loi-hing-v-prs-of-lin-lok-shi/", "title": "Ouster of co-owner and adverse possession: Lin Loi Hing v PRs of Lin Lok Shi", "date": "2024-11-30", "type": "case-note", "topics": ["adverse-possession", "co-ownership", "tenancy-in-common", "ouster", "limitation"], "cases": [{"name": "Lin Loi Hing v PRs of Lin Lok Shi", "citation": "[2024] HKCFI 3056", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "CFI declared a deceased co-owner's title extinguished: the other tenant in common had possessed exclusively since 1980, partly through licensees, and rebuilt a house on the land. Adverse possession can run between co-owners, and the estate's lack of probate or administration did not stop time running."}, {"url": "https://hklandlaw.wordpress.com/2024/10/16/an-express-declaration-of-trust-can-be-varied-by-a-subsequent-common-intention-constructive-trust/", "title": "An express declaration of trust can be varied by a subsequent common intention constructive trust", "date": "2024-10-16", "type": "case-note", "topics": ["express-trusts", "common-intention", "constructive-trusts", "formalities", "co-ownership"], "cases": [{"name": "Nilsson v Cynberg", "citation": "[2024] EWHC 2164", "court": "other", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989", "Conveyancing and Property Ordinance s.3"], "summary": "Discusses Nilsson v Cynberg: an express declaration of trust concludes matters between the parties yet can be displaced by a later common intention constructive trust built on informal agreement and reliance, without statutory formalities, here giving one spouse sole beneficial ownership against a bankruptcy trustee."}, {"url": "https://hklandlaw.wordpress.com/2024/09/06/sun-hing-building-io-v-join-profit-hong-kong-limited-agreement-to-convert-common-part-to-private-use-was-it-lawful-was-it-revocable/", "title": "Sun Hing Building (IO) v Join Profit (Hong Kong) Limited. Agreement to convert common part to private use: Was it lawful? Was it revocable?", "date": "2024-09-06", "type": "case-note", "topics": ["common-parts", "building-management", "incorporated-owners", "deed-of-mutual-covenant", "licences", "implied-terms"], "cases": [{"name": "Sun Hing Building (IO) v Join Profit (Hong Kong) Limited", "citation": "[2024] HKCA 589", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.34I"], "summary": "CA upheld a management committee's deal allowing a shop owner exclusive private use of common parts under BMO s.34I, notwithstanding DMC rights over the area; the arrangement conferred enforceable rights rather than a bare licence and could be ended on reasonable notice only if restoration were genuinely needed."}, {"url": "https://hklandlaw.wordpress.com/2024/08/08/joint-tenant-does-not-die-possessed-of-an-interest-in-the-co-owned-property/", "title": "Joint tenant does not die possessed of an interest in the co-owned property", "date": "2024-08-08", "type": "case-note", "topics": ["joint-tenancy", "survivorship", "succession", "co-ownership", "estates"], "cases": [{"name": "Flowers v Scavella", "citation": "[2024] UKPC 25", "court": "UKPC", "jurisdiction": "other"}], "statutes": ["Probate and Administration of Estates Act 2011 (Bahamas) s.65", "Probate and Administration of Estates Ordinance (Cap 10) s.64"], "summary": "Privy Council appeal from the Bahamas: survivorship means a joint tenant dies possessed of no interest in the co-owned land, so the property sits outside the estate and cannot be statutorily charged with the deceased's debts. The note points to Hong Kong's matching probate provision."}, {"url": "https://hklandlaw.wordpress.com/2024/07/29/presumed-tenancy-in-common-when-partners-acquire-land-for-business-purposes/", "title": "Presumed tenancy in common when partners acquire land for business purposes", "date": "2024-07-29", "type": "case-note", "topics": ["co-ownership", "tenancy-in-common", "joint-tenancy", "partnership-property", "presumptions"], "cases": [{"name": "Williams v Williams", "citation": "[2024] EWCA Civ 42", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Marr v Collie", "citation": null, "court": "UKPC", "jurisdiction": "other"}], "statutes": ["Law of Property Act 1925 s.34", "Law of Property Act 1925 s.36"], "summary": "EWCA note: when partners take land for a farming business, equity presumes a tenancy in common because survivorship is not intended, and the domestic joint-names presumption from Stack and Kernott yields; post-acquisition statements, including wills, can evidence the intention held at purchase."}, {"url": "https://hklandlaw.wordpress.com/2024/06/28/life-changing-consequences-as-detriment-in-proprietary-estoppel-winter-v-winter/", "title": "Life-changing consequences as detriment in proprietary estoppel: Winter v Winter", "date": "2024-06-28", "type": "case-note", "topics": ["proprietary-estoppel", "detriment", "detrimental-reliance", "farming-families", "inheritance"], "cases": [{"name": "Winter v Winter", "citation": "[2024] EWCA Civ 699", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Thorner v Major", "citation": "[2009] UKHL 18", "court": "HL", "jurisdiction": "EN"}, {"name": "Gillett v Holt", "citation": "[2001] Ch 210", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "EWCA confirmed that spending one's working life in the family business on inheritance promises is substantial detriment even without identifying the career forgone: life-changing consequences count, balanced against benefits received. The sons' estoppel prevailed over the father's unequal testamentary dispositions."}, {"url": "https://hklandlaw.wordpress.com/2024/06/18/ancillary-relief-claim-not-a-proprietary-interest-in-the-family-home/", "title": "Ancillary relief claim not a proprietary interest in the family home", "date": "2024-06-18", "type": "case-note", "topics": ["ancillary-relief", "matrimonial-property", "family-home", "mortgages", "constructive-trusts"], "cases": [{"name": "WYM v LYM", "citation": "[2024] HKCA 499", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "CA held a spouse's prospective ancillary relief claim is no proprietary interest in the family home and so cannot bind a mortgagee, which takes free of any constructive notice of it; the wife's trust and estoppel arguments failed, leaving matrimonial remedies to reach only unencumbered assets."}, {"url": "https://hklandlaw.wordpress.com/2024/05/23/nuisance-and-the-but-for-test/", "title": "Nuisance and the 'but for' test", "date": "2024-05-23", "type": "case-note", "topics": ["nuisance", "causation", "japanese-knotweed", "damages", "diminution-in-value"], "cases": [{"name": "Davies v Bridgend County Borough Council", "citation": "[2024] UKSC 15", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "UKSC applied the but-for test to a Japanese knotweed nuisance: the fall in the claimant's land value predated the council's actionable default, so nothing recoverable flowed from the breach period; stigma-based diminution is real property damage rather than barred pure economic loss."}, {"url": "https://hklandlaw.wordpress.com/2024/04/23/newcomerinjunctions-and-the-uk-supreme-court/", "title": "'Newcomer' injunctions and the UK Supreme Court", "date": "2024-04-23", "type": "case-note", "topics": ["injunctions", "newcomer-injunctions", "trespass", "equitable-remedies"], "cases": [{"name": "Wolverhampton City Council v London Gypsies and Travellers", "citation": "[2023] UKSC 47", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Examines the UKSC's recognition of newcomer injunctions binding persons unknown against whom no cause of action yet exists: a novel equitable order, neither interim nor final, granted only on compelling need with robust procedural safeguards, full disclosure, and tight territorial and temporal limits."}, {"url": "https://hklandlaw.wordpress.com/2024/03/19/determining-whether-external-walls-are-common-parts/", "title": "Determining whether external walls are common parts", "date": "2024-03-19", "type": "case-note", "topics": ["common-parts", "external-walls", "deed-of-mutual-covenant", "building-management", "interpretation"], "cases": [{"name": "Donora Company Limited v Tsuen Kam Centre (IO)", "citation": "[2024] HKCFA 3", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "CFA held a building's external walls were common parts although the first assignment purported to reserve them to the developer: the DMC governs when the two conflict, exclusive use must correspond to undivided shares, and the manager's repair responsibility signalled communal status."}, {"url": "https://hklandlaw.wordpress.com/2024/02/20/registrability-of-agreements-for-the-sale-of-shares-in-a-property-owning-company/", "title": "Registrability of agreements for the sale of shares in a property-owning company", "date": "2024-02-20", "type": "case-note", "topics": ["land-registration", "lis-pendens", "share-sale-agreements", "registrable-interests", "liens"], "cases": [{"name": "Hundred Gain International Holding Limited v Cheng Mei Holdings Limited", "citation": "[2023] HKCFI 2705", "court": "CFI", "jurisdiction": "HK"}, {"name": "Anstalt Nybro v Hong Kong Resort Co Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Selim Ltd v Bickenhall Engineering Ltd", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Land Registration Ordinance s.2", "Land Registration Ordinance s.1A", "Land Registration Ordinance s.14", "Conveyancing and Property Ordinance s.60"], "summary": "CFI held an agreement to sell shares in a landowning company is generally not registrable: registrability turns on whether the instrument may create an interest in the land, and promises about possession or delivery do not. A lis pendens fails against a non-party owner; a forfeited deposit's lien lapsed."}, {"url": "https://hklandlaw.wordpress.com/2024/01/12/can-legal-tenants-in-common-create-an-equitable-joint-tenancy/", "title": "Can legal tenants in common create an equitable joint tenancy?", "date": "2024-01-12", "type": "case-note", "topics": ["joint-tenancy", "tenancy-in-common", "declarations-of-trust", "survivorship", "co-ownership"], "cases": [{"name": "Tam Lan Chi Lorche v Chan Siu Mui", "citation": "[2023] HKCA 1326", "court": "CA", "jurisdiction": "HK"}, {"name": "Whitlock v Moree", "citation": "[2017] UKPC 44", "court": "UKPC", "jurisdiction": "other"}], "statutes": [], "summary": "CA confirmed legal tenants in common can make themselves beneficial joint tenants by declaring a trust, in substance two trusts, one per share, so on the first death survivorship carried the whole beneficial interest to the survivor; assignment to oneself is one route but not the only one."}, {"url": "https://hklandlaw.wordpress.com/2023/12/20/marr-v-collie-the-interaction-between-presumed-resulting-and-common-intention-constructive-trusts/", "title": "Marr v Collie: The interaction between presumed resulting and common intention constructive trusts", "date": "2023-12-20", "type": "case-note", "topics": ["resulting-trusts", "common-intention", "constructive-trusts", "co-ownership", "presumptions"], "cases": [{"name": "Marr v Collie", "citation": "[2017] UKPC 17", "court": "UKPC", "jurisdiction": "other"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Thandi v Saggu", "citation": null, "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Explores Marr v Collie's message that presumed resulting trust and common intention constructive trust are not rigid alternatives: with evidence of actual intention courts analyse it directly, keeping the resulting-trust presumption for cases where unequal contributions stand alone; the equality presumption belongs to domestic joint titles."}, {"url": "https://hklandlaw.wordpress.com/2023/11/22/oral-land-contracts-and-proprietary-estoppel-thandi-v-saggu/", "title": "Oral land contracts and proprietary estoppel: Thandi v Saggu", "date": "2023-11-22", "type": "case-note", "topics": ["proprietary-estoppel", "formalities", "oral-contracts", "constructive-trusts", "sale-of-land"], "cases": [{"name": "Thandi v Saggu", "citation": "[2023] EWHC 2631", "court": "other", "jurisdiction": "EN"}, {"name": "Yaxley v Gotts", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Actionstrength Ltd v International Glass Engineering", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row Management Ltd", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Kinane v Mackie-Conteh", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Howe v Gossop", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2(1)", "Law of Property (Miscellaneous Provisions) Act 1989 s.2(5)", "Law of Property (Miscellaneous Provisions) Act 1989 s.2(8)", "Law of Property Act 1925 s.40"], "summary": "Uses Thandi v Saggu to map proprietary estoppel's uneasy coexistence with s.2 LPMPA: the statute saves constructive trusts but not estoppel, spawning five rival approaches; the claim succeeded because the claimant sought compensation for reliance rather than enforcement of the void oral sale."}, {"url": "https://hklandlaw.wordpress.com/2023/11/08/beneficial-interest-in-land-arising-from-contributions-to-purchase-price-presumed-resulting-trust-or-common-intention-constructive-trust/", "title": "Beneficial interest in land arising from contributions to purchase price - Presumed resulting trust or common intention constructive trust?", "date": "2023-11-08", "type": "overview", "topics": ["resulting-trusts", "common-intention", "constructive-trusts", "purchase-price-contributions", "beneficial-ownership"], "cases": [{"name": "Tang Hin Fai Chris v Tang Hin Lung", "citation": "[2023] HKCFI 2637", "court": "CFI", "jurisdiction": "HK"}, {"name": "Chan Chui Mee v Mak Chi Choi", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Primecredit Ltd v Yeung Chun Pang Barry", "citation": null, "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Overview asking whether purchase-price contributions generate a presumed resulting trust or a common intention constructive trust: Hong Kong courts favour the latter in domestic settings, where mortgage payments and wider dealings count, and the author would treat the resulting trust as a subcategory of it."}, {"url": "https://hklandlaw.wordpress.com/2023/10/03/implying-a-term-that-contractual-licence-can-be-terminated-on-reasonable-notice-focus-on-determining-the-parties-common-intention/", "title": "Implying a term that contractual licence can be terminated on reasonable notice: focus on determining the parties' common intention", "date": "2023-10-03", "type": "case-note", "topics": ["licences", "implied-terms", "termination", "reasonable-notice", "contractual-interpretation"], "cases": [{"name": "Hong Kong Polytechnic University v Rehabaid", "citation": "[2023] HKCA 856", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "CA implied a right to end a long-running contractual licence on reasonable notice by asking what duration the parties commonly intended: with the arrangement's mutual-benefit substratum gone and continued performance burdening the licensor, either side could terminate after giving reasonable notice."}, {"url": "https://hklandlaw.wordpress.com/2023/09/02/nuisance-caused-by-one-tenant-and-harming-a-neighbouring-tenant-where-there-is-a-common-landlord/", "title": "Nuisance caused by one tenant and harming a neighbouring tenant where there is a common landlord", "date": "2023-09-02", "type": "case-note", "topics": ["nuisance", "quiet-enjoyment", "landlord-and-tenant", "leases", "landlord-liability"], "cases": [{"name": "Southwark LBC v Tanner", "citation": "[2001] 1 AC 1", "court": "HL", "jurisdiction": "EN"}, {"name": "Coventry v Lawrence (No 2)", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Chartered Trust plc v Davies", "citation": "(1998) 76 P & CR 396", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Hilton v James Smith & Sons (Norwood) Limited", "citation": "[1979] 2 EGLR 44", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Malzy v Eicholz", "citation": "[1916] 2 KB 308", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Branchett v Beaney", "citation": "[1992] 3 All ER 910", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Perera v Vandiyar", "citation": "[1953] 1 WLR 672", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Explores when a common landlord answers for one tenant's nuisance harming another: liability requires authorisation rather than mere inaction; quiet enjoyment is not breached by defects predating the lease or neighbours' lawful use, though unmanaged retained common areas and acts of those claiming under the landlord stand apart."}, {"url": "https://hklandlaw.wordpress.com/2023/07/29/landlords-liability-for-a-tenants-nuisance/", "title": "Landlord's liability for a tenant's nuisance", "date": "2023-07-29", "type": "overview", "topics": ["nuisance", "landlord-liability", "licences", "landlord-and-tenant", "authorisation"], "cases": [{"name": "Southwark LBC v Tanner", "citation": "[2001] 1 AC 1", "court": "HL", "jurisdiction": "EN"}, {"name": "Malzy v Eichholz", "citation": "[1916] 2 KB 308", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Coventry v Lawrence (No 2)", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Cocking v Eacott", "citation": "[2016] EWCA Civ 140", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Doctrinal survey: a landlord answers for a tenant's nuisance only by authorising it or making it all but inevitable, possession having passed under the lease; a licensor who retains possession may instead be liable merely for knowing of the nuisance and not acting, possession-conferring licences aside."}, {"url": "https://hklandlaw.wordpress.com/2023/05/23/possession-claim-by-a-tenant-by-estoppel/", "title": "Possession claim by a tenant by estoppel", "date": "2023-05-23", "type": "case-note", "topics": ["tenancy-by-estoppel", "possession", "tso-land", "leases", "new-territories"], "cases": [{"name": "Tsang Shu Wo v Person unknown in occupation of Lot No 2643RP in DD 120, Yuen Long", "citation": "[2023] HKCA 644", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "CA dismissed a possession claim resting on tenancy by estoppel over Tso land: without the registered managers' consent neither head-lease nor sub-lease was valid, and estoppel operates only between the supposed landlord and tenant, so it gave no standing against occupiers in place since the 1920s."}, {"url": "https://hklandlaw.wordpress.com/2023/04/21/illegality-and-adverse-possession-in-hong-kong-after-patel/", "title": "Illegality and adverse possession in Hong Kong after Patel", "date": "2023-04-21", "type": "case-note", "topics": ["adverse-possession", "illegality", "limitation", "public-policy", "squatters"], "cases": [{"name": "Monat Investment Limited v All person(s) in occupation of part of the remaining portion of Lot No 591 in Mui Wo", "citation": "[2023] HKCA 479", "court": "CA", "jurisdiction": "HK"}, {"name": "Monat Investment Limited v All persons in occupation (first instance)", "citation": "[2020] HKCFI 1970", "court": "CFI", "jurisdiction": "HK"}, {"name": "Les Laboratoires Servier v Apotex Inc", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Patel v Mirza", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Tinsley v Milligan", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "A Solicitor v Law Society of Hong Kong", "citation": "[2008] HKCFA 15", "court": "CFA", "jurisdiction": "HK"}, {"name": "Manchester Ship Canal Company Limited v Vauxhall Motors Limited", "citation": "[2019] UKSC 46", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Buildings Ordinance s.14", "Buildings Ordinance s.40", "Limitation Ordinance"], "summary": "CA held illegality did not defeat a squatter's claim: adopting Patel v Mirza's range-of-factors approach, unlawful building works were separable from the possession itself, and since adverse possession serves public interests in productive land use, ex turpi causa needs genuine public-interest engagement to bite."}, {"url": "https://hklandlaw.wordpress.com/2023/03/13/fearn-v-trustees-of-the-tate-gallery/", "title": "Fearn v Trustees of the Tate Gallery", "date": "2023-03-13", "type": "case-note", "topics": ["nuisance", "overlooking", "privacy", "remedies", "planning"], "cases": [{"name": "Fearn v Trustees of the Tate Gallery", "citation": "[2023] UKSC 4", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Note on the UKSC's holding that the Tate's viewing platform, exposing glass-walled flats to constant observation, was an actionable nuisance: liability turns on whether the defendant's use is common and ordinary, sensitive design is no defence, planning permission does not legitimise, and public benefit affects only remedy."}, {"url": "https://hklandlaw.wordpress.com/2023/02/16/guest-v-guest-summing-up-for-now/", "title": "Guest v Guest - summing up (for now)", "date": "2023-02-16", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "detriment", "expectation-relief"], "cases": [{"name": "Guest v Guest", "citation": "[2022] UKSC 27", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Closing post of the Guest v Guest series, drawing interim conclusions on proprietary estoppel relief: it contrasts the majority's expectation-based, unconscionability-driven approach with the minority's detriment-focused method and takes stock of where the remedial principles now stand."}, {"url": "https://hklandlaw.wordpress.com/2023/02/01/guest-v-guest-aims-of-proprietary-estoppel-and-principles-governing-relief-the-detriment-focused-approach-in-the-minority-judgment-3/", "title": "Guest v Guest: Aims of proprietary estoppel and principles governing relief: the detriment-focused approach in the minority judgment (3)", "date": "2023-02-01", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "detriment", "reliance-loss"], "cases": [{"name": "Guest v Guest", "citation": "[2022] UKSC 27", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Crabb v Arun District Council", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Thorner v Major", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Walton v Walton", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Third instalment on Guest v Guest, unpacking Lord Leggatt's minority view: relief should undo reliance detriment rather than enforce the promise, yielding 610,000 pounds instead of 1.3 million on his figures, recasting the doctrine as property expectation claims and giving weight to fair settlement offers."}, {"url": "https://hklandlaw.wordpress.com/2023/01/09/guest-v-guest-aims-of-proprietary-estoppel-and-principles-governing-relief-2/", "title": "Guest v Guest: Aims of proprietary estoppel and principles governing relief (2)", "date": "2023-01-09", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "expectation-relief", "proportionality", "unconscionability"], "cases": [{"name": "Guest v Guest", "citation": "[2022] UKSC 27", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Second instalment analysing the Guest v Guest majority: relief starts from fulfilling the expectation but must not be out of all proportion to the detriment, unconscionability being the true target; life-changing harm that wage arithmetic cannot capture favours expectation relief, guided by a staged discretionary framework."}, {"url": "https://hklandlaw.wordpress.com/2022/12/05/guest-v-guest-aims-of-proprietary-estoppel-and-principles-governing-relief-1/", "title": "Guest v Guest: Aims of proprietary estoppel and principles governing relief (1)", "date": "2022-12-05", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "unconscionability", "farming-families"], "cases": [{"name": "Guest v Guest", "citation": "[2022] UKSC 27", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Opening instalment on Guest v Guest: the majority framed relief as removing the unconscionability of the repudiated farm-inheritance promise, letting the promisor elect between a trust preserving the parents' life interest and an immediate payment discounted for early receipt, and criticising awards that accelerate the inheritance."}, {"url": "https://hklandlaw.wordpress.com/2022/10/17/licence-with-no-provision-for-termination-implied-term/", "title": "Licence with no provision for termination - implied term", "date": "2022-10-17", "type": "case-note", "topics": ["licences", "implied-terms", "termination", "specific-performance"], "cases": [{"name": "The Hong Kong Polytechnic University v Rehabaid Society", "citation": "[2022] HKCFI 2830", "court": "CFI", "jurisdiction": "HK"}, {"name": "Marks & Spencer plc v BNP Paribas Securities Services Trust Co (Jersey) Limited", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Lo Yuk Sui v Fubon Bank (Hong Kong) Limited", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "CFI declined to imply a term allowing the university to end a licence containing no termination provision: under the Marks & Spencer implication principles the collapse of the collaborative purpose was not enough, the terminating party bearing the burden; specific performance secured the licensee's continued occupation."}, {"url": "https://hklandlaw.wordpress.com/2022/09/19/meaning-of-covenant-to-reinstate-to-bare-shell-condition/", "title": "Meaning of covenant to reinstate to 'bare shell' condition", "date": "2022-09-19", "type": "case-note", "topics": ["leases", "covenants", "reinstatement", "contractual-interpretation", "landlord-and-tenant"], "cases": [{"name": "AFH Hong Kong Stores Ltd v Fulton Corporation Ltd", "citation": "[2022] HKCA 1243", "court": "CA", "jurisdiction": "HK"}, {"name": "Eminent Investments (Asia Pacific) Ltd v DIO Corp", "citation": "[2020] HKCFA 38", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "CA construed a tenant's covenant to yield up premises in bare shell condition: floor slabs removed during fit-out had to be reinstated, the words 'on each floor' supporting that reading under Eminent Investments interpretation principles, and no free-standing reinstatement clause was necessary to reach it."}, {"url": "https://hklandlaw.wordpress.com/2022/08/27/priority-contest-between-a-charging-order-and-an-assignment/", "title": "Priority contest between a charging order and an assignment", "date": "2022-08-27", "type": "case-note", "topics": ["charging-orders", "priority", "land-registration", "assignment", "equitable-interests"], "cases": [{"name": "Asparouh Ianov Dimitrov v Dominic Tak Ming Lau", "citation": "[2022] HKCA 1146", "court": "CA", "jurisdiction": "HK"}, {"name": "Re Rose", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Land Registration Ordinance s.5", "Land Registration Ordinance s.5A"], "summary": "CA priority contest: a charging order absolute relates back to the registered nisi's priority date and so defeated a later-registered assignment; alleged prior equitable interests via incomplete gift or estoppel failed for want of documentation and detrimental reliance, LRO ss.5 and 5A fixing the operative dates."}, {"url": "https://hklandlaw.wordpress.com/2022/07/27/meaning-of-saleable-area-top-faith-property-ltd-v-wong-ben/", "title": "Meaning of 'saleable area': Top Faith Property Ltd v Wong Ben", "date": "2022-07-26", "type": "case-note", "topics": ["misrepresentation", "rescission", "sale-of-land", "contractual-interpretation"], "cases": [{"name": "Top Faith Property Ltd v Wong Ben", "citation": "[2022] HKCA 783", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building (Planning) Regulations (Cap 123F)"], "summary": "The Court of Appeal read 'saleable area' in its professionally accepted sense under the HKIS Code of Measuring Practice, judged the representation objectively from a reasonable recipient's standpoint, and permitted rescission where the stated area proved false in a share sale built around a property."}, {"url": "https://hklandlaw.wordpress.com/2022/06/29/interpretation-of-the-management-charge-provisions-of-a-dmc/", "title": "Interpretation of the management charge provisions of a DMC", "date": "2022-06-29", "type": "case-note", "topics": ["deed-of-mutual-covenant", "building-management", "contractual-interpretation", "implied-terms", "co-ownership"], "cases": [{"name": "Sam Woo Marine Works Ltd v Po Hang Building (IO)", "citation": "[2022] HKCA 733", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.20(2)"], "summary": "Construing a DMC, the Court of Appeal required separate accounts for each category of owners so that surpluses collected from one group cannot subsidise another group's expenses, and declined to imply a term allowing surpluses to be set off before further charges, citing contingency-fund obligations."}, {"url": "https://hklandlaw.wordpress.com/2022/04/28/priority-as-between-1-the-assignment-of-the-net-proceeds-of-any-future-sale-of-property-and-2-a-charging-order-over-the-property/", "title": "Priority as between (1) the assignment of the net proceeds of any future sale of property and (2) a charging order over the property", "date": "2022-04-28", "type": "case-note", "topics": ["charging-orders", "assignment-of-proceeds", "priority", "equitable-interests", "land-registration"], "cases": [{"name": "Winland Finance Ltd v Gain Hero Finance Ltd", "citation": "[2022] HKCFA 3", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["High Court Ordinance s.20B(3)", "Conveyancing and Property Ordinance s.54(1)"], "summary": "The Court of Final Appeal ranked a registrable charging order, which operates as an equitable charge on the land, ahead of an earlier assignment of future net sale proceeds, since that assignment gives no interest in the land and the assignee takes only what survives prior charges."}, {"url": "https://hklandlaw.wordpress.com/2022/04/08/undue-influence-presumption-of-undue-influence-where-lenders-lawyer-fails-to-properly-advise-borrower-for-whom-it-also-acts/", "title": "Undue influence: presumption of undue influence where lender's lawyer fails to properly advise borrower for whom it also acts", "date": "2022-04-08", "type": "case-note", "topics": ["undue-influence", "mortgages", "independent-advice", "solicitors", "presumptions"], "cases": [{"name": "Nature Resorts Ltd v First Citizens Bank Ltd", "citation": "[2022] UKPC 10", "court": "UKPC", "jurisdiction": "other"}, {"name": "Pesticcio v Huet", "citation": "[2004] EWCA Civ 372", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Royal Bank of Scotland plc v Etridge (No 2)", "citation": "[2001] UKHL 44", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Privy Council declined to presume undue influence where the lender's solicitor also acted for the corporate chargor in a commercial deal: benefits to the controlling shareholder made the transaction readily explicable, and shared representation alone does not raise the presumption, though deficient advice hampers rebuttal."}, {"url": "https://hklandlaw.wordpress.com/2022/03/09/part-performance-and-the-balance-of-probabilities-ng-yuk-pui-kelly-v-ng-lai-ling-winnie-in-the-court-of-final-appeal/", "title": "Part performance and the balance of probabilities: Ng Yuk Pui Kelly v Ng Lai Ling Winnie in the Court of Final Appeal", "date": "2022-03-09", "type": "case-note", "topics": ["part-performance", "formalities", "informal-land-contracts", "constructive-trust", "proprietary-estoppel"], "cases": [{"name": "Ng Yuk Pui Kelly v Ng Lai Ling Winnie", "citation": "[2021] HKCFA 40", "court": "CFA", "jurisdiction": "HK"}, {"name": "Ng Yuk Pui Kelly v Ng Lai Ling Winnie", "citation": "[2021] HKCA 724", "court": "CA", "jurisdiction": "HK"}, {"name": "Steadman v Steadman", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "The CFA confirmed that part performance lets courts enforce informal land contracts despite s.3(1): the acts are assessed cumulatively on the balance of probabilities as pointing to some such contract, not each act individually or unequivocally. Possession plus payment and transfer demands sufficed; constructive trust and estoppel remain alternatives."}, {"url": "https://hklandlaw.wordpress.com/2022/03/01/adverse-possession-woo-sai-mui-v-lam-island-development-company-limited/", "title": "Adverse Possession: Woo Sai Mui v Lam Island Development Company Limited", "date": "2022-03-01", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "intention-to-possess", "limitation"], "cases": [{"name": "Woo Sai Mui v Lam Island Development Company Ltd", "citation": "[2022] HKCFI 39", "court": "CFI", "jurisdiction": "HK"}, {"name": "Chang Shun Tak v Leung Sun Fat", "citation": "HCA 13809/1997", "court": "CFI", "jurisdiction": "HK"}, {"name": "Gatland Enterprises Ltd v Kwok Chi Yau", "citation": "CACV 260/2014", "court": "CA", "jurisdiction": "HK"}, {"name": "Wong Tak Yue v Kung Kwok Wai", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "A squatter claim over unenclosed land failed: sporadic acts such as planting fruit trees did not amount to factual possession, and willingness to pay rent if asked undermined the intention to possess. Compelling evidence is expected even though the standard remains the balance of probabilities."}, {"url": "https://hklandlaw.wordpress.com/2022/02/28/adverse-possession-wu-yim-chung-v-lo-wai-ching/", "title": "Adverse Possession: Wu Yim Chung v Lo Wai Ching", "date": "2022-02-28", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "intention-to-possess", "limitation"], "cases": [{"name": "Wu Yim Chung v Lo Wai Ching", "citation": "[2022] HKCA 100", "court": "CA", "jurisdiction": "HK"}, {"name": "Tsang Fu Keung v Chu Jim Mi Jimmy", "citation": "[2017] 3 HKC 527", "court": "CFI", "jurisdiction": "HK"}, {"name": "Powell v McFarlane", "citation": "(1979) 38 P & CR 452", "court": "other", "jurisdiction": "EN"}, {"name": "Wong Tak Yue v Kung Kwok Wai (No 2)", "citation": "(1997-98) 1 HKCFAR 55", "court": "CFA", "jurisdiction": "HK"}, {"name": "JA Pye (Oxford) Ltd v Graham", "citation": "[2003] 1 AC 419", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "The Court of Appeal dismissed a squatter claim to an open storage area: outsiders could and did enter without permission, so the claimant showed neither exclusive control nor an intention to exclude the world at large, and unbroken possession across the limitation period was not established."}, {"url": "https://hklandlaw.wordpress.com/2022/02/22/online-property-law-seminar-16-march-2022-details-and-registration/", "title": "Online Property Law seminar - 16 March 2022 - details and registration", "date": "2022-02-22", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces 16 March 2022 online seminar on adverse possession topics."}, {"url": "https://hklandlaw.wordpress.com/2022/02/14/break-clauses-and-sub-leases-pw-co-v-milton-gate-investments-limited/", "title": "Break clauses and sub-leases: PW & Co v Milton Gate Investments Limited", "date": "2022-02-14", "type": "case-note", "topics": ["leases", "break-clauses", "sub-leases", "termination-of-leases"], "cases": [{"name": "PW & Co v Milton Gate Investments Ltd", "citation": "[2004] Ch 142", "court": "other", "jurisdiction": "EN"}, {"name": "Pennell v Payne", "citation": "[1995] QB 192", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Barrett v Morgan", "citation": "[2000] 2 AC 264", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "When a head tenant ends the head lease under a break clause, sub-leases carved from it fall too, applying Pennell v Payne; landlord and head tenant cannot contract to preserve them, because a derivative estate cannot outlive the estate from which it was granted."}, {"url": "https://hklandlaw.wordpress.com/2022/01/31/inappropriate-to-register-successful-adverse-possession-claimant-as-owner-of-property/", "title": "Inappropriate to register successful adverse possession claimant as owner of property", "date": "2022-01-31", "type": "case-note", "topics": ["adverse-possession", "land-registration", "extinguishment-of-title", "acknowledgment-of-title"], "cases": [{"name": "Lam Sai Man v Minloy Ltd", "citation": "[2022] HKCA 37", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Because adverse possession merely extinguishes the paper title rather than conveying it, the winning squatter cannot be registered as owner: Hong Kong keeps a register of instruments, not titles. A written acknowledgment given after extinguishment cannot revive the old title, and controlling the whole plot suffices without using every part."}, {"url": "https://hklandlaw.wordpress.com/2022/01/09/registrability-and-priority-of-an-assignment-of-the-proceeds-of-a-future-sale-of-land/", "title": "Registrability and priority of an assignment of the proceeds of a future sale of land", "date": "2022-01-09", "type": "case-note", "topics": ["assignment-of-proceeds", "land-registration", "charging-orders", "priority", "equitable-mortgage"], "cases": [{"name": "Winland Finance Ltd v Gain Hero Finance Ltd", "citation": "[2021] HKCA 576", "court": "CA", "jurisdiction": "HK"}], "statutes": ["High Court Ordinance s.20B(3)", "Land Registration Ordinance"], "summary": "The Court of Appeal held an assignment of future sale proceeds is not an instrument affecting land and so is not registrable; it gives only an equitable claim to money. A charging order, treated by statute as an equitable charge, therefore prevailed, and depositing title deeds alone created no equitable mortgage."}, {"url": "https://hklandlaw.wordpress.com/2021/12/30/seminar-private-takings-of-land-for-urban-redevelopment-16-february-2022/", "title": "Seminar: Private takings of land for urban redevelopment - 16 February 2022", "date": "2021-12-30", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces February 2022 seminar on private takings for urban redevelopment."}, {"url": "https://hklandlaw.wordpress.com/2021/12/07/estate-encroaching-into-neighbouring-estate/", "title": "Estate encroaching into neighbouring estate", "date": "2021-12-07", "type": "case-note", "topics": ["adverse-possession", "encroachment", "easements", "limitation", "proprietary-estoppel"], "cases": [{"name": "Wah Fung (IO) v Morengo Court (IO)", "citation": "[2021] HKCFI 3400", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "An incorporated owners' adverse possession claim to structures encroaching on the neighbouring estate failed for want of compelling proof that its owners installed or exclusively used them through the twenty-year limitation period. The judge suggested easements, licences or estoppel as alternative answers to boundary overlaps in dense developments."}, {"url": "https://hklandlaw.wordpress.com/2021/10/31/covid-restrictions-leases-and-failure-of-basis/", "title": "Covid restrictions, leases and failure of basis", "date": "2021-10-31", "type": "case-note", "topics": ["leases", "implied-terms", "failure-of-basis", "unjust-enrichment", "covid-19"], "cases": [{"name": "London Trocadero (2015) LLP v Picturehouse Cinemas Ltd", "citation": "[2021] EWHC 2591 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Yoo Design Services Ltd v Iliv Realty Pte Ltd", "citation": "[2021] EWCA Civ 560", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Fibrosa Spolka Akcyjna v Fairbairn Lawson Combe Barbour Ltd", "citation": "[1943] AC 32", "court": "HL", "jurisdiction": "EN"}, {"name": "Dargamo Holdings Ltd v Avonwick Holding Ltd", "citation": "[2021] EWCA Civ 1149", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Cinema tenants shut by pandemic rules still owed rent: no term that the premises be usable could be implied into the leases, and a failure-of-basis restitution claim foundered because payment obligations followed the contract's own risk allocation and any failure must be total, not partial."}, {"url": "https://hklandlaw.wordpress.com/2021/09/26/proprietary-estoppel-and-oral-land-contracts-the-last-word/", "title": "Proprietary estoppel and oral land contracts: the last word?", "date": "2021-09-26", "type": "case-note", "topics": ["proprietary-estoppel", "formalities", "oral-land-contracts", "equitable-relief"], "cases": [{"name": "Howe v Gossop", "citation": "[2021] EWHC 637 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row Management Ltd", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Herbert v Doyle", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Kinane v Mackie-Conteh", "citation": "[2005] EWCA Civ 45", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "Howe v Gossop allows proprietary estoppel to bite despite section 2 formality rules when the relief granted, such as an irrevocable licence, stops short of enforcing the oral bargain itself; no exceptionality threshold applies, though directly enforcing a non-compliant contract may need representation beyond the agreement."}, {"url": "https://hklandlaw.wordpress.com/2021/09/11/recovering-pre-payment-of-purchase-price-where-the-agreement-was-never-completed/", "title": "Recovering pre-payment of purchase price where the agreement was never completed", "date": "2021-09-11", "type": "case-note", "topics": ["deposits", "unjust-enrichment", "sale-of-land", "termination", "repudiatory-breach"], "cases": [{"name": "Hui Tze Ha v Ho Yuet Lin", "citation": "[2021] HKCFI 1901", "court": "CFI", "jurisdiction": "HK"}, {"name": "Camberra Investment Ltd v Chan Wai Tak", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Chong Kai Tai Ringo v Lee Gee Kee", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Chao Keh Lung v Don Xia", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Polyset Ltd v Panhandat Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Where a sale agreement was never completed and the seller elected to treat it as ended, a pre-payment characterised as an advance of price rather than a true deposit could be recovered through unjust enrichment; a genuine deposit would instead be forfeited on the buyer's repudiation."}, {"url": "https://hklandlaw.wordpress.com/2021/08/17/online-property-law-seminar-6-october/", "title": "Online Property Law seminar - 6 October", "date": "2021-08-17", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces October seminar on non-fungible tokens and digital art."}, {"url": "https://hklandlaw.wordpress.com/2021/08/14/when-is-an-occupation-rent-payable/", "title": "When is an occupation rent payable?", "date": "2021-08-14", "type": "case-note", "topics": ["co-ownership", "occupation-rent", "equitable-accounting", "ouster", "partition"], "cases": [{"name": "Cheung Lai Mui v Cheung Wai Shing", "citation": "[2021] HKEC 2263", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "The Court of Final Appeal confined occupation rent to cases of ouster, including constructive ouster such as domestic violence, or agreement making the occupier an accounting agent, rejecting any free-standing equitable duty; in partition or sale proceedings it instead features within equitable accounting between co-owners."}, {"url": "https://hklandlaw.wordpress.com/2021/07/12/proprietary-estoppel-does-detrimental-reliance-need-to-be-incurred-before-the-death-of-the-promisor/", "title": "Proprietary estoppel: Does detrimental reliance need to be incurred before the death of the promisor?", "date": "2021-07-12", "type": "case-note", "topics": ["proprietary-estoppel", "detrimental-reliance", "constructive-trust", "succession", "family-property"], "cases": [{"name": "Cheung Lai Mui v Cheung Wai Shing", "citation": "[2021] HKEC 2263", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Partition Ordinance"], "summary": "On a family understanding that a descendant would take the co-owned property, the CFA required the detrimental reliance, here building works, to be incurred before the death of the last co-owner who gave the assurance; post-death events bear only on relief, satisfied via constructive trust."}, {"url": "https://hklandlaw.wordpress.com/2021/06/11/philanthropy-in-the-age-of-covid-19-asian-and-global-perspectives-online-conference-22-july-2021/", "title": "Philanthropy in the Age of COVID-19: Asian and Global Perspectives - Online conference - 22 July 2021", "date": "2021-06-11", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces July 2021 online conference on philanthropy during Covid-19."}, {"url": "https://hklandlaw.wordpress.com/2021/06/01/the-home-ownership-scheme-and-beneficial-ownership-16-june-2021-ms-phoebe-woo/", "title": "The Home Ownership Scheme and beneficial ownership. 16 June 2021. Ms Phoebe Woo.", "date": "2021-05-31", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces June 2021 talk on Home Ownership Scheme beneficial ownership."}, {"url": "https://hklandlaw.wordpress.com/2021/05/28/the-seven-deadly-sins-of-trustee-decision-making-online-seminar-23-june/", "title": "The seven deadly sins of trustee decision making - online seminar 23 June", "date": "2021-05-28", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces June seminar on pitfalls in trustee decision making."}, {"url": "https://hklandlaw.wordpress.com/2021/05/20/family-and-wealth-disputes-and-the-lawyers-toolkit-in-planning-and-litigation-property-law-seminar-online-26-may-2021/", "title": "Family and Wealth Disputes and the Lawyer's Toolkit in Planning and Litigation - Property Law seminar (online) - 26 May 2021", "date": "2021-05-20", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces May 2021 seminar on family wealth disputes toolkit."}, {"url": "https://hklandlaw.wordpress.com/2021/05/20/property-law-online-discussion-ms-yasmine-zahir-property-claims-for-cultural-property-26-may-2021-2/", "title": "Property Law Online Discussion - Ms Yasmine Zahir - Property claims for cultural property - 26 May 2021", "date": "2021-05-20", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces May 2021 discussion on cultural property ownership claims."}, {"url": "https://hklandlaw.wordpress.com/2021/05/15/demands-for-rent-and-waiver/", "title": "Demands for rent and waiver", "date": "2021-05-15", "type": "case-note", "topics": ["forfeiture", "waiver", "leases", "rent", "assignment"], "cases": [{"name": "Greenwood Reversions Ltd v World Environment Foundation Ltd", "citation": "[2008] EWCA Civ 47", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Yorkshire Metropolitan Properties Ltd v Co-Operative Retail Services Ltd", "citation": "[2001] L&TR 26", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "A landlord waives the right to forfeit only through an unqualified demand for rent made with knowledge of the breach; letters making the tenancy's continuation conditional on clearing arrears are not unqualified, and demands addressed to the assignor rather than the actual tenant do not waive."}, {"url": "https://hklandlaw.wordpress.com/2021/04/14/property-law-online-discussion-ms-yasmine-zahir-property-claims-for-cultural-property-26-may-2021/", "title": "Property Law Online Discussion - Ms Yasmine Zahir - Property claims for cultural property - 26 May 2021", "date": "2021-04-14", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces cultural property claims discussion scheduled for May 2021."}, {"url": "https://hklandlaw.wordpress.com/2021/04/13/property-law-seminar-26-may-2021-professor-tang-hang-wu/", "title": "Property Law seminar - 26 May 2021 - Professor Tang Hang Wu", "date": "2021-04-13", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces Professor Tang's May 2021 family wealth disputes seminar."}, {"url": "https://hklandlaw.wordpress.com/2021/03/30/prescriptive-easements-deciding-on-whether-user-was-as-of-right/", "title": "Prescriptive easements: deciding on whether user was as of right", "date": "2021-03-30", "type": "case-note", "topics": ["easements", "prescription", "user-as-of-right", "parking-rights"], "cases": [{"name": "Poste Hotels Ltd v Cousins", "citation": "[2020] EWHC 582 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Gardner v Hodgson's Kingston Brewery Company", "citation": "[1903] AC 229", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Long parking in a private street supported a prescriptive easement because no lawful origin other than a grant was reasonably possible; where two lawful explanations for the user exist, enjoyment as of right is not established. The right attached to the street generally, not a marked space."}, {"url": "https://hklandlaw.wordpress.com/2021/03/03/informal-land-contracts-overlapping-equitable-doctrines/", "title": "Informal land contracts: overlapping equitable doctrines", "date": "2021-03-03", "type": "case-note", "topics": ["part-performance", "common-intention-constructive-trust", "proprietary-estoppel", "formalities", "adverse-possession"], "cases": [{"name": "Ng Yuk Pui Kelly v Dung Wai Man", "citation": "[2019] HKCFI 210", "court": "CFI", "jurisdiction": "HK"}, {"name": "Luo Xing Juan", "citation": "[2008] HKCFA 48", "court": "CFA", "jurisdiction": "HK"}, {"name": "Cobbe v Yeoman's Row", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "Conveyancing and Property Ordinance s.5(1)"], "summary": "One dispute illustrates several routes around formality rules: payment alone is weak part performance unless referable to the agreement, yet common intention constructive trust and proprietary estoppel can each sidestep writing requirements, and possession under an unenforceable contract may even ground adverse possession."}, {"url": "https://hklandlaw.wordpress.com/2021/02/01/the-small-house-policy-and-the-basic-law/", "title": "The Small House Policy and the Basic Law", "date": "2021-02-01", "type": "case-note", "topics": ["small-house-policy", "basic-law", "traditional-rights", "constitutional-law", "discrimination"], "cases": [{"name": "Kwok Cheuk Kin v Director of Lands", "citation": "[2021] HKCA 54", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Basic Law art.40", "Basic Law art.25", "Basic Law art.39", "Hong Kong Bill of Rights art.22"], "summary": "The Court of Appeal upheld the Small House Policy: benefits for male indigenous New Territories villagers are lawful traditional rights and interests under Basic Law article 40, measured by legal recognition in 1990 and continuity of essential features, and that protection answers the equality-based challenges."}, {"url": "https://hklandlaw.wordpress.com/2020/12/29/subject-to-contract-re-affirmed/", "title": "'Subject to contract' re-affirmed", "date": "2020-12-29", "type": "case-note", "topics": ["contract-formation", "subject-to-contract", "negotiations", "sale-of-land"], "cases": [{"name": "Joanne Properties Ltd v Moneything Capital Ltd", "citation": "[2020] EWCA Civ 1541", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Negotiations conducted subject to contract yielded no binding settlement even though the substance seemed agreed: the qualification governs until both sides expressly or by necessary implication lift it, a single unqualified offer does not dissolve the umbrella, and one party's belief in a concluded deal is irrelevant."}, {"url": "https://hklandlaw.wordpress.com/2020/12/17/property-law-seminar-online-13-january-2021/", "title": "Property Law Seminar Online - 13 January 2021", "date": "2020-12-17", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces January 2021 seminar on limits of testamentary freedom."}, {"url": "https://hklandlaw.wordpress.com/2020/11/25/monat-investment-limited-v-all-persons-in-occupation-of-part-of-the-remaining-portion-of-lot-no-591-in-mui-wo-dd-4-no-16-ma-po-tsuen-mui-wo/", "title": "Monat Investment Limited v All person(s) in occupation of part of the remaining portion of Lot No 591 in Mui Wo DD 4 No 16 Ma Po Tsuen, Mui Wo", "date": "2020-11-25", "type": "case-note", "topics": ["adverse-possession", "illegality", "limitation", "unauthorised-structures"], "cases": [{"name": "Monat Investment Ltd v All Person(s) in Occupation of Part of the Remaining Portion of Lot No 591 in Mui Wo DD 4, No 16 Ma Po Tsuen, Mui Wo", "citation": "[2020] HKCFI 1970", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance", "Buildings Ordinance s.14"], "summary": "Illegality, whether trespassory entry or unauthorised structures breaching building controls or the Government lease, does not automatically defeat adverse possession; the purpose of the statute breached is weighed separately, and regulators may still enforce after title passes. Fencing the site and paying utilities evidenced possession."}, {"url": "https://hklandlaw.wordpress.com/2020/10/26/cheung-lai-mui-v-cheung-wai-shing-hong-kong-court-of-appeal/", "title": "Cheung Lai Mui v Cheung Wai Shing (Hong Kong Court of Appeal)", "date": "2020-10-26", "type": "case-note", "topics": ["common-intention-constructive-trust", "proprietary-estoppel", "detrimental-reliance", "acquiescence", "family-property"], "cases": [{"name": "Cheung Lai Mui v Cheung Wai Shing", "citation": "[2020] 2 HKLRD 15", "court": "CA", "jurisdiction": "HK"}, {"name": "Mo Ying", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Thorner v Major", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Walton v Walton", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "The Court of Appeal required detrimental reliance grounding a common intention constructive trust to occur before the promisor's death, treating proprietary estoppel as the more flexible tool; with active encouragement the promisor need not know of the reliance, though knowledge matters for estoppel by acquiescence."}, {"url": "https://hklandlaw.wordpress.com/2020/10/21/online-seminar-11-november-equity-and-the-enforcement-of-informal-land-contracts/", "title": "Online seminar 11 November: Equity and the enforcement of informal land contracts", "date": "2020-10-21", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces November seminar on equity and informal land contracts."}, {"url": "https://hklandlaw.wordpress.com/2020/09/26/contractual-intention-and-agreements-between-family-members/", "title": "Contractual intention and agreements between family members", "date": "2020-09-26", "type": "case-note", "topics": ["contractual-intention", "family-agreements", "domestic-agreements", "contract-formation"], "cases": [{"name": "Ho Lai King v Kwok Fung Ying", "citation": "[2020] HKCA 657", "court": "CA", "jurisdiction": "HK"}, {"name": "Balfour v Balfour", "citation": "[1919] 2 KB 571", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Family arrangements are presumed non-contractual, but the presumption yields to context: the parties' relationship, amity or estrangement, the asset's significance, how the deal was made and later conduct. Dealings over major capital assets between estranged relatives evidence intention more readily than everyday oral support promises."}, {"url": "https://hklandlaw.wordpress.com/2020/08/22/the-family-home-types-of-constructive-trust-the-end-of-detrimental-reliance/", "title": "The family home. Types of constructive trust. The end of detrimental reliance?", "date": "2020-08-22", "type": "case-note", "topics": ["constructive-trust", "common-intention-constructive-trust", "detrimental-reliance", "family-home", "formalities"], "cases": [{"name": "Archibald v Alexander", "citation": "[2020] EWHC 1621 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Rochefoucauld v Boustead", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Bannister v Bannister", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "De Bruyne v De Bruyne", "citation": "[2010] EWCA Civ 519", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Distinguishes two constructive trusts over family homes: the common intention type requiring detrimental reliance, and the Rochefoucauld and De Bruyne strand where property passes to a volunteer on a promise to hold for others, binding conscience without detriment. Siblings who left their interests unprotected illustrated both."}, {"url": "https://hklandlaw.wordpress.com/2020/08/15/fathers-gift-of-property-to-son-conditional-on-sons-caring-for-father/", "title": "Father's gift of property to son: Conditional on son's caring for father?", "date": "2020-08-15", "type": "case-note", "topics": ["gifts", "conditions", "constructive-trust", "resulting-trust", "limitation", "laches"], "cases": [{"name": "Yeung Hock Wai v Chan Wai Man", "citation": "[2020] HKCFI 1693", "court": "CFI", "jurisdiction": "HK"}, {"name": "Paragon Finance", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "Limitation Ordinance"], "summary": "A claim that a father's transfer to his son was conditional on being cared for failed: the caring language was precatory or too uncertain to cut down the gift. Trust-based counterattacks ran into Paragon Finance classification, limitation periods and laches given long, prejudicial delay."}, {"url": "https://hklandlaw.wordpress.com/2020/07/24/commentary-on-toms-v-ruberry/", "title": "Commentary on Toms v Ruberry", "date": "2020-07-24", "type": "case-note", "topics": ["forfeiture", "leases", "statutory-notices", "landlord-and-tenant"], "cases": [{"name": "Toms v Ruberry", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.146", "Conveyancing and Property Ordinance s.58"], "summary": "Signposts the author's published commentary on Toms v Ruberry, concerning when a landlord can serve a statutory forfeiture notice: the right to forfeit must already have arisen before a Law of Property Act s.146 notice, a question with parallels under Hong Kong's CPO s.58."}, {"url": "https://hklandlaw.wordpress.com/2020/07/14/when-does-a-landlord-have-right-to-serve-a-cpo-s-58-notice/", "title": "When does a landlord have right to serve a CPO s. 58 notice?", "date": "2020-07-14", "type": "case-note", "topics": ["forfeiture", "statutory-notices", "leases", "contractual-interpretation"], "cases": [{"name": "Toms v Ruberry", "citation": "[2019] EWCA Civ 128", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.58", "Law of Property Act 1925 s.146"], "summary": "Where the lease obliges the landlord to give a default notice with a cure period before forfeiting, a statutory forfeiture notice cannot validly be served until that period has expired unremedied: the right to forfeit must already exist, and arguments for concurrent notices to streamline matters failed."}, {"url": "https://hklandlaw.wordpress.com/2020/06/30/property-law-seminar-9-july/", "title": "Property Law seminar - 9 July", "date": "2020-06-30", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces July 2020 seminar surveying Hong Kong property market regulation."}, {"url": "https://hklandlaw.wordpress.com/2020/06/10/co-owner-in-occupation-ordered-to-account-for-income/", "title": "Co-owner in occupation ordered to account for income", "date": "2020-06-10", "type": "case-note", "topics": ["co-ownership", "account-of-profits", "occupation-rent", "tenancy-in-common", "equitable-accounting"], "cases": [{"name": "Tang Tak Sum v Tang Kai Fung (No 2)", "citation": "[2020] 2 HKLRD 338", "court": null, "jurisdiction": "HK"}, {"name": "Tang Tak Sum v Tang Kai Fung (No 1)", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A tenant in common who occupied and took rental income from the shared property without telling fellow owners was ordered to account for it on the common basis; wilful default accounting demands specific pleading and proof, while occupation rent still turns on agreement, ouster or countervailing equities."}, {"url": "https://hklandlaw.wordpress.com/2020/05/13/richard-susskind-keynote-speaker-at-online-conference-in-june/", "title": "Richard Susskind keynote speaker at online conference in June", "date": "2020-05-13", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces Richard Susskind keynote on legal education, June 2020 conference."}, {"url": "https://hklandlaw.wordpress.com/2020/05/09/can-landlord-of-block-of-flats-authorise-a-tenant-to-make-structural-alterations-in-breach-of-absolute-covenant/", "title": "Can landlord of block of flats authorise a tenant to make structural alterations in breach of absolute covenant?", "date": "2020-05-09", "type": "case-note", "topics": ["leasehold-covenants", "absolute-covenants", "implied-terms", "landlord-and-tenant", "mutual-enforceability"], "cases": [{"name": "Duval v 11-13 Randolph Crescent Ltd", "citation": "[2020] UKSC 18", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.41"], "summary": "The Supreme Court held that a landlord who must, at a tenant's request and cost, enforce the flat leases cannot license another tenant to break an absolute covenant against structural works: a term is implied that the landlord will not disable its own enforcement power. Comparisons with CPO s.41 follow."}, {"url": "https://hklandlaw.wordpress.com/2020/04/21/coronavirus-and-property-law/", "title": "Coronavirus and Property Law", "date": "2020-04-21", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Points readers to international coronavirus and property law resource portal."}, {"url": "https://hklandlaw.wordpress.com/2020/04/08/right-of-way-with-vehicles-or-only-pedestrian/", "title": "Right of way: with vehicles or only pedestrian?", "date": "2020-04-08", "type": "case-note", "topics": ["easements", "rights-of-way", "contractual-interpretation", "derogation-from-grant"], "cases": [{"name": "The Dairy Farm Company Ltd v Secretary for Justice", "citation": "[2020] HKCFI 306", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Construing the grant in its context, the court held a right of way over a road or path serving staff housing extended to vehicles: intended domestic use, maintenance obligations and the 75-year term pointed that way, and denying vehicular access would leave the land practically unusable, derogating from grant."}, {"url": "https://hklandlaw.wordpress.com/2020/04/04/online-seminar-sham-and-illusory-trusts/", "title": "Online seminar - Sham and illusory trusts", "date": "2020-04-04", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces April online seminar on sham and illusory trusts."}, {"url": "https://hklandlaw.wordpress.com/2019/12/14/purchaser-pays-owner-who-enters-into-a-second-contract-to-sell-to-a-third-party/", "title": "Purchaser pays owner who enters into a second contract to sell to a third party", "date": "2019-12-14", "type": "case-note", "topics": ["priority", "land-registration", "resulting-trust", "common-intention-constructive-trust", "unjust-enrichment", "specific-performance"], "cases": [{"name": "Mui So Bing v Wan Chi Sing", "citation": "[2019] HKCA 1341", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3(2)"], "summary": "The buyer who paid lost the land to the later registered contract and could establish neither species of trust. Recovery came instead through unjust enrichment against the sellers. Arguments not run at trial were shut out on appeal."}, {"url": "https://hklandlaw.wordpress.com/2019/11/21/equitable-subrogation-filby-v-mortgage-express-no-2/", "title": "Equitable subrogation: Filby v Mortgage Express (No 2)", "date": "2019-11-21", "type": "case-note", "topics": ["equitable-subrogation", "unjust-enrichment", "secured-lending", "restitution", "remedies"], "cases": [{"name": "Filby v Mortgage Express (No 2) Ltd", "citation": "[2004] EWCA Civ 759", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Money used to clear earlier borrowing lets the new lender step into the discharged creditor's shoes, even unsecured ones. The windfall of being relieved of a debt is unjust where the expected security failed; intentions about the funds are beside the point."}, {"url": "https://hklandlaw.wordpress.com/2019/11/14/developer-retains-exclusive-right-to-use-the-external-walls-are-they-common-parts/", "title": "Developer retains exclusive right to use the external walls. Are they common parts?", "date": "2019-11-14", "type": "case-note", "topics": ["common-parts", "external-walls", "deed-of-mutual-covenant", "building-management", "management-charges"], "cases": [{"name": "Kong Wai Hsien v Tai Wai Glamour Garden (IO)", "citation": "[2019] HKCA 1229", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Reserving advertising and similar uses to the developer does not privatise the walls. Because they enclose and support the building, every occupier benefits, so they remain common parts and owners must still contribute to maintaining them."}, {"url": "https://hklandlaw.wordpress.com/2019/11/11/when-does-the-proprietary-estoppel-right-arise/", "title": "When does the proprietary estoppel right arise?", "date": "2019-11-11", "type": "case-note", "topics": ["proprietary-estoppel", "inchoate-equity", "bankruptcy", "detrimental-reliance", "property-rights"], "cases": [{"name": "Walden v Atkins", "citation": "[2013] EWHC 1387", "court": "other", "jurisdiction": "EN"}], "statutes": ["Insolvency Act 1986 s.436"], "summary": "The equity crystallises as soon as promise, reliance and detriment coincide, making the promise irrevocable, rather than when it is later broken. That timing determines whether the interest passes to a trustee in bankruptcy, however remedial questions are resolved afterwards."}, {"url": "https://hklandlaw.wordpress.com/2019/10/12/occupation-rent-joint-tenants-trustee-in-bankruptcy/", "title": "Occupation rent: joint tenant's trustee in bankruptcy", "date": "2019-10-12", "type": "case-note", "topics": ["occupation-rent", "equitable-accounting", "co-ownership", "bankruptcy", "trustee-in-bankruptcy"], "cases": [{"name": "Davis v Jackson", "citation": "[2017] EWHC 698 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Nothing is owed for occupying jointly owned property unless fairness demands it, and the court looks at events preceding the claimant's acquisition. A trustee inherits no better position than the bankrupt, who never enjoyed a right to occupy."}, {"url": "https://hklandlaw.wordpress.com/2019/10/09/equitable-accounting-is-an-ouster-necessary-before-an-occupation-rent-becomes-payable/", "title": "Equitable accounting: is an ouster necessary before an occupation rent becomes payable?", "date": "2019-10-09", "type": "case-note", "topics": ["equitable-accounting", "occupation-rent", "ouster", "co-ownership", "set-off"], "cases": [{"name": "Murphy v Gooch", "citation": "[2007] EWCA Civ 603", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Trusts of Land and Appointment of Trustees Act 1996"], "summary": "No formal exclusion need be proved: rent may be charged whenever just and equitable, and leaving after a relationship ends counts as constructive exclusion anyway. Mortgage instalments and rent paid are set against the sum due, whichever route is taken."}, {"url": "https://hklandlaw.wordpress.com/2019/10/07/adverse-possession-what-is-the-limitation-period-when-time-began-to-run-before-1-july-1991/", "title": "Adverse possession: what is the limitation period when time began to run before 1 July 1991?", "date": "2019-10-07", "type": "case-note", "topics": ["adverse-possession", "limitation", "transitional-provisions", "statutory-interpretation", "paper-owner"], "cases": [{"name": "Tang Moon Lam v Tang Ying Yeung", "citation": "[2019] HKCA 1102", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.7", "Limitation Ordinance s.38A"], "summary": "Occupation starting before July 1991 and still running then must last the full twenty years. A squatter cannot simply count twelve years from that date onwards, an argument the appellate court rejected; twelve years applies only to later-starting possession."}, {"url": "https://hklandlaw.wordpress.com/2019/10/05/determining-the-extent-of-an-easement-by-prescription/", "title": "Determining the extent of an easement by prescription", "date": "2019-10-05", "type": "case-note", "topics": ["easements", "prescription", "foreshore", "extent-of-right", "fluctuating-boundaries"], "cases": [{"name": "Lynn Shellfish Ltd v Loose", "citation": "[2016] UKSC 14", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Scope follows the use actually enjoyed as of right. Rights can attach to ground whose limits move, so long as they remain ascertainable, meaning a shifting low water mark carries the right with it, but newly joined sandbanks fall outside it."}, {"url": "https://hklandlaw.wordpress.com/2019/09/02/priority-as-between-unwritten-equitable-interest-and-lender-supplying-funds-to-re-mortgage/", "title": "Priority as between unwritten equitable interest and lender supplying funds to re-mortgage", "date": "2019-09-02", "type": "case-note", "topics": ["priority", "equitable-interests", "imputed-intention", "re-mortgage", "secured-lending"], "cases": [{"name": "Bristol & West Building Society v Henning", "citation": "[1985] 1 WLR 778", "court": null, "jurisdiction": "EN"}, {"name": "Abbey National Building Society v Cann", "citation": "[1991] 1 AC 56", "court": "HL", "jurisdiction": "EN"}, {"name": "Equity & Law Home Loans Limited v Prestidge", "citation": "[1992] 1 FCR 353", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Someone contributing to the price gets an interest, but is taken to have accepted that the purchase lender ranks ahead. That imputed acceptance carries over to a replacement charge redeeming the first, capped at the sum originally secured. The reasoning suits Hong Kong."}, {"url": "https://hklandlaw.wordpress.com/2019/08/17/tinsley-v-milligan-still-applies-in-hong-kong/", "title": "Tinsley v Milligan still applies in Hong Kong", "date": "2019-08-17", "type": "case-note", "topics": ["illegality", "resulting-trust", "reliance-principle", "ding-rights", "voluntary-transfer"], "cases": [{"name": "Tinsley v Milligan", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Patel v Mirza", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Tang Teng Tso v Cheung Tin Wah", "citation": "[2014] HKCFI 680", "court": "CFI", "jurisdiction": "HK"}, {"name": "Kwan Hung Shing v Fong Kwok Shan", "citation": "[2019] HKCFI 1687", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "London has moved to a policy-weighing approach, but Hong Kong keeps the older reliance test. A transferor who gave land away for nothing under an unlawful village development scheme recovered it through a resulting trust without pleading the wrongdoing."}, {"url": "https://hklandlaw.wordpress.com/2019/07/16/pipikos-v-trayans-part-performance-and-the-unequivocal-referability-test/", "title": "Pipikos v Trayans: part performance and the unequivocal referability test", "date": "2019-07-16", "type": "case-note", "topics": ["part-performance", "formalities", "sale-of-land", "unequivocal-referability", "specific-performance"], "cases": [{"name": "Maddison v Alderson", "citation": "(1883) 8 App Cas 467", "court": "HL", "jurisdiction": "EN"}, {"name": "Steadman v Steadman", "citation": "[1976] AC 536", "court": "HL", "jurisdiction": "EN"}, {"name": "Pipikos v Trayans", "citation": "[2018] HCA 39", "court": "other", "jurisdiction": "AU"}], "statutes": ["Law of Property Act (South Australia) s.26", "Conveyancing and Property Ordinance s.3(1)"], "summary": "Australia keeps the demanding rule that the acts relied on must point of their own nature to a land bargain, declining the looser probability approach. Paying arrears, contributing to a deposit and lodging a caveat did not qualify."}, {"url": "https://hklandlaw.wordpress.com/2019/06/22/fundamental-importance-of-the-right-to-apply-for-relief-from-forfeiture-golding-v-martin/", "title": "Fundamental importance of the right to apply for relief from forfeiture: Golding v Martin", "date": "2019-06-21", "type": "case-note", "topics": ["relief-from-forfeiture", "forfeiture", "rent-arrears", "leases", "statutory-safeguards"], "cases": [{"name": "Golding v Martin", "citation": "[2019] EWCA Civ 446", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Pittalis v Grant", "citation": "[1989] QB 605", "court": "other", "jurisdiction": "EN"}], "statutes": ["County Courts Act 1984 s.138(3)"], "summary": "Possession orders for arrears must give at least four weeks to pay and cannot be unconditional. Parliament cannot have meant so important a protection to be sidestepped where a valuable lease is at stake; any other reading would be irrational."}, {"url": "https://hklandlaw.wordpress.com/2019/06/13/forfeiture-is-immoral-user-by-a-sub-tenant-always-an-irremediable-breach-of-a-head-lease-covenant/", "title": "Forfeiture: is immoral user by a sub-tenant always an irremediable breach of a head-lease covenant?", "date": "2019-06-13", "type": "case-note", "topics": ["forfeiture", "irremediable-breach", "immoral-user", "sub-tenancy", "relief-from-forfeiture"], "cases": [{"name": "Patel v K&J Restaurants Ltd", "citation": "[2010] EWCA Civ 1211", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Rugby School (Governors) v Tannahill", "citation": "[1935] 1 KB 87", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Glass v Kencakes Ltd", "citation": "[1966] 1 QB 611", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Ropemaker Properties Ltd v Noonhaven Ltd", "citation": "[1989] 2 EGLR 50", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.58", "Law of Property Act 1925 s.146"], "summary": "A head tenant answers for a subtenant's disreputable use only once he knows or has grounds to suspect and then fails to act. Such breaches are not automatically beyond cure, and relief remains possible where no lasting taint attaches to the premises."}, {"url": "https://hklandlaw.wordpress.com/2019/06/08/habberfield-v-habberfield/", "title": "Habberfield v Habberfield", "date": "2019-06-08", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "proportionality", "expectation-relief", "family-property"], "cases": [{"name": "Habberfield v Habberfield", "citation": "[2019] EWCA Civ 890", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A daughter assured of the family farm won in proprietary estoppel; the Court of Appeal favoured relief reflecting her expectation over her smaller quantified detriment, viewing near-contractual assurances as points on a continuum, and upheld a sum letting her buy an equivalent farm despite the mother's hardship."}, {"url": "https://hklandlaw.wordpress.com/2019/04/26/estoppel-where-the-family-home-is-owned-by-a-company/", "title": "Estoppel where the family home is owned by a company", "date": "2019-04-26", "type": "overview", "topics": ["promissory-estoppel", "proprietary-estoppel", "piercing-the-corporate-veil", "family-home", "satisfying-the-equity", "just-and-equitable-winding-up"], "cases": [{"name": "Prest v Petrodel Resources Ltd", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Luo Xing Juan v Hui Shui See", "citation": null, "court": "CFA", "jurisdiction": "HK"}, {"name": "Maharaj v Chand", "citation": null, "court": null, "jurisdiction": null}, {"name": "Crabb v Arun District Council", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Pascoe v Turner", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Gillett v Holt", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Campbell v Griffin", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jennings v Rice", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Coombe v Coombe", "citation": null, "court": null, "jurisdiction": null}, {"name": "Hong Kong Hua Qiao Co Ltd v Cham Ka Tai", "citation": null, "court": "CFI", "jurisdiction": "HK"}, {"name": "Chan Sung Lai v Chan Sung Lim Paul", "citation": null, "court": "CFI", "jurisdiction": "HK"}, {"name": "Thorner v Major", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Matrimonial Causes Act s.24"], "summary": "When the home sits in a company, the veil rarely yields and a trust must usually be inferred instead. An estoppel may bind the controlling shareholder in how he votes, with winding up on just and equitable grounds as a possible route to relief."}, {"url": "https://hklandlaw.wordpress.com/2019/04/23/frustration-of-leases-brexit-and-illegality/", "title": "Frustration of leases: Brexit and illegality", "date": "2019-04-23", "type": "case-note", "topics": ["frustration", "leases", "supervening-illegality", "self-induced-frustration", "brexit"], "cases": [{"name": "Canary Wharf (BP4) T1 Ltd v European Medicines Agency", "citation": "[2019] EWHC 335", "court": "other", "jurisdiction": "EN"}, {"name": "London and Northern Estates Company v Schlesinger", "citation": "[1916] 1 KB 20", "court": "other", "jurisdiction": "EN"}], "statutes": ["Withdrawal Agreement art.119"], "summary": "Illegality discharges a bargain only by stripping away substantially the whole benefit, and a prohibition under another country's law does not touch an English contract. The tenant agency lost because the constraints it invoked flowed from choices it could have avoided."}, {"url": "https://hklandlaw.wordpress.com/2019/03/31/brexit-and-the-doctrine-of-frustration/", "title": "Brexit and the doctrine of frustration", "date": "2019-03-31", "type": "case-note", "topics": ["frustration", "leases", "supervening-illegality", "self-induced-frustration", "radical-change", "brexit"], "cases": [{"name": "Canary Wharf (BP4) T1 Ltd v European Medicines Agency", "citation": "[2019] EWHC 335", "court": "other", "jurisdiction": "EN"}, {"name": "Davis Contractors v Fareham UDC", "citation": "[1956] UKHL 3", "court": "HL", "jurisdiction": "EN"}, {"name": "National Carriers v Panalpina", "citation": "[1980] UKHL 8", "court": "HL", "jurisdiction": "EN"}, {"name": "Edwinton Commercial Corporation v Tsavliris Russ (Worldwide Salvage & Towage) Ltd (The 'Sea Angel')", "citation": "[2007] EWCA Civ 547", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Krell v Henry", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Patel v Mirza", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "The Super Servant Two", "citation": "[1989] EWCA Civ 6", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Discharge requires performance to become radically different from what was bargained for, judged by weighing the terms, the setting and shared expectations. Foreign prohibitions rarely count unless they strike the place of performance, and nothing within a party's own control will do."}, {"url": "https://hklandlaw.wordpress.com/2019/02/22/regency-villas-the-validity-of-a-recreational-easement/", "title": "Regency Villas: the validity of a recreational easement", "date": "2019-02-22", "type": "case-note", "topics": ["easements", "recreational-easement", "accommodation", "ouster-principle", "positive-obligations"], "cases": [{"name": "Regency Villas Title Ltd v Diamond Resorts (Europe) Ltd", "citation": "[2018] UKSC 57", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Re Ellenborough Park", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Moncrieff v Jamieson", "citation": null, "court": "HL", "jurisdiction": "other"}], "statutes": [], "summary": "Rights to use a golf course, pool and courts can be easements where the benefited land is itself holiday accommodation. The burdened owner need only stay passive, never maintain; if he lets facilities decay the neighbours may enter and do it themselves."}, {"url": "https://hklandlaw.wordpress.com/2019/02/07/right-of-way-and-lost-modern-grant/", "title": "Right of way and lost modern grant", "date": "2019-02-07", "type": "case-note", "topics": ["easements", "prescription", "lost-modern-grant", "right-of-way", "nec-precario"], "cases": [{"name": "Yik Wai Pong v Yick Pak Kin", "citation": "[2019] HKCFI 21", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Twenty years of use without force, secrecy or permission yields a way. Handing over a key looked like permission, and family tolerance supplied it implicitly, so only the years after 2002 counted and the claim fell short."}, {"url": "https://hklandlaw.wordpress.com/2019/01/12/satisfying-the-equity-in-proprietary-estoppel/", "title": "Satisfying the equity in proprietary estoppel", "date": "2019-01-11", "type": "case-note", "topics": ["proprietary-estoppel", "satisfying-the-equity", "expectation-and-detriment", "remedies", "clean-break"], "cases": [{"name": "Moore v Moore", "citation": "[2018] EWCA Civ 2669", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Davies v Davies", "citation": "[2016] EWCA Civ 463", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jennings v Rice", "citation": "[2002] EWCA Civ 159", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Crabb v Arun District Council", "citation": "[1976] Ch 179", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Relief is fixed looking back from when the promise fell due, tending towards the expectation where the assurance resembled a bargain. Family breakdown, tax and rival claims all bear on it; an immediate transfer gave way to a generous lump sum."}, {"url": "https://hklandlaw.wordpress.com/2018/12/10/misrepresentation-misleading-descriptions-of-a-flat/", "title": "Misrepresentation: misleading descriptions of a flat", "date": "2018-12-10", "type": "case-note", "topics": ["misrepresentation", "rescission", "sale-of-land", "ostensible-authority", "reliance", "damages"], "cases": [{"name": "Joytex Development Ltd v Super Homes Ltd", "citation": "[2018] HKCFI 2286", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Several individually hazy statements about a flat added up to an actionable falsehood, and small-print qualifications did not cure them. An agent within apparent authority bound the seller; a buyer who could have checked the papers still relied. Rescission with interest followed."}, {"url": "https://hklandlaw.wordpress.com/2018/11/18/family-home-legally-owned-by-company-controlled-by-one-of-the-spouses/", "title": "Family home legally owned by company controlled by one of the spouses", "date": "2018-11-18", "type": "case-note", "topics": ["piercing-the-corporate-veil", "resulting-trust", "family-home", "matrimonial-property", "beneficial-ownership"], "cases": [{"name": "Prest v Petrodel Resources Ltd", "citation": "[2013] UKSC 34", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Matrimonial Proceedings and Property Ordinance s.6"], "summary": "Matrimonial jurisdiction confers no special power over corporate assets. Either the company holds on trust for the spouse, which a matrimonial home often invites the court to infer, or the veil is lifted where a company was interposed to dodge an existing obligation."}, {"url": "https://hklandlaw.wordpress.com/2018/10/18/does-the-voice-of-the-trustee-in-bankruptcy-of-one-co-owner-carry-greater-weight-when-considering-an-order-for-sale/", "title": "Does the voice of the trustee in bankruptcy of one co-owner carry greater weight when considering an order for sale?", "date": "2018-10-18", "type": "case-note", "topics": ["order-for-sale", "co-ownership", "bankruptcy", "severance", "hardship"], "cases": [{"name": "Lo Yau Shing (a bankrupt)", "citation": "[2018] HKCFI 1574", "court": "CFI", "jurisdiction": "HK"}, {"name": "Re Dennis", "citation": null, "court": null, "jurisdiction": null}, {"name": "Wong Chun Kei v Poon Vai Ching", "citation": null, "court": null, "jurisdiction": null}, {"name": "Re Bremner", "citation": null, "court": null, "jurisdiction": null}, {"name": "Everitt v Budhram", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Bankruptcy Ordinance s.60", "Partition Ordinance s.6"], "summary": "Sale is the norm unless it benefits nobody or inflicts very great hardship, which the objector must prove. A trustee in bankruptcy speaks with no louder voice than the other co-owner, and bankruptcy severs a joint tenancy."}, {"url": "https://hklandlaw.wordpress.com/2018/09/16/no-presumption-of-advancement-between-siblings/", "title": "No presumption of advancement between siblings", "date": "2018-09-16", "type": "case-note", "topics": ["resulting-trust", "presumption-of-advancement", "joint-names", "beneficial-ownership", "intention"], "cases": [{"name": "Lee Yee Yan Eva v Lee Tak Gate Richard", "citation": "[2018] HKCFI 1137", "court": "CFI", "jurisdiction": "HK"}, {"name": "Westdeutsche Landesbank Girozentrale v Islington London Borough Council", "citation": "[1996] AC 669", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Paying for property put into joint names raises a rebuttable presumption against any gift, and nothing about a brother-sister relationship reverses it. Evidence showed the sister meant to keep the whole beneficial interest, so conveyance to her was ordered."}, {"url": "https://hklandlaw.wordpress.com/2018/08/18/waiver-mandatory-injunctions-and-building-schemes/", "title": "Waiver, mandatory injunctions and building schemes", "date": "2018-08-18", "type": "case-note", "topics": ["waiver", "acquiescence", "building-scheme", "restrictive-covenants", "mandatory-injunction"], "cases": [{"name": "Singh v Rainbow Court Townhouses Ltd", "citation": "[2018] UKPC 19", "court": "UKPC", "jurisdiction": "other"}, {"name": "Chatsworth Estates Co v Fewell", "citation": "[1931] 1 Ch 224", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "The question is whether the enforcing body's acts and omissions signalled that the covenants were dead letters. Silence while uninformed about works is not waiver, though before compelling demolition a court should ask how comparable alterations elsewhere were treated."}, {"url": "https://hklandlaw.wordpress.com/2018/07/14/no-oral-modification-clauses-rock-advertising-v-mwb-business-exchanges-ltd-part-2/", "title": "No oral modification clauses: Rock Advertising v MWB Business Exchanges Ltd (Part 2)", "date": "2018-07-14", "type": "case-note", "topics": ["no-oral-modification", "contractual-variation", "estoppel", "freedom-of-contract", "formalities"], "cases": [{"name": "Rock Advertising Ltd v MWB Business Exchanges Ltd", "citation": "[2018] UKSC 24", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Beatty v Guggenheim Exploration Co", "citation": "(1919) 225 NY 380", "court": "other", "jurisdiction": "other"}, {"name": "Actionstrength Ltd v International Glass Engineering In Gl En SpA", "citation": "[2003] 2 AC 51", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "The majority gives such clauses full effect, citing protection against invented variations, evidential certainty and internal authority controls. The minority would let parties escape them, but only on clear signs of deliberate departure, such as genuine urgency. Estoppel needs something unequivocal beyond the promise."}, {"url": "https://hklandlaw.wordpress.com/2018/06/15/no-oral-modification-clauses-rock-advertising-v-mwb-business-exchanges-ltd-part-1/", "title": "'No oral modification' clauses: Rock Advertising v MWB Business Exchanges Ltd (Part 1)", "date": "2018-06-15", "type": "case-note", "topics": ["no-oral-modification", "contractual-variation", "consideration", "estoppel", "entire-agreement-clause"], "cases": [{"name": "Rock Advertising Ltd v MWB Business Exchange Centres Ltd", "citation": "[2018] UKSC 24", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Foakes v Beer", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Formality requirements for variations hold good on their terms where the spoken deal alters the contract itself, though a genuinely separate collateral bargain with its own consideration may survive. Departure is not inferred from simply agreeing orally without mentioning the clause."}, {"url": "https://hklandlaw.wordpress.com/2018/05/14/receipt-clauses-and-contractual-estoppel/", "title": "Receipt clauses and contractual estoppel", "date": "2018-05-14", "type": "case-note", "topics": ["contractual-estoppel", "estoppel-by-convention", "receipt-clause", "conveyancing", "purchase-price"], "cases": [{"name": "Asgain Co Ltd v Cheng Ka Yam", "citation": "[2018] HKEC 889", "court": "CA", "jurisdiction": "HK"}, {"name": "Ming Shiu Chung v Ming Shiu Sum", "citation": "(2006) 9 HKCFAR 334", "court": "CFA", "jurisdiction": "HK"}, {"name": "Prime Sight Ltd v Lavarello", "citation": "[2014] AC 436", "court": "PC", "jurisdiction": "other"}, {"name": "Grundt v Great Boulder Proprietary Gold Mines Ltd", "citation": "(1937) 59 CLR 641", "court": "other", "jurisdiction": "AU"}], "statutes": ["Conveyancing and Property Ordinance s.18(1)"], "summary": "An acknowledgement of payment in a deed binds at law but yields to contrary proof in equity. Parties adopting a shared factual assumption for their transaction are held to it without reliance, yet part payments can cancel that estoppel and revive the vendor's claim."}, {"url": "https://hklandlaw.wordpress.com/2018/04/21/does-acceptance-of-an-obligation-to-fence-off-access-to-an-easement-amount-to-abandonment/", "title": "Does acceptance of an obligation to fence off access to an easement amount to abandonment?", "date": "2018-04-21", "type": "case-note", "topics": ["easements", "abandonment", "non-user", "positive-covenants", "dominant-tenement"], "cases": [{"name": "Annetts v Adeleye", "citation": "[2018] EWCA Civ 555", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Dwyer v Westminster CC", "citation": "[2014] 2 P & CR 7", "court": null, "jurisdiction": "EN"}, {"name": "Dyer", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "Giving up a right of way is judged objectively and presumed against, since owners seldom discard assets for nothing. Agreeing to fence, and years of disuse, fell short of showing a settled resolve that no successor would ever use the way."}, {"url": "https://hklandlaw.wordpress.com/2018/03/02/seminar-promissory-estoppel-as-a-cause-of-action-luo-xing-juan-v-estate-of-hui-shui-see/", "title": "Seminar: Promissory estoppel as a cause of action? Luo Xing Juan v Estate of Hui Shui See", "date": "2018-03-02", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "CUHK seminar asking whether promissory estoppel founds an independent claim."}, {"url": "https://hklandlaw.wordpress.com/2018/02/24/whitlock-v-moree-clauses-declaring-that-a-joint-bank-account-is-held-under-a-joint-tenancy/", "title": "Whitlock v Moree: clauses declaring that a joint bank account is held under a joint tenancy", "date": "2018-02-24", "type": "case-note", "topics": ["joint-bank-accounts", "joint-tenancy", "survivorship", "resulting-trusts", "contractual-interpretation"], "cases": [{"name": "Whitlock v Moree", "citation": "[2017] UKPC 44", "court": "UKPC", "jurisdiction": "other"}, {"name": "Niles v Lake", "citation": "[1947] SCR 294", "court": "other", "jurisdiction": "other"}, {"name": "Stack v Dowden", "citation": "[2007] UKHL 17", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Note on the Privy Council's majority holding that a signed account-opening clause declaring joint tenancy settles beneficial as well as legal title, excluding presumed resulting trusts: the clause is read as an ordinary bank customer would, extending Stack's rule that express declarations are usually conclusive."}, {"url": "https://hklandlaw.wordpress.com/2018/01/24/proprietary-estoppel-australian-take-on-proving-detrimental-reliance-in-relationship-cases/", "title": "Proprietary estoppel: Australian take on proving detrimental reliance in relationship cases", "date": "2018-01-24", "type": "case-note", "topics": ["proprietary-estoppel", "detrimental-reliance", "burden-of-proof", "unconscionability", "satisfying-the-equity"], "cases": [{"name": "Sidhu v Van Dyke", "citation": "[2014] HCA 19", "court": "other", "jurisdiction": "AU"}, {"name": "Van Dyke v Sidhu", "citation": "(2013) 301 ALR 769", "court": "other", "jurisdiction": "AU"}, {"name": "Greasley v Cooke", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Amalgamated Investment & Property Co Ltd (In Liq) v Texas Commerce International Bank Ltd", "citation": "[1982] QB 84", "court": "other", "jurisdiction": "EN"}, {"name": "Steria Ltd v Hutchison", "citation": "[2007] ICR 448", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Donis v Donis", "citation": "(2007) 19 VR 577", "court": "other", "jurisdiction": "AU"}, {"name": "Jorden v Money", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Reliance must be established as a fact by the claimant, never assumed from thin evidence, though the promise need only be a significant contributing cause. Where someone reshapes her life irreversibly, relief should measure up to what was promised."}, {"url": "https://hklandlaw.wordpress.com/2018/01/14/proprietary-estoppel-in-relationship-cases-assurance-or-not/", "title": "Proprietary estoppel in relationship cases: assurance or not?", "date": "2018-01-13", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "detrimental-reliance", "common-intention-constructive-trust", "unjust-enrichment"], "cases": [{"name": "Cook v Thomas", "citation": "[2010] EWCA Civ 227", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Greasley v Cooke", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Thorner v Major", "citation": "[2009] UKHL 18", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Loose talk about everything passing on death signals present intention, not commitment, so nothing bound the owner. A gap in time weakened any link to the claimant's later work, and the reliance presumption yields once the facts are fully explored."}, {"url": "https://hklandlaw.wordpress.com/2018/01/03/proprietary-estoppel-and-co-habitees-assurance-must-relate-to-a-specific-property/", "title": "Proprietary estoppel and co-habitees: assurance must relate to a specific property", "date": "2018-01-03", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "specific-property", "detriment", "co-habitation"], "cases": [{"name": "Lissimore v Downing", "citation": "[2003] EWHC B1 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "The promise must attach to identified land or to everything the promisor owns; vague talk of being provided for will not do. Years of living together generate no entitlement by themselves, and detriment is weighed against the benefits enjoyed."}, {"url": "https://hklandlaw.wordpress.com/2017/12/19/compensation-for-land-resumption-valuation-where-a-restriction-on-use-has-been-abandoned/", "title": "Compensation for land resumption: valuation where a restriction on use has been abandoned", "date": "2017-12-18", "type": "case-note", "topics": ["land-resumption", "compulsory-purchase-compensation", "user-covenant", "abandonment", "valuation"], "cases": [{"name": "Cheermark Investment Ltd v Director of Lands", "citation": "[2017] HKEC 2536", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Lands Resumption Ordinance s.12", "Basic Law art.105"], "summary": "Where Government tolerated open shop use for years despite a narrower user covenant, the Tribunal could find the restriction abandoned. Equivalence requires compensation reflecting that surrender of enforcement, notwithstanding the statutory wording tying value to lease-compliant use."}, {"url": "https://hklandlaw.wordpress.com/2017/12/15/cuhk-property-law-seminar-professor-steven-gallagher-january-2018/", "title": "CUHK Property Law Seminar - Professor Steven Gallagher - January 2018", "date": "2017-12-15", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "CUHK seminar by Professor Steven Gallagher on gifts, trusts, presumptions."}, {"url": "https://hklandlaw.wordpress.com/2017/12/02/recovering-property-transferred-pursuant-to-an-agreement-tainted-with-illegality-patel-v-mirza-in-hong-kong/", "title": "Recovering property transferred pursuant to an agreement tainted with illegality: Patel v Mirza in Hong Kong", "date": "2017-12-02", "type": "case-note", "topics": ["illegality", "unjust-enrichment", "restitution", "public-policy", "proportionality"], "cases": [{"name": "Chung Tin Pui v Li Pak Sau", "citation": "[2017] HKEC 2103", "court": "CFI", "jurisdiction": "HK"}, {"name": "Patel v Mirza", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "A transferor may reclaim property passed under an unlawful arrangement once unjust enrichment is made out. The court now weighs the purpose of the prohibition, competing policies and proportionality, rather than asking whether performance occurred or the claimant knew."}, {"url": "https://hklandlaw.wordpress.com/2017/11/22/owners-liability-for-management-charges-need-for-adequate-legal-basis-and-proper-procedure/", "title": "Owner's liability for management charges - need for adequate legal basis and proper procedure", "date": "2017-11-22", "type": "case-note", "topics": ["building-management", "management-charges", "incorporated-owners", "deed-of-mutual-covenant", "contingency-fund"], "cases": [{"name": "San Po Kong Mansion (IO) v On Rich (HK) Investment Ltd", "citation": "[2017] HKEC 2321", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.20", "Building Management Ordinance s.21", "Building Management Ordinance s.22"], "summary": "Incorporated owners recovering charges must show valid meeting procedure, authority in the covenant, and a statutory head of expenditure. Contingency funding covers only outlays the body was empowered to make, so unauthorised indemnity commitments bind nobody."}, {"url": "https://hklandlaw.wordpress.com/2017/11/13/each-owner-potentially-liable-for-owners-corporations-entire-indebtedness/", "title": "Each owner potentially liable for owners' corporation's entire indebtedness", "date": "2017-11-13", "type": "case-note", "topics": ["building-management", "incorporated-owners", "joint-and-several-liability", "winding-up", "contribution"], "cases": [{"name": "Wong Tak Man Stephen v Chang Ching Wai", "citation": "[2017] HKEC 2266", "court": "CFI", "jurisdiction": "HK"}, {"name": "Chi Kit Co Ltd v Lucky Health International Enterprise Ltd", "citation": "[2000] 2 HKLRD 503", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.34", "Building Management Ordinance s.17(1)", "Building Management Ordinance s.33"], "summary": "On a winding up of incorporated owners, any single owner can be pursued for the whole debt. Wording about respective shares governs contribution between owners, not the ceiling of each one's exposure, sparing creditors delay and risk."}, {"url": "https://hklandlaw.wordpress.com/2017/11/04/family-home-in-joint-names-and-wifes-failure-to-transfer-her-interest-to-her-husband-in-accordance-with-a-consent-order/", "title": "Family home in joint names and wife's failure to transfer her interest to her husband in accordance with a consent order", "date": "2017-11-04", "type": "case-note", "topics": ["undue-influence", "beneficial-ownership", "consent-order", "family-home", "joint-names"], "cases": [{"name": "Chu Tsan Leung v Leung Mee Ling Amy", "citation": "[2017] HKEC 2347", "court": "CFI", "jurisdiction": "HK"}, {"name": "Bank of China (Hong Kong) Ltd v Fung Chin Kan", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Ming Shiu Chung v Ming Shiu Sum", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "No presumption of undue influence arose from the wife signing away her share; signing binds even an imperfect understanding. Sole beneficial ownership passed to the husband at decree absolute despite no assignment ever being executed."}, {"url": "https://hklandlaw.wordpress.com/2017/10/23/no-waiver-where-landlord-accepts-rent-after-commencing-possession-proceedings/", "title": "No waiver where landlord accepts rent after commencing possession proceedings", "date": "2017-10-22", "type": "case-note", "topics": ["waiver", "forfeiture", "election", "possession-proceedings", "leases"], "cases": [{"name": "Evans v Enever", "citation": "[1920] 2 KB 315", "court": "other", "jurisdiction": "EN"}], "statutes": ["Common Law Procedure Act s.212"], "summary": "Issuing possession proceedings is an irrevocable election ending the lease, so rent taken afterwards cannot revive it. Settling the arrears claim did not waive the separate forfeiture ground arising from the tenant's bankruptcy."}, {"url": "https://hklandlaw.wordpress.com/2017/10/16/gift-or-trust-proving-the-relevant-intention/", "title": "Gift or trust: proving the relevant intention", "date": "2017-10-15", "type": "case-note", "topics": ["resulting-trust", "presumption-of-advancement", "gift", "intention", "evidence"], "cases": [{"name": "Leung Wing Yi Asther v Kwok Yu Wah", "citation": "(2015) 18 HKCFAR 605", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "What counts is the transferor's actual intention, inferred objectively from words and conduct. Presumptions of resulting trust or advancement operate only in an evidential vacuum, and dealings around the transfer outweigh anything done long afterwards."}, {"url": "https://hklandlaw.wordpress.com/2017/10/08/the-equity-of-exoneration-tenant-in-common-charging-her-share-to-protect-property-from-partners-creditor/", "title": "The equity of exoneration: tenant in common charging her share to protect property from partner's creditor", "date": "2017-10-07", "type": "case-note", "topics": ["equity-of-exoneration", "tenancy-in-common", "suretyship", "beneficial-ownership", "secured-creditors"], "cases": [{"name": "Insol Funding Company Limited v Cowlam", "citation": "[2017] EWHC 1822 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Charging your own share for someone else's debt can generate a proprietary and personal right of indemnity. It failed here because the co-owner settled on her own account as a volunteer, with no intention of standing as surety."}, {"url": "https://hklandlaw.wordpress.com/2017/10/06/seminar-about-proprietary-estoppel-and-the-family-home-at-cuhk-faculty-of-law/", "title": "Seminar about proprietary estoppel and the family home at CUHK Faculty of Law", "date": "2017-10-06", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "CUHK seminar on proprietary estoppel, assurance, detriment, family home claims."}, {"url": "https://hklandlaw.wordpress.com/2017/10/01/equitable-subrogation-one-co-habitee-charging-interest-to-secured-creditor-of-her-partner/", "title": "Equitable subrogation: one co-habitee charging interest to secured creditor of her partner", "date": "2017-10-01", "type": "case-note", "topics": ["equitable-subrogation", "unjust-enrichment", "secured-lending", "co-habitation", "suretyship"], "cases": [{"name": "Insol Funding Company Limited v Cowlam", "citation": "[2017] EWHC 1822 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Subrogation serves sureties who discharge another's debt, or lenders whose expected security misfires. Neither fitted a partner who simply promised her own money under a binding bargain, so the creditor kept its security and gained nothing unjustly."}, {"url": "https://hklandlaw.wordpress.com/2017/09/24/variation-of-an-express-trust-or-a-common-intention-constructive-trust/", "title": "Variation of an express trust or a common intention constructive trust", "date": "2017-09-24", "type": "case-note", "topics": ["common-intention-constructive-trust", "express-trust", "detrimental-reliance", "formalities", "beneficial-joint-tenancy"], "cases": [{"name": "Insol Funding Company Ltd v Cowlam", "citation": "[2017] EWHC 1822 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.53(1)(b)", "Conveyancing and Property Ordinance s.5(1)(b)"], "summary": "An initial equal joint tenancy gave way to a later agreed 80/20 split, shown by the co-owner shouldering the mortgage alone. Shifting shares this way needs fresh common intention plus detrimental reliance where writing formalities went unmet."}, {"url": "https://hklandlaw.wordpress.com/2017/09/17/adverse-possession-the-slightest-act-of-the-paper-owner-sufficient-to-retain-possession/", "title": "Adverse possession: the slightest act of the paper owner sufficient to retain possession", "date": "2017-09-17", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "discontinuance", "paper-owner", "common-parts"], "cases": [{"name": "Tierra Trading Ltd v Land Base Ltd", "citation": "[2017] HKEC 1809", "court": "CFI", "jurisdiction": "HK"}, {"name": "Powell v McFarlane", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Barely anything is needed to show a paper owner never abandoned possession. Counting the disputed landings and staircases within the development's gross floor area was itself enough, so the occupiers could not make out factual possession."}, {"url": "https://hklandlaw.wordpress.com/2017/09/10/objective-nature-of-the-intention-to-possess-where-the-squatter-believed-itself-to-be-the-true-owner/", "title": "Objective nature of the intention to possess: where the squatter believed itself to be the true owner", "date": "2017-09-10", "type": "case-note", "topics": ["adverse-possession", "intention-to-possess", "animus-possidendi", "mistake", "government-land"], "cases": [{"name": "Pang Yiu Chor v Wong Wai Leung", "citation": "[2017] HKEC 1874", "court": null, "jurisdiction": "HK"}, {"name": "Tsang Foo Keung v Chu Jim Mi Jimmy", "citation": "CACV 178/2015", "court": "CA", "jurisdiction": "HK"}, {"name": "Cheung Kwong Yuen v Sun Hai Fang", "citation": "[2016] 1 HKLRD 464", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Thinking oneself the true owner is no obstacle: the required intention is simply to exclude everyone else so far as practicable, judged from what the occupier did with land of that character rather than from professed beliefs."}, {"url": "https://hklandlaw.wordpress.com/2017/09/05/adverse-possession-intention-to-possess-when-squatter-was-a-licensee/", "title": "Adverse possession: intention to possess when squatter was a licensee", "date": "2017-09-05", "type": "case-note", "topics": ["adverse-possession", "intention-to-possess", "licence", "limitation", "superior-title"], "cases": [{"name": "Jin Yu Chia v Personal Representatives of Lee Ah Hsin", "citation": "[2017] HKEC 1829", "court": null, "jurisdiction": "HK"}, {"name": "Wong Tak Yue v Kung Kwok Wai", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "An occupier who concedes he would have paid rent on demand lacks the required intention. Someone who entered lawfully must show a genuine change of mind, denying any superior title at all, which is notoriously hard to establish."}, {"url": "https://hklandlaw.wordpress.com/2017/08/27/equitable-ownership-single-framework-for-domestic-consumer-and-investment-cases/", "title": "Equitable ownership: single framework for 'domestic consumer' and 'investment' cases", "date": "2017-08-26", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "beneficial-ownership", "presumptions", "investment-property"], "cases": [{"name": "Marr v Collie", "citation": "[2017] UKPC 17", "court": "UKPC", "jurisdiction": "other"}, {"name": "Muschinski", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "One method now covers both homes and investments. Start from the title, put the burden on whoever disputes it, and reach for the contribution presumption only when unequal payments are the sole evidence; otherwise the whole course of dealing governs."}, {"url": "https://hklandlaw.wordpress.com/2017/08/17/compelling-evidence-of-post-acquisition-variation-of-common-intention/", "title": "Compelling evidence of post-acquisition variation of common intention", "date": "2017-08-17", "type": "case-note", "topics": ["common-intention-constructive-trust", "post-acquisition-variation", "tenancy-in-common", "beneficial-shares", "family-property"], "cases": [{"name": "Chan Ling Ling v Chan Ching Kit", "citation": "[2017] HKEC 1474", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Four siblings started with equal beneficial shares and stayed there. A sibling who met most mortgage instalments could not claim eighty percent: changing an agreed split after purchase demands compelling proof, and conduct alone rarely supports the inference."}, {"url": "https://hklandlaw.wordpress.com/2017/08/02/equitable-ownership-of-the-family-home-interaction-of-the-common-intention-constructive-trust-and-the-presumed-resulting-trust/", "title": "Equitable ownership of the family home: interaction of the common intention constructive trust and the presumed resulting trust", "date": "2017-08-02", "type": "case-note", "topics": ["common-intention-constructive-trust", "presumed-resulting-trust", "family-home", "charging-order", "severance"], "cases": [{"name": "Primecredit Ltd v Yeung Chun Pang Barry", "citation": "[2017] HKEC 1533", "court": "CA", "jurisdiction": "HK"}, {"name": "Stack v Dowden", "citation": "[2007] 2 AC 432", "court": null, "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": "[2012] 1 AC 776", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Mo Ying v Brillex Development Ltd", "citation": "[2015] 2 HKLRD 985", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A spouse's equitable share may rest either on inferred common intention drawn from the whole background, or on the contribution-based presumption as a fallback. The judgment leaves open whether a charging order works an equitable severance of a joint tenancy."}, {"url": "https://hklandlaw.wordpress.com/2017/07/25/settlement-induced-by-misrepresentation-that-one-of-the-parties-had-title-to-land-as-bona-fide-purchaser-for-value/", "title": "Settlement induced by misrepresentation that one of the parties had title to land as bona fide purchaser for value", "date": "2017-07-25", "type": "case-note", "topics": ["misrepresentation", "rescission", "resulting-trust", "sham-transactions", "limitation", "ding-rights"], "cases": [{"name": "Howin Industrial Ltd v China Group Global Ltd", "citation": "[2017] HKEC 1485", "court": "CFI", "jurisdiction": "HK"}, {"name": "Zurich Insurance Co plc v Hayward", "citation": "[2016] 3 WLR 637", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance s.26(1)"], "summary": "A settlement deed fell away because a false claim to purchaser status had influenced the party into signing. Unregistered trust declarations still bind, transfers without consideration throw up a resulting trust, and concealment postpones time running."}, {"url": "https://hklandlaw.wordpress.com/2017/07/17/easements-of-necessity/", "title": "Easements of necessity", "date": "2017-07-17", "type": "case-note", "topics": ["easements", "easement-of-necessity", "implied-grant", "access", "unity-of-ownership"], "cases": [{"name": "Manjang v Drammeh", "citation": "(1990) 61 P & CR 194", "court": "PC", "jurisdiction": "other"}], "statutes": [], "summary": "Three things must coincide: one owner held both plots when they were split, the disputed route is the only way to the highway, and no express right was granted. Mere convenience never generates such an easement."}, {"url": "https://hklandlaw.wordpress.com/2017/07/14/car-parking-spaces-common-parts/", "title": "Car parking spaces: common parts?", "date": "2017-07-14", "type": "case-note", "topics": ["common-parts", "deed-of-mutual-covenant", "car-parking", "estoppel-by-convention", "contractual-interpretation", "government-grant"], "cases": [{"name": "Tai Fat Development (Holding) Co Ltd v Gold King Industrial Building (IO)", "citation": "[2017] HKEC 1366", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Reading the covenant against the grant and surrounding documents, thirteen bays described as loading areas belonged to everyone, not the first owner. That reading also kept the grant intact. The convention argument collapsed for want of shared understanding or detriment."}, {"url": "https://hklandlaw.wordpress.com/2017/07/03/repairing-covenant-and-the-removal-of-a-handrail-from-a-staircase/", "title": "Repairing covenant and the removal of a handrail from a staircase", "date": "2017-07-03", "type": "case-note", "topics": ["repairing-covenant", "disrepair", "leases", "defective-premises", "alterations"], "cases": [{"name": "Dodd v Raebarn Estates Ltd", "citation": "[2017] EWCA Civ 439", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Defective Premises Act 1972 s.4(4)"], "summary": "Repairing obligations bite only on deterioration, and never require making premises safe. A feature that was never there cannot be missing, so a staircase lawfully altered under the head lease was not thereby out of repair."}, {"url": "https://hklandlaw.wordpress.com/2017/06/26/adverse-possession-death-of-licensor-terminates-a-licence/", "title": "Adverse possession: death of licensor terminates a licence", "date": "2017-06-26", "type": "case-note", "topics": ["adverse-possession", "licence", "termination-of-licence", "limitation", "compulsory-sale"], "cases": [{"name": "Hsieh Haw Shane Gary v Chang Ho Ying", "citation": "[2017] HKEC 1246", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Land (Compulsory Sale for Redevelopment) Ordinance (Cap. 545)"], "summary": "Permission to occupy dies with the person who gave it, even one who never perfected legal title. Time then runs afresh against the paper owner, and after twelve years the occupier can claim a share of compulsory sale proceeds."}, {"url": "https://hklandlaw.wordpress.com/2017/06/19/adverse-possession-and-the-land-compulsory-sale-for-redevelopment-ordinance/", "title": "Adverse possession and the Land (Compulsory Sale for Redevelopment) Ordinance", "date": "2017-06-19", "type": "case-note", "topics": ["adverse-possession", "compulsory-sale", "periodic-tenancy", "limitation", "vacant-possession"], "cases": [{"name": "Chung Chiu Hing v Law Sam", "citation": "[2017] HKEC 1198", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Land (Compulsory Sale for Redevelopment) Ordinance", "Limitation Ordinance s.12(2)"], "summary": "An oral periodic tenancy is deemed to end a year after grant or last rent, letting time run from 1986. A squatter counts as owner for the redevelopment sale regime, or at least holds an incumbrance payable from proceeds."}, {"url": "https://hklandlaw.wordpress.com/2017/06/11/interpretation-of-dmc-apportionment-provision-and-order-for-sale-of-defaulting-owners-shares/", "title": "Interpretation of DMC apportionment provision and order for sale of defaulting owner's shares", "date": "2017-06-11", "type": "case-note", "topics": ["deed-of-mutual-covenant", "management-charges", "apportionment", "equitable-charge", "order-for-sale"], "cases": [{"name": "Hertford Mansion (Un Chau Street) (IO) v Wong Shing Kwan", "citation": "[2017] HKEC 1154", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Two schedules charging the same expenditure must be read as one scheme, so the vague reference to a due proportion takes the precise fraction given elsewhere. Persistent non-payment justified charging and selling the owner's shares."}, {"url": "https://hklandlaw.wordpress.com/2017/06/03/adverse-possession-the-significance-of-a-failure-to-fence-rural-land/", "title": "Adverse possession: the significance of a failure to fence rural land", "date": "2017-06-03", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "enclosure", "rural-land", "intention-to-possess"], "cases": [{"name": "Winpo Development Ltd v Wong Kar Fu", "citation": "[2017] HKEC 1093", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Not fencing usually counts heavily against a squatter, but natural boundaries can make enclosure pointless. A family farming the plot since 1968 behaved as an owner would and shut out everyone else, so the defence succeeded."}, {"url": "https://hklandlaw.wordpress.com/2017/05/27/relief-from-forfeiture-will-ordinarily-only-be-granted-once-during-a-lease-term/", "title": "Relief from forfeiture will ordinarily only be granted once during a lease term", "date": "2017-05-27", "type": "case-note", "topics": ["relief-from-forfeiture", "forfeiture", "rent-arrears", "leases", "judicial-discretion"], "cases": [{"name": "Ramadour Industries Ltd v Bullen", "citation": "[2017] HKEC 974", "court": "CA", "jurisdiction": "HK"}], "statutes": ["High Court Ordinance s.21F(1A)"], "summary": "Statute allows a tenant one rescue per term unless good cause is shown for another. A tenant already relieved of arrears who defaulted again bore the burden, failed to discharge it, and lost on appeal."}, {"url": "https://hklandlaw.wordpress.com/2017/05/20/developers-informal-allocation-of-private-parking-space-in-the-common-area/", "title": "Developer's informal allocation of private parking space in the common area", "date": "2017-05-20", "type": "case-note", "topics": ["common-parts", "licence", "promissory-estoppel", "acquiescence", "car-parking", "deed-of-mutual-covenant"], "cases": [{"name": "Faraday House (IO) v Shine Wheel Ltd", "citation": "[2017] HKEC 957", "court": "other", "jurisdiction": "HK"}, {"name": "Luo Xing Juan v Estate of Hui Shui See", "citation": "(2009) 12 HKCFAR 1", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "A developer cannot licence away space already dedicated as common area; any such permission stays revocable and does not run with the land. Having paid before the promise, the occupier showed no detriment, so estoppel failed."}, {"url": "https://hklandlaw.wordpress.com/2017/05/12/ouster-and-car-parking-applying-batchelor/", "title": "Ouster and car parking: applying Batchelor", "date": "2017-05-12", "type": "case-note", "topics": ["easements", "ouster-principle", "car-parking", "injunction", "negotiating-damages"], "cases": [{"name": "Kettel v Bloomfold Ltd", "citation": "[2012] EWHC 1422", "court": "other", "jurisdiction": "EN"}, {"name": "Batchelor v Marlow", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Moncrieff", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "Ask whether the burdened owner retains any reasonable use. Walking across the bays, letting others cross, resurfacing, running services and building above all remained, so the parking right stood and was protected by injunction rather than money."}, {"url": "https://hklandlaw.wordpress.com/2017/05/04/car-parking-easements-and-the-ouster-principle-understanding-batchelor/", "title": "Car parking easements and the ouster principle: understanding Batchelor", "date": "2017-05-04", "type": "case-note", "topics": ["easements", "ouster-principle", "car-parking", "servient-tenement", "possession-and-control"], "cases": [{"name": "Virdi v Chana", "citation": "[2008] EWHC 2901 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Batchelor v Marlow", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Moncrieff v Jamieson", "citation": null, "court": null, "jurisdiction": "other"}], "statutes": [], "summary": "Two rival measures compete: whether a parked car swallows the entire surface, or whether the owner keeps control and possession. Applying the stricter version, the easement still survived because planting, trellises and resurfacing left genuine residual value."}, {"url": "https://hklandlaw.wordpress.com/2017/04/26/common-intention-constructive-trust-context/", "title": "Common intention constructive trust: context", "date": "2017-04-26", "type": "case-note", "topics": ["common-intention-constructive-trust", "estoppel-by-standing-by", "adverse-possession", "family-property", "informal-agreements"], "cases": [{"name": "Cheung Lai Mui v Cheung Wai Shing", "citation": "[2017] HKEC 740", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Express family discussions founded sole beneficial entitlement, the absence of paperwork being unsurprising in a traditional Chinese household. The claim also succeeded on standing by, and on possession, an unlocked gate still asserting control unambiguously."}, {"url": "https://hklandlaw.wordpress.com/2017/04/18/the-equity-of-exoneration-family-homes-and-indirect-benefits/", "title": "The equity of exoneration: family homes and indirect benefits", "date": "2017-04-18", "type": "case-note", "topics": ["equity-of-exoneration", "family-home", "suretyship", "co-ownership", "bankruptcy"], "cases": [{"name": "Armstrong v Onyearu", "citation": "[2017] EWCA Civ 268", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Where a jointly owned home secures only one owner's debts, the other may charge his share, subject to their shared intention. Vague hopes that his business would survive were too speculative and unquantifiable to count as a defeating benefit."}, {"url": "https://hklandlaw.wordpress.com/2017/04/10/adverse-possession-by-co-owner-in-breach-of-dmc/", "title": "Adverse possession by co-owner in breach of DMC", "date": "2017-04-10", "type": "case-note", "topics": ["adverse-possession", "co-ownership", "deed-of-mutual-covenant", "laches", "limitation", "restrictive-covenants"], "cases": [{"name": "Foremost Hill Ltd v Li Hon", "citation": "[2017] HKEC 708", "court": null, "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.4(1)", "Limitation Ordinance s.7(2)"], "summary": "One unit owner can dispossess another despite the mutual covenant, given conduct inconsistent with the neighbour's exclusive occupation. Suing on the covenant was six years too late at law, and delay of decades made equitable enforcement inequitable."}, {"url": "https://hklandlaw.wordpress.com/2017/04/04/the-priority-of-unwritten-equitable-interests/", "title": "The priority of unwritten equitable interests", "date": "2017-04-03", "type": "case-note", "topics": ["priority", "equitable-interests", "doctrine-of-notice", "land-registration", "charging-order"], "cases": [{"name": "Si Tou Choi Kam v Wealth Credit Ltd", "citation": "[2017] 1 HKLRD 1074", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Competing equities should rank by time and notice, yet the court let the date of registering a declaration decide against a beneficial owner whose interest arose at purchase. The author doubts any authority obliges a claimant to register."}, {"url": "https://hklandlaw.wordpress.com/2017/03/28/estoppel-by-convention-need-for-a-common-assumption-or-understanding/", "title": "Estoppel by convention: need for a common assumption or understanding", "date": "2017-03-28", "type": "case-note", "topics": ["estoppel-by-convention", "common-assumption", "proprietary-estoppel", "detriment", "unconscionability"], "cases": [{"name": "Preedy v Dunne", "citation": "[2016] EWCA Civ 805", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Without a genuinely shared assumption there is nothing for this estoppel to bite on, and a mistaken belief about who owned the pub business was not enough. Spending heavily without securing anyone's commitment attracts no free-standing equitable rescue."}, {"url": "https://hklandlaw.wordpress.com/2017/03/20/sale-of-land-as-agricultural-land-in-the-new-territories/", "title": "Sale of land as 'agricultural land' in the New Territories", "date": "2017-03-20", "type": "case-note", "topics": ["government-lease", "restrictive-covenants", "agricultural-land", "new-territories", "construction-of-grants", "columbarium"], "cases": [{"name": "Splendid Resources Inc v Secretary for Justice", "citation": "[2017] HKEC 504", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Selling land described as agricultural was not merely descriptive: cultivation terms in the grant evidenced an implied restriction binding successors, ambiguity being resolved for the Government. Erecting a columbarium therefore breached the prohibition on building."}, {"url": "https://hklandlaw.wordpress.com/2017/03/11/common-intention-constructive-trust-condition-attached-to-express-agreement-not-satisfied/", "title": "Common intention constructive trust: condition attached to express agreement not satisfied", "date": "2017-03-11", "type": "case-note", "topics": ["common-intention-constructive-trust", "quantification", "express-agreement", "financial-contributions", "beneficial-shares"], "cases": [{"name": "Gallarotti v Sebastianelli", "citation": "[2012] EWCA Civ 865", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "An agreed equal split was premised on one friend paying more of the mortgage; he never did. Their conduct showed shares were meant broadly to track what each put in, producing a seventy-five to twenty-five division without exact accounting."}, {"url": "https://hklandlaw.wordpress.com/2017/03/04/family-ownership-disputes-when-does-jones-v-kernott-apply/", "title": "Family ownership disputes: when does Jones v Kernott apply?", "date": "2017-03-04", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "proprietary-estoppel", "joint-tenancy", "family-property"], "cases": [{"name": "Wodzicki v Wodzicki", "citation": "[2017] EWCA Civ 95", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Hammersmith & Fulham LBC v Monk", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Between father, stepmother and daughter the shares followed contributions on resulting trust lines; no fair-shares imputation was available outside a cohabiting couple. The estoppel claim failed once actual intentions were found, and one joint tenant cannot fix another's beneficial position."}, {"url": "https://hklandlaw.wordpress.com/2017/02/26/trustee-acquiring-property-on-his-own-account-using-trust-property/", "title": "Trustee acquiring property on his own account using trust property", "date": "2017-02-26", "type": "case-note", "topics": ["trustees-duties", "unauthorised-profit", "tracing", "proprietary-remedies", "election-by-beneficiaries"], "cases": [{"name": "Tang Ying Loi v Tang Ying Ip", "citation": "[2017] HKEC 204", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Where estate money funds a purchase, beneficiaries may adopt the deal and take a share of the asset itself, with no need for tracing and no shortfall in the accounts. Equity keeps gains for beneficiaries and losses with the trustee."}, {"url": "https://hklandlaw.wordpress.com/2017/02/19/england-oral-agreements-and-the-common-intention-constructive-trust/", "title": "England: oral agreements and the common intention constructive trust", "date": "2017-02-19", "type": "case-note", "topics": ["common-intention-constructive-trust", "formalities", "oral-agreements", "detrimental-reliance", "proprietary-estoppel"], "cases": [{"name": "Matchmove Ltd v Dowding", "citation": "[2016] EWCA Civ 1233", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Herbert v Doyle", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2(1)", "Law of Property (Miscellaneous Provisions) Act 1989 s.2(5)"], "summary": "Parties who treated the written contract as a formality, considering themselves already bound, could enforce an unwritten land bargain through a constructive trust after paying over the money. The saving provision fails where terms are open or documents genuinely awaited."}, {"url": "https://hklandlaw.wordpress.com/2017/02/11/failure-to-pay-deposit-by-stipulated-date-the-seller-did-not-waive-the-breach-by-cashing-a-cheque-for-the-deposit-after-communicating-an-intention-to-treat-the-agreements-as-term/", "title": "Failure to pay deposit by stipulated date: the seller did not waive the breach by cashing a cheque for the deposit after communicating an intention to treat the agreements as terminated", "date": "2017-02-11", "type": "case-note", "topics": ["waiver", "time-of-the-essence", "deposit", "termination", "sale-of-land"], "cases": [{"name": "Fast Happy Ltd v Lee Chun Pong Bruce", "citation": "[2017] HKEC 121", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Payment dates for deposits were essential, so late tender let the seller end the bargains. Telling the agents acting for both sides sufficed as notice, and banking the cheque afterwards was consistent with forfeiture rather than affirmation."}, {"url": "https://hklandlaw.wordpress.com/2017/02/03/agreement-determines-whether-landlords-must-give-credit-for-security-deposit-when-enforcing-a-judgment-against-tenant/", "title": "Agreement determines whether landlords must give credit for security deposit when enforcing a judgment against tenant", "date": "2017-02-03", "type": "case-note", "topics": ["security-deposit", "liquidated-damages", "leases", "contractual-interpretation", "enforcement-of-judgment"], "cases": [{"name": "Power Plus Ltd v Fruit Design & Build Ltd", "citation": "[2016] 5 HKLRD 707", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "The lease made the forfeited deposit liquidated damages for any claim, so the landlord could not both keep it and enforce the arrears judgment in full. The deposit had to be set against the sum owed."}, {"url": "https://hklandlaw.wordpress.com/2017/01/25/elderly-fathers-gifts-to-his-children-set-aside-on-the-grounds-of-undue-influence/", "title": "Elderly father's gifts to his children set aside on the grounds of undue influence", "date": "2017-01-25", "type": "case-note", "topics": ["undue-influence", "unconscionability", "gift", "independent-legal-advice", "setting-aside"], "cases": [{"name": "Chan Yuk Pui v Chan Yui Chi", "citation": "[2016] HKEC 1891", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Children who dominated their father, said nothing about how badly the transfers served him and let one solicitor act for everyone had actually exerted influence. Stripping him of his income was manifestly disadvantageous, so the transfers were undone."}, {"url": "https://hklandlaw.wordpress.com/2017/01/19/did-son-hold-property-on-trust-for-his-mother/", "title": "Did son hold property on trust for his mother?", "date": "2017-01-19", "type": "case-note", "topics": ["common-intention-constructive-trust", "presumed-resulting-trust", "survivorship", "gift", "burden-of-proof"], "cases": [{"name": "Primecredit Ltd v Yeung Chun Pang Barry", "citation": "[2016] HKEC 2667", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "On the father's death survivorship left the son sole legal owner, and the mother had to displace that. Her purchase money had been meant as a gift to him, so neither trust route gave her a beneficial share."}, {"url": "https://hklandlaw.wordpress.com/2017/01/12/proprietary-estoppel-and-co-habitation/", "title": "Proprietary estoppel and co-habitation", "date": "2017-01-12", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "detrimental-reliance", "co-habitation", "satisfying-the-equity"], "cases": [{"name": "Southwell v Blackburn", "citation": "[2014] EWCA Civ 1347", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Greasley v Cooke", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "A promise of a secure home was clear enough to found an equity. Detriment is weighed across the whole relationship, not totted up, and the shared benefits of living together do not cancel it. Compensation, not a share, satisfied the claim."}, {"url": "https://hklandlaw.wordpress.com/2017/01/07/fixed-term-followed-by-periodic-tenancy-a-single-term/", "title": "Fixed term followed by periodic tenancy: a single term?", "date": "2017-01-07", "type": "case-note", "topics": ["leases", "certainty-of-term", "periodic-tenancy", "fixed-term", "hybrid-tenancy"], "cases": [{"name": "Leeds City Council v Broadley", "citation": "[2016] EWCA Civ 1212", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Prudential Assurance v London Residuary Body", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Mexfield Housing Co-operative v Berrisford", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.1(1)", "Law of Property Act 1925 s.205(1)(xxvii)"], "summary": "Granting a set period and then a running periodic term creates one tenancy, not two, and offends no certainty requirement. Centuries of authority recognised the hybrid, and the 1925 statute carried that position forward."}, {"url": "https://hklandlaw.wordpress.com/2016/12/31/recovery-of-land-transferred-pursuant-to-an-unlawful-contract/", "title": "Recovery of land transferred pursuant to an unlawful contract", "date": "2016-12-31", "type": "case-note", "topics": ["illegality", "resulting-trust", "small-house-policy", "equitable-compensation", "bona-fide-purchaser"], "cases": [{"name": "Li Ting Kit Tso v Cheung Tin Wah", "citation": "[2016] HKEC 2720", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "An oral deal requiring villagers to make false declarations was unenforceable, yet the Tso could still invoke a resulting trust. No consideration passed and the deed raised no estoppel. Onward sales to innocent buyers left only equitable compensation."}, {"url": "https://hklandlaw.wordpress.com/2016/12/17/joint-adverse-possession/", "title": "Joint adverse possession?", "date": "2016-12-17", "type": "case-note", "topics": ["adverse-possession", "joint-possession", "factual-possession", "pleadings", "recovery-of-land"], "cases": [{"name": "U Po Chu v Tsang Pui Ling", "citation": "[2016] HKEC 2673", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A former tenant who stopped paying rent claimed she possessed the whole building jointly with other occupiers. Each in fact held only their own part, and she had failed to plead a claim to hers."}, {"url": "https://hklandlaw.wordpress.com/2016/12/10/common-intention-constructive-trust-when-is-the-agreement-subject-to-contract/", "title": "Common intention constructive trust: when is the agreement 'subject to contract'?", "date": "2016-12-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "subject-to-contract", "formalities", "detrimental-reliance", "compromise-agreements"], "cases": [{"name": "Ely v Robson", "citation": "[2016] EWCA Civ 774", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Herbert v Doyle", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2(1)"], "summary": "No trust arises if formal documents are awaited, terms are still open, or immediate binding effect was not intended. None of those applied here: dropping possession proceedings and other claims was detrimental reliance on a settled oral compromise."}, {"url": "https://hklandlaw.wordpress.com/2016/12/08/article-marriage-and-acquisition-of-a-beneficial-interest-in-the-family-home-in-hong-kong/", "title": "Article - Marriage and acquisition of a beneficial interest in the family home in Hong Kong", "date": "2016-12-08", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Announces the author's Conveyancer article on marriage and beneficial interests."}, {"url": "https://hklandlaw.wordpress.com/2016/12/03/removal-of-the-duty-manager-of-a-tso-or-tong/", "title": "Removal of the duty manager of a tso or t'ong", "date": "2016-12-03", "type": "case-note", "topics": ["tso-and-tong", "new-territories-land", "chinese-custom", "managers-duties", "trusts"], "cases": [{"name": "Tang Fu Sun v Tang Lik Yuen", "citation": "[2016] 4 HKLRD 608", "court": null, "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance s.15"], "summary": "A duty manager is simply an employee whom the managers, and also the general assembly, may dismiss. No custom of unanimity was proved, and requiring it would absurdly let him block his own removal."}, {"url": "https://hklandlaw.wordpress.com/2016/11/26/misrepresentation-as-to-the-identity-of-the-purchaser/", "title": "Misrepresentation as to the identity of the purchaser", "date": "2016-11-26", "type": "case-note", "topics": ["misrepresentation", "rescission", "estate-agents", "compulsory-sale", "sale-of-land"], "cases": [{"name": "Greatland Property Consultants Ltd v Charis Patria Ltd", "citation": "[2016] HKEC 2518", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land (Compulsory Sale for Redevelopment) Ordinance"], "summary": "An agent disguised the buyer as a mainland businessman to hide that it was the neighbouring assembler, who would have been charged more. That induced the sale, so the vendor rescinded and escaped the commission."}, {"url": "https://hklandlaw.wordpress.com/2016/11/20/joint-bank-account-can-one-holder-take-all-of-the-money-for-her-own-benefit/", "title": "Joint bank account: can one holder take all of the money for her own benefit?", "date": "2016-11-20", "type": "case-note", "topics": ["joint-bank-account", "beneficial-ownership", "tenancy-in-common", "equity-follows-the-law", "sale-proceeds"], "cases": [{"name": "Lun Kwai Har v Hung Ying Yi", "citation": "[2016] HKEC 724", "court": "CFI", "jurisdiction": "HK"}, {"name": "Yung Shu Wu v Vivienne Sung Wu", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Ordinarily either holder may draw a joint account for herself, but the balance here was sale proceeds of land held as tenants in common. Those shares carried through, so the withdrawn money had to be shared."}, {"url": "https://hklandlaw.wordpress.com/2016/11/12/equity-follows-the-law-the-burden-of-proof/", "title": "Equity follows the law: the burden of proof", "date": "2016-11-12", "type": "case-note", "topics": ["equity-follows-the-law", "severance", "joint-tenancy", "burden-of-proof", "order-for-sale"], "cases": [{"name": "Lam Fung Ching Annie v Tse Kwok Wing Jacky", "citation": "[2016] HKEC 2387", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Notice of severance left three legal tenants in common with a third each. Anyone asserting different beneficial shares must prove it, and here that burden was not discharged, so the sale order stood."}, {"url": "https://hklandlaw.wordpress.com/2016/11/05/post-acquisition-variation-of-existing-common-intention/", "title": "Post-acquisition variation of existing common intention?", "date": "2016-11-05", "type": "case-note", "topics": ["common-intention-constructive-trust", "post-acquisition-variation", "joint-tenancy", "inferred-intention", "domestic-context"], "cases": [{"name": "Chen Lily v Yip Tsun Wah Alvan", "citation": "[2016] HKEC 2326", "court": "CA", "jurisdiction": "HK"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Conduct can in principle show a later change of intention, but nothing here proved one. Tallying contributions in a domestic joint venture was misconceived, and post-separation payments reflected new circumstances rather than a revised bargain."}, {"url": "https://hklandlaw.wordpress.com/2016/11/01/actual-intention-common-intention-constructive-trust-not-presumed-resulting-trust/", "title": "Actual intention? Common intention constructive trust not presumed resulting trust.", "date": "2016-11-01", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "presumption-of-advancement", "beneficial-ownership", "corporate-vehicles"], "cases": [{"name": "Re Superyield Holdings Ltd", "citation": "[2000] 2 HKC 90", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Companies Ordinance"], "summary": "Once actual intention is found, the resulting trust presumption drops out. The company was really the son's, the father's guarantee was not treated as a price contribution, and advancement made it a gift anyway."}, {"url": "https://hklandlaw.wordpress.com/2016/10/23/abbey-national-v-cann-mind-the-gap/", "title": "Abbey National v Cann: mind the gap?", "date": "2016-10-23", "type": "case-note", "topics": ["priority-of-interests", "actual-occupation", "acquisition-mortgage", "scintilla-temporis", "overriding-interests"], "cases": [{"name": "Abbey National Building Society v Cann", "citation": "[1991] 1 AC 56", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Land Registration Act 1925"], "summary": "Purchase and mortgage form one indivisible transaction, leaving no instant in which the occupier's interest could bite first. The mother also knew borrowing was essential, and the lender arguably held an equity before completion."}, {"url": "https://hklandlaw.wordpress.com/2016/10/15/vague-arrangements-as-to-the-completion-date/", "title": "Vague arrangements as to the completion date", "date": "2016-10-15", "type": "case-note", "topics": ["certainty-of-terms", "completion", "contract-formation", "formalities", "sale-of-land"], "cases": [{"name": "Tsang Wing Man v Chung On Ling", "citation": "[2016] HKEC 2164", "court": "CA", "jurisdiction": "HK"}, {"name": "Kwan Siu Man v Yaacov Ozer", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "Completing within three days of selling another property was too indefinite to bind, and the vagueness itself suggested no intention to contract. A later oral fix could not cure the want of writing."}, {"url": "https://hklandlaw.wordpress.com/2016/10/08/express-agreement-leads-to-constructive-trust-not-resulting-trust/", "title": "Express agreement leads to constructive trust not resulting trust", "date": "2016-10-08", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "express-agreement", "tracing-proceeds", "family-property"], "cases": [{"name": "Wong Yuk Tung v Wong Po Ling", "citation": "[2016] HKEC 2143", "court": null, "jurisdiction": "HK"}, {"name": "Re Superyield Holdings Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Liu Wai Keung v Liu Wai Man", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Because the dispute turned on whether father and daughters had expressly agreed, the analysis belonged to constructive rather than resulting trust. The agreement was proved, so the daughters held the flat and its replacements for him."}, {"url": "https://hklandlaw.wordpress.com/2016/10/01/right-of-way-interference-by-co-owner-and-derogation-from-grant-by-erecting-a-gate/", "title": "Right of way: interference by co-owner and derogation from grant by erecting a gate", "date": "2016-10-01", "type": "case-note", "topics": ["easements", "right-of-way", "substantial-interference", "derogation-from-grant", "co-ownership"], "cases": [{"name": "Chin Ling Investment Ltd v General of Salvation Army", "citation": "[2016] HKEC 1876", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "A gate across the shared access substantially interfered with co-owners' rights. Moving it onto the defendant's own land and handing over a key still derogated from the promised free and uninterrupted passage, so removal was ordered."}, {"url": "https://hklandlaw.wordpress.com/2016/09/21/do-owners-of-sub-divided-units-count-as-owners-for-general-meeting-purposes/", "title": "Do owners of sub-divided units count as owners for general meeting purposes?", "date": "2016-09-21", "type": "case-note", "topics": ["building-management", "owners-corporation", "quorum", "deed-of-mutual-covenant", "land-registration"], "cases": [{"name": "Chow Chui Chui v Kafull Investment Ltd", "citation": "[2016] HKEC 1889", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.2", "Building Management Ordinance s.39", "Building Management Ordinance Schedule 3 paragraph 5(1)(b)"], "summary": "Owners of subdivided units holding shares under sub-DMCs and registered at the Land Registry are owners for meeting purposes. The statutory definition looks to the register, and references to a DMC are not confined to the principal deed."}, {"url": "https://hklandlaw.wordpress.com/2016/09/14/landlords-repairing-covenant-tenant-must-give-the-landlord-notice-of-a-defect-in-the-property-in-the-tenants-possession/", "title": "Landlord's repairing covenant: tenant must give the landlord notice of a defect in the property in the tenant's possession", "date": "2016-09-14", "type": "case-note", "topics": ["repairing-covenant", "landlord-and-tenant", "notice-of-disrepair", "implied-terms", "easements"], "cases": [{"name": "Edwards v Kumarasamy", "citation": "[2016] UKSC 40", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Landlord and Tenant Act 1985 s.11"], "summary": "A paved path was not part of the exterior. Reversing the court below, the Supreme Court held notice is required for defects in premises the tenant possesses, and extended that to shared areas the tenant may use."}, {"url": "https://hklandlaw.wordpress.com/2016/09/09/building-management-management-fee-for-handling-renovation-works-needs-owners-approval/", "title": "Building management: Management fee for handling renovation works needs owners' approval", "date": "2016-09-09", "type": "case-note", "topics": ["building-management", "owners-corporation", "management-fees", "penalty-clauses", "approval-of-expenditure"], "cases": [{"name": "Flora Garden (IO) v Li Do Wai", "citation": "[2016] HKEC 1830", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Owners voted on the works but not on a ten percent handling fee, and past informal payments gave no authority, so it was irrecoverable. Late-payment surcharges survived as protecting a legitimate interest without being extravagant."}, {"url": "https://hklandlaw.wordpress.com/2016/08/31/can-the-creation-of-a-common-intention-constructive-trust-be-inferred-from-conduct-alone/", "title": "Can the creation of a common intention constructive trust be inferred from conduct alone?", "date": "2016-08-31", "type": "case-note", "topics": ["common-intention-constructive-trust", "inferred-intention", "conduct", "family-business", "detrimental-reliance"], "cases": [{"name": "Morris v Morris", "citation": "[2008] EWCA Civ 257", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Courts hesitate to spell a shared intention out of behaviour alone. A wife's money and labour in the farm business were explicable by her own trading interests. The blogger doubts demanding that agreement be the sole explanation."}, {"url": "https://hklandlaw.wordpress.com/2016/08/25/contracts-and-illegality-patel-v-mirza/", "title": "Contracts and illegality: Patel v Mirza", "date": "2016-08-25", "type": "case-note", "topics": ["illegality", "restitution", "public-policy", "proportionality", "unjust-enrichment"], "cases": [{"name": "Patel v Mirza", "citation": "[2016] UKSC 42", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Tinsley v Milligan", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Money paid under a failed illegal bargain was recoverable, but the nine justices split on method. The majority weighs the prohibition's purpose, competing policies and proportionality, displacing the older test of whether illegality must be pleaded."}, {"url": "https://hklandlaw.wordpress.com/2016/08/17/misrepresentation-a-flat-with-a-view-in-the-court-of-appeal/", "title": "Misrepresentation: a flat with a view in the Court of Appeal", "date": "2016-08-17", "type": "case-note", "topics": ["misrepresentation", "sale-of-land", "statements-of-intention", "sales-brochures", "disclaimers"], "cases": [{"name": "Yang Dandan v Hong Kong Resort Co Ltd", "citation": "[2016] HKEC 1722", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Contrasting high-rise and mid-rise labels could not reasonably be read as promising a height gap, statements about unbuilt phases were predictions rather than assertions of fact, and brochure reservations coloured how a buyer should read them."}, {"url": "https://hklandlaw.wordpress.com/2016/08/10/man-promises-mistress-a-home-for-life-if-she-leaves-her-home-country-to-live-with-him/", "title": "Man promises mistress a home for life if she leaves her home country to live with him", "date": "2016-08-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "life-interest", "settled-land", "licences", "home-for-life"], "cases": [{"name": "Ungurian v Lesnoff", "citation": "[1990] Ch. 206", "court": "other", "jurisdiction": "EN"}, {"name": "Grant v Edwards", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Eves v Eves", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Bannister v Bannister", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Settled Land Act 1925"], "summary": "Her understanding on leaving Poland was lifelong security, which a revocable permission could not deliver. He held the flat so she could occupy for life unless she consented to a substitute, making her tenant for life."}, {"url": "https://hklandlaw.wordpress.com/2016/08/04/adverse-possession-where-part-of-the-limitation-period-is-taken-up-by-squatters-declaration-proceedings/", "title": "Adverse possession: where part of the limitation period is taken up by squatter's declaration proceedings", "date": "2016-08-04", "type": "case-note", "topics": ["adverse-possession", "limitation", "tso-and-tong", "new-territories-land", "declaratory-proceedings"], "cases": [{"name": "Tang Wai Tung v Tang Wai Lun", "citation": "[2016] 3 HKLRD 96", "court": "CA", "jurisdiction": "HK"}, {"name": "Light Ocean Investments Ltd v Emway Development Ltd", "citation": "[1994] 3 HKC 31", "court": null, "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance s.15"], "summary": "Earlier litigation halted time even though the Tso never formally pleaded a possession claim; substance outweighed pleading form. Separately, missing consent under the New Territories Ordinance would void any conveyance of the land."}, {"url": "https://hklandlaw.wordpress.com/2016/07/27/oral-variation-of-contract-despite-clause-requiring-variations-to-be-in-writing/", "title": "Oral variation of contract despite clause requiring variations to be in writing", "date": "2016-07-27", "type": "case-note", "topics": ["variation-of-contract", "no-oral-modification-clause", "consideration", "promissory-estoppel", "leases"], "cases": [{"name": "MWB Business Exchange Centres Ltd v Rock Advertising Ltd", "citation": "[2016] EWCA Civ 553", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Globe Motors Inc v TRW Lucas Varity Electric Steering Ltd", "citation": "[2016] EWCA Civ 396", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Pinnel's Case", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Foakes v Beer", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Tool Metal Manufacturing Co Ltd v Tungsten Electric Co Ltd", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "In re Selectmove", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A clause demanding written variations did not stop an oral rescheduling of arrears taking effect. Avoiding a damaging empty period and securing part payment supplied consideration, and reliance on the concession made resiling inequitable."}, {"url": "https://hklandlaw.wordpress.com/2016/07/21/proprietary-estoppel-genuine-belief-but-no-assurance/", "title": "Proprietary estoppel: genuine belief but no assurance", "date": "2016-07-21", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "common-intention-constructive-trust", "commercial-context", "family-farm"], "cases": [{"name": "McGuiness v Preece", "citation": "[2016] EWHC 1518 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Thorner v Major", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Sincerely believing you will inherit land is not enough; the owner must have given a clear enough assurance, and the father gave none. Absent any agreement the constructive trust route failed too."}, {"url": "https://hklandlaw.wordpress.com/2016/07/14/property-acquired-in-contemplation-of-marriage/", "title": "Property acquired in contemplation of marriage", "date": "2016-07-14", "type": "case-note", "topics": ["conditional-gift", "engagement", "joint-tenancy", "beneficial-ownership", "matrimonial-home"], "cases": [{"name": "Tsun Kok Chung Richard v Lee Chun Yu", "citation": "[2016] HKEC 1482", "court": "CFI", "jurisdiction": "HK"}, {"name": "Ian Hung Wai v Cheung Sau Kuen", "citation": "[2011] 3 HKLRD 458", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Law Amendment and Reform (Consolidation) Ordinance s.25"], "summary": "A flat bought as the future matrimonial home and put into joint names carried an implied condition that the wedding happen. It did not, no outright gift was intended, and the fiancee had to reconvey."}, {"url": "https://hklandlaw.wordpress.com/2016/07/06/implied-grant-of-easements/", "title": "Implied grant of easements", "date": "2016-07-06", "type": "case-note", "topics": ["easements", "implied-grant", "non-derogation-from-grant", "common-intention", "quasi-easements"], "cases": [{"name": "Collins v Collins (No 2)", "citation": "[2015] EWHC 2652; [2016] 2 P & C.R. 6", "court": "other", "jurisdiction": "EN"}, {"name": "Arnold v Britton", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Pwllbach Colliery Co Ltd v Woodman", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "McAdams Homes Ltd v Robinson", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.62", "Conveyancing and Property Ordinance s.16"], "summary": "Rights needed to work commercially gifted land were implied into a trust deed, both through non-derogation and the parties' shared purpose. Until a sale the access ranked as a quasi-easement, which the statutory word-saving provision would then upgrade."}, {"url": "https://hklandlaw.wordpress.com/2016/06/29/whether-a-right-to-set-aside-a-transaction-bound-third-party-mortgagee-england/", "title": "Whether a right to set aside a transaction bound third party mortgagee (England)", "date": "2016-06-29", "type": "case-note", "topics": ["mere-equities", "unconscionable-bargain", "overreaching", "priority-of-interests", "registered-land"], "cases": [{"name": "Mortgage Express v Lambert", "citation": "[2016] EWCA Civ 555", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Land Registration Act 2002 s.26", "Land Registration Act 2002 s.29", "Land Registration Act 2002 Schedule 3 paragraph 2", "Land Registration Act 2002 s.116", "Law of Property Act 1925 s.2"], "summary": "A seller's right to undo an unconscionable bargain is only a mere equity. Though such equities can bind, the statutory protection of a disponee's title and overreaching on the mortgage advance let the lender's charge prevail."}, {"url": "https://hklandlaw.wordpress.com/2016/06/22/australia-presumption-of-beneficial-joint-tenancy-where-both-spouses-contributed-to-the-purchase-price-of-the-matrimonial-home/", "title": "Australia: presumption of beneficial joint tenancy where both spouses contributed to the purchase price of the matrimonial home", "date": "2016-06-22", "type": "case-note", "topics": ["beneficial-joint-tenancy", "matrimonial-home", "resulting-trust", "survivorship", "bankruptcy"], "cases": [{"name": "Trustees of Property of Cummins v Cummins", "citation": "[2006] HCA 6", "court": "other", "jurisdiction": "AU"}], "statutes": [], "summary": "Australia's High Court presumes spouses who both funded the matrimonial home intend equal beneficial shares whatever the arithmetic, the ongoing marriage explaining the choice of survivorship. Both must nonetheless have contributed for the presumption to operate."}, {"url": "https://hklandlaw.wordpress.com/2016/06/20/lkw-v-dd-equal-sharing-principle/", "title": "LKW v DD - 'equal sharing' principle", "date": "2016-06-20", "type": "case-note", "topics": ["matrimonial-property", "equal-sharing", "ancillary-relief", "non-discrimination", "financial-provision"], "cases": [{"name": "LKW v DD", "citation": "(2010) 13 HKCFAR 537", "court": "CFA", "jurisdiction": "HK"}, {"name": "White v White", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Miller v Miller; McFarlane v McFarlane", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "C v C", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Matrimonial Proceedings and Property Ordinance s.7", "Matrimonial Causes Act 1973 s.25"], "summary": "Confining a homemaker to her reasonable requirements was discriminatory, and the English fairness approach was adopted for Hong Kong. A five-step method with equal division as yardstick discourages retrospective conduct inquiries; the wife kept half."}, {"url": "https://hklandlaw.wordpress.com/2016/06/16/establishing-a-common-intention-constructive-trust/", "title": "Establishing a common intention constructive trust", "date": "2016-06-16", "type": "case-note", "topics": ["common-intention-constructive-trust", "inferred-intention", "family-context", "financial-contributions", "recovery-of-possession"], "cases": [{"name": "Fung Oi Ha v Fung Pui On", "citation": "[2016] HKEC 1272", "court": "CFI", "jurisdiction": "HK"}, {"name": "Lloyds Bank v Rosset", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Burns v Burns", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "The court surveyed the whole dealings rather than confining itself to price and mortgage. Still, a daughter's help with household expenses read naturally as ordinary family support, especially where the flat was the parents' retirement shelter; possession went to her brother."}, {"url": "https://hklandlaw.wordpress.com/2016/06/12/white-v-white-the-equality-yardstick/", "title": "White v White: the equality 'yardstick'", "date": "2016-06-12", "type": "case-note", "topics": ["matrimonial-property", "equality-yardstick", "non-discrimination", "ancillary-relief", "homemaker-contributions"], "cases": [{"name": "White v White", "citation": "[2001] 1 AC 596", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Matrimonial Causes Act 1973 s.25", "Matrimonial Causes Act 1973 s.25(2)(f)"], "summary": "Where assets exceed needs, judges should check their provisional division against equality and depart only for articulated reasons. Earning and homemaking count alike, so the wife's two-fifths share of the farming wealth stood."}, {"url": "https://hklandlaw.wordpress.com/2016/06/08/specific-performance-ready-willing-and-able-hardship-calculating-damages/", "title": "Specific performance: ready willing and able; hardship; calculating damages", "date": "2016-06-08", "type": "case-note", "topics": ["specific-performance", "ready-willing-and-able", "hardship", "damages", "sale-of-land"], "cases": [{"name": "Siu Wei v Ng Ying Ying", "citation": "[2016] HKEC 1162", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Capacity to perform is judged at writ and at decree on the balance of probabilities. Hardship must outweigh the claimant's prejudice, and it did not where he wanted a home and she an investment. Damages track lost rental value less interest saved."}, {"url": "https://hklandlaw.wordpress.com/2016/06/01/non-registration-of-trust-dispositions-to-defraud-creditors/", "title": "Non-registration of trust. Dispositions to defraud creditors", "date": "2016-06-01", "type": "case-note", "topics": ["land-registration", "priority-of-interests", "fraudulent-conveyance", "trusts", "valuation"], "cases": [{"name": "Goldfame Consultants Ltd v Tse Sai Ming", "citation": "[2016] HKEC 1113", "court": "CFI", "jurisdiction": "HK"}, {"name": "Tradepower (Holdings) Ltd (in liquidation) v Tradepower (Hong Kong) Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3(2)", "Conveyancing and Property Ordinance s.60"], "summary": "An unregistered trust declaration lost to the buyer. Actual intent to defraud must be proved where the sale was for value, the seller solvent, or creditors' fund undiminished; none existed. Rural land is best valued by comparable sales."}, {"url": "https://hklandlaw.wordpress.com/2016/05/25/proprietary-estoppel-expectations-and-proportionality/", "title": "Proprietary estoppel: expectations and proportionality", "date": "2016-05-25", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "proportionality", "detrimental-reliance", "expectation"], "cases": [{"name": "Davies v Davies", "citation": "[2016] EWCA Civ 643", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jennings v Rice", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Gillett v Holt", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Thorner v Major", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Relief is calibrated, not simply the fulfilment of what was hoped for. On a sliding scale, sharper expectations, heavier detriment and longer reliance count for more. This daughter's hazy hopes and repeated departures earned only a modest sum."}, {"url": "https://hklandlaw.wordpress.com/2016/05/18/proving-the-existence-of-a-common-intention-constructive-trust/", "title": "Proving the existence of a common intention constructive trust", "date": "2016-05-18", "type": "case-note", "topics": ["common-intention-constructive-trust", "nominee-ownership", "inferred-intention", "whole-course-of-conduct", "family-company"], "cases": [{"name": "Ip Man Shan v Ching Hing Construction Co Ltd", "citation": "[2005] HKEC 188", "court": "CA", "jurisdiction": "HK"}, {"name": "Lloyds Bank v Rosset", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Burns v Burns", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A son held as bare nominee for his father and the family firm. Evidence need not be confined to money: his inability to fund the building, absence from the design, a power of attorney and a lease were compelling enough."}, {"url": "https://hklandlaw.wordpress.com/2016/05/11/burns-v-burns-unmarried-cohabitees-title-to-family-home-in-sole-name/", "title": "Burns v Burns: unmarried cohabitees, title to family home in sole name", "date": "2016-05-11", "type": "case-note", "topics": ["common-intention-constructive-trust", "cohabitation", "sole-name-cases", "referability", "domestic-contributions"], "cases": [{"name": "Burns v Burns", "citation": "[1984] Ch. 317", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Seventeen years of housekeeping and child-rearing bought no share. Payments had to be referable to acquiring the property, and covering household bills not needed to service the mortgage, plus domestic labour, did not qualify."}, {"url": "https://hklandlaw.wordpress.com/2016/05/04/registration-of-a-personal-loan-agreement-unjustified/", "title": "Registration of a personal loan agreement unjustified", "date": "2016-05-04", "type": "case-note", "topics": ["land-registration", "vacation-of-registration", "interest-in-land", "inherent-jurisdiction", "costs"], "cases": [{"name": "Re Flat 4 on 3/F of Block A, Tin Yau Court, No 1 Tin Shing Road, Tin Shui Wai, Yuen Long, New Territories", "citation": "[2016] HKEC 751", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance"], "summary": "A purely personal loan agreement creates no interest in land and should never have been registered. Courts hold inherent power to clear the register of such instruments, and indemnity costs may follow against those who lodge them."}, {"url": "https://hklandlaw.wordpress.com/2016/04/27/unlawful-holding-overmeaning-of-possession-and-calculating-mesne-profits/", "title": "Unlawful holding over: meaning of possession and calculating mesne profits", "date": "2016-04-27", "type": "case-note", "topics": ["mesne-profits", "holding-over", "possession", "restitution", "landlord-and-tenant"], "cases": [{"name": "Fordtime Industrial Ltd v Yip Shing Lam", "citation": "[2016] HKEC 812", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "A wall left standing kept the landlord out, so possession returned only when it came down months after the tenant said he had left. Mesne profits were fixed restitutionally on the contemplated use, stripping the tenant's gain."}, {"url": "https://hklandlaw.wordpress.com/2016/04/20/good-title-not-affected-by-fanciful-risks-of-a-successful-legal-challenge/", "title": "Good title: not affected by 'fanciful' risks of a successful legal challenge", "date": "2016-04-20", "type": "case-note", "topics": ["good-title", "requisitions", "government-lease", "sale-of-land", "encumbrances"], "cases": [{"name": "Jovian Corporate Communications Ltd v Link Wide International Investment Ltd", "citation": "[2016] HKEC 808", "court": "CA", "jurisdiction": "HK"}, {"name": "Mexon Holdings Ltd v Silver Bay International Ltd", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "De Monsa Investments Ltd v Whole Win Management Ltd", "citation": null, "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Title is judged as robustly sensible parties would see it and fails only on a realistic threat of an encumbrance being enforced. Doubts over gubernatorial approval were fanciful given the Government's knowledge and endorsements."}, {"url": "https://hklandlaw.wordpress.com/2016/04/13/proprietary-estoppel-co-habitees/", "title": "Proprietary estoppel: co-habitees", "date": "2016-04-13", "type": "case-note", "topics": ["proprietary-estoppel", "cohabitation", "detrimental-reliance", "unconscionability", "remedies"], "cases": [{"name": "Liden v Burton", "citation": "[2016] EWCA Civ 275", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Told her monthly payments were towards the house, a partner handed over £28,500 across twelve years. Reliance plus detriment made denial unconscionable, and a trust returning her money with interest was the least needed to do justice."}, {"url": "https://hklandlaw.wordpress.com/2016/04/07/mortgage-or-not-look-at-the-substance-of-the-transaction/", "title": "Mortgage or not: look at the substance of the transaction", "date": "2016-04-07", "type": "case-note", "topics": ["mortgages", "clogs-on-the-equity-of-redemption", "options-to-purchase", "substance-over-form", "security-transactions"], "cases": [{"name": "Warnborough Ltd v Garmite Ltd", "citation": "[2003] EWCA Civ 1544", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Samuel v Jarrah Timber and Wood Paving Corporation Ltd", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Davies v Chamberlain", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Whether a deal is really a mortgage turns on substance. Where the option holder had sold the property to the grantor leaving the price on charge, the arrangement is very likely genuine sale, so no impermissible clog arose."}, {"url": "https://hklandlaw.wordpress.com/2016/04/07/one-millionth-view/", "title": "One millionth view", "date": "2016-04-07", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Blog marks passing one million cumulative page views and thanks readers."}, {"url": "https://hklandlaw.wordpress.com/2016/04/06/open-contracts-in-hong-kong/", "title": "Open contracts in Hong Kong", "date": "2016-04-06", "type": "case-note", "topics": ["open-contracts", "certainty-of-terms", "completion", "time-of-the-essence", "specific-performance"], "cases": [{"name": "Fong Yin Hing v Fong Kwan Pui", "citation": "[2016] HKEC 740", "court": "CFI", "jurisdiction": "HK"}, {"name": "Kwan Siu Man v Yaacov Ozer", "citation": null, "court": "CFA", "jurisdiction": "HK"}, {"name": "Behzadi v Shaftesbury Hotels Ltd", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Lau Suk Ching Peggy v Ma Hing Lam", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Omitting a completion date does not prevent a binding sale; what matters is whether the parties agreed to sell that property at that price. A reasonable time is implied, and notice can later make time essential. Specific performance granted."}, {"url": "https://hklandlaw.wordpress.com/2016/03/30/there-is-an-implied-term-that-a-sale-of-land-is-with-vacant-possession/", "title": "There is an implied term that a sale of land is with vacant possession", "date": "2016-03-30", "type": "case-note", "topics": ["vacant-possession", "implied-terms", "sale-of-land", "tenancies", "deposit-recovery"], "cases": [{"name": "Wong Yuk Ying v Chan Pui Shan May", "citation": "[2016] HKEC 537", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Unless otherwise agreed, land is sold with vacant possession, and the risk of tenants overstaying falls on the vendor. Disclosed tenancies due to expire before completion showed no contrary intention, so the buyer could recover her deposit."}, {"url": "https://hklandlaw.wordpress.com/2016/03/23/an-express-declaration-of-trust-is-conclusive-in-the-absence-of-a-vitiating-factor/", "title": "An express declaration of trust is conclusive in the absence of a vitiating factor", "date": "2016-03-23", "type": "case-note", "topics": ["express-declaration-of-trust", "beneficial-ownership", "rectification", "sham-trusts", "co-ownership"], "cases": [{"name": "Pankhania v Chandegra", "citation": "[2012] EWCA Civ 1438", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Goodman v Gallant", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Pettitt v Pettitt", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A signed declaration settles the beneficial shares unless fraud or mistake is shown. Someone whose real intentions differ must seek rectification; a mismatch alone is no sham, particularly where nobody outside was deceived."}, {"url": "https://hklandlaw.wordpress.com/2016/03/16/proprietary-estoppel-alleged-representations-made-by-a-person-who-is-dead-at-the-time-of-the-trial/", "title": "Proprietary estoppel: alleged representations made by a person who is dead at the time of the trial", "date": "2016-03-16", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "standard-of-proof", "deceased-declarants", "gifts"], "cases": [{"name": "Szeto Chak Mei v Chan Lam Shan", "citation": "[2016] HKEC 482", "court": "CFI", "jurisdiction": "HK"}, {"name": "Yung Shu Wu v Vivienne Sung Wu", "citation": "(2011) 14 HKCFAR 39", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Claims resting on a promise attributed to someone who has died are viewed with suspicion. The defendant could not satisfy the court that the assurance was ever given, so her proprietary estoppel case collapsed."}, {"url": "https://hklandlaw.wordpress.com/2016/03/09/illegal-sale-of-ding-rights-tinsley-v-milligan-re-affirmed/", "title": "Illegal sale of ding rights: Tinsley v Milligan re-affirmed", "date": "2016-03-09", "type": "case-note", "topics": ["illegality", "resulting-trust", "presumption-of-resulting-trust", "ding-rights", "proprietary-interest"], "cases": [{"name": "Kan Wai Chung v Hau Wan Fai", "citation": "[2016] HKLRD 632", "court": "CFI", "jurisdiction": "HK"}, {"name": "Tinsley v Milligan", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Nelson v Nelson", "citation": null, "court": "other", "jurisdiction": "AU"}], "statutes": [], "summary": "Developers who financed an unlawful dealing in village ding rights could still assert a resulting trust, since establishing the proprietary interest required no reliance on the illegality. Hong Kong keeps Tinsley rather than the Australian discretionary alternative."}, {"url": "https://hklandlaw.wordpress.com/2016/03/02/acquiescence-is-a-history-of-non-enforcement-of-dmc-terms-relevant/", "title": "Acquiescence: Is a history of non-enforcement of DMC terms relevant?", "date": "2016-03-02", "type": "case-note", "topics": ["acquiescence", "deed-of-mutual-covenant", "common-parts", "injunctive-relief", "building-management"], "cases": [{"name": "Freder Centre (IO) v Gringo Ltd", "citation": "[2016] HKEC 418", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.34I"], "summary": "Unauthorised signage on an external wall breached the mutual covenant, but years of tolerating identical breaches by nearly every other owner amounted to acquiescence, making injunctive relief inequitable. Enforcement history is therefore directly relevant to discretion."}, {"url": "https://hklandlaw.wordpress.com/2016/02/24/contractual-obligation-to-produce-an-architects-certificate-before-completion-an-implied-term-that-it-will-be-produced-within-a-reasonable-time-before-completion/", "title": "Contractual obligation to produce an architect's certificate before completion: an implied term that it will be produced within a reasonable time before completion", "date": "2016-02-24", "type": "case-note", "topics": ["implied-terms", "sale-of-land", "completion", "conveyancing", "time-of-the-essence"], "cases": [{"name": "Guo Jianjun v Dragon Fame Investment Ltd", "citation": "[2015] HKEC 1986", "court": "CA", "jurisdiction": "HK"}, {"name": "Summit Link v Sunlink Group", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Kensland Realty Ltd v Whale View Investment Ltd", "citation": "(2001) 4 HKCFAR 381", "court": "CFA", "jurisdiction": "HK"}, {"name": "Attorney General of Belize v Belize Telecom", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "A seller bound to hand over an architect's certificate must do so early enough on completion day for the buyer's solicitors to check it during ordinary office hours. Delivery after business hours breaches that implied timing obligation."}, {"url": "https://hklandlaw.wordpress.com/2016/02/17/mistaken-belief-that-one-is-the-owner-or-tenant-is-not-fatal-to-an-adverse-possession-claim/", "title": "Mistaken belief that one is the owner or tenant is not fatal to an adverse possession claim", "date": "2016-02-17", "type": "case-note", "topics": ["adverse-possession", "intention-to-possess", "factual-possession", "mistake", "limitation"], "cases": [{"name": "Cheung Kwong Yuen v Sun Hui Fang", "citation": "[2016] 1 HKLRD 464", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Believing wrongly that one holds title or a tenancy does not bar adverse possession. The Lands Tribunal was reversed: what matters is actual control plus an intention to possess, whatever the occupier assumed about their legal standing."}, {"url": "https://hklandlaw.wordpress.com/2016/02/10/common-intention-constructive-trust-valuation-outside-the-domestic-consumer-context/", "title": "Common intention constructive trust: valuation outside the 'domestic consumer context'", "date": "2016-02-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "beneficial-ownership", "sham-transactions", "investment-property"], "cases": [{"name": "Erlam v Rahman", "citation": "[2016] EWHC 111", "court": "other", "jurisdiction": "EN"}, {"name": "Laskar v Laskar", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Buy-to-let purchases fall outside the family-home approach, so shares are quantified on resulting trust lines by contribution. An unregistered declaration of trust may be treated as a sham where one party in fact kept all the rent."}, {"url": "https://hklandlaw.wordpress.com/2016/02/03/charging-order-over-share-in-the-family-home-striking-the-balance/", "title": "Charging order over share in the family home: striking the balance", "date": "2016-02-03", "type": "case-note", "topics": ["charging-order", "family-home", "common-intention-constructive-trust", "order-for-sale", "creditors-rights"], "cases": [{"name": "Melco Crown Gaming (Macau) Ltd v Wong Yam Tak", "citation": "[2016] HKEC 237", "court": null, "jurisdiction": "HK"}, {"name": "Kresmen v Agrest", "citation": "[2013] EWCA Civ 41", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["High Court Ordinance s.20(3)"], "summary": "A judgment creditor may charge a debtor spouse's beneficial share, the court weighing all circumstances including hardship and rival creditors. Making the order absolute settles nothing about sale, leaving the occupying family's position for a later stage."}, {"url": "https://hklandlaw.wordpress.com/2016/01/27/land-registration-ordinance-a-lis-pendens-involves-a-claim-to-a-proprietary-interest/", "title": "Land Registration Ordinance: a lis pendens involves a claim to a proprietary interest", "date": "2016-01-27", "type": "case-note", "topics": ["lis-pendens", "land-registration", "proprietary-interest", "deed-of-mutual-covenant", "unauthorised-building-works"], "cases": [{"name": "Wide Power Corp Ltd v Manhattan Court (IO)", "citation": "[2015] 4 HKLRD 480", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.1A"], "summary": "Only litigation asserting an interest in the land itself can be registered as a lis pendens. Seeking an injunction to undo one owner's unauthorised works is a personal claim, so no successor is bound by it."}, {"url": "https://hklandlaw.wordpress.com/2016/01/20/penalty-or-pre-estimate-of-loss-an-inadequate-dichotomy/", "title": "Penalty or pre-estimate of loss: an inadequate dichotomy", "date": "2016-01-20", "type": "case-note", "topics": ["penalty-clauses", "liquidated-damages", "relief-from-forfeiture", "deposits", "unconscionability"], "cases": [{"name": "Cavendish Square Holding BV v Talal El Makdessi", "citation": "[2015] UKSC 67", "court": "UKSC", "jurisdiction": "EN"}, {"name": "ParkingEye Ltd v Beavis", "citation": "[2015] UKSC 67", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Asking only whether a sum genuinely pre-estimates loss is too narrow. A clause triggered by breach survives if it protects a legitimate commercial interest without being extravagant, and unenforceable penalties fail entirely rather than partially."}, {"url": "https://hklandlaw.wordpress.com/2016/01/13/does-acceptance-of-rent-waive-a-continuing-breach-of-covenant/", "title": "Does acceptance of rent waive a continuing breach of covenant?", "date": "2016-01-13", "type": "case-note", "topics": ["waiver", "forfeiture", "continuing-breach", "user-covenant", "relief-from-forfeiture"], "cases": [{"name": "Kwok Hon Shing v Happy Team (China) Ltd", "citation": "[2015] HKEC 2038", "court": "other", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.58"], "summary": "Anti-waiver wording cannot neutralise the legal effect of taking rent knowing of a breach. With continuing user breaches, waiver reaches only what the landlord knew of at that point; suing for possession ends any later waiver."}, {"url": "https://hklandlaw.wordpress.com/2016/01/06/break-clause-implied-term-that-rent-paid-in-advance-in-respect-of-a-period-after-termination-should-be-repaid/", "title": "Break clause: implied term that rent paid in advance in respect of a period after termination should be repaid?", "date": "2016-01-06", "type": "case-note", "topics": ["implied-terms", "break-clause", "apportionment-of-rent", "leases", "contractual-interpretation"], "cases": [{"name": "Marks & Spencer plc v BNP Paribas Securities Services Trust Co (Jersey) Ltd", "citation": "[2015] UKSC 72", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Attorney General of Belize v Belize Telecom", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Apportionment Act 1870 s.2"], "summary": "A tenant breaking the lease mid-quarter recovers nothing of the advance rent absent express words, because rent is not apportionable in time and the 1870 Act rescues only rent payable in arrears. Implication demands strict necessity."}, {"url": "https://hklandlaw.wordpress.com/2015/12/30/small-house-policy-judicial-review-of-a-decision-not-to-grant-vehicular-access-over-government-land/", "title": "Small House Policy: judicial review of a decision not to grant vehicular access over Government land?", "date": "2015-12-30", "type": "case-note", "topics": ["small-house-policy", "judicial-review", "government-land", "new-territories-land", "rights-of-access"], "cases": [{"name": "Hung Hing v Director of Lands", "citation": "[2015] 5 HKLRD 516", "court": "CA", "jurisdiction": "HK"}, {"name": "Koon Ping Leung v Director of Lands", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Deciding whether to sell or grant rights over its own land, the Government acts as owner, beyond review. The policy leaves applicants to secure their own vehicular access before applying."}, {"url": "https://hklandlaw.wordpress.com/2015/12/23/a-lis-pendens-must-affect-land/", "title": "A lis pendens must affect land", "date": "2015-12-23", "type": "case-note", "topics": ["lis-pendens", "land-registration", "vacation-of-registration", "undue-influence", "indemnity-costs"], "cases": [{"name": "Luen Ford Industrial Co Ltd v Woo Ming Han Juliana", "citation": "[2015] HKEC 2639", "court": "CFI", "jurisdiction": "HK"}, {"name": "Thian's Plastics Industrial Company Limited v Tin's Chemical Industrial Company Limited", "citation": null, "court": null, "jurisdiction": null}, {"name": "Anstalt Nybro v HK Resort Company Limited", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Land Registration Ordinance s.19"], "summary": "The real fight was over shares obtained by alleged undue influence, not title, so the registration was struck out as a tactic. Freezing the proceeds sufficed, and indemnity costs followed."}, {"url": "https://hklandlaw.wordpress.com/2015/12/16/joint-ownership-of-family-home-presumption-of-equality-and-equitable-accounting/", "title": "Joint ownership of family home: presumption of equality and equitable accounting", "date": "2015-12-16", "type": "case-note", "topics": ["joint-ownership", "presumption-of-equality", "equitable-accounting", "severance", "family-home"], "cases": [{"name": "Chen lily v Yip Tsun Wah Alvan", "citation": "[2015] HKEC 2611", "court": "CFI", "jurisdiction": "HK"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Domestic joint owners share equally without tallying contributions. Departure and an offer to fund half the mortgage severed the tenancy equitably; the occupier got credit for capital repaid and shared debts, not interest."}, {"url": "https://hklandlaw.wordpress.com/2015/12/09/common-intention-constructive-trust-the-intention-to-create-the-trust-cannot-be-imputed/", "title": "Common intention constructive trust: the intention to create the trust cannot be imputed", "date": "2015-12-09", "type": "case-note", "topics": ["common-intention-constructive-trust", "imputed-intention", "quantification", "sole-name-cases", "beneficial-interests"], "cases": [{"name": "Capehorn v Harris", "citation": "[2015] EWCA Civ 955", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Where one partner alone holds title, a real agreement must be shown; courts cannot supply one. Sales LJ confined imputation to working out shares once the trust already exists, so the judge erred."}, {"url": "https://hklandlaw.wordpress.com/2015/12/02/the-courts-power-to-vacate-a-lis-pendens/", "title": "The court's power to vacate a lis pendens", "date": "2015-12-02", "type": "case-note", "topics": ["lis-pendens", "land-registration", "inherent-jurisdiction", "formalities", "vacation-of-registration"], "cases": [{"name": "Join Win Holdings Ltd v City Target Ltd", "citation": "[2015] HKEC 2477", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "Land Registration Ordinance s.19"], "summary": "Registration can be removed where proceedings are not pursued in good faith or other good cause appears, and by inherent jurisdiction. Merits matter: with no writing satisfying the formality rule, the claim could not touch the land."}, {"url": "https://hklandlaw.wordpress.com/2015/11/26/subrogation-to-the-unpaid-vendors-lien/", "title": "Subrogation to the unpaid vendor's lien", "date": "2015-11-26", "type": "case-note", "topics": ["subrogation", "vendors-lien", "unjust-enrichment", "equitable-remedies", "mortgages"], "cases": [{"name": "Bank of Cyprus UK Ltd v Menelaou", "citation": "[2015] UKSC 66", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Benedetti v Sawiris", "citation": "[2013] UKSC 50", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "A bank whose expected charge never materialised stepped into the unpaid seller's lien. Most judges reasoned through unjust enrichment against the daughter, a mere donee; Lord Carnwath preferred orthodox subrogation and Quistclose analysis."}, {"url": "https://hklandlaw.wordpress.com/2015/11/18/promissory-estoppel-hong-kong-hua-qiao-in-the-court-of-appeal/", "title": "Promissory estoppel: Hong Kong Hua Qiao in the Court of Appeal", "date": "2015-11-18", "type": "case-note", "topics": ["promissory-estoppel", "proprietary-estoppel", "detrimental-reliance", "assurances", "proportionality-of-remedy"], "cases": [{"name": "Hong Kong Hua Qiao Co Ltd v Cham Ka Tai", "citation": "[2015] HKEC 394", "court": "CA", "jurisdiction": "HK"}, {"name": "Luo Xing Juan v Estate of Hui Shee See", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Wayling v Jones", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Repeated firm assurances founded the estoppel. Reliance need not be decisive, only influential, and is presumed once promises are followed by matching conduct; earlier behaviour continuing afterwards counts. Relief should meet the expectation unless disproportionate."}, {"url": "https://hklandlaw.wordpress.com/2015/11/11/common-intention-constructive-trust-no-imputation-of-agreement-to-vary-beneficial-interests/", "title": "Common intention constructive trust: no imputation of agreement to vary beneficial interests.", "date": "2015-11-11", "type": "case-note", "topics": ["common-intention-constructive-trust", "imputed-intention", "variation-of-shares", "quantification", "cohabitation"], "cases": [{"name": "Barnes v Phillips", "citation": "[2015] EWCA Civ 1056", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Whether shares were altered must be found, not invented, though it may be inferred, as from one partner pocketing nearly all the remortgage money before separating. Only the resulting proportions may be imputed."}, {"url": "https://hklandlaw.wordpress.com/2015/11/04/legal-tenancy-in-common-contractual-interpretation/", "title": "Legal tenancy in common: contractual interpretation", "date": "2015-11-04", "type": "case-note", "topics": ["tenancy-in-common", "co-ownership", "contractual-interpretation", "constructive-trust", "new-territories-land"], "cases": [{"name": "Lam Kwok Hing v Lam Siu Keung", "citation": "[2015] HKEC 2228", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Shares between brothers holding land as tenants in common were fixed by reading the 1972 assignment, a division-of-property agreement and official certification as contract, so no constructive trust analysis was needed."}, {"url": "https://hklandlaw.wordpress.com/2015/10/28/resulting-or-express-trust/", "title": "Resulting or express trust?", "date": "2015-10-28", "type": "case-note", "topics": ["resulting-trust", "express-trust", "presumption-of-advancement", "beneficial-ownership", "formalities"], "cases": [{"name": "Ng Tak Kau v Cheung Man Kwai", "citation": "[2015] HKEC 1942", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.60", "Conveyancing and Property Ordinance s.5(1)"], "summary": "A son's name was added to title only for convenient succession, rebutting advancement; the father remained sole beneficial owner. The court labelled this an express trust, which sits oddly with its resulting-trust reasoning."}, {"url": "https://hklandlaw.wordpress.com/2015/10/21/legal-joint-tenancy-unequal-contributions-often-not-enough-to-establish-common-intention-constructive-trust-in-the-family-context/", "title": "Legal joint tenancy: unequal contributions often not enough to establish common intention constructive trust in the family context", "date": "2015-10-21", "type": "case-note", "topics": ["common-intention-constructive-trust", "joint-tenancy", "beneficial-ownership", "order-for-sale", "bankruptcy"], "cases": [{"name": "Chow Chung Kwan", "citation": "[2015] HKEC 2112", "court": "CFI", "jurisdiction": "HK"}, {"name": "Mo Ying v Brillex Developments", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}, {"name": "Oxley v Hiscock", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Ip Man Shan Henry v Ching Hing Construction Co Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Chan Chui Mee v Mak Chi Choi", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Re Lau Hiu Tuen, bankrupt", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Partition Ordinance s.6(1)"], "summary": "Where spouses hold legally as joint tenants, uneven payment of price and mortgage rarely displaces equal beneficial shares. Courts weigh the whole relationship holistically. The wife's claim failed and a sale was ordered for creditors."}, {"url": "https://hklandlaw.wordpress.com/2015/10/14/can-a-developer-retain-exclusive-use-of-the-external-walls-of-a-building-and-pass-repair-costs-onto-the-other-owners/", "title": "Can a developer retain exclusive use of the external walls of a building and pass repair costs onto the other owners?", "date": "2015-10-14", "type": "case-note", "topics": ["building-management", "deed-of-mutual-covenant", "common-parts", "repair-obligations", "external-walls"], "cases": [{"name": "Green & Grace Ltd v Wang Lung Industrial Building", "citation": "[2015] HKEC 1935", "court": "other", "jurisdiction": "HK"}, {"name": "Uniland Investment Enterprises Ltd v IO of Sea View Estate", "citation": "[1999] 4 HKC 141", "court": null, "jurisdiction": "HK"}, {"name": "鄭惠娟 對 永利中心業主立案法團及另一人", "citation": null, "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.34H(1)", "Building Management Ordinance s.34C(2)", "Conveyancing and Property Ordinance s.41"], "summary": "Keeping exclusive use of external walls carries a statutory duty to maintain them. A DMC clause shifting that burden onto other owners conflicted with s.34H and was void, leaving repair costs with the developer."}, {"url": "https://hklandlaw.wordpress.com/2015/10/07/promised-sea-view-misrepresentation-claim/", "title": "Promised sea view? Misrepresentation claim.", "date": "2015-10-07", "type": "case-note", "topics": ["misrepresentation", "sale-of-land", "entire-agreement-clause", "exemption-clauses", "damages"], "cases": [{"name": "Yang Dandan v Hong Kong Resort Co Ltd", "citation": "[2015] HKEC 2050", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Misrepresentation Ordinance s.3(1)", "Misrepresentation Ordinance s.4"], "summary": "Brochure disclaimers warning that development plans might change defeated the buyer's claim about a promised harbour view. The entire agreement clause merely superseded earlier terms rather than excluding liability, and loss was unproven."}, {"url": "https://hklandlaw.wordpress.com/2015/10/02/no-equitable-lien-where-no-part-of-the-purchase-price-has-been-paid/", "title": "No equitable lien where no part of the purchase price has been paid", "date": "2015-10-02", "type": "case-note", "topics": ["equitable-lien", "purchasers-lien", "deposit", "sale-of-land", "registration"], "cases": [{"name": "Wong Kam Fung v Smart Profit Enterprises Ltd", "citation": "[2014] 5 HKLRD 853", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A purchaser's lien needs money actually paid to the vendor towards price. An unpresented deposit cheque gave nothing, so no lien arose and the buyer's registration against the property had to be vacated."}, {"url": "https://hklandlaw.wordpress.com/2015/09/23/managers-dmc-duty-to-bring-legal-proceedings-where-necessary-enough-to-act-reasonably/", "title": "Manager's DMC duty to bring legal proceedings where necessary: enough to act reasonably?", "date": "2015-09-23", "type": "case-note", "topics": ["building-management", "deed-of-mutual-covenant", "managers-duties", "fiduciary-duty", "implied-terms"], "cases": [{"name": "Long Source Industrial Ltd v Guardian Property Management Ltd", "citation": "[2015] HKEC 1964", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "A DMC duty to take necessary action is measured by reasonableness. Declining to sue was justified where owners were already remedying the problem and the Buildings Department was enforcing; litigation would have wasted management funds."}, {"url": "https://hklandlaw.wordpress.com/2015/09/16/property-owner-in-breach-of-a-covenant-not-to-permit-or-suffer-a-nuisance-to-be-caused/", "title": "Property owner in breach of a covenant not to 'permit or suffer' a nuisance to be caused", "date": "2015-09-16", "type": "case-note", "topics": ["nuisance", "restrictive-covenants", "deed-of-mutual-covenant", "injunctions", "knowledge-requirement"], "cases": [{"name": "MTR Corp Ltd v Cheung Ching Kin", "citation": "[2015] HKEC 1535", "court": "other", "jurisdiction": "HK"}, {"name": "Realty Harvest Limited v Gold Margin Development Limited", "citation": "[2001] 1 HKC 234", "court": "CA", "jurisdiction": "HK"}, {"name": "Berton v Alliance Economic Investment Company Limited", "citation": "[1922] 1 KB 742", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "To permit or suffer covers both authorising an act and failing to take steps within one's power to stop it. Knowing of repeated noise complaints yet not restraining his daughter, the owner breached; injunction granted."}, {"url": "https://hklandlaw.wordpress.com/2015/09/09/making-time-of-the-essence-for-completion/", "title": "Making time of the essence for completion", "date": "2015-09-09", "type": "case-note", "topics": ["time-of-the-essence", "completion", "specific-performance", "sale-of-land", "repudiatory-breach"], "cases": [{"name": "Many Gain Investment Ltd v Chan Fai Ho", "citation": "[2015] HKEC 1553", "court": "CFI", "jurisdiction": "HK"}, {"name": "United Scientific Holdings Ltd v Burnley Borough Council", "citation": "[1978] AC 904", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A solicitor's letter demanding withdrawal of a requisition did not make time essential, and five days was in any event too short given the vendor's own unreadiness. Specific performance was ordered despite delay."}, {"url": "https://hklandlaw.wordpress.com/2015/09/02/adverse-possession-the-effect-of-being-added-as-a-party-after-expiry-of-the-limitation-period-to-proceedings-begun-within-the-limitation-period/", "title": "Adverse possession: the effect of being added as a party after expiry of the limitation period to proceedings begun within the limitation period", "date": "2015-09-02", "type": "case-note", "topics": ["adverse-possession", "limitation-period", "joinder-of-parties", "animus-possidendi", "recovery-of-land"], "cases": [{"name": "Yu Fung Co Ltd v Olympic City Properties Ltd", "citation": "[2015] HKEC 1523", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.35(1)(b)", "Limitation Ordinance s.35(2)(a)", "Limitation Ordinance s.35(3)"], "summary": "Adding a defendant after limitation expired counted as a new claim relating back to the original writ, defeating the limitation defence. Time ran from the buyer taking possession intending to exclude everyone, vendor included."}, {"url": "https://hklandlaw.wordpress.com/2015/08/26/implied-terms-the-tension-between-the-plain-meaning-of-the-words-and-an-evident-commercial-purpose/", "title": "Implied terms: the tension between the plain meaning of the words and an evident commercial purpose", "date": "2015-08-26", "type": "case-note", "topics": ["implied-terms", "contractual-interpretation", "commercial-purpose", "development-agreements", "profit-share"], "cases": [{"name": "Aberdeen City Council v Stewart Milne Group", "citation": "[2011] UKSC 56", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "A developer's intra-group sale at undervalue would have gutted the council's profit share. The court implied a term that non-arm's-length disposals be valued at open market rates, letting commercial purpose override literal wording."}, {"url": "https://hklandlaw.wordpress.com/2015/08/24/where-there-are-two-arguable-interpretations-of-a-contractual-provision-it-is-reasonable-to-have-regard-to-the-commercial-consequences-of-the-rival-approaches/", "title": "Where there are two arguable interpretations of a contractual provision it is reasonable to have regard to the commercial consequences of the rival approaches", "date": "2015-08-24", "type": "case-note", "topics": ["contractual-interpretation", "business-common-sense", "guarantees", "ambiguity", "commercial-consequences"], "cases": [{"name": "Rainy Sky SA v Kookmin Bank", "citation": "[2011] UKSC 50", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Faced with two tenable readings of a refund guarantee, the court chose the one making business sense and rejected the bank's construction. Where wording is unambiguous, however, it governs whatever the commercial outcome."}, {"url": "https://hklandlaw.wordpress.com/2015/08/19/the-common-intention-constructive-trust-post-acquisition-statements-in-ones-own-interest-promissory-estoppel-the-limits-of-luo-xing-juan-v-estate-of-hui-shui-see/", "title": "The common intention constructive trust: post-acquisition statements in one's own interest. Promissory estoppel: the limits of Luo Xing Juan v Estate of Hui Shui See", "date": "2015-08-19", "type": "case-note", "topics": ["common-intention-constructive-trust", "promissory-estoppel", "evidence-admissibility", "beneficial-ownership", "joint-tenancy"], "cases": [{"name": "Chan Sung Lai v Chan Sung Lim Paul", "citation": "[2015] HKEC 1366", "court": "other", "jurisdiction": "HK"}, {"name": "Shepherd v Cartwright", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Overseas Trust Bank v Lee See Ching Jong", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Luo Xing Juan v Estate of Hui Shui See", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Self-serving statements made after acquisition cannot prove beneficial ownership, so title governed. Promissory estoppel also failed: no existing legal right was identified, and neither a clear enough representation nor detrimental reliance was shown."}, {"url": "https://hklandlaw.wordpress.com/2015/08/14/co-habitation-and-equitable-accounting/", "title": "Co-habitation and equitable accounting", "date": "2015-08-14", "type": "case-note", "topics": ["equitable-accounting", "cohabitation", "co-ownership", "mortgage-payments", "common-intention"], "cases": [{"name": "Wilcox v Tait", "citation": "[2006] EWCA Civ 1867", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Equitable accounting is not automatic between separating cohabitees. Courts may infer from living together that neither intended to charge the other for outgoings, so unequal mortgage payments during the relationship need not be reimbursed."}, {"url": "https://hklandlaw.wordpress.com/2015/08/12/the-brocklesbury-principle-postponing-an-owners-rights-to-those-of-a-later-lender-or-purchaser/", "title": "The Brocklesbury principle: postponing an owner's rights to those of a later lender or purchaser", "date": "2015-08-12", "type": "case-note", "topics": ["priority-of-interests", "brocklesbury-principle", "agency", "mortgages", "pallant-v-morgan-equity"], "cases": [{"name": "Credit and Mercantile plc v Kaymuu Ltd", "citation": "[2015] EWCA Civ 655", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Brocklesbury v Temperance Permanent BS", "citation": "[1895] AC 173", "court": "HL", "jurisdiction": "EN"}, {"name": "Abbey National Building Society v Cann", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Land Registration Act 2002 s.29"], "summary": "An owner who lets an agent appear to be the owner, without flagging limits on authority, bears the fraud risk. The beneficiary's Pallant v Morgan equity was therefore postponed to the innocent lender's charge."}, {"url": "https://hklandlaw.wordpress.com/2015/08/05/the-common-intention-constructive-trust-is-an-express-trust/", "title": "The common intention constructive trust is an express trust", "date": "2015-08-05", "type": "case-note", "topics": ["common-intention-constructive-trust", "express-trust", "formalities", "bankruptcy", "beneficial-ownership"], "cases": [{"name": "Yip Yuk Kwong v Yip Chun Yin", "citation": "[2015] HKEC 1312", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A solicitor son was named on title only to obtain cheaper conveyancing while his father funded the purchase and mortgage. A common intention constructive trust arose, dispensing with written formalities, and survived the son's bankruptcy."}, {"url": "https://hklandlaw.wordpress.com/2015/07/29/one-tenant-in-common-can-bring-possession-proceedings/", "title": "One tenant in common can bring possession proceedings", "date": "2015-07-29", "type": "case-note", "topics": ["tenancy-in-common", "co-ownership", "recovery-of-possession", "mesne-profits", "leases"], "cases": [{"name": "Chan Po King v Yau Wai Yin", "citation": "[2015] HKEC 1283", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A holdover tenant argued every co-owner landlord had to sue. The Court of Appeal disagreed: one tenant in common may recover possession alone, exercising her own right to possession once the fixed term expired."}, {"url": "https://hklandlaw.wordpress.com/2015/07/22/interpretation-of-service-charge-clauses/", "title": "Interpretation of service charge clauses", "date": "2015-07-22", "type": "case-note", "topics": ["contractual-interpretation", "service-charges", "leases", "letting-scheme", "implied-terms"], "cases": [{"name": "Arnold v Britton", "citation": "[2015] UKSC 36", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Fixed 10% annual escalation of service charges was enforced as written despite producing extravagant sums. Courts cannot rewrite a bargain because inflation behaved unexpectedly, and service charge clauses attract no special interpretive rule. Lord Carnwath dissented."}, {"url": "https://hklandlaw.wordpress.com/2015/07/15/england-where-one-beneficial-joint-tenant-is-excluded-from-possession/", "title": "England: Where one beneficial joint tenant is excluded from possession", "date": "2015-07-15", "type": "case-note", "topics": ["beneficial-joint-tenancy", "occupation-rights", "equitable-accounting", "order-for-sale", "overriding-interests"], "cases": [{"name": "Begum v Issa", "citation": null, "court": "other", "jurisdiction": "EN"}, {"name": "Clarke v Harlowe", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Wilcox v Tait", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Land Registration Act 2002 s.29", "Trusts of Land and Appointment of Trustees Act 1996 s.12", "Trusts of Land and Appointment of Trustees Act 1996 s.13(1)", "Trusts of Land and Appointment of Trustees Act 1996 s.14", "Trusts of Land and Appointment of Trustees Act 1996 s.15"], "summary": "Actual occupation preserved a sister's equitable share against a fraudulent transfer. Sale was postponed a year to weigh her housing and her child's needs against the brother's investment, and no accounting was required for cohabitation outgoings."}, {"url": "https://hklandlaw.wordpress.com/2015/07/08/deed-of-gift-where-the-donor-held-the-property-on-trust/", "title": "Deed of gift where the donor held the property on trust", "date": "2015-07-08", "type": "case-note", "topics": ["deed-of-gift", "resulting-trust", "beneficial-ownership", "trustees", "nemo-dat"], "cases": [{"name": "Leung Mee Kuen v Leung Siu Kuen Bessie", "citation": "[2015] HKEC 1148", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A mother gifted her registered share, but she held only bare legal title for her children under a resulting trust. Having no beneficial entitlement herself, she could pass none, so the gift moved nothing substantive."}, {"url": "https://hklandlaw.wordpress.com/2015/07/01/agreement-to-transfer-beneficial-interest-proprietary-estoppel-as-a-way-of-circumventing-the-lack-of-formalities/", "title": "Agreement to transfer beneficial interest: proprietary estoppel as a way of circumventing a failure to satisfy the formalities", "date": "2015-07-01", "type": "case-note", "topics": ["proprietary-estoppel", "formalities", "assignment-of-equitable-interest", "detrimental-reliance", "beneficial-ownership"], "cases": [{"name": "Sum Fan Hung v Chum Mei Diu", "citation": "[2015] HKEC 1100", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.5(1)(a)"], "summary": "An oral swap of beneficial ownership for taking over the mortgage breached the writing requirement for assigning equitable interests. Proprietary estoppel rescued it: the promise was an assurance and the assumed mortgage payments were detrimental reliance."}, {"url": "https://hklandlaw.wordpress.com/2015/06/24/a-person-in-possession-of-property-has-the-right-to-eject-a-later-possessor/", "title": "A person in possession of property has the right to eject a later possessor", "date": "2015-06-24", "type": "case-note", "topics": ["possessory-title", "relativity-of-title", "estoppel-by-agreement", "mesne-profits", "abandonment"], "cases": [{"name": "Chan Hau Ling v 劉西", "citation": "[2015] HKEC 1095", "court": "CFI", "jurisdiction": "HK"}, {"name": "Asher v Whitlock", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Mabo v Queensland (No 2)", "citation": null, "court": null, "jurisdiction": "AU"}, {"name": "Manchester Airport plc v Dutton", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Earlier possession, whether as owner or licensee, beats a later occupier. The abandonment defence had no support, and entry under an agreement estopped the occupier from disputing title. Possession and market-rate mesne profits followed."}, {"url": "https://hklandlaw.wordpress.com/2015/06/17/the-common-intention-constructive-trust-is-not-limited-to-the-domestic-consumer-context/", "title": "The common intention constructive trust is not limited to the 'domestic consumer' context", "date": "2015-06-17", "type": "case-note", "topics": ["common-intention-constructive-trust", "commercial-property", "joint-names", "presumption-of-equality", "beneficial-ownership"], "cases": [{"name": "Chan Sang v Chan Kwok", "citation": "[2015] HKEC 822", "court": "CFI", "jurisdiction": "HK"}, {"name": "Laskar v Laskar", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "A brother's name sat on shop title only as security for a family loan the plaintiff repaid alone. The doctrine reaches commercial property; only the equality presumption for joint names is confined to domestic settings."}, {"url": "https://hklandlaw.wordpress.com/2015/06/10/post-acquisition-constructive-trust-evidential-burden-where-there-is-reliance-on-an-express-statement-detriment-where-the-plaintiffs-benefit-outweigh-any-detriment/", "title": "Post-acquisition constructive trust: evidential burden where there is reliance on an express statement. Detriment: where the plaintiff's benefit outweigh any detriment", "date": "2015-06-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "post-acquisition-trust", "proprietary-estoppel", "detriment", "standard-of-proof"], "cases": [{"name": "Kwan So Ling v Woo Kee Yiu Harry", "citation": "[2015] HKEC 694", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "The heavier proof standard for post-acquisition trusts falls away when an express promise is alleged. Modest partition spending was outweighed by rental benefits received, and moving to Hong Kong out of affection lacked causal link to any assurance."}, {"url": "https://hklandlaw.wordpress.com/2015/06/03/common-intention-constructive-trust-the-family-context-confirms-equality-in-a-joint-names-case-severance-contractual-licence-granted-by-tenant-in-common-binding-on-a-subsequent-owner-of-the-licenso/", "title": "Common intention constructive trust: the family context confirms equality in a joint names case. Severance: contractual licence granted by tenant in common binding on a subsequent owner of the licensor's share", "date": "2015-06-03", "type": "case-note", "topics": ["common-intention-constructive-trust", "joint-names", "contractual-licence", "severance", "notice"], "cases": [{"name": "Chen Tek Yee v Chan Moon Shing", "citation": "[2015] HKEC 735", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Unequal contributions did not displace equal shares where the couple bought a permanent family home. Assurances of lifelong occupation, relied on to detriment, created a licence binding a purchaser with notice who bought at a discount."}, {"url": "https://hklandlaw.wordpress.com/2015/05/27/proving-the-existence-of-a-common-intention-constructive-trust-in-sole-name-cases-is-marriage-enough-beneficiaries-have-a-duty-to-inform-purchasers-where-they-are-aware-that-a-contract-has-been-sign/", "title": "Proving the existence of a common intention constructive trust in sole name cases: is marriage enough?", "date": "2015-05-27", "type": "case-note", "topics": ["common-intention-constructive-trust", "sole-name-cases", "detrimental-reliance", "estoppel-by-silence", "purchaser-protection"], "cases": [{"name": "Mo Ying v Brillex Development Ltd", "citation": "[2015] HKEC 583", "court": "CA", "jurisdiction": "HK"}, {"name": "Grant v Edwards", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Eves v Eves", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Abbott v Abbott", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Being married is only one strand in the whole course of conduct, never enough by itself in sole-name cases. Vague remarks proved nothing, detrimental reliance is still required, and a silent beneficiary risks estoppel against buyers."}, {"url": "https://hklandlaw.wordpress.com/2015/05/20/sale-and-option-to-re-purchase-does-the-option-terminate-the-original-buyers-rights/", "title": "Sale and option to re-purchase: does the option terminate the original buyer's rights?", "date": "2015-05-20", "type": "case-note", "topics": ["options-to-purchase", "equitable-interest", "specific-performance", "sale-of-land", "remedies"], "cases": [{"name": "Siu Kai Ming v Lau Sai Hing", "citation": "[2015] HKEC 211", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Granting and exercising a repurchase option simply produced a second contract; it did not destroy the equitable interest the developer already held under the first. He could still seek specific performance or elect damages."}, {"url": "https://hklandlaw.wordpress.com/2015/05/13/adverse-possession-paving-land-as-evidence-of-possession/", "title": "Adverse possession: Paving land as evidence of possession", "date": "2015-05-13", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "animus-possidendi", "limitation", "extinguishment-of-title"], "cases": [{"name": "Tsoi Ping Hung v Cheung Chow Lan", "citation": "[2015] HKEC 701", "court": "CA", "jurisdiction": "HK"}, {"name": "Powell v McFarlane", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Clearing, levelling and paving land in 2000, which left a six-foot drop to the adjoining ditch, amounted to factual possession before any fence went up. Intention was clearly evidenced, and the owners' title was extinguished."}, {"url": "https://hklandlaw.wordpress.com/2015/05/06/the-common-intention-constructive-trust-and-the-specious-excuse/", "title": "The common intention constructive trust and the 'specious' excuse", "date": "2015-05-06", "type": "case-note", "topics": ["common-intention-constructive-trust", "excuse-cases", "detrimental-reliance", "family-home", "inferred-agreement"], "cases": [{"name": "Curran v Collins", "citation": "[2015] EWCA Civ 404", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Eves v Eves", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Grant v Edwards", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Offering a reason for leaving a partner off the deeds does not automatically imply she was promised a share. No pre-existing family unit acquired the home and reliance was missing, so the claim failed."}, {"url": "https://hklandlaw.wordpress.com/2015/04/29/common-intention-constructive-trust-arising-on-a-family-division/", "title": "Common intention constructive trust arising on a family division", "date": "2015-04-29", "type": "case-note", "topics": ["common-intention-constructive-trust", "family-division", "detriment", "limitation", "constructive-trustee"], "cases": [{"name": "Yip Chiu Fu v Ip Chiu Fat", "citation": "[2015] HKEC 201", "court": "CFI", "jurisdiction": "HK"}, {"name": "Lloyds Bank v Rosset", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Graham-York v York", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Chan Chui Mee", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.20(1)(b)"], "summary": "Dividing family-funded land between branches created a constructive trust, the detriment being each branch surrendering claims to the others' allocations. No limitation period bars recovery against constructive trustees, and silence after a broken promise was not acquiescence."}, {"url": "https://hklandlaw.wordpress.com/2015/04/22/presumption-of-advancement-and-participation-in-an-unlawful-scheme/", "title": "Presumption of advancement and participation in an unlawful scheme", "date": "2015-04-22", "type": "case-note", "topics": ["presumption-of-advancement", "illegality", "resulting-trust", "small-house-policy", "new-territories-land"], "cases": [{"name": "Yip Wai Hong v Yip Kai Tong", "citation": "[2015] HKEC 501", "court": "CFI", "jurisdiction": "HK"}, {"name": "Tribe v Tribe", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Calverly v Green", "citation": null, "court": null, "jurisdiction": "AU"}], "statutes": [], "summary": "Advancement still applies robustly to father-to-son transfers and need not be pleaded. The father could not rebut it, because doing so meant relying on his own participation in an unlawful sale of villagers' Ting rights."}, {"url": "https://hklandlaw.wordpress.com/2015/04/15/inchoate-encroachment-claims-did-the-handover-start-time-running-again/", "title": "Inchoate encroachment claims: did the Handover start time running again?", "date": "2015-04-15", "type": "case-note", "topics": ["encroachment", "adverse-possession", "limitation", "government-land", "basic-law"], "cases": [{"name": "Li Kwok Ching v Secretary for Justice", "citation": "[2015] HKEC 552", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.7(1)", "Basic Law Article 120"], "summary": "The claim failed for want of sixty years' possession, but the court rejected the argument that 1997 reset time. The SAR merely succeeded the British Government, and Article 120 preserved encroachment rights existing at the Handover."}, {"url": "https://hklandlaw.wordpress.com/2015/04/08/missing-title-deeds-showing-good-title-in-accordance-with-section-13-of-the-conveyancing-and-property-ordinance/", "title": "Missing title deeds: showing good title in accordance with section 13 of the Conveyancing and Property Ordinance", "date": "2015-04-08", "type": "case-note", "topics": ["good-title", "title-deeds", "encumbrances", "sale-of-land", "statutory-declaration"], "cases": [{"name": "Zhang Xueshai v Lai Chin Wing", "citation": "[2015] HKEC 295", "court": "CA", "jurisdiction": "HK"}, {"name": "De Monsa Investments", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.13", "Housing Ordinance s.17B"], "summary": "Absent deeds matter only if they create a real risk of an encumbrance surviving completion. Past loans, cancelled agreements and charging orders raised that risk; a declaration by someone lacking personal knowledge could not dispel it."}, {"url": "https://hklandlaw.wordpress.com/2015/04/01/interpretation-of-a-letter-modifying-conditions-of-sale/", "title": "Interpretation of a letter modifying conditions of sale", "date": "2015-04-01", "type": "case-note", "topics": ["government-lease", "contractual-interpretation", "conditions-of-sale", "building-covenants", "admissibility-of-context"], "cases": [{"name": "United Bright Limited v Secretary for Justice", "citation": "[2015] HKEC 438", "court": "CA", "jurisdiction": "HK"}, {"name": "Fully Profit (Asia) Limited v Secretary for Justice", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Ying Ho Co Ltd v Secretary for Justice", "citation": null, "court": "CFA", "jurisdiction": "HK"}, {"name": "Hang Wah Chong Investment Ltd v AG", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Cherry Tree Investments Ltd v Landmain Limited", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["New Territories Ordinance s.13", "Conveyancing and Property Ordinance s.13", "Buildings Ordinance"], "summary": "A 1957 modification letter allowing flats did not free the lessee from the design, disposition and height restriction, so 37 storeys were impermissible. Background correspondence was admissible, unlike under the English registration approach."}, {"url": "https://hklandlaw.wordpress.com/2015/03/25/compensation-paid-on-the-resumption-of-land-is-not-land-for-the-purposes-of-section-13-of-the-new-territories-ordinance/", "title": "Compensation paid on the resumption of land is not 'land' for the purposes of section 13 of the New Territories Ordinance", "date": "2015-03-25", "type": "case-note", "topics": ["new-territories-ordinance", "chinese-custom", "land-resumption", "trusts", "statutory-interpretation"], "cases": [{"name": "Lok Tin Choi v Lai Kwai Lin", "citation": "[2015] HKEC 389", "court": "CA", "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance s.13", "New Territories Ordinance s.2"], "summary": "Money paid when the Government resumes New Territories land falls outside the statutory definition of land, so the power to apply Chinese custom does not reach it. Earlier Tong compensation cases decided no differently."}, {"url": "https://hklandlaw.wordpress.com/2015/03/18/the-limitation-ordinance-and-tenancies-without-a-lease-in-writing/", "title": "The Limitation Ordinance and tenancies 'without a lease in writing'", "date": "2015-03-18", "type": "case-note", "topics": ["limitation", "periodic-tenancy", "adverse-possession", "tenancy-by-estoppel", "estoppel-by-convention"], "cases": [{"name": "Mitchell v Watkinson", "citation": "[2014] EWCA Civ 1472", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance s.12(2)", "New Territories Ordinance s.13"], "summary": "Continued rent payments generated a fresh implied periodic tenancy, surrendering the earlier written one. Being unwritten, it engaged the provision restarting time from the last rent received. The estoppel by convention argument lacked any shared assumption."}, {"url": "https://hklandlaw.wordpress.com/2015/03/11/legal-joint-tenancy-determining-beneficial-ownership-under-a-common-intention-constructive-trust/", "title": "Legal joint tenancy: determining beneficial ownership under a common intention constructive trust", "date": "2015-03-11", "type": "case-note", "topics": ["common-intention-constructive-trust", "joint-tenancy", "equity-follows-the-law", "adverse-possession", "ouster"], "cases": [{"name": "Lo Kau Kun v Cheung Yuk Yun", "citation": "[2015] HKEC 316", "court": "CFI", "jurisdiction": "HK"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Joint legal title presumptively yields equal beneficial shares, and the challenger bears the burden. The couple's shared view that the flat was a family asset decided the split, not contribution figures. No ouster meant no adverse possession between co-owners."}, {"url": "https://hklandlaw.wordpress.com/2015/03/03/interpretation-of-a-clause-barring-requisitions-about-unauthorised-structures-justification-of-a-large-deposit/", "title": "Interpretation of a clause barring requisitions about unauthorised structures. Justification of a large deposit.", "date": "2015-03-03", "type": "case-note", "topics": ["requisitions", "title", "exclusion-clauses", "deposits", "unauthorised-structures", "sale-of-land"], "cases": [{"name": "Channel Green Ltd v Huge Grand Ltd", "citation": "[2015] 1 HKLRD 655", "court": "CA", "jurisdiction": "HK"}, {"name": "Jumbo King", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Buildings Ordinance"], "summary": "A widely drafted clause barring requisitions over unauthorised structures bound purchasers who contracted knowing of the defects, illegal structure meaning anything built against the law, lease or DMC. A deposit above the customary ten percent required objective justification, supplied here by a long completion period carrying market risk."}, {"url": "https://hklandlaw.wordpress.com/2015/02/24/landlords-repairing-covenant-the-scope-of-the-rule-in-obrien-v-robinson/", "title": "Landlord's repairing covenant: the scope of the rule in O'Brien v Robinson", "date": "2015-02-24", "type": "case-note", "topics": ["repairing-covenant", "landlord-and-tenant", "notice-of-disrepair", "demised-premises", "leases"], "cases": [{"name": "Edwards v Kumarasamy", "citation": "[2015] EWCA Civ 20", "court": "EWCA", "jurisdiction": "EN"}, {"name": "O'Brien v Robinson", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "British Telecommunications plc v Sun Life Assurance Society plc", "citation": "[1996] Ch 69", "court": "other", "jurisdiction": "EN"}], "statutes": ["Landlord and Tenant Act 1985 s.11"], "summary": "Liability for disrepair normally bites the moment a defect appears. The notice exception is confined to defects inside the demised premises, so a landlord was liable for a defective paved area lying outside them."}, {"url": "https://hklandlaw.wordpress.com/2015/02/17/common-intention-constructive-trust-valuation-in-sole-name-cases-where-there-is-no-actual-agreement-as-to-how-ownership-is-shared/", "title": "Common intention constructive trust: valuation in sole name cases where there is no actual agreement as to how ownership is shared", "date": "2015-02-17", "type": "case-note", "topics": ["common-intention-constructive-trust", "sole-name-cases", "quantification", "imputed-intention", "fairness"], "cases": [{"name": "Graham-York v York", "citation": "[2015] EWCA Civ 72", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Where sharing is established but proportions cannot be found, the court imputes an intention judged fair across the whole dealings with the property. This is not redistribution, and sole-name cases carry no equality presumption; twenty-five percent stood."}, {"url": "https://hklandlaw.wordpress.com/2015/02/10/deposit-where-sums-are-described-as-a-deposit-but-the-escape-clauses-in-the-provisional-agreement-have-been-deleted/", "title": "Deposit: where sums are described as a deposit but the 'escape' clauses in the provisional agreement have been deleted", "date": "2015-02-10", "type": "case-note", "topics": ["deposits", "forfeiture", "provisional-agreement", "contractual-interpretation", "repudiation"], "cases": [{"name": "Best Linkage Ltd v Marbella Garden Ltd", "citation": "[2015] HKEC 167", "court": "CFI", "jurisdiction": "HK"}, {"name": "Polyset Ltd v Panhandat Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "The Golden Leader", "citation": null, "court": null, "jurisdiction": "other"}], "statutes": [], "summary": "Calling money a deposit brings the usual forfeiture consequences even after express escape clauses were struck out. Deleted wording cannot be read as agreeing the opposite where the text is unambiguous, so the vendor kept the money."}, {"url": "https://hklandlaw.wordpress.com/2015/02/04/does-a-charging-order-sever-a-joint-tenancy/", "title": "Does a charging order sever a joint tenancy?", "date": "2015-02-04", "type": "case-note", "topics": ["severance", "joint-tenancy", "charging-orders", "four-unities", "judgment-enforcement"], "cases": [{"name": "Ho Hai Kwan v Chan Hon Kuen", "citation": "[2015] HKEC 132", "court": "CFI", "jurisdiction": "HK"}, {"name": "Malahon Credit Co Ltd v Siu Chun Wah Alice", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Fortis Bank v Yu Kam Hoi Herman", "citation": null, "court": "CA", "jurisdiction": "HK"}], "statutes": ["High Court Ordinance s.20B(3)"], "summary": "A charging order merely encumbers a debtor's share without transferring title. It leaves the four unities intact and lacks the finality of an alienation, so it does not sever a beneficial joint tenancy."}, {"url": "https://hklandlaw.wordpress.com/2015/01/27/liability-of-incorporated-owners-selling-items-left-by-residents-in-common-areas/", "title": "Liability of Incorporated owners selling items left by residents in common areas", "date": "2015-01-27", "type": "case-note", "topics": ["building-management", "involuntary-bailment", "conversion", "common-parts", "deed-of-mutual-covenant"], "cases": [{"name": "Desir Anthony C v Knight Frank (Services) Ltd", "citation": "[2015] HKEC 44", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Owners' corporations holding abandoned bicycles were involuntary bailees. Selling them converted the goods: the DMC gave no power to sell, and clearing an obstruction is not the commercial necessity that excuses disposal. Damages equalled sale-date value."}, {"url": "https://hklandlaw.wordpress.com/2015/01/20/purchasers-from-squatters-take-subject-to-equitable-interests-of-which-they-have-notice/", "title": "Purchasers from squatters take subject to equitable interests of which they have notice", "date": "2015-01-20", "type": "case-note", "topics": ["restrictive-covenants", "adverse-possession", "doctrine-of-notice", "bona-fide-purchaser", "investigation-of-title"], "cases": [{"name": "Re Nisbet and Potts' Contract", "citation": "[1906] 1 Ch. 386", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Restrictive covenants outlive the paper title they burdened. A squatter takes subject to them regardless of notice, and someone buying from the squatter who skimps on the full title investigation has constructive notice and is bound."}, {"url": "https://hklandlaw.wordpress.com/2015/01/12/closure-of-basement-parking-area-during-renovation-works/", "title": "Closure of basement parking area during renovation works", "date": "2015-01-12", "type": "case-note", "topics": ["building-management", "deed-of-mutual-covenant", "nuisance", "common-parts", "reasonableness"], "cases": [{"name": "Tung Lo Court (IO) v Leung May Chun Alison Aliance", "citation": "[2014] HKEC 2104", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Shutting a flooded basement car park for four months on contractor safety advice breached neither the DMC nor nuisance law. Safety warnings, exposure to injury claims and cheaper faster works all made the decision reasonable."}, {"url": "https://hklandlaw.wordpress.com/2015/01/05/construction-of-dmc-were-parking-spaces-common-parts/", "title": "Construction of DMC: were parking spaces common parts?", "date": "2015-01-05", "type": "case-note", "topics": ["deed-of-mutual-covenant", "common-parts", "contractual-interpretation", "undivided-shares", "car-parking"], "cases": [{"name": "Tai Fat Development (Holding) Co Ltd v Gold King Industrial Building (IO)", "citation": "[2014] HKEC 2130", "court": "CA", "jurisdiction": "HK"}, {"name": "Jumbo King", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Thirteen bays were common parts, not retained by the developer. The DMC labelled them so, no undivided shares attached, they were distinguished from allocated Parking Spaces, and loading access for outsiders pointed the same way."}, {"url": "https://hklandlaw.wordpress.com/2014/12/15/common-intention-constructive-trusts-where-the-agreement-is-formed-for-an-unlawful-purpose-does-tinsley-v-milligan-apply/", "title": "Common intention constructive trusts where the agreement is formed for an unlawful purpose: does Tinsley v Milligan apply?", "date": "2014-12-15", "type": "case-note", "topics": ["common-intention-constructive-trust", "illegality", "unlawful-purpose", "reliance-principle", "family-home"], "cases": [{"name": "O'Kelly v Davies", "citation": "[2014] EWCA Civ 1606", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Tinsley v Milligan", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Barrett v Barrett", "citation": null, "court": "other", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Note on O'Kelly v Davies: a common intention constructive trust can arise despite the parties' unlawful purpose where the claim is proved by conduct and contributions without pleading the illegality, extending Tinsley v Milligan reliance reasoning; contrasted with Barrett v Barrett, where the illegal purpose had to be invoked."}, {"url": "https://hklandlaw.wordpress.com/2014/12/01/common-intention-constructive-trust-abandonment-after-jones-v-kernott/", "title": "Common intention constructive trust - abandonment after Jones v Kernott", "date": "2014-12-01", "type": "case-note", "topics": ["common-intention-constructive-trust", "joint-names", "abandonment", "ambulatory-intention", "family-home"], "cases": [{"name": "Quintance v Tandan", "citation": "[2012] EWHC 4416 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Note on Quintance v Tandan: a joint legal owner who paid nothing and walked away shortly after purchase lost his beneficial share; applying Jones v Kernott, the court treated post-acquisition conduct as varying the original intention or as grounding a fair, fact-sensitive outcome."}, {"url": "https://hklandlaw.wordpress.com/2014/11/10/looking-after-the-family-as-detrimental-reliance/", "title": "Looking after the family as detrimental reliance?", "date": "2014-11-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "detrimental-reliance", "indirect-contributions", "family-home", "imputed-intention"], "cases": [{"name": "HKCB Finance Ltd v Yuen Yi Wan", "citation": "[2006] HKEC 1425", "court": "CA", "jurisdiction": "HK"}, {"name": "Burns v Burns", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Hong Kong Court of Appeal refused a wife's constructive trust claim built on childcare, housework and modest payments, finding them not referable to any shared ownership intention; Cheung JA dissented, urging a Canadian/New Zealand-style imputed intention approach to domestic contributions."}, {"url": "https://hklandlaw.wordpress.com/2014/05/23/proprietary-estoppel-holistic-approach-to-detriment/", "title": "Proprietary estoppel: holistic approach to detriment", "date": "2014-05-23", "type": "case-note", "topics": ["proprietary-estoppel", "detrimental-reliance", "holistic-assessment", "appellate-review"], "cases": [{"name": "Davies v Davies", "citation": "[2014] EWCA Civ 568", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Suggitt v Suggitt", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Gillett v Holt", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Discusses the English Court of Appeal upholding a holistic weighing of benefits against burdens when assessing detrimental reliance in a farm-inheritance estoppel claim, deferring to the trial judge's balancing of lost employment advantages against free accommodation absent perversity."}, {"url": "https://hklandlaw.wordpress.com/2014/05/13/common-intention-constructive-trust-and-equitys-darling/", "title": "Common intention constructive trust and equity's darling", "date": "2014-05-13", "type": "case-note", "topics": ["common-intention-constructive-trust", "detrimental-reliance", "constructive-notice", "bona-fide-purchaser", "laches"], "cases": [{"name": "Mo Ying v Brillex Development Ltd", "citation": "[2014] HKEC 724", "court": "CFI", "jurisdiction": "HK"}, {"name": "Grant v Edwards", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Eves v Eves", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance s.20(2)"], "summary": "Hong Kong decision holding that marriage alone cannot ground a common intention constructive trust; an excuse for omitting a spouse from title must be equivocal and induce belief; household contributions were insufficient detriment; and purchaser notice and estoppel arguments against the buyer largely failed."}, {"url": "https://hklandlaw.wordpress.com/2013/10/10/common-intention-constructive-trust-or-resulting-trust/", "title": "Common intention constructive trust or resulting trust?", "date": "2013-10-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "detrimental-reliance", "limitation-periods", "family-home"], "cases": [{"name": "Liu Wai Keung v Liu Wai Man", "citation": "[2013] HKEC 1567", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.20"], "summary": "Hong Kong case treating a family home financed by one relative but titled in another as raising a common intention constructive trust rather than a resulting trust; payments under the acquisition agreement supplied detriment, and the titleholder could not plead limitation against the beneficiary in enjoyment."}, {"url": "https://hklandlaw.wordpress.com/2013/08/08/missing-title-deeds-giving-good-title-and-yiu-ping-fong/", "title": "Missing title deeds, giving good title and Yiu Ping Fong", "date": "2013-08-08", "type": "case-note", "topics": ["title-deeds", "good-title", "conveyancing", "equitable-charge", "land-registration"], "cases": [{"name": "De Monsa Investments Ltd v Whole Win Management Fund Ltd", "citation": "[2013] HKEC 1162", "court": "CFA", "jurisdiction": "HK"}, {"name": "Yiu Ping Fong v Lam Lai Hing", "citation": null, "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.13A", "Land Registration Ordinance"], "summary": "Hong Kong Court of Final Appeal ruling that a vendor need not produce every missing original title deed; good title is only imperilled where the absence creates a real, not fanciful, risk of undisclosed registrable encumbrances, and unwritten deposit-based charges cannot defeat the purchaser."}, {"url": "https://hklandlaw.wordpress.com/2013/02/15/when-is-there-sufficient-evidence-that-a-resulting-trust-has-been-brought-to-an-end/", "title": "When is there sufficient evidence that a resulting trust has been brought to an end?", "date": "2013-02-15", "type": "case-note", "topics": ["resulting-trust", "termination-of-trust", "limitation-of-actions", "constructive-trust", "title-defects"], "cases": [{"name": "Rose Palace Ltd v Jung Christopher Lam", "citation": "[2013] HKEC 146", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.7(2)", "Limitation Ordinance s.20(1)(b)"], "summary": "CFI accepted a solicitor's statutory declaration recording the beneficiary's assent, corroborated by years of silence, as proof that a purchase-money resulting trust had ended; limitation protection was denied to dishonest stranger constructive trustees, letting the vendor establish good title."}, {"url": "https://hklandlaw.wordpress.com/2012/12/19/trusts-alienation-and-the-home-ownership-scheme/", "title": "Trusts, 'alienation' and the Home Ownership Scheme", "date": "2012-12-19", "type": "case-note", "topics": ["resulting-trust", "constructive-trust", "home-ownership-scheme", "alienation-restrictions", "statutory-interpretation"], "cases": [{"name": "Cheuk Shu Yin v Yip So Wan", "citation": "[2012] HKEC 1554", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Housing Ordinance s.17B", "Housing Ordinance s.27A"], "summary": "The CFA ruled that a trust over a Home Ownership Scheme flat is not prohibited 'alienation' under the Housing Ordinance: trusts arising by operation of law involve no positive act, the scheme targets speculative resale, and family purchase-price contributors deserve beneficial interests."}, {"url": "https://hklandlaw.wordpress.com/2012/11/26/common-intention-constructive-trust-applying-jones-v-kernott/", "title": "Common intention constructive trust? Applying Jones v Kernott.", "date": "2012-11-26", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "imputed-intention", "beneficial-ownership", "family-property"], "cases": [{"name": "Geary v Rankine", "citation": "[2012] EWCA Civ 555", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Jones v Kernott", "citation": null, "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "English Court of Appeal applied Jones v Kernott: a common intention constructive trust needs actual shared intention, express or inferred from conduct; imputation only quantifies an established interest. A claim over a commercially purchased property failed absent any shared ownership intention."}, {"url": "https://hklandlaw.wordpress.com/2011/12/31/weekly-review-27th-30th-december-2011/", "title": "Weekly Review: 27th - 30th December 2011", "date": "2011-12-31", "type": "overview", "topics": ["easements", "implied-easements", "proprietary-estoppel", "conveyancing"], "cases": [{"name": "Alford v Hannaford", "citation": null, "court": null, "jurisdiction": null}, {"name": "Pang Chi Yeung v Lau Yuk Choi", "citation": null, "court": null, "jurisdiction": null}, {"name": "Pridean Ltd v Forest Taverns Ltd", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Conveyancing and Property Ordinance s.16", "Law of Property Act 1925 s.62"], "summary": "Round-up of the week: construing a deed's easement against the factual matrix despite a wrong plan, the diversity of occupation limit on implied easements, a buyer rescued after the seller vanished, and estoppel failing with collapsed negotiations."}, {"url": "https://hklandlaw.wordpress.com/2011/12/30/the-factual-matrix-and-the-construction-of-easements/", "title": "The factual matrix and the construction of easements", "date": "2011-12-30", "type": "case-note", "topics": ["easements", "deed-construction", "implied-easements", "diversity-of-occupation", "factual-matrix"], "cases": [{"name": "Alford v Hannaford", "citation": "[2011] EWCA Civ 1099", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Kung Ming Tak Tong Co Ltd v Park Solid Enterprises Ltd", "citation": "(2008) 11 HKCFAR 403", "court": "CFA", "jurisdiction": "HK"}, {"name": "Wong Kwan Yee v Incorporated Owners of Diamond Mansion", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.16", "Law of Property Act 1925 s.62"], "summary": "A deed's grant is read against the parties' shared background, so an inaccurate attached plan gave way to the route intended. Section 62 needed diversity of occupation, which a grazing licensee's seasonal use could not supply."}, {"url": "https://hklandlaw.wordpress.com/2011/12/29/no-proprietary-estoppel-when-the-expectation-depended-on-failed-joint-venture-negotiations/", "title": "No proprietary estoppel when the expectation depended on failed joint venture negotiations", "date": "2011-12-29", "type": "case-note", "topics": ["proprietary-estoppel", "joint-venture", "failed-negotiations", "detrimental-reliance"], "cases": [{"name": "Pridean Ltd v Forest Taverns Ltd", "citation": "(1998) 75 P. & C.R. 447", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Work done in anticipation of a joint venture generated no estoppel: the only expectation encouraged was of an interest through the company that never came about, so nothing survived the breakdown. Compensation for outlay had to be claimed separately."}, {"url": "https://hklandlaw.wordpress.com/2011/12/27/a-long-delayed-completion/", "title": "A long-delayed completion", "date": "2011-12-27", "type": "case-note", "topics": ["conveyancing", "completion", "title", "specific-performance"], "cases": [{"name": "Pang Chi Yeung v Lau Yuk Choi", "citation": "[2011] HKEC 1666", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A purchaser who had paid by instalments and occupied the property obtained a conveyance directly from the true owner after the intermediate seller vanished; the long gap before the compliance certificate surfaced did not defeat the claim."}, {"url": "https://hklandlaw.wordpress.com/2011/12/24/weekly-review-19th-23rd-december/", "title": "Weekly review: 19th - 23rd December", "date": "2011-12-24", "type": "overview", "topics": ["adverse-possession", "conveyancing", "proprietary-estoppel", "estoppel-by-convention", "easements"], "cases": [{"name": "Wai Wah Traders Ltd v Wong Yim", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Active Keen Industries Ltd v Fok Chi-Keong", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Edwin Shirley Productions Ltd v Workspace Management Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "James v Evans", "citation": null, "court": null, "jurisdiction": null}, {"name": "Valentine v Allen", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "Week's summary: trivial acts do not establish possession; vendors must show good title and answer requisitions candidly; estoppel cannot spring from subject to contract talks; and reliance on an agreed access route can raise an equitable easement."}, {"url": "https://hklandlaw.wordpress.com/2011/12/23/estoppel-arising-from-an-agreement-as-to-the-layout-of-an-internal-access-road-on-a-development-site/", "title": "Estoppel arising from an agreement as to the layout of an internal access road on a development site", "date": "2011-12-23", "type": "case-note", "topics": ["proprietary-estoppel", "estoppel-by-convention", "easements", "detrimental-reliance", "development"], "cases": [{"name": "Valentine v Allen", "citation": "[2002] EWCA Civ 915", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Owners who settled an access road layout at a site meeting and then built and conveyed in reliance were bound. Estoppel, whether proprietary or by convention, produced equitable easements that inaccurate deed descriptions could not displace."}, {"url": "https://hklandlaw.wordpress.com/2011/12/22/common-sense-when-raising-and-answering-requisitions/", "title": "Less is more: Common sense when raising and answering requisitions", "date": "2011-12-22", "type": "case-note", "topics": ["conveyancing", "requisitions", "good-title", "open-contract", "solicitors-duties"], "cases": [{"name": "Active Keen Industries Ltd v Fok Chi-Keong", "citation": "[1994] 1 HKLR 396", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Under an open contract the vendor must show good title and answer material requisitions. Where nothing further exists, say so: piling up documents that miss the point can lose a case the vendor should have won."}, {"url": "https://hklandlaw.wordpress.com/2011/12/21/proprietary-estoppel-and-rent-free-periods/", "title": "Proprietary estoppel and rent free periods", "date": "2011-12-21", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "constructive-trust", "commercial-negotiations", "leases"], "cases": [{"name": "Edwin Shirley Productions Ltd v Workspace Management Ltd", "citation": "[2001] 2 EGLR 16", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Assurances given while negotiations remained subject to contract could not found an estoppel or constructive trust, and the claim failed anyway because arrears exceeded the supposed rent-free period. Equity is a hard sell in commercial dealings."}, {"url": "https://hklandlaw.wordpress.com/2011/12/20/article-on-kerr-v-baranow-in-the-conveyancer-and-property-lawyer/", "title": "Article on Kerr v Baranow in the Conveyancer and Property Lawyer", "date": "2011-12-20", "type": "overview", "topics": ["constructive-trust", "unjust-enrichment", "cohabitation", "common-intention", "joint-family-venture"], "cases": [{"name": "Kerr v Baranow", "citation": null, "court": "other", "jurisdiction": "other"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Flags a Conveyancer article on the Canadian Supreme Court's use of unjust enrichment to divide assets in joint family ventures, and asks whether that approach and the English common intention trust, post-Stack, are converging."}, {"url": "https://hklandlaw.wordpress.com/2011/12/20/adverse-possession-relatively-trivial-acts-on-land-can-mean-that-there-is-neither-possession-nor-intention-to-possess/", "title": "Adverse possession: relatively trivial acts on land can mean that there is neither possession nor intention to possess", "date": "2011-12-20", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "intention-to-possess", "limitation"], "cases": [{"name": "Wai Wah Traders Ltd v Wong Yim", "citation": "[2011] HKEC 1624", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Picking fruit and trimming branches, however often repeated, amounted to persistent trespass rather than possession. A squatter must show open, single and effective control judged against the land's character, sustained across the full limitation period."}, {"url": "https://hklandlaw.wordpress.com/2011/12/19/proprietary-estoppel-and-subject-to-contract-proposed-lease-of-a-farm/", "title": "Proprietary estoppel and subject to contract: proposed lease of a farm", "date": "2011-12-19", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "formalities", "leases", "unconscionability"], "cases": [{"name": "James v Evans", "citation": "[2000] 3 EGLR 1", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Attorney-General of Hong Kong v Humphrey's Estate (Queen's Gardens) Ltd", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "A prospective tenant who took possession during subject to contract negotiations got no estoppel: the owner stayed free to walk away unless refusing would be unconscionable, and writing remained essential to a binding land contract."}, {"url": "https://hklandlaw.wordpress.com/2011/12/17/weekly-review-12th-16th-december/", "title": "Weekly review: 12th - 16th December", "date": "2011-12-17", "type": "overview", "topics": ["duress", "encroachment", "government-lease", "subject-to-contract", "licences"], "cases": [{"name": "Mir Abdul Rehman v Mir Heena", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Secretary for Justice v Chau Ka Chik Tso", "citation": null, "court": "CFA", "jurisdiction": "HK"}, {"name": "Derby & Co Ltd v ITC Pension Trust Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "Maharaj v Chand", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["New Territories (Renewable Government Leases) Ordinance (Cap. 152)"], "summary": "The week in brief: gifts made under duress can be undone; a tenant's encroachment is presumed added to the lease and may become irrecoverable until it ends; subject to contract talks bind nobody; and a personal licence is no dealing."}, {"url": "https://hklandlaw.wordpress.com/2011/12/16/2040/", "title": "Gift of land and duress", "date": "2011-12-16", "type": "case-note", "topics": ["duress", "gift", "resulting-trust", "beneficial-ownership", "co-ownership"], "cases": [{"name": "Mir Abdul Rehman v Mir Heena", "citation": "[2011] HKEC 1644", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "A deed of gift procured by duress can be set aside, but here nothing showed the property was meant to be held on trust, so the donee took both legal and beneficial ownership under the 2001 deed."}, {"url": "https://hklandlaw.wordpress.com/2011/12/15/promissory-estoppel-and-permanent-licence-to-occupy-family-home/", "title": "Promissory estoppel and permanent licence to occupy family home", "date": "2011-12-15", "type": "case-note", "topics": ["promissory-estoppel", "licences", "family-home", "cohabitation", "statutory-consent"], "cases": [{"name": "Maharaj v Chand", "citation": "[1986] 3 W.L.R. 440", "court": "PC", "jurisdiction": "other"}], "statutes": ["Native Land Trust Act s.12"], "summary": "A woman who gave up her flat and spent savings on the strength of a promise could resist eviction: a purely personal licence, unlike a constructive trust, needed no statutory consent and so escaped the prohibition on dealings."}, {"url": "https://hklandlaw.wordpress.com/2011/12/14/article-on-bruton-in-kings-law-journal/", "title": "Article on Bruton in King's Law Journal", "date": "2011-12-14", "type": "overview", "topics": ["non-proprietary-lease", "relativity-of-title", "leases", "estate-in-land"], "cases": [{"name": "Bruton v London & Quadrant Housing Trust", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Mexfield Housing Co-operative Ltd v Berrisford", "citation": "[2011] UKSC 52", "court": "UKSC", "jurisdiction": "EN"}], "statutes": [], "summary": "Notes an article probing what Bruton rests on. Lord Neuberger's relativity of title would let the trust's own possession support a grant, keeping leases proprietary, whereas Lord Hoffmann denied the occupier held any title at all."}, {"url": "https://hklandlaw.wordpress.com/2011/12/14/gift-in-contemplation-of-marriage-and-resulting-trust/", "title": "Gift in contemplation of marriage and resulting trust", "date": "2011-12-14", "type": "case-note", "topics": ["resulting-trust", "gift", "contemplation-of-marriage", "part-performance", "beneficial-ownership"], "cases": [{"name": "Lai Chung Ming v Fung Kar Luen Candy", "citation": "[2011] HKEC 1633", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Property handed over in expectation of a marriage that never happened was recoverable on a resulting trust, and an oral promise to reconvey, backed by part performance in the form of payment, could also be enforced."}, {"url": "https://hklandlaw.wordpress.com/2011/12/13/estoppel-and-lease-renewal-negotiations/", "title": "Estoppel and lease renewal negotiations", "date": "2011-12-13", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "lease-renewal", "forbearance", "leases"], "cases": [{"name": "Derby & Co Ltd v ITC Pension Trust Ltd", "citation": "[1977] 2 All ER 890", "court": null, "jurisdiction": "EN"}], "statutes": ["Landlord and Tenant Act 1954 Part II"], "summary": "Renewal terms negotiated subject to contract left both sides free to withdraw, especially where the tenant kept its statutory right to have terms fixed by the court. Nor could estoppel be built on unprompted forbearance over interim rent."}, {"url": "https://hklandlaw.wordpress.com/2011/12/12/the-doctrine-of-encroachment-in-the-court-of-final-appeal/", "title": "The doctrine of encroachment in the Court of Final Appeal", "date": "2011-12-12", "type": "case-note", "topics": ["encroachment", "adverse-possession", "limitation", "government-lease", "leases"], "cases": [{"name": "Secretary for Justice v Chau Ka Chik Tso", "citation": "[2011] HKEC 1617", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.7", "Limitation Ordinance s.17", "New Territories (Renewable Government Leases) Ordinance (Cap. 152)", "New Territories Leases (Extension) Ordinance"], "summary": "A tenant who encroaches on the landlord's neighbouring land is presumed to hold it as part of the demise; once time runs the landlord waits until the lease ends. Statutory renewal did not restart the clock, and the doctrine's basis stayed contested."}, {"url": "https://hklandlaw.wordpress.com/2011/12/10/weekly-review-5th-9th-december/", "title": "Weekly review: 5th - 9th December", "date": "2011-12-10", "type": "overview", "topics": ["collateral-contracts", "constructive-trust", "pallant-v-morgan", "forfeiture", "resulting-trust"], "cases": [{"name": "Inntrepreneur Pub Company Ltd v East Crown Ltd", "citation": "[2007] EWCA Civ 622", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Business Environment Bow Lane Ltd v Deanwater Estates Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": null}, {"name": "Baynes Clarke v Corless", "citation": null, "court": null, "jurisdiction": null}, {"name": "New G Mei Uk Restaurant v Tin Kwok Keung", "citation": null, "court": null, "jurisdiction": null}, {"name": "Tang Wai Cho v Tang Wai Leung", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "Recaps posts on when pre-contract statements become collateral warranties, the Pallant v Morgan constructive trust arising from an agreement not to bid, the hazards of peaceable re-entry, and how courts test who really paid the purchase price."}, {"url": "https://hklandlaw.wordpress.com/2011/12/09/pallant-v-morgan/", "title": "Pallant v Morgan", "date": "2011-12-09", "type": "case-note", "topics": ["constructive-trust", "pallant-v-morgan", "detrimental-reliance", "joint-venture", "specific-performance"], "cases": [{"name": "Pallant v Morgan", "citation": "[1953] Ch 43", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Neighbours agreed that one would bid alone and share the land afterwards. Uncertain boundaries and price ruled out specific performance, but because the other held back from bidding equity intervened, ordering division or sale with equal profits."}, {"url": "https://hklandlaw.wordpress.com/2011/12/08/proving-a-purchase-price-resulting-trust/", "title": "Proving a purchase price resulting trust", "date": "2011-12-08", "type": "case-note", "topics": ["resulting-trust", "purchase-price", "beneficial-ownership", "evidence"], "cases": [{"name": "Tang Wai Cho v Tang Wai Leung", "citation": "[2011] HKEC 1570", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "The claimant failed to show he had put up the purchase money for property registered in another's name. The court weighed what the parties said and did from the outset, plus the documents, rather than bare assertion."}, {"url": "https://hklandlaw.wordpress.com/2011/12/07/elements-of-a-pallant-v-morgan-equity/", "title": "Elements of a Pallant v Morgan equity", "date": "2011-12-07", "type": "case-note", "topics": ["constructive-trust", "pallant-v-morgan", "detrimental-reliance", "joint-venture"], "cases": [{"name": "Baynes Clarke v Corless", "citation": "[2010] EWCA Civ 338", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Sets out the equity's ingredients: an agreement that one party acquire the property, an understanding it is for both, and consequent advantage or detriment. Leaving the legal mechanism open does not matter, but without reliance the claim fails."}, {"url": "https://hklandlaw.wordpress.com/2011/12/06/forfeiture-by-peaceable-re-entry-caught-in-the-cross-fire/", "title": "Forfeiture by peaceable re-entry: caught in the cross-fire?", "date": "2011-12-06", "type": "case-note", "topics": ["forfeiture", "peaceable-re-entry", "trespass", "leases", "solicitors-liability"], "cases": [{"name": "New G Mei Uk Restaurant v Tin Kwok Keung", "citation": "[2002] HKEC 255", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "A re-entry staged through a neighbouring unit exposed everyone to trespass and breach of lease claims. The neighbouring tenant's action against the advising solicitors failed, but the episode shows how risky self-help forfeiture can be."}, {"url": "https://hklandlaw.wordpress.com/2011/12/05/statements-during-negotiations-as-collateral-contracts/", "title": "Statements during negotiations as collateral contracts", "date": "2011-12-05", "type": "case-note", "topics": ["collateral-contracts", "pre-contract-statements", "formalities", "conveyancing", "entire-agreement"], "cases": [{"name": "Inntrepreneur Pub Company Ltd v East Crown Ltd", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Business Environment Bow Lane Ltd v Deanwater Estates Ltd", "citation": "[2007] EWCA Civ 622", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "Sets out the markers of a collateral warranty. A statement left out of the eventual contract, made well before it and followed by more bargaining, rarely binds, and where solicitors act commercially everything agreed is expected to reach the documents."}, {"url": "https://hklandlaw.wordpress.com/2011/12/05/weekly-review-28th-november-2nd-decmber/", "title": "Weekly review: 28th November - 2nd December", "date": "2011-12-05", "type": "overview", "topics": ["constructive-trust", "alienation", "proprietary-estoppel", "common-intention", "agency"], "cases": [{"name": "Ling Wing Fai Billy v Ling Shui Fai", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Herbert v Doyle", "citation": null, "court": null, "jurisdiction": null}, {"name": "Brightlingsea Haven Ltd v Morris", "citation": null, "court": null, "jurisdiction": null}, {"name": "Wisecal Ltd v Conwell International Ltd", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Housing Ordinance s.17B(1)"], "summary": "The week covered: a common intention trust counting as an alienation even when agreed before purchase; the conditions defeating a constructive trust from informal dealings; estoppel and trust arising from shared expectations; and pleading challenges to an agent's authority."}, {"url": "https://hklandlaw.wordpress.com/2011/12/02/agents-authority-limited-to-open-contract/", "title": "Agent's authority: limited to open contract?", "date": "2011-12-02", "type": "case-note", "topics": ["agency", "authority", "land-contracts", "conveyancing", "pleadings"], "cases": [{"name": "Wisecal Ltd v Conwell International Ltd", "citation": "[2011] 4 HKLRD 275", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Authority to sell at a set price carried authority to sign a contract on usual terms, including liquidated damages. A principal disputing that must plead it; raising the point in closing submissions came far too late."}, {"url": "https://hklandlaw.wordpress.com/2011/12/01/proprietary-estoppel-and-constructive-trusts-again/", "title": "Proprietary estoppel and constructive trusts (again)", "date": "2011-12-01", "type": "case-note", "topics": ["proprietary-estoppel", "constructive-trust", "assurances", "formalities", "leases"], "cases": [{"name": "Brightlingsea Haven Ltd v Morris", "citation": "[2008] EWHC 1928 (QB)", "court": "other", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "Assurances about tenure, permitted use and rent rises, given by one company, bound its sister and generated both an estoppel and a constructive trust, with relief left over. The overlap with section 2 remains awkward."}, {"url": "https://hklandlaw.wordpress.com/2011/11/30/the-meaning-of-alienation/", "title": "The meaning of 'alienation'", "date": "2011-11-30", "type": "case-note", "topics": ["alienation", "constructive-trust", "common-intention", "public-housing", "statutory-restrictions"], "cases": [{"name": "Ling Wing Fai Billy v Ling Shui Fai", "citation": "[2010] 6 HKC 434", "court": "CA", "jurisdiction": "HK"}, {"name": "Re A Solicitor", "citation": "[2000] HKCU 1003", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Housing Ordinance s.17B(1)"], "summary": "Agreeing that a flat would be held on a common intention trust was an alienation under section 17B(1), even though made before purchase and between relatives; alienation covers positive acts creating rights that bite on core ownership. Later reversed on appeal."}, {"url": "https://hklandlaw.wordpress.com/2011/11/29/when-can-an-informal-agreement-give-rise-to-a-constructive-trust/", "title": "When can an informal agreement give rise to a constructive trust?", "date": "2011-11-29", "type": "case-note", "topics": ["constructive-trust", "informal-agreement", "proprietary-estoppel", "certainty-of-terms"], "cases": [{"name": "Herbert v Doyle", "citation": "[2010] EWCA Civ 1095", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "No constructive trust arises where the parties expected a formal contract, left essential terms open so the interest cannot be identified, and did not mean to be bound at once. Minor gaps in an otherwise certain bargain can be filled."}, {"url": "https://hklandlaw.wordpress.com/2011/11/28/adverse-possession-of-a-lane-between-two-buildings/", "title": "Adverse possession of a lane between two buildings", "date": "2011-11-28", "type": "case-note", "topics": ["adverse-possession", "limitation", "common-parts", "building-management"], "cases": [{"name": "黄景廉 v 牡丹大厦業主立案法團", "citation": "[2011] HKEC 1487", "court": "other", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance"], "summary": "A shopkeeper who used a scavenging lane behind his premises for storage was held to have possessed both sections for more than the twenty years needed, defeating the incorporated owners' claim to recover the strip."}, {"url": "https://hklandlaw.wordpress.com/2011/11/26/weekly-review-21st-25th-november/", "title": "Weekly Review: 21st - 25th November", "date": "2011-11-26", "type": "overview", "topics": ["co-ownership", "proprietary-estoppel", "building-management", "title-defects", "easements"], "cases": [{"name": "Chen Yu Tsui v Tong Kui Kwong", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Chaudhay v Yavuz", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Chi Kit Co Ltd v Lucky Health International Enterprise Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Salvation Army Trustee Co Ltd v West Yorkshire Metropolitan County Council", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Willmott v Barber", "citation": null, "court": null, "jurisdiction": null}, {"name": "Lyus v Prowsa", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Building Management Ordinance s.17(1)(b)"], "summary": "Digest of the week: when a rent-collecting co-owner must account, why informal interests seldom bind purchasers without registration, incorporated owners' liabilities as title defects, and the narrow room for estoppel in subject to contract dealings."}, {"url": "https://hklandlaw.wordpress.com/2011/11/25/lyus-an-exceptional-case/", "title": "Lyus an exceptional case", "date": "2011-11-25", "type": "case-note", "topics": ["constructive-trust", "proprietary-estoppel", "easements", "land-registration", "purchaser-without-notice"], "cases": [{"name": "Chaudhay v Yavuz", "citation": "[2011] EWCA Civ 1314", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Lyus v Prowsa", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Land Registration Act 2002"], "summary": "An informal easement resting on estoppel did not bind the buyer. A general clause about discoverable incumbrances leaves the conscience untouched; Lyus turned on a specific undertaking, and the failure to enter a notice told against the claim."}, {"url": "https://hklandlaw.wordpress.com/2011/11/24/when-is-one-co-owner-who-collected-rent-liable-to-account-to-the-other/", "title": "When is one co-owner who collected rent liable to account to the other?", "date": "2011-11-24", "type": "overview", "topics": ["co-ownership", "duty-to-account", "agency", "constructive-trust", "limitation"], "cases": [{"name": "Chen Yu Tsui v Tong Kui Kwong", "citation": "[2005] HKEC 1679", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.20(1)"], "summary": "Co-ownership alone imposes no duty to account for rents. Liability follows where the collector acts as agent or bailiff, or on partition, administration or a constructive trust claim; here an implied agency arose and limitation did not bar the action."}, {"url": "https://hklandlaw.wordpress.com/2011/11/23/subject-to-contract-and-a-land-exchange/", "title": "'Subject to contract' and a land exchange", "date": "2011-11-23", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "acquiescence", "part-performance", "land-exchange"], "cases": [{"name": "Salvation Army Trustee Co Ltd v West Yorkshire Metropolitan County Council", "citation": "(1981) 41 P. & C.R. 179", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Exceptionally, estoppel survived a subject to contract label: the council let the charity take the new site and build, then stayed silent while it acted on the assumption of commitment. The successor authority inherited the resulting equity."}, {"url": "https://hklandlaw.wordpress.com/2011/11/22/owner-for-the-purposes-of-section-171b-of-the-building-management-ordiunance/", "title": "'Owner' for the purposes of section 17(1)(b) of the Building Management Ordinance", "date": "2011-11-22", "type": "case-note", "topics": ["building-management", "incorporated-owners", "title-defects", "co-ownership", "conveyancing"], "cases": [{"name": "Chi Kit Co Ltd v Lucky Health International Enterprise Ltd", "citation": "[2002] 2 HKLRD 503", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.17(1)(b)"], "summary": "Owner means whoever owns the share at the time, so an incorporated owners' unexpected liability attaches to the new purchaser. That exposure is an incumbrance and a defect in title which a buyer cannot be made to accept."}, {"url": "https://hklandlaw.wordpress.com/2011/11/21/willmott-v-barber/", "title": "Willmott v Barber", "date": "2011-11-21", "type": "case-note", "topics": ["proprietary-estoppel", "acquiescence", "five-probanda", "leases", "specific-performance"], "cases": [{"name": "Willmott v Barber", "citation": "(1880) L.R. 15 Ch. D. 96", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Fry J's five requirements for estoppel by acquiescence: the claimant's mistake, expenditure on it, the owner's knowledge of his own right and of the mistake, and his encouragement. Without all five, a written consent requirement stands."}, {"url": "https://hklandlaw.wordpress.com/2011/11/19/weekly-review-14th-18th-november/", "title": "Weekly review: 14th - 18th November", "date": "2011-11-19", "type": "overview", "topics": ["certainty-of-term", "proprietary-estoppel", "customary-law", "leases", "formalities"], "cases": [{"name": "Tang Kap Wing Tso v Tang Leuk Tso", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Actionstrength Ltd v International Glass Engineering In.GL.en SpA", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Mexfield Housing Co-operative Ltd v Berrisford", "citation": null, "court": null, "jurisdiction": null}, {"name": "Siew Soon Wah v Yong Tong Hong", "citation": null, "court": null, "jurisdiction": null}, {"name": "Matharu v Matharu", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Statute of Frauds"], "summary": "Weekly digest: fong heads' consent binding a tso, oral guarantees defeated by the Statute of Frauds, uncertain terms taking effect as leases for life, statutory caps supplying certainty for permanent tenancies, and expectation capping estoppel relief."}, {"url": "https://hklandlaw.wordpress.com/2011/11/18/consent-of-the-heads-of-fongs-signifies-the-consent-of-all-of-the-members/", "title": "Consent of the heads of fongs signifies the consent of all of the members", "date": "2011-11-18", "type": "case-note", "topics": ["customary-law", "tso", "new-territories", "consent", "land-transfer"], "cases": [{"name": "Tang Kap Wing Tso v Tang Leuk Tso", "citation": "[2011] 4 HKLRD 132", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Customary law treats the heads of the fongs as speaking for all members, and a sole fong head can consent alone. Absent active dissent, the buying side's managers need not probe the transferring tso's internal affairs."}, {"url": "https://hklandlaw.wordpress.com/2011/11/17/permanent-tenancy-void-for-uncertainty/", "title": "'Permanent' tenancy: void for uncertainty?", "date": "2011-11-17", "type": "case-note", "topics": ["certainty-of-term", "leases", "proprietary-estoppel", "statutory-limits"], "cases": [{"name": "Siew Soon Wah v Yong Tong Hong", "citation": "[1973] 2 W.L.R. 713", "court": "PC", "jurisdiction": "other"}], "statutes": [], "summary": "A permanent tenancy escaped invalidity because local legislation capped leases at thirty years, supplying the missing maximum. Where the lease itself could not be enforced, estoppel could still protect an occupier who had paid and stayed."}, {"url": "https://hklandlaw.wordpress.com/2011/11/16/matharu-v-matharu/", "title": "Matharu v Matharu", "date": "2011-11-16", "type": "case-note", "topics": ["proprietary-estoppel", "family-home", "detrimental-reliance", "licence-for-life", "remedy"], "cases": [{"name": "Matharu v Matharu", "citation": "(1994) 26 H.L.R. 648", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A father let his daughter-in-law believe the house was her husband's; she stayed and spent on it. Estoppel gave her a licence to occupy for life, subject to paying outgoings, rather than any share of ownership."}, {"url": "https://hklandlaw.wordpress.com/2011/11/15/a-lease-for-an-uncertain-term-granted-to-an-individual-is-a-lease-for-life/", "title": "A lease for an uncertain term granted to an individual is a lease for life", "date": "2011-11-15", "type": "case-note", "topics": ["certainty-of-term", "lease-for-life", "leases", "contractual-licence", "notice-to-quit"], "cases": [{"name": "Mexfield Housing Co-operative Ltd v Berrisford", "citation": "[2011] UKSC 52", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.149(6)"], "summary": "An uncertain term granted to a person took effect at common law as a lease for life, converted by section 149(6) into a ninety-year term determinable on notice. The Supreme Court doubted the certainty rule but left it standing."}, {"url": "https://hklandlaw.wordpress.com/2011/11/14/estoppel-and-the-statute-of-frauds/", "title": "Estoppel and the Statute of Frauds", "date": "2011-11-14", "type": "case-note", "topics": ["estoppel", "statute-of-frauds", "formalities", "guarantees", "part-performance"], "cases": [{"name": "Actionstrength Ltd v International Glass Engineering In.GL.en SpA", "citation": "[2003] UKHL 17", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Statute of Frauds s.4"], "summary": "Relying on an oral guarantee is not enough to sidestep the writing requirement: since giving credit is what a guarantee is for, reliance alone adds nothing. Some further inducement, or a payment made, would be needed."}, {"url": "https://hklandlaw.wordpress.com/2011/11/12/weekly-review-7th-11th-november/", "title": "Weekly Review: 7th - 11th November", "date": "2011-11-12", "type": "overview", "topics": ["constructive-trust", "proprietary-estoppel", "common-intention", "licences", "co-ownership"], "cases": [{"name": "Re Sharpe", "citation": null, "court": null, "jurisdiction": null}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Ha Yuet Chi v Yeung Yiu Keung", "citation": null, "court": "other", "jurisdiction": "HK"}, {"name": "Lam Sik Shi v Lam Sik Ying", "citation": null, "court": null, "jurisdiction": null}, {"name": "A v B", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "Digest: a life licence generating a trust or estoppel that binds those with notice, the joint names presumption and objectively deduced common intention, trustees' duties on sale, and estoppel refused where negotiations stayed incomplete."}, {"url": "https://hklandlaw.wordpress.com/2011/11/11/jones-v-kernott-in-the-supreme-court/", "title": "Jones v Kernott in the Supreme Court", "date": "2011-11-11", "type": "case-note", "topics": ["common-intention", "constructive-trust", "joint-names", "imputed-intention", "family-home"], "cases": [{"name": "Jones v Kernott", "citation": "[2011] UKSC 53", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Kernott v Jones", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Joint names without a declaration presume equal beneficial shares, rebuttable by a different intention at purchase or later. Intention is found objectively across the whole dealings, and where none can be inferred the court may impute a share."}, {"url": "https://hklandlaw.wordpress.com/2011/11/10/licence-for-life-binding-on-trustee-in-bankruptcy/", "title": "Licence for life binding on trustee in bankruptcy", "date": "2011-11-10", "type": "case-note", "topics": ["licences", "constructive-trust", "proprietary-estoppel", "bankruptcy", "notice"], "cases": [{"name": "Re Sharpe", "citation": "[1980] 1 W.L.R. 219", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "A licence for life between aunt and nephew produced a constructive trust close to proprietary estoppel, binding the trustee in bankruptcy, who took with notice. Whether a purchaser without notice would be bound was left open."}, {"url": "https://hklandlaw.wordpress.com/2011/11/09/beneficiary-seeking-order-for-sale-account-in-an-interlocutory-application/", "title": "Beneficiary seeking order for sale / account in an interlocutory application", "date": "2011-11-09", "type": "case-note", "topics": ["trusts", "interlocutory-relief", "sale-at-undervalue", "lis-pendens", "constructive-trustee"], "cases": [{"name": "Lam Sik Shi v Lam Sik Ying", "citation": "[2008] HKEC 1048", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A beneficiary alleging a sale at undervalue was refused interim orders for sale of the property, payment into court and a receiver: registering a lis pendens already gave enough protection pending trial."}, {"url": "https://hklandlaw.wordpress.com/2011/11/08/stack-v-dowden-in-hong-kong/", "title": "Stack v Dowden in Hong Kong", "date": "2011-11-08", "type": "case-note", "topics": ["common-intention", "constructive-trust", "co-ownership", "beneficial-ownership", "family-home"], "cases": [{"name": "Ha Yuet Chi v Yeung Yiu Keung", "citation": "[2010] HKEC 1726", "court": "other", "jurisdiction": "HK"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Holding as joint tenants at law does not fix the beneficial shares. In family disputes the court reads the parties' intentions from their history rather than tallying contributions arithmetically, and will not presume an outright gift."}, {"url": "https://hklandlaw.wordpress.com/2011/11/07/failed-contractual-negotiations-and-proprietary-estoppel-after-cobbe/", "title": "Failed contractual negotiations and proprietary estoppel after Cobbe", "date": "2011-11-07", "type": "case-note", "topics": ["proprietary-estoppel", "failed-negotiations", "constructive-trust", "pallant-v-morgan", "quantum-meruit"], "cases": [{"name": "A v B", "citation": "[2008] EWCH 2687", "court": "other", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "After Cobbe, an expectation tied to concluding negotiations rather than to a defined interest cannot found estoppel, and no owner is estopped from relying on facts both sides knew. A quantum meruit still rewarded the services rendered."}, {"url": "https://hklandlaw.wordpress.com/2011/11/05/weekly-review-31st-october-4th-november/", "title": "Weekly Review: 31st October - 4th November", "date": "2011-11-05", "type": "overview", "topics": ["building-management", "common-parts", "constructive-trust", "conveyancing", "proprietary-estoppel"], "cases": [{"name": "Hollywood Shopping Centre Owners Committee Ltd v Wing Wah Building Mongkok Kowloon (IO)", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Hapeshi v Allnatt", "citation": null, "court": null, "jurisdiction": null}, {"name": "Chinawell Management Ltd v Strong Huge Corp Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Gonthier v Orange Contract Scaffolding Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "Pakwell Investment Ltd v CRC Department Store", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Building Management Ordinance"], "summary": "The week: incorporated owners cannot permanently waive deed of mutual covenant duties, co-owners gain no easements over shared parts, trusts inferred from the whole course of dealing, cautious answers to late requisitions, and estoppel needing real detriment."}, {"url": "https://hklandlaw.wordpress.com/2011/11/04/owner-placing-advertising-hoardings-on-a-common-part/", "title": "Owner placing advertising hoardings on a common part", "date": "2011-11-04", "type": "case-note", "topics": ["common-parts", "building-management", "easements", "adverse-possession", "deed-of-mutual-covenant"], "cases": [{"name": "Hollywood Shopping Centre Owners Committee Ltd v Wing Wah Building Mongkok Kowloon (IO)", "citation": "[2011] 4 HKLRD 623", "court": "CA", "jurisdiction": "HK"}, {"name": "Wheeldon v Burrows", "citation": null, "court": null, "jurisdiction": null}, {"name": "China Field", "citation": null, "court": null, "jurisdiction": null}, {"name": "Attorney-General of Hong Kong v Fairfax", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Building Management Ordinance"], "summary": "Hoardings on an external wall used common parts for private gain and had to stop. Adverse possession fell short, quasi-easement and lost modern grant arguments failed among co-owners, and acquiescence barred profits for the years tolerated."}, {"url": "https://hklandlaw.wordpress.com/2011/11/03/proprietary-estoppel-and-very-clear-assurances-given-in-the-course-of-negotiations/", "title": "Proprietary estoppel and very clear assurances given in the course of negotiations", "date": "2011-11-03", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "assurances", "clean-hands", "formalities"], "cases": [{"name": "Attorney-General v Humphrey's Estate", "citation": null, "court": null, "jurisdiction": null}, {"name": "Gillett v Holt", "citation": null, "court": null, "jurisdiction": null}, {"name": "Gonthier v Orange Contract Scaffolding Ltd", "citation": "[2003] EWCA Civ 873", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "Repeated and unambiguous assurances can support estoppel even where the promisee knows they may be withdrawn, a pull against the Humphrey's Estate line. Here false invoices cost the claimant clean hands and the relief with it."}, {"url": "https://hklandlaw.wordpress.com/2011/11/02/contractual-negotiations-and-proprietary-estoppel-the-need-for-detrimental-reliance/", "title": "Contractual negotiations and proprietary estoppel: the need for detrimental reliance", "date": "2011-11-02", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "detrimental-reliance", "negotiations", "leases"], "cases": [{"name": "Pakwell Investment Ltd v CRC Department Store", "citation": "[2002] HKEC 112", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A subject to contract heading in early letters coloured the later exchanges too. Even assuming an assurance, spending that any party would expect to incur while a deal progresses is not the detriment estoppel demands."}, {"url": "https://hklandlaw.wordpress.com/2011/11/01/joint-name-case-quantifying-the-beneficial-interest-by-reference-to-the-whole-course-of-conduct/", "title": "Joint name case: quantifying the beneficial interest by reference to the whole course of conduct", "date": "2011-11-01", "type": "case-note", "topics": ["common-intention", "constructive-trust", "joint-names", "beneficial-ownership", "family-home"], "cases": [{"name": "Hapeshi v Allnatt", "citation": "[2010] EWHC 392", "court": "other", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Beneficial shares in a jointly bought home were inferred from everything the parties did, not just any express agreement. Misunderstandings about what joint tenancy meant could displace the apparent effect of the paperwork."}, {"url": "https://hklandlaw.wordpress.com/2011/10/31/conveyancing-caution-when-answering-late-requisitions-and-the-burden-of-proof-when-clearing-up-doubts-concerning-title/", "title": "Conveyancing: caution when answering 'late' requisitions and the burden of proof when clearing up doubts concerning title", "date": "2011-10-31", "type": "case-note", "topics": ["conveyancing", "requisitions", "good-title", "burden-of-proof", "title-defects"], "cases": [{"name": "Chinawell Management Ltd v Strong Huge Corp Ltd", "citation": "[2011] HKEC 1403", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Late requisitions should be refused or answered without prejudice, since answering on the merits may waive the objection. The vendor carries the burden of showing title good beyond reasonable doubt, and the buyer's silence does not shift it."}, {"url": "https://hklandlaw.wordpress.com/2011/10/29/weekly-review-24th-28th-october/", "title": "Weekly review: 24th - 28th October", "date": "2011-10-29", "type": "overview", "topics": ["proprietary-estoppel", "licences", "encumbrances", "conveyancing", "remedy"], "cases": [{"name": "Cheung Ting (or Teng) Fan (or Fun) Tso", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Whittaker v Kinnear", "citation": null, "court": null, "jurisdiction": null}, {"name": "Inwards v Baker", "citation": null, "court": null, "jurisdiction": null}, {"name": "Chalmers v Pardoe", "citation": null, "court": null, "jurisdiction": null}, {"name": "Baker v Baker", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Conveyancing and Property Ordinance s.12A", "Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "Week in review: clearing an incumbrance whose owner has vanished, estoppel surviving gaps in written agreements, a licence coupled with an equity for life occupation, no relief where reliance was unlawful, and expectation capping the remedy."}, {"url": "https://hklandlaw.wordpress.com/2011/10/28/proprietary-estoppel-and-contracts-facts-sensitive-inquiry/", "title": "Proprietary estoppel and contracts: facts sensitive inquiry", "date": "2011-10-28", "type": "overview", "topics": ["proprietary-estoppel", "formalities", "land-contracts", "assurances", "detrimental-reliance"], "cases": [{"name": "Whittaker v Kinnear", "citation": "[2011] EWHC 1479", "court": "other", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "Estoppel can still be argued in England even where the assurance was meant to be contractual. Absence of writing may hint that no assurance or reliance existed, and weighs more heavily in commercial deals with lawyers involved."}, {"url": "https://hklandlaw.wordpress.com/2011/10/27/proprietary-estoppel-expectation-or-reliance/", "title": "Proprietary estoppel: expectation or reliance?", "date": "2011-10-27", "type": "case-note", "topics": ["proprietary-estoppel", "remedy", "expectation", "detrimental-reliance", "family-home"], "cases": [{"name": "Baker v Baker", "citation": "(1993) 25 H.L.R. 408", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A father who put money into a house on the footing he would live there for life had his equity measured by the accommodation he lost, not by returning the sum given, though later rehousing could scale the award down."}, {"url": "https://hklandlaw.wordpress.com/2011/10/26/procedure-where-owner-of-an-encumbrance-cannot-be-found/", "title": "Procedure where owner of an encumbrance cannot be found", "date": "2011-10-26", "type": "case-note", "topics": ["encumbrances", "conveyancing", "title", "marketability", "statutory-procedure"], "cases": [{"name": "Cheung Ting (or Teng) Fan (or Fun) Tso", "citation": "[2011] HKEC 1369", "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.12A"], "summary": "Section 12A rescues titles blocked by an incumbrancer who cannot be traced: the owner pays into court, advertises locally at least twenty-one days ahead, and then applies for a declaration freeing the land so it can be dealt with."}, {"url": "https://hklandlaw.wordpress.com/2011/10/25/licence-coupled-with-an-equity/", "title": "Licence coupled with an equity", "date": "2011-10-25", "type": "case-note", "topics": ["proprietary-estoppel", "licences", "detrimental-reliance", "binding-successors", "equity"], "cases": [{"name": "Inwards v Baker", "citation": "[1965] 2 QB 29", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Dillwyn v Llewellyn", "citation": null, "court": null, "jurisdiction": null}, {"name": "Ramsden v Dyson", "citation": null, "court": null, "jurisdiction": null}, {"name": "Plimmer v Wellington", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "A son who built on his father's land at his father's urging earned an equity to stay for life. That licence coupled with an equity bound those taking with notice, including the estate's trustees, defeating their possession claim."}, {"url": "https://hklandlaw.wordpress.com/2011/10/24/no-relief-where-the-detrimental-reliance-was-unlawful/", "title": "No relief where the detrimental reliance was unlawful", "date": "2011-10-24", "type": "case-note", "topics": ["proprietary-estoppel", "illegality", "statutory-consent", "equitable-relief", "detrimental-reliance"], "cases": [{"name": "Chalmers v Pardoe", "citation": "[1963] 1 WLR 677", "court": "PC", "jurisdiction": "other"}], "statutes": [], "summary": "Equity gave nothing where the building work relied on had gone ahead without the Native Land Trust Board's required consent. Estoppel cannot be used to bypass a statutory permission, so no charge or lien was granted."}, {"url": "https://hklandlaw.wordpress.com/2011/10/22/weekly-review-17th-21st-october/", "title": "Weekly review: 17th - 21st October", "date": "2011-10-22", "type": "overview", "topics": ["proprietary-estoppel", "subject-to-contract", "good-title", "partition", "notice"], "cases": [{"name": "Cohen v Nessdale Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "De Monsa Investments Ltd v Whole Win Management Fund Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "Lam Sik Shi v Lam Sik Ying", "citation": null, "court": null, "jurisdiction": null}, {"name": "Crabb v Arun DC", "citation": null, "court": null, "jurisdiction": null}, {"name": "ER Ives Investment Ltd v High", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Partition Ordinance s.6(1)"], "summary": "Round-up of the week's posts: negotiations stay subject to contract absent express release; giving title needs originals or cogent secondary proof; all statutory partition grounds count; estoppel equities bind purchasers with notice."}, {"url": "https://hklandlaw.wordpress.com/2011/10/22/proprietary-estoppel-2/", "title": "Proprietary estoppel", "date": "2011-10-22", "type": "overview", "topics": ["proprietary-estoppel", "promissory-estoppel", "equity"], "cases": [], "statutes": [], "summary": "Short signpost entry pointing readers to an externally hosted brief account of proprietary estoppel doctrine; no cases or statutes are analysed in the post itself."}, {"url": "https://hklandlaw.wordpress.com/2011/10/21/e-r-ives-investment-ltd-v-high/", "title": "E.R. Ives Investment Ltd v High", "date": "2011-10-21", "type": "case-note", "topics": ["proprietary-estoppel", "benefit-and-burden", "easements", "land-registration", "notice"], "cases": [{"name": "E.R. Ives Investment Ltd v High", "citation": "[1967] 2 QB 379", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Crabb v Arun District Council", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "An equity founded on acquiescence over encroaching foundations bound a later purchaser. Denning MR reasoned from mutual benefit and burden or conduct estoppel; the others applied estoppel directly. The equity fell outside registration requirements."}, {"url": "https://hklandlaw.wordpress.com/2011/10/20/crabb-v-arun-district-council/", "title": "Crabb v Arun District Council", "date": "2011-10-20", "type": "case-note", "topics": ["proprietary-estoppel", "easements", "remedies", "unconscionability", "promissory-estoppel"], "cases": [{"name": "Crabb v Arun District Council", "citation": "[1976] Ch 179", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Assurance about access, detrimental reliance and unconscionability grounded an estoppel despite an admittedly incomplete bargain; erecting a permanent gate counted as the representation. Relief was an easement plus compensation for the landlocked period."}, {"url": "https://hklandlaw.wordpress.com/2011/10/19/showing-and-giving-good-title/", "title": "Showing and giving good title", "date": "2011-10-19", "type": "case-note", "topics": ["good-title", "conveyancing", "title-deeds", "requisitions", "vendor-purchaser"], "cases": [{"name": "De Monsa Investments Ltd v Whole Win Management Fund Ltd", "citation": "[2011] 4 HKLRD 478", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.13(2)"], "summary": "Showing title permits certified copies of certified copies, but giving title demands the original deeds relating exclusively to the property, or cogent proof of a lost document's contents, execution and loss. Missing originals defeated completion here."}, {"url": "https://hklandlaw.wordpress.com/2011/10/18/the-continuing-effect-of-subject-to-contract/", "title": "The continuing effect of subject to contract", "date": "2011-10-18", "type": "case-note", "topics": ["subject-to-contract", "contract-formation", "land-contracts", "leases"], "cases": [{"name": "Cohen v Nessdale Ltd", "citation": "[1982] 2 All ER 97", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Once correspondence carries the subject to contract label, the whole course of dealing stays conditional until the parties expressly or impliedly lift it. A protected tenant's later oral agreement on a long lease was therefore unenforceable."}, {"url": "https://hklandlaw.wordpress.com/2011/10/17/order-for-sale-need-to-show-that-the-nature-of-the-land-makes-partition-undesirable/", "title": "Order for sale - need to show that the nature of the land makes partition undesirable?", "date": "2011-10-17", "type": "case-note", "topics": ["partition", "co-ownership", "order-for-sale", "statutory-interpretation"], "cases": [{"name": "Lam Sik Shi v Lam Sik Ying", "citation": "[2010] HKEC 779", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Partition Ordinance s.6(1)"], "summary": "The physical character of the land is only one of four statutory routes to finding partition unbeneficial, so an applicant need not prove it. With no evidence that dividing the land was workable, sale was properly ordered."}, {"url": "https://hklandlaw.wordpress.com/2011/10/15/weekly-review-10th-14th-october/", "title": "Weekly review: 10th - 14th October", "date": "2011-10-15", "type": "overview", "topics": ["adverse-possession", "part-performance", "proprietary-estoppel", "bona-fide-purchaser", "deeds-of-mutual-covenant"], "cases": [{"name": "B.P. Properties Ltd v Buckler", "citation": null, "court": null, "jurisdiction": null}, {"name": "Steadman v Steadman", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "In Re Gonin", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Li Yin Hong v Wan To Kui Incorporated Owners", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Ng Luk Mui v Shiu Tsun Wai Vincent", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Jennings v Rice", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance"], "summary": "Digest of the week: a one-sided licence stops squatters' time; part performance authority is unsettled on pointing to a land contract; DMC managers must not withhold consent unreasonably; a purchaser ignorant of an equity is bona fide; estoppel relief must stay proportionate."}, {"url": "https://hklandlaw.wordpress.com/2011/10/14/part-performance-do-the-relevant-acts-have-to-point-to-a-contract-concerning-land/", "title": "Part performance: do the relevant acts have to point to a contract concerning land?", "date": "2011-10-14", "type": "case-note", "topics": ["part-performance", "land-contracts", "formalities", "proprietary-estoppel", "rule-in-strong-v-bird"], "cases": [{"name": "Re Gonin", "citation": "[1979] Ch 16", "court": "other", "jurisdiction": "EN"}, {"name": "Steadman v Steadman", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Strong v Bird", "citation": null, "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Walton J preferred the strict requirement that the acts relied on indicate a land contract, the Lords having differed in Steadman. A daughter's years of caring for her parents satisfied neither part performance nor Strong v Bird; estoppel would have fitted better."}, {"url": "https://hklandlaw.wordpress.com/2011/10/13/equitys-darling-revisited/", "title": "Equity's darling revisited", "date": "2011-10-13", "type": "case-note", "topics": ["bona-fide-purchaser", "notice", "breach-of-trust", "equitable-interests", "good-faith"], "cases": [{"name": "Ng Luk Mui v Shiu Tsun Wai Vincent", "citation": "[2011] HKEC 1325", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A grandson transferred his grandmother's flat to his wife in breach of trust. The wife took free of the equity: purchaser is a term of art wider than buyer, consideration need not be full value, and ignorance of the trust supplied good faith."}, {"url": "https://hklandlaw.wordpress.com/2011/10/12/unilateral-licence-can-stop-time-running-for-adverse-possession/", "title": "Unilateral licence can stop time running for adverse possession", "date": "2011-10-12", "type": "case-note", "topics": ["adverse-possession", "limitation", "licences", "possession"], "cases": [{"name": "B.P. Properties Ltd v Buckler", "citation": "(1988) 55 P & CR 337", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "An owner unilaterally offered a squatter a licence for life; because she neither accepted nor refused it, her occupation stopped being adverse and the limitation clock halted. Outright rejection would have kept time running."}, {"url": "https://hklandlaw.wordpress.com/2011/10/11/enforcing-a-dmc-covenant-not-to-keep-animals-in-flats/", "title": "Enforcing a DMC covenant not to keep animals in flats", "date": "2011-10-11", "type": "case-note", "topics": ["deeds-of-mutual-covenant", "building-management", "incorporated-owners", "restrictive-covenants", "reasonableness"], "cases": [{"name": "Lee Yin Hong v Serenade Cove (IO)", "citation": "[2011] HKEC 1309", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "Incorporated owners must not withhold consent unreasonably, but their power is contractual, not amenable to judicial review standards. Refusing pet permission was reasonable given the express prohibition, notified residents' complaints of noise and mess."}, {"url": "https://hklandlaw.wordpress.com/2011/10/10/the-proprietary-estoppel-award-should-the-expectation-always-be-met/", "title": "The proprietary estoppel award: should the expectation always be met?", "date": "2011-10-10", "type": "case-note", "topics": ["proprietary-estoppel", "remedies", "proportionality", "detrimental-reliance", "unconscionability"], "cases": [{"name": "Jennings v Rice", "citation": "[2002] EWCA Civ 159", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Relief aims at removing unconscionability, weighing the encouraged expectation against the detriment suffered and keeping the two proportionate. An unpaid carer who hoped for a large inheritance received only an award reflecting the value of his services."}, {"url": "https://hklandlaw.wordpress.com/2011/10/08/weekly-review-3rd-7th-october/", "title": "Weekly review: 3rd - 7th October", "date": "2011-10-08", "type": "overview", "topics": ["vacant-possession", "deeds-of-mutual-covenant", "forfeiture", "waiver", "access-for-repairs"], "cases": [{"name": "Cumberland Consolidated Holdings Ltd v Ireland", "citation": null, "court": null, "jurisdiction": null}, {"name": "Beacon Heights (Management) Ltd v Leung Ping-Hung, Antonio", "citation": null, "court": null, "jurisdiction": null}, {"name": "The Incorporated Owners of Tak Wing Industrial Building v Poon Chi Hung William", "citation": null, "court": null, "jurisdiction": null}, {"name": "Cornillie v Saha", "citation": null, "court": null, "jurisdiction": null}, {"name": "Far East Land Holdings Ltd v Empire Asian Ltd", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["High Court Ordinance"], "summary": "Week in review: vacant possession means no rival claimant and unimpeded physical use; a DMC charge needs writing though equity may excuse signature; managers can compel access by injunction; conduct affirming a lease waives breaches; forfeiture relief may be repeated."}, {"url": "https://hklandlaw.wordpress.com/2011/10/07/relief-against-forfeiture-on-a-second-occasion-where-late-payment-was-inadvertent/", "title": "Relief against forfeiture on a second occasion where late payment was inadvertent", "date": "2011-10-07", "type": "case-note", "topics": ["forfeiture", "relief-against-forfeiture", "waiver", "leases", "rent-arrears"], "cases": [{"name": "Far East Land Holdings Ltd v Empire Asian Ltd", "citation": "[2011] 4 HKLRD 472", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A tenant already relieved once paid rent a few days late again. Relief was granted a second time: the lateness was accidental, the court's statutory and inherent discretion is not spent after one use, and taking the money waived the breach."}, {"url": "https://hklandlaw.wordpress.com/2011/10/06/unpaid-management-fees-can-the-dmc-create-a-charge-over-a-defaulting-owners-share/", "title": "Unpaid management fees: can the DMC create a charge over a defaulting owner's share?", "date": "2011-10-06", "type": "case-note", "topics": ["deeds-of-mutual-covenant", "equitable-charge", "management-fees", "formalities", "registration"], "cases": [{"name": "Beacon Heights (Management) Ltd v Leung Ping-Hung, Antonio", "citation": "[1995] 1 HKLR 181", "court": null, "jurisdiction": "HK"}, {"name": "Wise Wave Investments Ltd v TKF Services Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.5(1)"], "summary": "Wording that shares shall stand charged does not itself burden the defaulter; a separate written charge is needed, though equity can excuse the owner's signature. The charge must also be registered to bite."}, {"url": "https://hklandlaw.wordpress.com/2011/10/05/owner-refusing-to-allow-access-for-repair-works/", "title": "Owner refusing to allow access for repair works", "date": "2011-10-05", "type": "case-note", "topics": ["building-management", "incorporated-owners", "common-parts", "mandatory-injunction", "access-for-repairs"], "cases": [{"name": "The Incorporated Owners of Tak Wing Industrial Building v Poon Chi Hung William", "citation": "[2011] HKEC 1300", "court": "other", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "Where incorporated owners need to reach a flat roof forming a common part, an obstructive owner cannot dictate terms or demand close supervision. The Lands Tribunal ordered access on the days and hours the body had proposed."}, {"url": "https://hklandlaw.wordpress.com/2011/10/04/implied-waiver-of-a-breach-of-covenant/", "title": "Implied waiver of a breach of covenant", "date": "2011-10-04", "type": "case-note", "topics": ["waiver", "forfeiture", "leasehold-covenants", "subletting"], "cases": [{"name": "Cornillie v Saha", "citation": "[1996] 28 HLR 561", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.58"], "summary": "Waiver follows where a landlord knows of the breach, acts in a way that unmistakably treats the lease as alive, and conveys that to the tenant. Suing for inspection while aware of an unlawful sub-letting forfeited the right to forfeit."}, {"url": "https://hklandlaw.wordpress.com/2011/10/03/no-vacant-possession-if-the-seller-leaves-lots-of-rubbish-behind-him/", "title": "No vacant possession if the seller leaves lots of rubbish behind him", "date": "2011-10-03", "type": "case-note", "topics": ["vacant-possession", "completion", "sale-of-land", "vendor-obligations"], "cases": [{"name": "Cumberland Consolidated Holdings Ltd v Ireland", "citation": "[1946] KB 264", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Vacant possession goes beyond freedom from rival claims to actual unimpeded physical enjoyment. Leaving substantial debris, here hardened bags of cement, breaches the obligation, subject only to a de minimis allowance."}, {"url": "https://hklandlaw.wordpress.com/2011/10/01/weekly-review-26th-30th-september/", "title": "Weekly review: 26th - 30th September", "date": "2011-10-01", "type": "overview", "topics": ["common-parts", "compulsory-sale", "quiet-enjoyment", "certainty-of-term", "implied-terms"], "cases": [{"name": "Tam Sze Man v Incorporated Owners of Shan Tsui Court", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Lead Traders Ltd v Lucky Land Enterprise Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Kenny v Preen", "citation": null, "court": null, "jurisdiction": null}, {"name": "Mexfield Housing Co-operative v Berrisford", "citation": null, "court": null, "jurisdiction": null}, {"name": "Yiktown Properties Ltd v Jeon Bok Sool", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance", "Land (Compulsory Sale for Redevelopment) Ordinance"], "summary": "Weekly digest: non-structural partitions are usually not common parts; the compulsory sale threshold drops from ninety to eighty percent for large units; harassment breaches quiet enjoyment; vague fetters on notices to quit fail; no implied fitness covenant."}, {"url": "https://hklandlaw.wordpress.com/2011/09/30/no-implied-lease-term-that-premises-are-fit-for-any-particular-purpose/", "title": "No implied lease term that premises are fit for any particular purpose", "date": "2011-09-30", "type": "case-note", "topics": ["implied-terms", "leases", "fitness-for-purpose", "misrepresentation", "collateral-contract"], "cases": [{"name": "Yiktown Properties Ltd v Jeon Bok Sool", "citation": "[2011] HKEC 1149", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A lease carries no implied promise that the premises are physically or legally suitable for any given use. A restaurant tenant blocked by inadequate toilets could prove neither a representation nor a collateral warranty of suitability."}, {"url": "https://hklandlaw.wordpress.com/2011/09/29/a-periodic-tenancy-with-an-uncertain-restriction-on-serving-a-notice-to-quit/", "title": "A periodic tenancy with an (uncertain) restriction on serving a notice to quit", "date": "2011-09-29", "type": "case-note", "topics": ["certainty-of-term", "periodic-tenancies", "notice-to-quit", "leases", "estoppel"], "cases": [{"name": "Mexfield Housing Co-operative v Berrisford", "citation": "[2010] EWCA Civ 811", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A fetter on the landlord's power to serve notice offends the certainty of term rule and cannot be saved by equity, which here follows the law. Estoppel remains a possible route where insisting on the rule would be unconscionable."}, {"url": "https://hklandlaw.wordpress.com/2011/09/28/ownership-of-internal-partition-walls/", "title": "Ownership of internal partition walls", "date": "2011-09-28", "type": "case-note", "topics": ["common-parts", "deeds-of-mutual-covenant", "building-management", "multi-storey-ownership", "structural-alterations"], "cases": [{"name": "Tam Sze Man v Incorporated Owners of Shan Tsui Court", "citation": "[2011] HKEC 1259", "court": "CA", "jurisdiction": "HK"}, {"name": "Incorporated Owners of Westlands Garden v Oey Chiou Ling", "citation": null, "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "Reversing below, the Court of Appeal held a non-structural wall dividing two flats belongs to their owners rather than everyone. The DMC did not list it, no one else could reach it, and shared repair liability would produce odd results."}, {"url": "https://hklandlaw.wordpress.com/2011/09/27/covenant-for-quiet-enjoyment/", "title": "Covenant for quiet enjoyment", "date": "2011-09-27", "type": "case-note", "topics": ["quiet-enjoyment", "leasehold-covenants", "harassment", "possession"], "cases": [{"name": "Kenny v Preen", "citation": "[1963] 1 QB 499", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Pearson LJ framed the covenant as a qualified guarantee against disturbance of the tenant's possession by the landlord or those under him. Bogus notices, doorstep intimidation and threats to dump an elderly tenant's belongings breached it."}, {"url": "https://hklandlaw.wordpress.com/2011/09/26/compulsory-sale-paper-sub-division-not-adequate/", "title": "Compulsory sale: 'paper' sub-division not adequate", "date": "2011-09-26", "type": "case-note", "topics": ["compulsory-sale", "redevelopment", "sub-division", "statutory-interpretation", "deeds-of-mutual-covenant"], "cases": [{"name": "Lead Traders Ltd v Lucky Land Enterprise Ltd", "citation": "[2011] HKEC 1058", "court": "other", "jurisdiction": "HK"}], "statutes": ["Land (Compulsory Sale for Redevelopment) Ordinance"], "summary": "Splitting a floor by assignment and sub-DMC, without any physical division, did not create genuine separate units. Reading the legislative brief, the Lands Tribunal held the floor still fell under the lowered eighty percent threshold."}, {"url": "https://hklandlaw.wordpress.com/2011/09/24/weekly-review-19th-23rd-september/", "title": "Weekly review: 19th - 23rd September", "date": "2011-09-24", "type": "overview", "topics": ["beneficial-ownership", "incorporated-owners", "public-nuisance", "exclusive-possession", "proprietary-estoppel"], "cases": [{"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Abbey National Bank plc v Stringer", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Kwan & Pun Co Ltd v Chan Lai Yee", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Leung Tsang Hung v Incorporated Owners of Kwok Wing House", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Street v Mountford", "citation": "[1985] AC 809", "court": "HL", "jurisdiction": "EN"}, {"name": "Marcroft Wagons Ltd v Smith", "citation": null, "court": "EWCA", "jurisdiction": "EN"}, {"name": "Yiu Lin Tei v Lui Pui Lan", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.16"], "summary": "Weekly digest: joint names presume equal shares absent unusual facts; owners' meetings may follow their own procedure within the DMC; incorporated owners can be publicly liable for dangerous common parts; exclusive possession usually means a lease; estoppel needs proof of encouragement."}, {"url": "https://hklandlaw.wordpress.com/2011/09/23/no-proprietary-estoppel-where-weak-evidence-of-promise/", "title": "No proprietary estoppel where weak evidence of promise", "date": "2011-09-23", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "evidence", "oral-agreements", "family-home"], "cases": [{"name": "Yiu Lin Tei v Lui Pui Lan", "citation": "[2011] HKEC 1154", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "A woman said the deceased had promised her the home they shared. On the balance of probabilities the judge found no such assurance was ever given, so estoppel failed, as did the fallback claim of an oral agreement."}, {"url": "https://hklandlaw.wordpress.com/2011/09/22/beneficial-title-in-sole-name-even-though-the-legal-title-is-in-joint-names/", "title": "Beneficial title in sole name even though the legal title is in joint names", "date": "2011-09-22", "type": "case-note", "topics": ["beneficial-ownership", "common-intention-constructive-trust", "joint-tenancy", "undue-influence", "mortgages"], "cases": [{"name": "Abbey National Bank plc v Stringer", "citation": "[2006] EWCA Civ 338", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A son was added to the title only to satisfy the lender and put in nothing, so his mother held the whole beneficial interest, a marked departure from the equal-shares presumption. A later mortgage procured by undue influence, without independent advice, did not bind her."}, {"url": "https://hklandlaw.wordpress.com/2011/09/21/incorporated-owners-can-be-liable-in-public-nuisance/", "title": "Incorporated owners can be liable in public nuisance", "date": "2011-09-21", "type": "case-note", "topics": ["public-nuisance", "incorporated-owners", "common-parts", "building-management", "tortious-liability"], "cases": [{"name": "Leung Tsang Hung v Incorporated Owners of Kwok Wing House", "citation": "[2007] 4 HKLRD 654", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.16"], "summary": "Owners' corporations that know, or ought to know, that common parts such as external walls threaten public safety must take practicable steps or answer in public nuisance. Individual owners with knowledge, control and means may be liable alongside them."}, {"url": "https://hklandlaw.wordpress.com/2011/09/20/is-there-a-lease-where-the-arrangement-is-an-act-of-kindness/", "title": "Is there a lease where the arrangement is an act of kindness?", "date": "2011-09-20", "type": "case-note", "topics": ["lease-or-licence", "exclusive-possession", "intention-to-create-legal-relations", "rent-control"], "cases": [{"name": "Marcroft Wagons Ltd v Smith", "citation": "[1952] 2 KB 496", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Exclusive occupation for a term normally yields a tenancy, but generosity is an exception. Letting a deceased tenant's daughter stay on out of sympathy created no lease, the court being unwilling to fasten statutory protection onto a kindness."}, {"url": "https://hklandlaw.wordpress.com/2011/09/19/conduct-of-owners-meetings/", "title": "Conduct of owners' meetings", "date": "2011-09-19", "type": "case-note", "topics": ["building-management", "owners-meetings", "management-committee", "resolutions", "incorporated-owners"], "cases": [{"name": "Kwan & Pun Co Ltd v Chan Lai Yee", "citation": "[2002] HKEC 1401", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.3(2)"], "summary": "Those attending may settle their own procedure. Votes appointing a management committee implicitly resolved the prior question whether one should exist, and a majority owner who stayed silent at the meeting could not attack the resolutions afterwards."}, {"url": "https://hklandlaw.wordpress.com/2011/09/17/weekly-review-12th-16th-september/", "title": "Weekly review: 12th - 16th September", "date": "2011-09-17", "type": "overview", "topics": ["building-management", "commorientes", "fixtures", "restrictive-covenants", "owners-meetings"], "cases": [{"name": "Wong Tak Keung v Management Committee of the Incorporated Owners of Grenville House", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Tang Kam Yuen v Cheung Wing Kin", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Botham v TSB Bank plc", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Fully Profit (Asia) Ltd v Secretary for Justice", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Grande Properties Management Ltd v Sun Wah Manufactory Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.20A(2)"], "summary": "Digest of the week: the tendering provision binds rather than guides; the younger joint tenant is presumed to outlive the elder; annexation questions turn on objective permanence; house takes meaning from its instrument; majorities may vote in self-interest short of oppression."}, {"url": "https://hklandlaw.wordpress.com/2011/09/16/commorientes-and-survivorship/", "title": "Commorientes and survivorship", "date": "2011-09-16", "type": "case-note", "topics": ["commorientes", "survivorship", "joint-tenancy", "co-ownership", "creditors"], "cases": [{"name": "Ting Kam Yuen v Cheung Wing Kin", "citation": "[2011] HKEC 1151", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.11(1)"], "summary": "The statutory presumption that the younger joint tenant survives applies only where the order of deaths is genuinely uncertain. Evidence showed the husband outlived his wife briefly, so the flats accrued to his estate and were exposed to his creditors."}, {"url": "https://hklandlaw.wordpress.com/2011/09/15/fixture-or-chattel/", "title": "Fixture or chattel?", "date": "2011-09-15", "type": "case-note", "topics": ["fixtures", "chattels", "annexation", "mortgages", "personal-property"], "cases": [{"name": "Botham v TSB Bank plc", "citation": "[1996] EG 149 (CS)", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Applying degree and purpose of annexation, bathroom fittings, built-in kitchen units and some lights passed with the mortgaged flat, while carpets, curtains, blinds, gas fires and white goods stayed personal. Roch LJ listed five practical indicators."}, {"url": "https://hklandlaw.wordpress.com/2011/09/14/what-is-a-house/", "title": "What is a 'house'?", "date": "2011-09-14", "type": "case-note", "topics": ["restrictive-covenants", "government-lease-conditions", "construction-of-deeds", "redevelopment", "planning"], "cases": [{"name": "Fully Profit (Asia) Ltd v Secretary for Justice", "citation": "[2011] 3 HKLRD 434", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "House has no all-purpose legal meaning; it takes colour from the particular instrument. Leases limiting each site to one house were infringed by a proposed twenty-six storey tower, something the original parties would never have envisaged."}, {"url": "https://hklandlaw.wordpress.com/2011/09/13/bmo-s-20a2-the-duty-to-put-bids-out-to-tender-is-mandatory/", "title": "BMO, s.20A(2): the duty to put bids out to tender is mandatory", "date": "2011-09-13", "type": "case-note", "topics": ["building-management", "tendering", "incorporated-owners", "management-committee", "statutory-interpretation"], "cases": [{"name": "Wong Tak Keung v Management Committee of the Incorporated Owners of Grenville House", "citation": "[2003] HKEC 1495", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.20A(2)", "Building Management Ordinance s.40B(1)"], "summary": "Once the statutory value threshold is crossed, inviting tenders is compulsory rather than advisory. Appointment of an administrator requires every s.40B(1) condition to be met, and the court may still fashion other remedies."}, {"url": "https://hklandlaw.wordpress.com/2011/09/13/happy-mid-autumn-festival-2/", "title": "Happy Mid-Autumn Festival!", "date": "2011-09-13", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Festive greeting post with a Sai Kung dragon boat photograph; no legal content."}, {"url": "https://hklandlaw.wordpress.com/2011/09/12/majority-of-owners-can-vote-as-they-wish-provided-there-is-no-oppression-of-the-minority/", "title": "Majority of owners can vote as they wish provided there is no oppression of the minority", "date": "2011-09-12", "type": "case-note", "topics": ["building-management", "owners-meetings", "deeds-of-mutual-covenant", "minority-oppression", "service-charges"], "cases": [{"name": "Grande Properties Management Ltd v Sun Wah Manufactory Ltd", "citation": "[2006] 3 HKLRD 473", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "A meeting may sanction works after they are finished and charge every owner, unless the DMC forbids it. Majorities may vote in their own interest so long as the decision is lawful, within the DMC and not oppressive; liability attaches on approval."}, {"url": "https://hklandlaw.wordpress.com/2011/09/10/weekly-review-5th-9th-september/", "title": "Weekly review: 5th - 9th September", "date": "2011-09-10", "type": "overview", "topics": ["common-parts", "incorporated-owners", "building-management", "licences", "management-committee"], "cases": [{"name": "Hollywood Shopping Centre Owners' Committee Ltd v Incorporated Owners of Wing Wah Building", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Jikan Development Ltd v Incorporated Owners of Million Fortune Industrial Centre", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Incorporated Owners of One Beacon Hill v Match Power Investment Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Incorporated Owners of Finance Building v Bright Hill Management Consultants Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "ADCO Enterprises Ltd v Pets Central (HK) Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.34I", "Building Management Ordinance s.16"], "summary": "Week in review: whatever is not reserved for one owner is common; appropriating it breaks the DMC; owners' corporations may sue over pre-incorporation dues; an overstaying committee still functions; a tenant's licensee must go when the tenancy ends."}, {"url": "https://hklandlaw.wordpress.com/2011/09/09/licensor-who-refused-to-leave/", "title": "Licensor who refused to leave", "date": "2011-09-09", "type": "case-note", "topics": ["licences", "lease-renewal", "possession", "damages", "summary-judgment"], "cases": [{"name": "ADCO Enterprises Ltd v Pets Central (HK) Ltd", "citation": "[2011] HKEC 1129", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Questions covered whether written notice validly renewed a four year term, the duty to give up occupation at expiry, and recovery of loss caused by staying on. Summary judgment was given, execution stayed pending the counterclaim."}, {"url": "https://hklandlaw.wordpress.com/2011/09/07/management-committees-failure-to-step-down-does-not-leave-a-power-vacuum/", "title": "Management Committee's failure to step down does not leave a power vacuum", "date": "2011-09-07", "type": "case-note", "topics": ["building-management", "management-committee", "incorporated-owners", "standing", "corporate-governance"], "cases": [{"name": "Incorporated Owners of Finance Building v Bright Hill Management Consultants Ltd", "citation": "[2001] HKEC 1431", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance Second Schedule"], "summary": "Missing the rotation deadline does not dissolve a management committee. It stays the lawful committee, able to sue and defend for the corporation, so no gap in authority opens up."}, {"url": "https://hklandlaw.wordpress.com/2011/09/07/canopy-as-a-common-part/", "title": "Canopy as a common part", "date": "2011-09-07", "type": "case-note", "topics": ["common-parts", "building-management", "incorporated-owners", "account-of-profits", "advertising-rights"], "cases": [{"name": "Hollywood Shopping Centre Owners' Committee Ltd v Incorporated Owners of Wing Wah Building", "citation": "[2011] HKEC 1063", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.34I"], "summary": "A canopy fixed to the outside wall belonged to everyone. Letting it for advertising for the shopping centre owners alone appropriated shared property contrary to the Ordinance, and the revenue had to be accounted for once objection was taken."}, {"url": "https://hklandlaw.wordpress.com/2011/09/06/can-incorporated-owners-bring-proceedings-where-the-duty-was-owed-only-to-some-owners/", "title": "Can incorporated owners bring proceedings where the duty was owed only to some owners?", "date": "2011-09-06", "type": "case-note", "topics": ["incorporated-owners", "standing", "common-parts", "building-management", "defective-construction"], "cases": [{"name": "Incorporated Owners of One Beacon Hill v Match Power Investment Ltd", "citation": "[2011] HKEC 1156", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "The developer argued only duties owed to every owner could be enforced by the corporation. That failed: it suffices that the obligation concerns common parts and is owed to at least one owner, contractual origin being no obstacle. Later reversed on appeal."}, {"url": "https://hklandlaw.wordpress.com/2011/09/05/incorporated-owners-took-over-right-to-require-managers-to-account-for-fees-from-common-parts/", "title": "Incorporated owners took over right to require managers to account for fees from common parts", "date": "2011-09-05", "type": "case-note", "topics": ["incorporated-owners", "common-parts", "building-management", "account-of-profits", "assignment-of-rights"], "cases": [{"name": "Jikan Development Ltd v Incorporated Owners of Million Fortune Industrial Centre", "citation": "[2004] 1 HKLRD 181", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.16", "Building Management Ordinance s.18(2)"], "summary": "Rights owners held against managers who pocketed income from shared areas vest in the corporation on incorporation under s.16, even for earlier defaults. Section 18(2) supplies management powers only and does not itself transfer causes of action."}, {"url": "https://hklandlaw.wordpress.com/2011/09/03/weekly-review-29-august-2-september/", "title": "Weekly review: 29 August - 2 September", "date": "2011-09-03", "type": "overview", "topics": ["defects-in-title", "fixtures", "annexation", "compulsory-sale", "management-charges"], "cases": [{"name": "Wise Wave Investments Ltd v TKF Services Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Elitestone Ltd v Morris", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Goldful Way Development Ltd v Wellstable Development Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Hamp v Bygrave", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Hero Progress Ltd v Ting Ping Kwan Billy", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Weekly digest: undisclosed arrears of management charges flaw the title; degree and purpose of annexation, plus intention, decide what belongs to the land, and even a free-standing structure may; missing owners' shares need a fair and reasonable offer."}, {"url": "https://hklandlaw.wordpress.com/2011/09/02/redevelopment-where-there-is-a-missing-owner/", "title": "Redevelopment where there is a missing owner", "date": "2011-09-02", "type": "case-note", "topics": ["compulsory-sale", "redevelopment", "missing-owners", "valuation", "co-ownership"], "cases": [{"name": "Hero Progress Ltd v Ting Ping Kwan Billy", "citation": "[2011] HKEC 1004", "court": "other", "jurisdiction": "HK"}], "statutes": ["Land (Compulsory Sale for Redevelopment) Ordinance (Cap 545) s.4(1)(a)"], "summary": "A developer holding almost ninety-three percent sought sale where the remaining owner had died leaving no personal representative. Testing the offer against the unit's pro rata slice of redevelopment value, the tribunal found it fair and ordered sale."}, {"url": "https://hklandlaw.wordpress.com/2011/09/01/unpaid-management-charges-a-defect-in-title/", "title": "Unpaid management charges - a defect in title?", "date": "2011-09-01", "type": "case-note", "topics": ["defects-in-title", "management-charges", "equitable-charge", "deeds-of-mutual-covenant", "registration"], "cases": [{"name": "Wise Wave Investments Ltd v TKF Services Ltd", "citation": "[2007] 4 HKLRD 762", "court": "CFI", "jurisdiction": "HK"}, {"name": "Chi Kit Co Ltd v Lucky Health International Enterprise Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.5(1)(a)", "Land Registration Ordinance"], "summary": "Substantial arrears blot the title unless the buyer plainly had them in view when contracting. A DMC only obliges the owner to grant a charge; a signed writing is needed, equity may excuse signature, and registration remains essential."}, {"url": "https://hklandlaw.wordpress.com/2011/08/31/was-a-greenhouse-part-of-the-land/", "title": "Was a greenhouse part of the land?", "date": "2011-08-31", "type": "case-note", "topics": ["fixtures", "annexation", "good-title", "unauthorised-structures", "substantial-performance"], "cases": [{"name": "Goldful Way Development Ltd v Wellstable Development Ltd", "citation": "[1999] 1 HKLRD 563", "court": null, "jurisdiction": "HK"}, {"name": "Elitestone Ltd v Morris", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Built to measure, firmly joined to the house and removable only by demolition, the greenhouse formed part of the land though unauthorised. The seller still won: pulling it down would leave it substantially performing its promise of good title."}, {"url": "https://hklandlaw.wordpress.com/2011/08/30/is-a-bungalow-part-of-the-land/", "title": "Is a bungalow part of the land?", "date": "2011-08-30", "type": "case-note", "topics": ["fixtures", "chattels", "annexation", "part-and-parcel-of-the-land", "security-of-tenure"], "cases": [{"name": "Elitestone Ltd v Morris", "citation": "(1998) 30 HLR 266", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Rent Act 1977"], "summary": "Lord Lloyd drew a threefold division between chattels, fixtures and things part and parcel of the land, the last two counting as land. Timber bungalows resting by their own weight on pillars, removable only by demolition, were part of the land."}, {"url": "https://hklandlaw.wordpress.com/2011/08/29/fixtures-what-was-intended/", "title": "Fixtures? What was intended?", "date": "2011-08-29", "type": "case-note", "topics": ["fixtures", "annexation", "intention", "estoppel-by-representation", "sale-of-land"], "cases": [{"name": "Hamp v Bygrave", "citation": "[1983] 1 EGLR 174", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Stone urns, a statue and a lead trough counted, on annexation and intention, as passing with the garden. The sale particulars listed them, an abatement was offered to keep them, and the solicitors confirmed inclusion, so estoppel barred denial; return and damages followed."}, {"url": "https://hklandlaw.wordpress.com/2011/08/27/weekly-review-22-26-august/", "title": "Weekly review: 22 - 26 August", "date": "2011-08-27", "type": "overview", "topics": ["assignment-of-reversion", "leasehold-covenants", "equitable-leases", "beneficial-ownership", "partition"], "cases": [{"name": "Re King", "citation": null, "court": null, "jurisdiction": null}, {"name": "Rye v Purcell", "citation": null, "court": null, "jurisdiction": null}, {"name": "Johnsey Estates Ltd v Lewis and Manley (Engineering) Ltd", "citation": null, "court": null, "jurisdiction": null}, {"name": "Laskar v Laskar", "citation": null, "court": null, "jurisdiction": null}, {"name": "Ip Fung Ying v Cheng Chi Chung", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.31", "Partition Ordinance s.6"], "summary": "Weekly digest: the statute moves the right to sue on tenant covenants to the new reversioner, past breaches included; it reaches written agreements too; assignees answer only while the term is vested; joint buy-to-let escapes equal shares; sentiment will not block sale."}, {"url": "https://hklandlaw.wordpress.com/2011/08/26/does-cpo-s-31-apply-to-equitable-leases-does-the-tenant-need-to-sign-an-agreement-for-lease-to-bring-the-lease-within-cpo-s-31/", "title": "Does CPO s.31 apply to equitable leases? Does the tenant need to sign an agreement for lease to bring the lease within CPO s.31?", "date": "2011-08-26", "type": "case-note", "topics": ["equitable-leases", "assignment-of-reversion", "leasehold-covenants", "privity-of-estate", "formalities"], "cases": [{"name": "Rye v Purcell", "citation": "[1926] 1 KB 446", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.31"], "summary": "A letter signed by the landlord alone sufficed as the written agreement, so the section applied. No counterpart from the tenant is needed: either side could seek specific performance, and privity of estate arose once the tenant entered on those terms."}, {"url": "https://hklandlaw.wordpress.com/2011/08/25/assignee-of-lease-only-liable-on-lease-covenants-while-in-possession/", "title": "Assignee of lease only liable on lease covenants while in possession", "date": "2011-08-25", "type": "case-note", "topics": ["assignment-of-lease", "leasehold-covenants", "privity-of-estate", "indemnity", "rent-arrears"], "cases": [{"name": "Johnsey Estates Ltd v Lewis and Manley (Engineering) Ltd", "citation": "(1987) 54 P & CR 296", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.77(1)", "Conveyancing and Property Ordinance s.35"], "summary": "Liability under the covenants runs only while the term is vested in the assignee, so a first assignee escaped rent falling due after it passed the lease on, though the statutory indemnity to the original tenant survived. Hong Kong has an equivalent provision."}, {"url": "https://hklandlaw.wordpress.com/2011/08/24/sentimental-attachment-a-reason-not-to-make-an-order-for-sale/", "title": "Sentimental attachment: a reason not to make an order for sale?", "date": "2011-08-24", "type": "case-note", "topics": ["partition", "order-for-sale", "co-ownership", "matrimonial-property", "oral-agreements"], "cases": [{"name": "Ip Fung Ying v Cheng Chi Chung", "citation": "[2011] HKEC 894", "court": "other", "jurisdiction": "HK"}], "statutes": ["Partition Ordinance s.6"], "summary": "An alleged unwritten promise never to seek sale was disbelieved, clashing with a consent order that expressly envisaged one. Fondness for the flat carried no weight, undercut by neglect of it; dividing the property was impractical, so sale was ordered."}, {"url": "https://hklandlaw.wordpress.com/2011/08/23/can-assignor-of-reversion-enforce-tenants-covenants/", "title": "Can assignor of reversion enforce tenant's covenants?", "date": "2011-08-23", "type": "case-note", "topics": ["assignment-of-reversion", "leasehold-covenants", "touch-and-concern", "insurance-proceeds"], "cases": [{"name": "Re King", "citation": "[1963] Ch 459", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.31", "Law of Property Act 1925 s.141"], "summary": "Parting with the reversion strips the former landlord of any right to sue on covenants touching and concerning the land, whenever the breach happened. Money paid under a joint names insurance policy was held to belong to the tenant alone."}, {"url": "https://hklandlaw.wordpress.com/2011/08/22/departing-from-the-presumption-in-stack/", "title": "Departing from the presumption in Stack", "date": "2011-08-22", "type": "case-note", "topics": ["beneficial-ownership", "resulting-trust", "common-intention-constructive-trust", "co-ownership", "investment-property"], "cases": [{"name": "Laskar v Laskar", "citation": "[2008] EWCA Civ 347", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Where relatives buy jointly as an investment rather than a home, the equal-shares presumption either does not apply or yields easily. A resulting trust analysis gave the mother two thirds and the daughter one third, counting the tenant's discount and shared mortgage liability."}, {"url": "https://hklandlaw.wordpress.com/2011/08/20/weekly-review-15-19-august/", "title": "Weekly review: 15 - 19 August", "date": "2011-08-20", "type": "overview", "topics": ["assignment-of-lease", "assignment-of-reversion", "incorporated-owners", "service-charges", "set-off"], "cases": [{"name": "City & Metropolitan Properties Ltd v Greycroft", "citation": null, "court": null, "jurisdiction": null}, {"name": "Elegant Profit Ltd v Chung Lai Sang", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Grenville House v Incorporated Owners of Grenville House", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Akorita v Marine Heights (St Leonards) Ltd", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Bank of China (Hong Kong) Ltd v Creative Far East Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.31", "Building Management Ordinance s.16"], "summary": "Digest of the week: an outgoing tenant keeps claims against the landlord but an outgoing landlord loses claims against the tenant; the corporation alone sues over common parts affecting all; certification precedes payment; set-off needs a close link between the claims."}, {"url": "https://hklandlaw.wordpress.com/2011/08/19/assignor-of-lease-loses-right-to-sue-for-tenants-breach-of-covenant/", "title": "Assignor of lease loses right to sue for tenant's breach of covenant", "date": "2011-08-19", "type": "case-note", "topics": ["assignment-of-reversion", "leasehold-covenants", "rent-arrears", "standing"], "cases": [{"name": "Elegant Profit Ltd v Chung Lai Sang", "citation": "[2005] HKEC 1300", "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.31"], "summary": "Because the statute annexes the benefit of the covenants to the reversion, selling it hands the right to sue to the buyer, even for breaches during the seller's ownership. Rent arrears are included; letting both sue would be wrong."}, {"url": "https://hklandlaw.wordpress.com/2011/08/18/service-charges-to-be-properly-certified/", "title": "Service charges to be properly certified", "date": "2011-08-18", "type": "case-note", "topics": ["service-charges", "condition-precedent", "leasehold-covenants", "construction-of-leases"], "cases": [{"name": "Akorita v Marine Heights (St Leonards) Ltd", "citation": "[2011] UKUT 255 (LC)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Where the lease calls for a surveyor's or accountant's certificate, producing it is normally a precondition of recovery, the parties having wanted certainty about what is due. Without the certificate the landlord could not collect the arrears."}, {"url": "https://hklandlaw.wordpress.com/2011/08/17/can-assignor-of-lease-sue-landlord-after-the-assignment/", "title": "Can assignor of lease sue landlord after the assignment?", "date": "2011-08-17", "type": "case-note", "topics": ["assignment-of-lease", "leasehold-covenants", "landlord-obligations", "damages", "privity-of-estate"], "cases": [{"name": "City and Metropolitan Properties Ltd v Greycroft Ltd", "citation": "[1987] 1 WLR 1085", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.32", "Law of Property Act 1925 s.142(1)"], "summary": "A former tenant may still sue for breaches of the landlord's covenants that caused it loss while the term was vested in it. The statutory provisions do not take that away, matching its continuing liability for its own period."}, {"url": "https://hklandlaw.wordpress.com/2011/08/16/mortgagee-in-possession-and-tenants-right-of-set-off/", "title": "Mortgagee in possession and tenant's right of set-off", "date": "2011-08-16", "type": "case-note", "topics": ["mortgages", "mortgagee-in-possession", "set-off", "rent-deposits", "leases"], "cases": [{"name": "Bank of China (Hong Kong) Ltd v Creative Far East Ltd", "citation": "[2005] HKEC 403", "court": "CA", "jurisdiction": "HK"}, {"name": "Young v Kitchen", "citation": "(1878) 3 Ex D 127", "court": "other", "jurisdiction": "EN"}], "statutes": ["Law Amendment and Reform (Consolidation) Ordinance (Cap 23) s.9"], "summary": "A mortgagee demanding rent in its own name takes a fresh title to it rather than an assigned one, so the tenant cannot deduct claims against the former landlord. Return of the rent deposit stays a personal matter between the original parties."}, {"url": "https://hklandlaw.wordpress.com/2011/08/15/incorporated-owners-right-to-sue/", "title": "Incorporated owners' right to sue", "date": "2011-08-15", "type": "case-note", "topics": ["incorporated-owners", "standing", "common-parts", "building-management", "negligence"], "cases": [{"name": "Grenville House v The Incorporated Owners of Grenville House", "citation": "[1978] HKLR 235", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.16"], "summary": "Where the harm to common parts falls on the owners collectively, only the corporation may sue; an individual keeps a claim for his own private loss. The corporation here recovered repair costs in negligence from developer, architect and contractor after landslips."}, {"url": "https://hklandlaw.wordpress.com/2011/08/13/weekly-review-8-12-august/", "title": "Weekly review: 8 - 12 August", "date": "2011-08-13", "type": "overview", "topics": ["restrictive-covenants", "abandonment", "promissory-estoppel", "proprietary-estoppel", "vacant-possession"], "cases": [{"name": "Attorney-General of Hong Kong v Fairfax Ltd", "citation": null, "court": "UKPC", "jurisdiction": "HK"}, {"name": "White v Bijou Mansions", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Beswick v Beswick", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Walton's Stores (Interstate) Ltd v Maher", "citation": null, "court": "other", "jurisdiction": "AU"}, {"name": "Luo Xing Juan v Estate of Hui Shui See", "citation": null, "court": "CFA", "jurisdiction": "HK"}, {"name": "Suggitt v Suggitt", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "NYK Logistics (UK) Ltd v Ibrend Estates BV", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.26", "Law of Property Act 1925 s.84"], "summary": "Weekly digest: long acquiescence can abandon a covenant; the Ordinance lets non-parties under a building scheme enforce; promissory estoppel, normally defensive, has been used offensively; estoppel need not rest on overwhelming proof; vacant possession explored."}, {"url": "https://hklandlaw.wordpress.com/2011/08/12/scope-of-cpo-s-16/", "title": "Scope of CPO s.26", "date": "2011-08-12", "type": "case-note", "topics": ["privity-of-contract", "third-party-rights", "covenants", "specific-performance", "statutory-interpretation"], "cases": [{"name": "Beswick v Beswick", "citation": "[1968] AC 58", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.26"], "summary": "The section reaches only interests in land and does not turn a stranger to the contract into an enforcer. The widow succeeded only as administratrix seeking specific performance, not personally under the English counterpart provision."}, {"url": "https://hklandlaw.wordpress.com/2011/08/11/abandonment-of-covenant/", "title": "Abandonment of covenant", "date": "2011-08-11", "type": "case-note", "topics": ["restrictive-covenants", "abandonment", "acquiescence", "government-lease-conditions", "redevelopment"], "cases": [{"name": "Attorney General of Hong Kong v Fairfax Ltd", "citation": "[1997] HKLRD 243", "court": "UKPC", "jurisdiction": "HK"}], "statutes": [], "summary": "An 1862 Crown lease confined the lot to villas, yet from 1957 tower blocks went up unchallenged until the area was dense high-rise. Forty years of obvious, unopposed breaches meant the restriction was abandoned; the Crown could not plausibly plead ignorance."}, {"url": "https://hklandlaw.wordpress.com/2011/08/10/promissory-estoppel-as-a-sword/", "title": "Promissory estoppel as a sword?", "date": "2011-08-10", "type": "case-note", "topics": ["promissory-estoppel", "estoppel-by-conduct", "unconscionability", "contract-formation", "detrimental-reliance"], "cases": [{"name": "Walton's Stores (Interstate) Ltd v Maher", "citation": "(1988) 164 CLR 387", "court": "other", "jurisdiction": "AU"}], "statutes": [], "summary": "Australia's High Court let promissory estoppel found a claim rather than merely repel one. Having let the other side think exchange was a formality and watched it act, the retreating party was bound; two judges preferred estoppel in pais."}, {"url": "https://hklandlaw.wordpress.com/2011/08/09/the-meaning-of-vacant-possession/", "title": "The meaning of 'vacant possession'", "date": "2011-08-09", "type": "case-note", "topics": ["vacant-possession", "break-clauses", "leases", "possession", "chattels"], "cases": [{"name": "NYK Logistics (UK) Ltd v Ibrend Estates BV", "citation": "[2011] EWCA Civ 683", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "The premises must be free of people and allow the recipient immediate, exclusive occupation and control; leftover goods matter only if they substantially impede enjoyment of a substantial part. Workmen left on site after the break date defeated the notice."}, {"url": "https://hklandlaw.wordpress.com/2011/08/08/the-quality-of-evidence-in-proprietary-estoppel-cases/", "title": "The quality of evidence in proprietary estoppel cases", "date": "2011-08-08", "type": "case-note", "topics": ["proprietary-estoppel", "evidence", "detrimental-reliance", "testamentary-promises", "remedies"], "cases": [{"name": "Suggitt v Suggitt", "citation": "[2011] EWHC 903 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Although proof of the father's assurance was described as less than overwhelming and the son's detriment slight, the claim succeeded and a large share of the estate was transferred, despite the will pointing the other way."}, {"url": "https://hklandlaw.wordpress.com/2011/08/06/weekly-review-1-5-august/", "title": "Weekly review: 1 - 5 August", "date": "2011-08-06", "type": "overview", "topics": ["adverse-possession", "human-rights", "implied-licence", "structural-repairs", "compensation"], "cases": [{"name": "JA Pye (Oxford) Ltd v Graham", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Harvest Good Development Ltd v Secretary for Justice", "citation": null, "court": "CFI", "jurisdiction": "HK"}, {"name": "Beaulane Properties Ltd v Palmer", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Colin Dawson Windows Ltd v Borough Council of King's Lynn", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Grand v Gill", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Penny's Bay Investment Co Ltd v Director of Lands", "citation": null, "court": "CFA", "jurisdiction": "HK"}, {"name": "Ashley 121 Ltd v Appeal Tribunal (Buildings)", "citation": null, "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance", "Basic Law art.6", "European Convention on Human Rights Protocol 1 art.1", "Foreshore and Sea-bed (Reclamations) Ordinance (Cap 127)"], "summary": "Weekly digest: limitation wipes out the paper owner and hands the squatter ownership, raising human rights questions; express permission shields an owner during long negotiations; plaster can be structural; marine rights compensation compares values; planning applicants need land control."}, {"url": "https://hklandlaw.wordpress.com/2011/08/05/compensation-for-loss-of-marine-rights/", "title": "Compensation for loss of marine rights", "date": "2011-08-05", "type": "case-note", "topics": ["marine-rights", "reclamation", "compensation", "valuation", "government-land"], "cases": [{"name": "Penny's Bay Investment Co Ltd v Director of Lands", "citation": "(2010) 13 HKCFAR 287", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Foreshore and Sea-bed (Reclamations) Ordinance (Cap 127) s.12"], "summary": "Entitlement fixed at the 1995 notice, not the later surrender of the lease. The measure is the gap between open market value with and without the marine rights, and a 1995 buyer might have valued them modestly given other possible uses."}, {"url": "https://hklandlaw.wordpress.com/2011/08/04/implied-licence-during-negotiations/", "title": "Implied licence during negotiations", "date": "2011-08-04", "type": "case-note", "topics": ["adverse-possession", "implied-licence", "limitation", "possession", "negotiations"], "cases": [{"name": "Colin Dawson Windows Ltd v Borough Council of King's Lynn", "citation": "[2005] EWCA Civ 9", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Someone occupying while bargaining for an interest in the land is naturally taken to be there by permission for as long as talks continue, so the years spent negotiating do not count towards the twelve needed to bar the owner."}, {"url": "https://hklandlaw.wordpress.com/2011/08/03/is-wall-and-ceiling-plaster-structural/", "title": "Is wall and ceiling plaster 'structural'?", "date": "2011-08-03", "type": "case-note", "topics": ["repairing-covenants", "structure", "leases", "landlord-obligations", "disrepair"], "cases": [{"name": "Grand v Gill", "citation": "[2011] EWCA Civ 554", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Irvine v Moran", "citation": "(1992) 24 HLR 1", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Structure covers what gives a dwelling its shape, stability and appearance. Plasterwork is a constructional finish forming part of the wall or ceiling rather than decoration laid over it, so repairing it falls to the landlord."}, {"url": "https://hklandlaw.wordpress.com/2011/08/02/adverse-possession-and-human-rights/", "title": "Adverse possession and human rights", "date": "2011-08-02", "type": "case-note", "topics": ["adverse-possession", "human-rights", "limitation", "land-registration", "concealment"], "cases": [{"name": "Beaulane Properties Ltd v Palmer", "citation": "[2005] EWCA 817", "court": null, "jurisdiction": "EN"}, {"name": "JA Pye (Oxford) Ltd v United Kingdom", "citation": null, "court": "other", "jurisdiction": "other"}], "statutes": ["Land Registration Act 1925 s.75", "Limitation Act 1980", "Limitation Ordinance s.26(1)(b)", "European Convention on Human Rights"], "summary": "After the Grand Chamber ruling in Pye the author treats Beaulane as no longer sound, the Convention posing no bar to limitation extinguishing a paper title. Deliberate concealment restarts time, though the occupier may still complete twelve years."}, {"url": "https://hklandlaw.wordpress.com/2011/08/01/planning-applications-the-applicant-must-own-or-have-a-realistic-prospect-of-controlling-the-site/", "title": "Planning applications: the applicant must own or have a realistic prospect of controlling the site", "date": "2011-08-01", "type": "case-note", "topics": ["planning", "development-potential", "building-control", "judicial-review", "surrender-of-land"], "cases": [{"name": "Ashley 121 Ltd v Appeal Tribunal (Buildings)", "citation": "[2011] 2 HKLRD 728", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "An applicant lacking ownership or a realistic prospect of control over part of the scheme site cannot proceed. One application confined to the plot actually owned went back for fresh consideration of its residual and transferable development potential."}, {"url": "https://hklandlaw.wordpress.com/2011/07/30/weekly-review-25-29-july/", "title": "Weekly review: 25 - 29 July", "date": "2011-07-30", "type": "overview", "topics": ["chinese-customary-trusts", "easements", "common-parts", "requisitions-on-title", "adverse-possession"], "cases": [{"name": "Million Way Ltd v To Shing Wo", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Cogi Enterprises Ltd v IO of Malahon Apartments", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Tam Sze Man v Shan Tsui Court (IO)", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Jumbo King v Faithful Properties Ltd", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Nation Group Development Ltd v New Pacific Properties Ltd", "citation": "(2000) 3 HKCFAR 427", "court": "CFA", "jurisdiction": "HK"}, {"name": "Central Management Ltd v Light Field Investment Ltd", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "The Incorporated Owners of Westlands Garden v Oey Chiou Ling and Wong Fung Ling", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Smart Max Enterprise Ltd v Speedy Way Ltd", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Profit World Trading v Ho So Yung", "citation": null, "court": "CA", "jurisdiction": "HK"}, {"name": "Edginton v Clark", "citation": "[1964] 1 QB 367", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["New Territories Ordinance s.15", "Limitation Ordinance s.23", "Building Management Ordinance"], "summary": "Weekly digest: tso managers are trustees, not agents, and members may still object; reserved rights resemble but are not easements and do not license new pipework in private areas; partitions are not common parts; buyers need time on requisitions; an offer to buy acknowledges title."}, {"url": "https://hklandlaw.wordpress.com/2011/07/29/squatters-letter-offering-to-purchase-land-can-be-an-acknowledgement-of-title/", "title": "Squatter's letter offering to purchase land can be an acknowledgement of title", "date": "2011-07-29", "type": "case-note", "topics": ["adverse-possession", "limitation", "acknowledgement-of-title", "possession"], "cases": [{"name": "Edginton v Clark", "citation": "[1964] 1 QB 367", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance s.23"], "summary": "Acknowledging the paper owner's title restarts the limitation clock, and no fixed test says what counts, each case turning on its facts. Two letters offering to buy the plot, sent to the owner's agent, were enough."}, {"url": "https://hklandlaw.wordpress.com/2011/07/28/did-incorporated-owners-have-a-right-to-install-new-pipes-in-exclusive-area/", "title": "Did Incorporated Owners have a right to install new pipes in exclusive area?", "date": "2011-07-28", "type": "case-note", "topics": ["deeds-of-mutual-covenant", "reservations", "common-parts", "incorporated-owners", "construction-of-deeds"], "cases": [{"name": "Cogi Enterprises Ltd v IO of Malahon Apartments", "citation": "[2011] HKEC 883", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A reservation covering pipes now or at any time hereafter running through the land did not authorise laying fresh pipes in an area already assigned for exclusive use. What the developer and first purchaser meant governed the wording."}, {"url": "https://hklandlaw.wordpress.com/2011/07/27/vendor-must-show-good-title-unless-a-clearly-worded-contractual-term-excuses-him-from-this-responsibility/", "title": "Vendor must show good title unless a clearly worded contractual term excuses him from this responsibility", "date": "2011-07-27", "type": "case-note", "topics": ["good-title", "conveyancing", "requisitions", "encroachment", "de-minimis"], "cases": [{"name": "Profit World Trading Ltd v Ho So Yung", "citation": "[2011] 2 HKLRD 773", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Only very plain contractual words displace the duty to prove title; the buyer's earlier awareness and late requisitions did not. An encroachment of five percent onto common areas was not trivial, taking in part of the townhouse's showpiece living room."}, {"url": "https://hklandlaw.wordpress.com/2011/07/26/member-of-wui-objecting-to-sale/", "title": "Member of Wui objecting to sale", "date": "2011-07-26", "type": "case-note", "topics": ["chinese-customary-trusts", "new-territories-land", "trustees", "rectification", "sale-of-land"], "cases": [{"name": "Million Way Ltd v To Shing Wo", "citation": "[2011] HKEC 560", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Having signed a consent form did not bar a member from objecting to the District Officer. Managers hold as trustees rather than agents, so contracts they make do not bind members; rectifying the formal agreement would need convincing proof."}, {"url": "https://hklandlaw.wordpress.com/2011/07/25/time-to-be-allowed-for-considering-answers-to-requisitions-on-title/", "title": "Time to be allowed for considering answers to requisitions on title", "date": "2011-07-25", "type": "case-note", "topics": ["requisitions-on-title", "conveyancing", "completion", "good-title", "reasonable-time"], "cases": [{"name": "Smart Max Enterprise Ltd v Speedy Way Ltd", "citation": "[2011] HKEC 734", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A buyer must get a fair chance to digest replies even when they are simple. Sellers who sat on the requisitions for months, answered two hours before completion and allowed one extra day fell short of the contract's own seven day yardstick."}, {"url": "https://hklandlaw.wordpress.com/2011/07/25/another-case-on-partition-walls/", "title": "Another case on partition walls", "date": "2011-07-25", "type": "case-note", "topics": ["common-parts", "deeds-of-mutual-covenant", "construction-of-deeds", "first-assignment", "structural-alterations"], "cases": [{"name": "Tam Sze Man v Shan Tsui Court (IO)", "citation": "[2011] HKEC 111", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Ownership of a dividing wall turns on what the DMC and first assignment intended, ideally spelled out expressly. Colouring and legends on plans proved too weak, so the owners could not take down the wall between their flats."}, {"url": "https://hklandlaw.wordpress.com/2011/07/23/weekly-review-18-23-july/", "title": "Weekly review: 18 - 23 July", "date": "2011-07-23", "type": "overview", "topics": ["easements-of-necessity", "home-ownership-scheme", "licences", "registration-priority", "right-of-support"], "cases": [{"name": "Nickerson v Barraclough", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Cheung Shu Yin v Yip So Wan", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Terunnanse v Terunnanse", "citation": null, "court": "UKPC", "jurisdiction": "other"}, {"name": "Incorporated Owners of Century Centre v Bank of China (Hong Kong)", "citation": null, "court": null, "jurisdiction": "HK"}, {"name": "Rees v Skerrett", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Phipps v Pears", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Weekly digest: necessity easements rest on intention and fail where the transfer excludes them; unapproved dealings with subsidised flats are void; a licensee cannot dispute the title he accepted; re-registration does not reshuffle earlier priorities; prescriptive support may extend to weathering."}, {"url": "https://hklandlaw.wordpress.com/2011/07/22/late-re-registration-of-charging-orders-does-not-affect-priority-vis-a-vis-charging-orders-antecedent-to-the-re-registration/", "title": "Late re-registration of charging orders does not affect priority vis-a-vis charging orders antecedent to the re-registration", "date": "2011-07-22", "type": "case-note", "topics": ["land-registration", "priority", "charging-orders", "re-registration", "incorporated-owners"], "cases": [{"name": "Incorporated Owners of Century Centre v Bank of China (Hong Kong) Ltd", "citation": "[2011] HKEC 864", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.17"], "summary": "Renewing registration does not rearrange the order between existing charging orders: the earlier one keeps its place. Lateness tells only against interests arising afterwards, since any other reading would leave priorities perpetually shifting."}, {"url": "https://hklandlaw.wordpress.com/2011/07/21/effect-of-unlawful-alienation-of-home-ownership-scheme-flat/", "title": "Effect of unlawful alienation of Home Ownership Scheme flat", "date": "2011-07-21", "type": "case-note", "topics": ["home-ownership-scheme", "resulting-trust", "alienation", "statutory-invalidity", "subsidised-housing"], "cases": [{"name": "Cheung Shu Yin v Yip So Wan", "citation": "[2011] HKEC 841", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Housing Ordinance"], "summary": "A daughter-in-law funded her parents-in-law's subsidised flat and so acquired a resulting trust interest. The Court of Appeal treated creating that interest as an unapproved alienation and void, a conclusion the Court of Final Appeal later reversed."}, {"url": "https://hklandlaw.wordpress.com/2011/07/20/licensee-estopped-from-challenging-licensors-title/", "title": "Licensee estopped from challenging licensor's title", "date": "2011-07-20", "type": "case-note", "topics": ["licences", "estoppel", "title", "implied-grant"], "cases": [{"name": "Terunnanse v Terunnanse", "citation": "[1968] AC 1086", "court": "UKPC", "jurisdiction": "other"}], "statutes": [], "summary": "Someone who takes a licence knowing the grantor asserts a title cannot afterwards dispute it. The licence ended with the grantor's death, but continued payment of the fee to his successor implied the grant of a fresh one."}, {"url": "https://hklandlaw.wordpress.com/2011/07/19/scope-of-the-right-of-support-from-an-adjoining-building/", "title": "Scope of the right of support from an adjoining building", "date": "2011-07-19", "type": "case-note", "topics": ["easements", "right-of-support", "negligence", "demolition", "weather-protection"], "cases": [{"name": "Rees v Skerrett", "citation": "[2001] EWCA Civ 760", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Phipps v Pears", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Pulling down a party wall without adequate replacement can make the demolisher answerable for wind-driven damage next door, that protection being an aspect of support rather than a separate right. Foreseeable harm also engages a duty of care in negligence."}, {"url": "https://hklandlaw.wordpress.com/2011/07/18/easements-of-necessity-are-based-on-intention-and-not-public-policy/", "title": "Easements of necessity are based on intention and not public policy", "date": "2011-07-18", "type": "case-note", "topics": ["easements-of-necessity", "implied-grant", "intention", "landlocked-land", "public-policy"], "cases": [{"name": "Nickerson v Barraclough", "citation": "[1981] Ch 426", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Manjang v Drummond", "citation": null, "court": "UKPC", "jurisdiction": "other"}], "statutes": [], "summary": "Necessity easements spring from the parties' presumed intention, nobody being taken to want a landlocked plot, not from policy. Express words denying any grant therefore defeat the implication even where the land is otherwise inaccessible; water access may also negate necessity."}, {"url": "https://hklandlaw.wordpress.com/2011/07/16/cpo-s-16-and-transfer-to-lessee/", "title": "CPO s.16 and transfer to lessee", "date": "2011-07-16", "type": "case-note", "topics": ["easements", "implied-grant", "assignment-of-reversion", "statutory-general-words", "leases"], "cases": [{"name": "Kent v Kavanagh", "citation": "[2006] EWCA Civ 162", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "When the landlord sells the reversion to his own tenant, the statutory general words carry across the rights the tenant already enjoyed and reserve them against the neighbouring reversion. Buyers of one house thus kept as freeholders what they had held as tenants."}, {"url": "https://hklandlaw.wordpress.com/2011/07/15/acquiesence-no-bar-to-easement-by-prescription/", "title": "Acquiescence no bar to easement by prescription", "date": "2011-07-15", "type": "case-note", "topics": ["prescription", "easements", "user-as-of-right", "acquiescence", "rights-of-way"], "cases": [{"name": "Mills v Silver", "citation": "[1991] Ch 271", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "User must be as of right and permission defeats it, but a servient owner who merely knows and does not object does not stop the right maturing; such tolerance is typical. Surfacing a rough track went beyond repair into improvement, sounding in damages."}, {"url": "https://hklandlaw.wordpress.com/2011/07/14/when-lost-modern-grant-cant-work/", "title": "When lost modern grant can't work", "date": "2011-07-14", "type": "case-note", "topics": ["prescription", "lost-modern-grant", "easements", "rights-of-way", "public-rights"], "cases": [{"name": "Smith v Brudenell-Bruce", "citation": "[2002] 2 P & CR 4", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "The fiction fails where the use is readily explained without any grant, or where such a grant would have been unlawful. Here the claimant's traffic over the track differed in character and intensity from the public's, so twenty years' use founded the easement."}, {"url": "https://hklandlaw.wordpress.com/2011/07/13/acquisition-of-right-of-support-by-prescription/", "title": "Acquisition of right of support by prescription", "date": "2011-07-13", "type": "case-note", "topics": ["prescription", "right-of-support", "easements", "lost-modern-grant", "excavation"], "cases": [{"name": "Dalton v Henry Angus & Co", "citation": "(1880-81) LR 6 App Cas 740", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Twenty years of peaceable, uninterrupted enjoyment can raise a presumed grant of support, including where a building is altered so as to press harder on neighbouring soil. Excavating that soil, and thereby withdrawing support from a factory, infringed the right."}, {"url": "https://hklandlaw.wordpress.com/2011/07/12/cpo-s-16-only-operates-where-the-right-claimed-had-actually-been-exercised/", "title": "CPO s.16 only operates where the right claimed had actually been exercised", "date": "2011-07-12", "type": "case-note", "topics": ["easements", "conveyancing", "implied-grant", "right-of-way", "unity-of-ownership"], "cases": [{"name": "Payne v Inwood", "citation": "(1997) 74 P & CR 42", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "Section 16 is only a conveyancing shortcut passing existing rights; it cannot manufacture or revive an easement. Common ownership had extinguished the claimed rear access, and no later exercise of it was proved, so nothing passed."}, {"url": "https://hklandlaw.wordpress.com/2011/07/11/reserving-easements-dont-forget/", "title": "Reserving easements: don't forget!", "date": "2011-07-11", "type": "case-note", "topics": ["easements", "implied-reservation", "rectification", "leases", "conveyancing"], "cases": [{"name": "Holaw (470) Ltd v Stockton Estate Ltd", "citation": "(2001) 81 P & CR 29", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Re Webb's Lease", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "A seller who wants easements over land sold must reserve them expressly. Here the landlord could no longer grant what it had parted with; the implied reservation argument failed the Webb's Lease criteria, and rectification failed factually."}, {"url": "https://hklandlaw.wordpress.com/2011/07/09/meaning-of-easement-of-necessity/", "title": "Meaning of easement of necessity", "date": "2011-07-09", "type": "case-note", "topics": ["easements", "easement-of-necessity", "implied-grant", "right-to-light"], "cases": [{"name": "Ray v Hazeldine", "citation": "[1904] 2 Ch 17", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Necessity means absolute necessity, not mere reasonable convenience. A claimed right to light for a pantry failed because the room remained usable for other purposes without it, so nothing was implied on that ground."}, {"url": "https://hklandlaw.wordpress.com/2011/07/08/exceptional-case-of-an-implied-reservation/", "title": "Exceptional case of an implied reservation", "date": "2011-07-08", "type": "case-note", "topics": ["easements", "implied-reservation", "common-intention", "right-of-way", "burden-of-proof"], "cases": [{"name": "Peckham v Ellison", "citation": "(1993) 31 HLR 1030", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Re Webb's Lease", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Implied reservation is exceptional: the claimant must show the facts admit no other explanation, raising a necessary inference of shared intention. Long-standing use of a path between former council houses, and everyone's shared assumption, satisfied that here."}, {"url": "https://hklandlaw.wordpress.com/2011/07/07/interpreting-the-grant-of-a-right-of-way/", "title": "Interpreting the grant of a right of way", "date": "2011-07-07", "type": "case-note", "topics": ["easements", "right-of-way", "construction-of-deeds", "scope-of-easement"], "cases": [{"name": "St Edmundsbury and Ipswich Diocesan Board of Finance v Clark (No 2)", "citation": "[1975] 1 WLR 468", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Words granting a way carry their natural meaning read against the whole document and surrounding circumstances. The physical condition of the track showed only foot access was contemplated, so the reserved right was pedestrian, not vehicular."}, {"url": "https://hklandlaw.wordpress.com/2011/07/06/obstruction-of-a-right-of-way/", "title": "Obstruction of a right of way", "date": "2011-07-06", "type": "case-note", "topics": ["easements", "right-of-way", "obstruction", "injunctions", "dominant-tenement"], "cases": [{"name": "Thorpe v Brumfitt", "citation": "(1872-73) LR 8 Ch App 650", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "An injunction restrains anyone blocking a way so as to defeat its reasonable enjoyment. A grant expressed as being for all purposes was read as purposes connected with the benefited land, so it was not void for want of a dominant tenement."}, {"url": "https://hklandlaw.wordpress.com/2011/07/05/resumption-authority-has-a-duty-to-disclose-relevant-factual-evidence-in-its-possession/", "title": "Resumption authority has a duty to disclose relevant factual evidence in its possession", "date": "2011-07-05", "type": "case-note", "topics": ["compulsory-acquisition", "land-resumption", "compensation", "disclosure", "expert-evidence"], "cases": [{"name": "Kaisilk Development Ltd v Director of Lands", "citation": "[2011] HKEC 677", "court": "other", "jurisdiction": "HK"}], "statutes": ["Lands Resumption Ordinance (Cap 124) s.10(2)"], "summary": "Site photographs and similar factual material held by the resuming authority attract no privilege and must be handed over to the claimant. Experts owe the Tribunal an overriding duty to enable a fair and fully informed compensation assessment."}, {"url": "https://hklandlaw.wordpress.com/2011/07/04/no-easement-where-there-is-exclusive-use/", "title": "No easement where there is exclusive use", "date": "2011-07-04", "type": "case-note", "topics": ["easements", "exclusive-possession", "characteristics-of-easements", "leases", "conveyancing"], "cases": [{"name": "Hanina v Morland", "citation": "(2000) 97(47) LSG 41", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "A long lessee of upper floors claimed rights over the retained ground-floor roof for sunbathing and entertaining. Because that amounted to exclusive use of the roof, it could not qualify as an easement; easements permit only non-exclusive user."}, {"url": "https://hklandlaw.wordpress.com/2011/07/02/re-opening-agreed-reserve-price-in-compulsory-sale-cases/", "title": "Re-opening agreed reserve price in compulsory sale cases", "date": "2011-07-02", "type": "case-note", "topics": ["compulsory-sale", "redevelopment", "land-tribunal", "valuation", "case-management"], "cases": [{"name": "Sin Ho Yuen v Fineway Properties Ltd", "citation": "[2011] HKEC 678", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Guidance on reserve prices when values move after the sale order. A collapse makes the auction futile and a fresh order should be sought; a rise needs no change if rival bidders exist, but the minority owner should apply where only the developer will bid."}, {"url": "https://hklandlaw.wordpress.com/2011/06/30/when-will-an-easement-be-impliedly-reserved/", "title": "When will an easement be impliedly reserved?", "date": "2011-06-30", "type": "case-note", "topics": ["easements", "implied-reservation", "common-intention", "necessity", "conveyancing"], "cases": [{"name": "In Re Webb's Lease", "citation": "[1951] Ch 808", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Wheeldon v Burrows", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Reservation is implied only exceptionally, on necessity or common intention, and the facts must be consistent with no other reading. A landlord's advertising displays failed that test because bare licence was an equally available explanation."}, {"url": "https://hklandlaw.wordpress.com/2011/06/29/easements-as-an-appurtenance/", "title": "Easements as an 'appurtenance'", "date": "2011-06-29", "type": "overview", "topics": ["easements", "implied-grant", "appurtenances", "common-intention", "conveyancing"], "cases": [{"name": "Hansford v Jago", "citation": "[1912] 1 Ch 322", "court": "other", "jurisdiction": "EN"}, {"name": "Wheeldon v Burrows", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "Conveying land with its appurtenances can imply an easement independently of s.16. Where adjoining plots sharing an access are sold at the same time and each buyer knows of the other sale, common intention supports mutual rights without offending Wheeldon's second limb."}, {"url": "https://hklandlaw.wordpress.com/2011/06/28/dock-claiming-easement-of-support-from-neighbouring-wharf/", "title": "Dock claiming easement of support from neighbouring wharf", "date": "2011-06-28", "type": "case-note", "topics": ["easements", "easement-of-support", "prescription", "implied-reservation", "non-derogation-from-grant"], "cases": [{"name": "Union Lighterage Company v London Graving Dock Company", "citation": "[1902] 2 Ch 557", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Wheeldon v Burrows", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Tie rods installed under a neighbouring wharf during common ownership generated no support easement once the properties were split. Nothing was reserved expressly, necessity could not be implied against the grantee, and the hidden rods were too secret to found prescription."}, {"url": "https://hklandlaw.wordpress.com/2011/06/27/cpo-s-16-and-licences/", "title": "CPO s.16 and licences", "date": "2011-06-27", "type": "overview", "topics": ["easements", "licences", "implied-grant", "right-of-way", "conveyancing"], "cases": [{"name": "International Tea Stores Co v Hobbs", "citation": "[1903] 2 Ch 165", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "Where an owner permits the occupier of one part to use land he retains, a later conveyance of the occupied part normally converts that permission into an easement. The test is whether the right was being used and enjoyed with the property at conveyance."}, {"url": "https://hklandlaw.wordpress.com/2011/06/25/cpo-s-16-turning-a-licence-into-an-easement/", "title": "CPO s.16: turning a licence into an easement", "date": "2011-06-25", "type": "overview", "topics": ["easements", "licences", "implied-grant", "leases", "conveyancing"], "cases": [{"name": "Wright v Macadam", "citation": "[1949] 2 KB 744", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "A permission enjoyed by a tenant can harden into an easement on a fresh grant such as a lease renewal, provided the right is one the law recognises and nothing shows it was meant to be temporary. Coal-shed storage is the classic illustration."}, {"url": "https://hklandlaw.wordpress.com/2011/06/24/the-rule-in-wheeldon-v-burrows/", "title": "The rule in Wheeldon v Burrows", "date": "2011-06-24", "type": "overview", "topics": ["easements", "implied-grant", "implied-reservation", "non-derogation-from-grant", "quasi-easements"], "cases": [{"name": "Wheeldon v Burrows", "citation": "(1879) LR 12 Ch D 31", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "Thesiger LJ's two propositions: a sale of part impliedly grants the continuous and apparent quasi-easements needed for reasonable enjoyment of what is sold, but nothing is impliedly reserved except exceptionally, as with necessity. Both rest on non-derogation, and the order of successive sales matters."}, {"url": "https://hklandlaw.wordpress.com/2011/06/23/easement-of-necessity-where-otherwise-the-envisaged-use-would-be-illegal/", "title": "Easement of necessity where otherwise the envisaged use would be illegal", "date": "2011-06-23", "type": "case-note", "topics": ["easements", "easement-of-necessity", "common-intention", "leases", "implied-grant"], "cases": [{"name": "Wong v Beaumont Property Trust Ltd", "citation": "[1965] 1 QB 173", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A lease tying the premises to restaurant use implied a right to run a ventilation duct over the landlord's land, because health rules made the premises unusable lawfully without it. Necessity is judged objectively at the grant, even if neither party then realised it."}, {"url": "https://hklandlaw.wordpress.com/2011/06/22/easement-granted-to-tenant-annexed-to-conveyance-of-freehold/", "title": "Easement granted to tenant annexed to conveyance of freehold", "date": "2011-06-22", "type": "case-note", "topics": ["easements", "right-of-way", "implied-grant", "leases", "conveyancing"], "cases": [{"name": "Graham v Philcox", "citation": "[1984] QB 747", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16(1)"], "summary": "A way granted to a tenant over the lessor's retained land is not confined to the leasehold. On a later conveyance of the reversion the benefit passes to the freehold owner, provided the lessor still holds the servient land and nothing contrary is expressed."}, {"url": "https://hklandlaw.wordpress.com/2011/06/21/estopped-from-unreasonably-refusing-consent-to-alterations/", "title": "Estopped from unreasonably refusing consent to alterations?", "date": "2011-06-21", "type": "case-note", "topics": ["proprietary-estoppel", "leases", "alterations", "consent", "trespass"], "cases": [{"name": "Eaton Mansions (Westminster) Ltd v Stinger Compania de Inversion SA", "citation": "[2011] EWCA Civ 607", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Estoppel could not stop the intermediate landlord objecting to rooftop air-conditioning plant installed without consent. It needed its own superior landlord's permission, the head landlord had voiced concerns and treated approval as revocable, so refusal was not unreasonable; summary judgment followed."}, {"url": "https://hklandlaw.wordpress.com/2011/06/20/easement-of-necessity-even-if-grantor-does-not-own-all-of-the-land-surrounding-the-dominant-tenement/", "title": "Easement of necessity: even if grantor does not own all of the land surrounding the dominant tenement", "date": "2011-06-20", "type": "case-note", "topics": ["easements", "easement-of-necessity", "landlocked-land", "right-of-way", "implied-grant"], "cases": [{"name": "Barry v Hasseldine", "citation": "[1952] Ch 835", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Land conveyed that would otherwise be landlocked attracts an implied way of necessity even though the grantor does not surround it, and even though access had previously been by a third party's permission. The court can settle the route to the highway."}, {"url": "https://hklandlaw.wordpress.com/2011/06/18/no-public-right-of-way-by-mere-user/", "title": "No public right of way by mere user", "date": "2011-06-18", "type": "case-note", "topics": ["public-rights-of-way", "dedication", "prescription", "user-as-of-right", "easements"], "cases": [{"name": "Attorney-General v Antrobus", "citation": "[1905] 2 Ch 188", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Farwell J held, in the Stonehenge litigation, that however long the public has walked a track that alone confers no public right of way; something more, such as public expenditure on maintaining the route, is required."}, {"url": "https://hklandlaw.wordpress.com/2011/06/17/a-letter-demanding-possession-does-not-stop-time-running-in-favour-of-a-squatter/", "title": "A letter demanding possession does not stop time running in favour of a squatter", "date": "2011-06-17", "type": "case-note", "topics": ["adverse-possession", "limitation", "extinguishment-of-title", "mesne-profits", "possession"], "cases": [{"name": "Mount Carmel Investments Ltd v Peter Thurlow Ltd", "citation": "(1989) 57 P & CR 396", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Writing to demand possession does not interrupt the limitation clock; only action does. Once title is extinguished the owner also loses accrued mesne profits claims, retaking with the squatter's consent starts no new period, and a squatter who abandons cannot assign the right to sue."}, {"url": "https://hklandlaw.wordpress.com/2011/06/16/extinguishing-a-purchasers-lien/", "title": "Extinguishing a purchaser's lien", "date": "2011-06-16", "type": "case-note", "topics": ["purchasers-lien", "equitable-interests", "priority", "security", "intention"], "cases": [{"name": "Re Bank of China (Hong Kong) Ltd", "citation": "[2011] HKEC 660", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "A purchaser's equitable lien ends by law, by the parties' shared intention, or by the holder's own act, intention being judged objectively. Fuller security taken under a cancellation agreement showed an intention to give up the lien, losing its priority over later encumbrances."}, {"url": "https://hklandlaw.wordpress.com/2011/06/15/construction-of-dmc-charging-clause/", "title": "Construction of DMC charging clause", "date": "2011-06-15", "type": "case-note", "topics": ["deed-of-mutual-covenant", "multi-storey-buildings", "contractual-interpretation", "service-charges", "common-parts"], "cases": [{"name": "Incorporated Owners of Kingley Industrial Building v Wan Fai Ping", "citation": "[2011] HKEC 652", "court": "CA", "jurisdiction": "HK"}, {"name": "Jumbo King Ltd v Faithful Properties Ltd", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Applying the reasonable-person approach to a deed of mutual covenant, roof unit owners had to share renovation costs though the charging clause never mentioned them. The schedules, treating those units as part of the top floor with stated saleable areas, supplied the answer."}, {"url": "https://hklandlaw.wordpress.com/2011/06/14/what-if-squatters-believe-mistakenly-that-they-are-licensees/", "title": "What if squatters believe (mistakenly) that they are licensees?", "date": "2011-06-14", "type": "case-note", "topics": ["adverse-possession", "animus-possidendi", "licences", "limitation", "possession"], "cases": [{"name": "Clowes Developments (UK) Ltd v Walters", "citation": "[2005] EWHC 669 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Ho Hang-wan", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "An occupier who wrongly thinks she stays by the owner's permission lacks the intention to possess. The defendant continued after a transfer had ended her licence but believed herself the claimant's licensee, so no possessory title accrued."}, {"url": "https://hklandlaw.wordpress.com/2011/06/13/intention-to-possess-so-far-as-the-law-allows/", "title": "Intention to possess so far as the law allows", "date": "2011-06-13", "type": "case-note", "topics": ["adverse-possession", "animus-possidendi", "limitation", "possession", "comparative-law"], "cases": [{"name": "Lambeth London Borough Council v Blackburn", "citation": "[2001] EWCA Civ 912", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Powell v McFarlane", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Buckinghamshire County Council v Moran", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Admitting that occupation is temporary, that rent would be paid if asked, or that eviction is expected does not destroy the intention to possess in England. The post flags that Hong Kong takes a different line on this point."}, {"url": "https://hklandlaw.wordpress.com/2011/06/11/can-true-owner-stay-in-possession-through-his-plants/", "title": "Can true owner stay in possession through his plants?", "date": "2011-06-11", "type": "case-note", "topics": ["adverse-possession", "discontinuance", "dispossession", "animus-possidendi", "limitation"], "cases": [{"name": "Hounslow London Borough Council v Minchinton", "citation": "(1997) 74 P & CR 221", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Buckinghamshire County Council v Moran", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A council could not claim to remain in possession merely through a hedge it had planted; Millett LJ called the argument impossible. The occupiers had treated the strip as theirs beyond the limitation period, and as the owner built the fence this was discontinuance."}, {"url": "https://hklandlaw.wordpress.com/2011/06/10/adverse-possession-no-need-to-have-a-positive-intention-to-defeat-the-rights-of-the-formal-title-owner/", "title": "Adverse possession: no need to have a positive intention to defeat the rights of the formal title owner", "date": "2011-06-10", "type": "case-note", "topics": ["adverse-possession", "animus-possidendi", "mistake", "possessory-title", "limitation"], "cases": [{"name": "Hughes v Cork", "citation": "[1994] EG 25 (CS)", "court": "other", "jurisdiction": "other"}], "statutes": [], "summary": "A squatter need not know he is a squatter or consciously aim to defeat the owner. The predecessor's honest but mistaken belief that he owned the land did not negate the intention to possess, so the possessory title claim succeeded on appeal."}, {"url": "https://hklandlaw.wordpress.com/2011/06/09/adverse-possession-requirements-of-acknowledgement-of-superior-title/", "title": "Adverse possession: requirements of acknowledgement of superior title", "date": "2011-06-09", "type": "case-note", "topics": ["adverse-possession", "acknowledgement-of-title", "limitation", "formalities", "agency"], "cases": [{"name": "Lambeth London Borough Council v Archangel", "citation": "(2001) 33 HLR 44", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance s.23", "Limitation Ordinance s.24"], "summary": "An acknowledgement restarts time only if written, signed by the squatter or an agent, and given to the person with superior title or his agent. A charity operator's letter referring generally to the property qualified, signed personally and received by an employee with authority."}, {"url": "https://hklandlaw.wordpress.com/2011/06/08/when-a-squatter-acknowledges-the-title-of-the-formal-paper-title-owner/", "title": "When a squatter acknowledges the title of the formal paper title owner", "date": "2011-06-08", "type": "case-note", "topics": ["adverse-possession", "acknowledgement-of-title", "limitation", "formalities", "encroachment"], "cases": [{"name": "Browne v Perry", "citation": "[1991] 1 WLR 1297", "court": "PC", "jurisdiction": "other"}], "statutes": ["Limitation Ordinance (Cap 347) s.23", "Limitation Ordinance (Cap 347) s.24"], "summary": "Only a written acknowledgement restarts the clock. A defendant who built on the claimant's land by mistake in 1972 and acknowledged the title orally in 1983 still made out adverse possession, because the spoken admission had no statutory effect."}, {"url": "https://hklandlaw.wordpress.com/2011/06/07/granting-a-lease-does-not-stop-the-limitation-period-from-running/", "title": "Granting a lease does not stop the limitation period from running", "date": "2011-06-07", "type": "case-note", "topics": ["adverse-possession", "limitation", "leases", "encroachment", "possession"], "cases": [{"name": "Kan Kam Cho v Kan Chiu Nam", "citation": "[2008] HKEC 1807", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance"], "summary": "Letting the land out after a squatter is already in occupation does not interrupt limitation. In a dispute between neighbouring houses sharing a wall, tenancies granted during the occupation took effect subject to the squatter's rights and time kept running."}, {"url": "https://hklandlaw.wordpress.com/2011/06/06/squatter-cannot-seek-relief-from-forfeiture-of-extinguished-leasehold-title/", "title": "Squatter cannot seek relief from forfeiture of extinguished leasehold title", "date": "2011-06-06", "type": "case-note", "topics": ["adverse-possession", "forfeiture", "relief-from-forfeiture", "leases", "estoppel"], "cases": [{"name": "Tickner v Buzzacott", "citation": "[1965] Ch 426", "court": "other", "jurisdiction": "EN"}, {"name": "Fairweather v St Marylebone Property Co Ltd", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Because barring the owner does not vest the extinguished lease in the squatter, the occupier has no interest under it and cannot claim relief when the landlord forfeits. Paying rent proved neither an assignment nor an estoppel preventing denial of a tenancy."}, {"url": "https://hklandlaw.wordpress.com/2011/06/04/adverse-possession-does-not-transfer-title/", "title": "Adverse possession does not transfer title", "date": "2011-06-04", "type": "case-note", "topics": ["adverse-possession", "possessory-title", "limitation", "leasehold-covenants", "extinguishment-of-title"], "cases": [{"name": "Tichborne v Weir", "citation": "[1891-94] All ER Rep 449", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Limitation bars the owner's action and extinguishes his title; it does not convey that title to the occupier. Having held for forty years, the defendant took an independent possessory title and so was not bound by the covenants in the original lease."}, {"url": "https://hklandlaw.wordpress.com/2011/06/03/removal-of-illegal-structures-seeking-leave-to-appeal/", "title": "Removal of illegal structures: seeking leave to appeal", "date": "2011-06-03", "type": "case-note", "topics": ["unauthorised-structures", "deed-of-mutual-covenant", "civil-procedure", "leave-to-appeal", "incorporated-owners"], "cases": [{"name": "Incorporated Owners of Champion Court v Pang", "citation": "[2011] HKEC 587", "court": "CA", "jurisdiction": "HK"}], "statutes": ["District Court Ordinance (Cap 336) s.63A(2)"], "summary": "Owners ordered to pull down unauthorised structures, and then made to pay for the owners' corporation doing the work, were refused leave to appeal. They showed neither a reasonable prospect of success nor any other reason of justice requiring a hearing."}, {"url": "https://hklandlaw.wordpress.com/2011/06/02/possession-orders-and-human-rights/", "title": "Possession orders and human rights", "date": "2011-06-02", "type": "case-note", "topics": ["human-rights", "possession-proceedings", "proportionality", "public-housing", "security-of-tenure"], "cases": [{"name": "Hounslow London Borough Council v Powell", "citation": "[2011] 2 WLR 287", "court": "UKSC", "jurisdiction": "EN"}, {"name": "Manchester City Council v Pinnock", "citation": "[2010] 3 WLR 1441", "court": "UKSC", "jurisdiction": "EN"}], "statutes": ["Housing Act 1996", "European Convention on Human Rights Article 8"], "summary": "Lawful occupiers must be told why possession is sought so proportionality can be tested, but courts address the point only if the occupier raises it and it is seriously arguable. Vindicating ownership or managing the housing stock will normally justify an order."}, {"url": "https://hklandlaw.wordpress.com/2011/06/01/whole-course-of-dealing-the-focus-is-not-on-financial-contributions/", "title": "Whole course of dealing: the focus is not on financial contributions", "date": "2011-06-01", "type": "case-note", "topics": ["common-intention-constructive-trust", "beneficial-ownership", "joint-names", "quantification", "cohabitation"], "cases": [{"name": "Stack v Dowden", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Fowler v Barron", "citation": "[2008] EWCA Civ 377", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A joint-names purchase presumes equal beneficial shares, displaced only in unusual cases. Unequal cash contributions do not by themselves rebut it; where the couple pooled income and assets, the whole course of dealing pointed to equality."}, {"url": "https://hklandlaw.wordpress.com/2011/05/31/strong-evidence-needed-for-post-separation-alteration-to-stack-presumption-ofequality/", "title": "Strong evidence needed for post-separation alteration to Stack presumption ofequality", "date": "2011-05-31", "type": "case-note", "topics": ["common-intention-constructive-trust", "beneficial-ownership", "joint-names", "quantification", "cohabitation"], "cases": [{"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Kernott v Jones", "citation": "[2009] EWCA Civ 578", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Oxley v Hiscock", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Equality in joint-names cases survives separation unless strong evidence shows the parties' intentions later changed. The majority held that one partner meeting all outgoings for fourteen years after the split was not enough to shift the shares."}, {"url": "https://hklandlaw.wordpress.com/2011/05/30/the-mysterious-tale-of-the-disappearing-landlord/", "title": "The mysterious tale of the disappearing landlord", "date": "2011-05-30", "type": "case-note", "topics": ["adverse-possession", "limitation", "tenancies", "extinguishment-of-title", "possession"], "cases": [{"name": "Lam Che v Foung Sheu Kwan", "citation": "[2010] HKEC 1252", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Tenants of a flat held under an oral tenancy whose landlord vanished in mid-1984 were treated as adverse possessors from 1 January 1985. Their unbroken occupation and payment of rates and charges extinguished the landlord's title."}, {"url": "https://hklandlaw.wordpress.com/2011/05/28/execution-of-assignment-by-prc-company/", "title": "Execution of assignment by PRC Company", "date": "2011-05-28", "type": "case-note", "topics": ["conveyancing", "title-requisitions", "execution-of-deeds", "company-seals", "good-title"], "cases": [{"name": "Wang Zhidun v Tsoi Ming Pui", "citation": "[2011] HKEC 611", "court": "other", "jurisdiction": "HK"}, {"name": "On Hong Trading Co Ltd v Bank of Communications", "citation": null, "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "A metallic common seal must carry a legible engraved corporate name, and a buyer may object where it does not. Hong Kong courts take no judicial notice of mainland execution practice, so a purchaser may insist on a PRC lawyer's opinion about a chop."}, {"url": "https://hklandlaw.wordpress.com/2011/05/27/rights-ancillary-to-a-right-of-way/", "title": "Rights ancillary to a right of way", "date": "2011-05-27", "type": "case-note", "topics": ["easements", "right-of-way", "ancillary-rights", "scope-of-easement", "parking"], "cases": [{"name": "Chatham Industries Ltd v Incorporated Owners of Gold King Industrial Building", "citation": "[2011] HKEC 605", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Ancillary rights attach where they were reasonably necessary to enjoy the way when granted, judged on the wording and the facts both parties knew. A vehicular way therefore carried the right to halt briefly to set down passengers and load goods."}, {"url": "https://hklandlaw.wordpress.com/2011/05/26/a-tenant-whose-title-has-been-extinguished-by-adverse-possession-can-surrender-the-lease/", "title": "A tenant whose title has been extinguished by adverse possession can surrender the lease", "date": "2011-05-26", "type": "case-note", "topics": ["adverse-possession", "limitation", "surrender-of-lease", "leases", "extinguishment-of-title"], "cases": [{"name": "Fairweather v St Marylebone Property Co Ltd", "citation": "[1963] AC 510", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance"], "summary": "Extinguishment of the tenant's title against the squatter leaves enough estate between tenant and landlord for a valid surrender. The majority held that the surrender gave the landlord an immediate right to possession without waiting out the term."}, {"url": "https://hklandlaw.wordpress.com/2011/05/25/adverse-possession-when-a-periodic-tenant-stops-paying-rent/", "title": "Adverse possession when a periodic tenant stops paying rent", "date": "2011-05-25", "type": "case-note", "topics": ["adverse-possession", "periodic-tenancy", "limitation", "corporation-sole", "possession"], "cases": [{"name": "Hayward v Chaloner", "citation": "[1968] 1 QB 107", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Time runs against the landlord once the period covered by the last rent payment ends and nothing further is paid. A rectory holding qualified, and because the rector is a corporation sole the change of incumbents did not break continuity of possession."}, {"url": "https://hklandlaw.wordpress.com/2011/05/24/adverse-possession-the-owner-of-the-paper-title-gets-the-benefit-of-the-doubt/", "title": "Adverse possession: the owner of the paper title gets the benefit of the doubt", "date": "2011-05-24", "type": "case-note", "topics": ["adverse-possession", "burden-of-proof", "factual-possession", "paper-title", "limitation"], "cases": [{"name": "Kam Lan Koon Ltd v Realray Investment Ltd", "citation": "[2009] HKEC 343", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Courts readily infer that the documentary owner remains in possession, leaving the claimant to prove he displaced him. Keeping keys, letting others in and using the land in an owner's way, not as licensee or member of the public, defeated the claim."}, {"url": "https://hklandlaw.wordpress.com/2011/05/23/encroachment-for-whose-benefit/", "title": "Encroachment: for whose benefit?", "date": "2011-05-23", "type": "case-note", "topics": ["encroachment", "adverse-possession", "landlord-and-tenant", "presumptions", "possessory-title"], "cases": [{"name": "Lau Wing Hong v Wong Wor Hung", "citation": "[2006] 4 HKLRD 671", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "A tenant's encroachment is presumed to accrue to the landlord, and the presumption reaches land belonging to third parties too. Here it was rebutted: the landlord disclaimed any interest in the strip and later leases said nothing about it, so the tenant kept the title."}, {"url": "https://hklandlaw.wordpress.com/2011/05/21/adverse-possession-when-licence-terminates-by-operation-of-law/", "title": "'Adverse possession' when licence terminates by operation of law?", "date": "2011-05-21", "type": "case-note", "topics": ["adverse-possession", "licences", "animus-possidendi", "limitation", "possession"], "cases": [{"name": "Ho Hang-wan v Ma Ting-cheung", "citation": "[1990] 1 HKLR 649", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A licence that ends automatically, as on the licensor's death, can start time running even though the occupier never realised it had ended. Building, enclosing and running a business there showed an intention to possess independent of the original permission."}, {"url": "https://hklandlaw.wordpress.com/2011/05/20/adverse-possession-what-if-the-landowner-purports-to-grant-a-licence-to-the-squatter/", "title": "Adverse possession: what if the landowner purports to grant a licence to the squatter?", "date": "2011-05-20", "type": "case-note", "topics": ["adverse-possession", "licences", "limitation", "possession", "consent"], "cases": [{"name": "Kam To Pui v Incorporated Owners of Lux Theatre Buildings", "citation": "[2000] HKEC 1014", "court": null, "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance"], "summary": "An owner cannot stop the clock by unilaterally offering a licence; the squatter must accept it. A solicitors' letter demanding departure but allowing a short extra period was no licence, and the occupation stayed adverse throughout."}, {"url": "https://hklandlaw.wordpress.com/2011/05/19/a-squatter-can-take-possession-by-granting-a-lease/", "title": "A squatter can take possession by granting a lease", "date": "2011-05-19", "type": "case-note", "topics": ["adverse-possession", "limitation", "leases", "possession", "extinguishment-of-title"], "cases": [{"name": "Cheung Yat Fuk v Tang Tak Hong", "citation": "[2004] 2 HKLRD 86", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.17"], "summary": "Possession can be held through a tenant, so a squatter who lets the land out stays in possession without being there. Seven years of occupation followed by a tenancy lasting thirty years extinguished the registered owner's title to the farmland."}, {"url": "https://hklandlaw.wordpress.com/2011/05/18/trivial-actions-and-adverse-possession/", "title": "Trivial actions and adverse possession", "date": "2011-05-18", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "animus-possidendi", "common-parts", "dispossession"], "cases": [{"name": "Incorporated Owners of San Po Kong Mansion v Shine Empire Ltd", "citation": "[2007] HKEC 977", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Acts slight in relation to the land in dispute are neither possession nor evidence of an intention to possess. Drying clothes, aerials, parties, a management office, a locked gate and licence fees from telecoms operators were still too trivial to dispossess the owners."}, {"url": "https://hklandlaw.wordpress.com/2011/05/17/fundamental-concepts-in-the-law-of-adverse-possession-powell-v-mcfarlane/", "title": "Fundamental concepts in the law of adverse possession: Powell v McFarlane", "date": "2011-05-17", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "animus-possidendi", "implied-licence", "limitation"], "cases": [{"name": "Powell v McFarlane", "citation": "(1979) 38 P & CR 452", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Slade J's framework: the documentary owner is presumed in possession; a claimant must show exclusive physical control appropriate to the land plus an outwardly evident intention to possess in his own name; and a former trespasser needs compelling proof. Grazing and fence repairs fell short."}, {"url": "https://hklandlaw.wordpress.com/2011/05/16/pye-in-the-house-of-lords/", "title": "Pye in the House of Lords", "date": "2011-05-16", "type": "case-note", "topics": ["adverse-possession", "factual-possession", "animus-possidendi", "limitation", "possession"], "cases": [{"name": "JA Pye (Oxford) Ltd v Graham", "citation": "[2003] 1 AC 419", "court": "HL", "jurisdiction": "EN"}, {"name": "Powell v McFarlane", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Two elements suffice: physical custody and control, and an intention to hold for oneself. Nothing hostile is needed, and readiness to pay rent if asked is irrelevant since the intention is to possess rather than own. Farming the enclosed land and controlling the gate qualified."}, {"url": "https://hklandlaw.wordpress.com/2011/05/14/compulsory-sale-for-redevelopment/", "title": "Compulsory sale for redevelopment", "date": "2011-05-14", "type": "case-note", "topics": ["compulsory-sale", "redevelopment", "land-tribunal", "valuation", "undivided-shares"], "cases": [{"name": "Gentway Ltd v Li King Fong", "citation": "[2011] HKEC 597", "court": "other", "jurisdiction": "HK"}], "statutes": ["Land (Compulsory Sale for Redevelopment) Ordinance (Cap 545) s.3", "Land (Compulsory Sale for Redevelopment) Ordinance (Cap 545) s.4(2)"], "summary": "Holders of 92.66 per cent of the shares obtained a sale order. The building was at the end of its life, untenantable and unfit to live in, redevelopment value far exceeded existing use value, and purchase attempts had failed; reserve HK$291 million."}, {"url": "https://hklandlaw.wordpress.com/2011/05/13/common-intention-constructive-trust-evidence-of-an-agreement/", "title": "Common intention constructive trust: evidence of an agreement", "date": "2011-05-13", "type": "case-note", "topics": ["common-intention-constructive-trust", "express-agreement", "detrimental-reliance", "beneficial-ownership", "cohabitation"], "cases": [{"name": "Grant v Edwards", "citation": "[1986] Ch 638", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "The claimant must show an agreement that she take a beneficial share and detriment suffered at least partly because of it. The excuse given for leaving her off the title evidenced an express agreement, and her financial contributions supplied the necessary link."}, {"url": "https://hklandlaw.wordpress.com/2011/05/12/proprietary-estoppel-where-the-representee-is-a-corporation/", "title": "Proprietary estoppel where the representee is a corporation", "date": "2011-05-12", "type": "case-note", "topics": ["proprietary-estoppel", "detrimental-reliance", "constructive-trust", "unconscionability", "purchasers"], "cases": [{"name": "Lloyd v Dugdale", "citation": "[2001] EWCA Civ 1754", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Where assurances are given to a director personally rather than his company, it is his own detriment that counts, satisfied here by passing up other purchases. A buyer takes free unless a constructive trust arises; buying expressly subject to an equity is not itself unconscionable."}, {"url": "https://hklandlaw.wordpress.com/2011/05/11/proprietary-estoppel-when-reliance-on-an-assurance-is-presumed/", "title": "Proprietary estoppel: when reliance on an assurance is presumed", "date": "2011-05-11", "type": "case-note", "topics": ["proprietary-estoppel", "reliance", "burden-of-proof", "assurances", "detriment"], "cases": [{"name": "Greasley v Cooke", "citation": "[1980] 1 WLR 1306", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Coombes v Smith", "citation": "[1987] 1 FLR 352", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Where assurances were meant to influence and would sway a reasonable person, reliance is presumed and the defendant must disprove the causal link. A live-in housekeeper promised a home for life obtained a declaration that she could stay rent free."}, {"url": "https://hklandlaw.wordpress.com/2011/05/09/the-burden-of-proving-reliance-in-proprietary-estoppel/", "title": "The burden of proving reliance in proprietary estoppel", "date": "2011-05-09", "type": "case-note", "topics": ["proprietary-estoppel", "reliance", "burden-of-proof", "detriment", "assurances"], "cases": [{"name": "Wayling v Jones", "citation": "(1995) 69 P & CR 170", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Once conduct is shown from which reliance may be inferred, the onus moves to the defendant to negative it. Years of work for little pay on the strength of a promised bequest raised that inference, so the estate had to disprove reliance."}, {"url": "https://hklandlaw.wordpress.com/2011/05/07/pascoe-v-turner/", "title": "Pascoe v Turner", "date": "2011-05-07", "type": "case-note", "topics": ["proprietary-estoppel", "assurances", "detrimental-reliance", "satisfying-the-equity", "acquiescence"], "cases": [{"name": "Pascoe v Turner", "citation": "[1979] 1 WLR 431", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Repeated assurances that the house was hers, money spent on repairs and improvements, and the owner standing by while she spent it raised an equity. A life licence was thought insufficient protection, so the court ordered the freehold conveyed to her."}, {"url": "https://hklandlaw.wordpress.com/2011/05/06/approach-to-raising-and-answering-requisitions/", "title": "Approach to raising and answering requisitions", "date": "2011-05-06", "type": "case-note", "topics": ["conveyancing", "title-requisitions", "good-title", "evidence-of-title", "sale-of-land"], "cases": [{"name": "So Mariko v Tse Chun Chung John", "citation": "[2011] HKEC 541", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Requisitions are judged with robust common sense, assuming a willing seller and buyer, and the best conceivable evidence is not demanded. A statutory declaration by the solicitor who drew the assignment sufficed to corroborate a recital; reasonable assurance, not certainty, is the test."}, {"url": "https://hklandlaw.wordpress.com/2011/05/05/plimmer-v-wellington/", "title": "Plimmer v Wellington", "date": "2011-05-05", "type": "case-note", "topics": ["proprietary-estoppel", "licences", "irrevocable-licence", "interests-in-land", "compensation"], "cases": [{"name": "Plimmer v Mayor of Wellington", "citation": "(1883-84) LR 9 App Cas 699", "court": "PC", "jurisdiction": "other"}, {"name": "Ramsden v Dyson", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A licensor who creates an expectation that the permission is permanent, relied on to the licensee's detriment, may find equity treating the licence as irrevocable and as an interest in land. Money spent at the government's request made the wharf licence irrevocable and compensatable."}, {"url": "https://hklandlaw.wordpress.com/2011/05/04/ramsden-v-dyson/", "title": "Ramsden v Dyson", "date": "2011-05-04", "type": "case-note", "topics": ["proprietary-estoppel", "acquiescence", "mistaken-belief", "expenditure-on-land", "leases"], "cases": [{"name": "Ramsden v Dyson", "citation": "(1866) LR 1 HL 129", "court": "HL", "jurisdiction": "EN"}, {"name": "Dillwyn v Llewelyn", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Plimmer v Mayor of Wellington", "citation": null, "court": null, "jurisdiction": "other"}], "statutes": [], "summary": "An owner who lets someone build while knowing of that person's mistaken belief in an interest must correct it. The majority refused relief because the tenant understood his real position and the landlord had not knowingly encouraged the error; Lord Kingsdown dissented."}, {"url": "https://hklandlaw.wordpress.com/2011/05/03/proprietary-estoppel-dillwyn-v-llewellyn/", "title": "Proprietary estoppel: Dillwyn v Llewellyn", "date": "2011-05-03", "type": "case-note", "topics": ["proprietary-estoppel", "imperfect-gifts", "expenditure-on-land", "assurances", "part-performance"], "cases": [{"name": "Dillwyn v Llewelyn", "citation": "(1864) 4 De GF & J 517; 45 ER 1285", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Equity may compel a donor to perfect an incomplete gift of land. Lord Westbury's example: a father putting a son in possession to build, followed by heavy expenditure in reliance on that assurance, entitles the son to call for a conveyance."}, {"url": "https://hklandlaw.wordpress.com/2011/05/02/resulting-trust-and-illegality/", "title": "Resulting trust and illegality", "date": "2011-05-02", "type": "case-note", "topics": ["resulting-trust", "illegality", "beneficial-ownership", "purchase-money", "co-ownership"], "cases": [{"name": "Teo Ai Hua (alias Teo Jimmy) v Teo Mui Mui", "citation": "[2011] SGHC 81", "court": "other", "jurisdiction": "SG"}], "statutes": [], "summary": "Three siblings funded a purchase registered in the sister's sole name. Her illegality defence failed: because a brother could rely on the presumption of resulting trust arising from his contribution, he never had to plead his own unlawful act."}, {"url": "https://hklandlaw.wordpress.com/2011/04/30/the-common-intention-constructive-trust-in-the-early-80s/", "title": "The common intention constructive trust in the early 80s", "date": "2011-04-30", "type": "case-note", "topics": ["common-intention-constructive-trust", "beneficial-ownership", "quantification", "cohabitation", "occupation-rent"], "cases": [{"name": "Bernard v Josephs", "citation": "[1982] Ch 391", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "The court hunts for what the couple intended at acquisition, using later conduct as evidence and allowing for subsequent agreements varying the shares. Equal sharing was found; sale was postponed for a buy-out and occupation rent was set against post-separation mortgage payments."}, {"url": "https://hklandlaw.wordpress.com/2011/04/29/quantifying-the-beneficial-interest-under-a-constructive-trust-focuses-on-intention/", "title": "Quantifying the beneficial interest under a constructive trust focuses on intention", "date": "2011-04-29", "type": "case-note", "topics": ["common-intention-constructive-trust", "quantification", "proprietary-estoppel", "sale-of-co-owned-land", "beneficial-ownership"], "cases": [{"name": "Holman v Howes", "citation": "[2007] EWCA Civ 877", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Stack v Dowden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Shares turn on intention, and where none is expressed the court takes a holistic view of the parties' dealings. Though title stood in one name, joint and equal ownership was found, and an assurance of secure occupation grounded an estoppel against forced sale."}, {"url": "https://hklandlaw.wordpress.com/2011/04/28/quantifying-the-beneficial-interest-constructive-v-resulting-trust/", "title": "Quantifying the beneficial interest: Constructive v resulting trust", "date": "2011-04-28", "type": "case-note", "topics": ["common-intention-constructive-trust", "resulting-trust", "quantification", "beneficial-ownership", "cohabitation"], "cases": [{"name": "Drake v Whipp", "citation": "(1996) 28 HLR 53", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Once a common intention trust is established, quantum comes from the whole course of dealing rather than arithmetic on contributions. An unmarried couple converted a barn together; taking the constructive rather than resulting trust route gave the claimant a third, more than contributions alone."}, {"url": "https://hklandlaw.wordpress.com/2011/04/27/issue-and-service-of-a-writ-for-possession-is-an-election-to-forfeit-the-lease/", "title": "Issue and service of a writ for possession is an election to forfeit the lease", "date": "2011-04-27", "type": "case-note", "topics": ["forfeiture", "leases", "election", "repudiatory-breach", "possession-proceedings"], "cases": [{"name": "Po Wai Ching v Pfeifer", "citation": "[1983] 1 HKC 204", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Issuing and serving a possession writ is itself the landlord's election to forfeit. The tenancy ends at that point, so the landlord cannot afterwards fall back on an alleged repudiatory breach: there is no longer any contract to repudiate."}, {"url": "https://hklandlaw.wordpress.com/2011/04/26/liberalising-the-constructive-trust/", "title": "Liberalising the constructive trust", "date": "2011-04-26", "type": "overview", "topics": ["common-intention-constructive-trust", "whole-course-of-dealing", "beneficial-ownership", "matrimonial-home", "quantification"], "cases": [{"name": "Abbott v Abbott", "citation": "[2007] UKPC 53", "court": "UKPC", "jurisdiction": "other"}, {"name": "Oxley v Hiscock", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "The whole course of dealing may show a shared intention without any express agreement, and may go to whether a trust exists at all rather than merely to size of shares. The post notes the reasoning is arguably obiter given a concession about mortgage contributions."}, {"url": "https://hklandlaw.wordpress.com/2011/04/25/blocking-access-to-car-park/", "title": "Blocking access to car park", "date": "2011-04-25", "type": "case-note", "topics": ["easements", "right-of-way", "obstruction", "common-parts", "injunctions"], "cases": [{"name": "Lung Po Kwan v Tang Kam Sheung", "citation": "[2011] HKEC 451", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A neighbour left a van partly across the shared passage in the development's common areas, blocking the way to an adjoining parking space. The owners obtained an injunction against parking that obstructed their access, plus damages."}, {"url": "https://hklandlaw.wordpress.com/2011/04/23/cpu-s-60-and-tort-of-conspiracy-to-injure/", "title": "CPO s.60 and tort of conspiracy to injure", "date": "2011-04-23", "type": "case-note", "topics": ["fraudulent-conveyance", "creditors", "conspiracy", "dispositions", "good-faith-purchaser"], "cases": [{"name": "China Construction Reality Ltd v Sino Business Services Proprietary Ltd", "citation": "[2011] HKEC 436", "court": null, "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.60(3)"], "summary": "Shares moved to a company to put assets beyond a judgment creditor's reach were a disposition intended to defraud creditors. The transferee could not show valuable consideration and good faith, and was also liable for conspiracy to injure the creditor."}, {"url": "https://hklandlaw.wordpress.com/2011/04/22/no-memorandum-where-the-parties-have-expressly-left-open-the-time-for-completion/", "title": "No memorandum where the parties have expressly left open the time for completion", "date": "2011-04-22", "type": "case-note", "topics": ["sale-of-land", "formalities", "memorandum-in-writing", "certainty-of-terms", "completion"], "cases": [{"name": "Johnson v Humphrey", "citation": "[1946] 1 All ER 460", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Where the parties expressly deal with completion in a non-standard way, no reasonable-time term can be implied, and the memorandum must record that arrangement. Tying completion to the seller finding other accommodation was too uncertain, so no contract arose."}, {"url": "https://hklandlaw.wordpress.com/2011/04/21/goods-available-for-distress/", "title": "Goods available for distress", "date": "2011-04-21", "type": "case-note", "topics": ["distress-for-rent", "landlord-and-tenant", "apparent-possession", "third-party-goods", "remedies"], "cases": [{"name": "Xipho Development Co Ltd v CHM Holdings Ltd", "citation": "[1997] HKLRD 36", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Landlord and Tenant (Consolidation) Ordinance (Cap 7) s.87", "Landlord and Tenant (Consolidation) Ordinance (Cap 7) s.88"], "summary": "Distress reaches goods in the tenant's apparent possession at the premises whatever their true ownership, subject to the statutory exceptions. A stranger's ownership claim to seized items accordingly failed."}, {"url": "https://hklandlaw.wordpress.com/2011/04/20/goods-that-can-be-seized-by-bailiff-under-a-warrant-of-distress/", "title": "Goods that can be seized by bailiff under a warrant of distress", "date": "2011-04-20", "type": "case-note", "topics": ["distress-for-rent", "landlord-and-tenant", "apparent-possession", "bailiffs", "third-party-goods"], "cases": [{"name": "Kelland Co Ltd v Pacific Ace International Holdings Ltd", "citation": "[2011] HKEC 427", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Landlord and Tenant (Consolidation) Ordinance s.91"], "summary": "A bailiff under a warrant may take goods belonging to the tenant and goods merely in the tenant's apparent possession. Claims by unpaid sellers and true owners of items found at the premises were rejected."}, {"url": "https://hklandlaw.wordpress.com/2011/04/19/licence-sometimes-it-means-what-it-says/", "title": "'Licence' - sometimes it means what it says", "date": "2011-04-19", "type": "case-note", "topics": ["licences", "leases", "exclusive-possession", "tenancy-by-estoppel", "public-housing"], "cases": [{"name": "Camden London Borough Council v Shortlife Community Housing", "citation": "(1993) 25 HLR 330", "court": "other", "jurisdiction": "EN"}, {"name": "Bruton v London & Quadrant Housing Trust", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Housing Act 1980 s.91"], "summary": "Occupation pending redevelopment was genuinely a licence: the council kept the control it needed, both sides so intended, and statute barred a lease without ministerial consent. Occupiers knowing the intermediary could grant no tenancy got no tenancy by estoppel."}, {"url": "https://hklandlaw.wordpress.com/2011/04/18/contractual-licence-coupled-with-actual-occupation-is-it-an-interest-in-land/", "title": "Contractual licence coupled with actual occupation: is it an interest in land?", "date": "2011-04-18", "type": "case-note", "topics": ["licences", "interests-in-land", "overriding-interests", "matrimonial-home", "mortgages"], "cases": [{"name": "National Provincial Bank Ltd v Hastings Car Mart Ltd", "citation": "[1964] Ch 665", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Land Registration Act 1925 s.70(1)(g)"], "summary": "A husband put the matrimonial home into his company, which mortgaged it. The majority reasoned that because equity would restrain revocation the deserted wife's licence was an equitable interest protected by her occupation; the dissent kept licences purely personal."}, {"url": "https://hklandlaw.wordpress.com/2011/04/16/constructive-trust-and-proprietary-estoppel-how-specific-must-the-assurance-be/", "title": "Constructive trust and proprietary estoppel: how specific must the assurance be?", "date": "2011-04-16", "type": "case-note", "topics": ["common-intention-constructive-trust", "proprietary-estoppel", "assurances", "post-acquisition-intention", "detrimental-reliance"], "cases": [{"name": "James v Thomas", "citation": "[2007] EWCA Civ 1212", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A trust can form after acquisition if intention is shown by agreement or conduct, and estoppel needs an assurance of some interest without exact quantification. Heavy work and money by the claimant proved nothing about intention, so both routes failed."}, {"url": "https://hklandlaw.wordpress.com/2011/04/15/son-holding-land-as-nominee-failure-to-show-that-there-had-been-a-gift/", "title": "Son holding land as nominee: failure to show that there had been a gift", "date": "2011-04-15", "type": "case-note", "topics": ["resulting-trust", "nominee-holding", "presumption-of-advancement", "beneficial-ownership", "family-property"], "cases": [{"name": "Ip Man Shan v Ching Hing Construction Co Ltd", "citation": "[2005] HKEC 188", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "The father and a family company paid for the land and the building work while title went into the son's name. With no evidence of any intention to give him the property, he held it as nominee and trustee for those who paid."}, {"url": "https://hklandlaw.wordpress.com/2011/04/14/failure-to-spot-a-break-clause/", "title": "Failure to spot a break clause", "date": "2011-04-14", "type": "case-note", "topics": ["break-clause", "leases", "proprietary-estoppel", "estoppel-by-convention", "constructive-trust"], "cases": [{"name": "Crossco No 4 Unlimited v Jolan Ltd", "citation": "[2011] EWHC 803 (Ch)", "court": "other", "jurisdiction": "EN"}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "After a demerger the trading side overlooked a break right and the property side exercised it. Estoppel, estoppel by convention and a Pallant v Morgan trust all failed: no assurance was given, the landlord did not know of the tenant's ignorance, and nothing was unconscionable."}, {"url": "https://hklandlaw.wordpress.com/2011/04/13/human-rights-and-rent-control-security-of-tenure/", "title": "Human rights and rent control / security of tenure", "date": "2011-04-13", "type": "case-note", "topics": ["human-rights", "rent-control", "security-of-tenure", "property-rights", "landlord-and-tenant"], "cases": [{"name": "Amato Gauci v Malta", "citation": "(2011) 52 EHRR 25", "court": "other", "jurisdiction": "other"}], "statutes": ["European Convention on Human Rights Protocol 1 Article 1"], "summary": "Rent restriction can serve the general interest but must not load an excessive burden on owners. Turning a 25-year lease into an indefinite inheritable tenancy at far below market rent, without regard to the landlord's own needs, went too far."}, {"url": "https://hklandlaw.wordpress.com/2011/04/12/human-rights-and-satellite-dishes/", "title": "Human rights and satellite dishes", "date": "2011-04-12", "type": "case-note", "topics": ["human-rights", "freedom-of-information", "landlord-and-tenant", "forfeiture", "proportionality"], "cases": [{"name": "Khurshid Mustafa v Sweden", "citation": "(2011) 52 EHRR 24", "court": "other", "jurisdiction": "other"}], "statutes": ["European Convention on Human Rights Article 10", "European Convention on Human Rights Article 10(2)"], "summary": "Ordering Iraqi tenants in Stockholm to take down a dish receiving home-country broadcasts breached freedom to receive information. Safety and appearance showed no pressing social need, and losing the family's home was disproportionate given the cultural interests at stake."}, {"url": "https://hklandlaw.wordpress.com/2011/04/11/ambulatory-constructive-trust-v-post-acquisition-agreement/", "title": "'Ambulatory' constructive trust v post-acquisition agreement", "date": "2011-04-11", "type": "overview", "topics": ["common-intention-constructive-trust", "ambulatory-trust", "post-acquisition-agreement", "priority", "beneficial-ownership"], "cases": [{"name": "Chan Chui Mee v Mak Chi Choi", "citation": "[2008] HKEC 1572", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Distinguish a trust where shares were always to be fixed later by the parties' dealings from a fresh agreement varying settled shares. The first takes priority from the outset; the second needs strong evidence and cannot override third-party interests already acquired."}, {"url": "https://hklandlaw.wordpress.com/2011/04/09/proprietary-estoppel-need-to-balance-the-needs-of-the-property-owner-and-the-detriment-suffered-by-the-claimant/", "title": "Proprietary estoppel: need to balance the needs of the property owner and the detriment suffered by the claimant?", "date": "2011-04-09", "type": "case-note", "topics": ["proprietary-estoppel", "satisfying-the-equity", "proportionality", "detriment", "remedies"], "cases": [{"name": "Sledmore v Dalby", "citation": "(1996) 72 P & CR 196", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "In shaping relief the court may weigh the owner's position against the claimant's detriment. Despite improvements made in reliance, the owner's pressing financial need and the claimant's slight use of the house meant she recovered possession; the equity was already spent."}, {"url": "https://hklandlaw.wordpress.com/2011/04/08/actual-undue-influence-does-it-need-to-make-a-difference/", "title": "Actual undue influence: does it need to make a difference?", "date": "2011-04-08", "type": "case-note", "topics": ["undue-influence", "mortgages", "sureties", "independent-advice", "matrimonial-home"], "cases": [{"name": "UCB Corporate Services Ltd v Williams", "citation": "[2002] EWCA Civ 555", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Once actual undue influence is established, no causation enquiry into what the victim would otherwise have done is needed. A wife who charged the home for her husband's business debts obtained relief even though the judge thought she would have signed anyway."}, {"url": "https://hklandlaw.wordpress.com/2011/04/07/receiver-managing-mortgaged-property-owes-the-mortgagor-a-duty-of-due-diligence/", "title": "Receiver managing mortgaged property owes the mortgagor a duty of due diligence", "date": "2011-04-07", "type": "case-note", "topics": ["mortgages", "receivers", "duties-of-mortgagee", "good-faith", "equity-of-redemption"], "cases": [{"name": "Medforth v Blake", "citation": "[2000] Ch 686", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A receiver owes good faith and, in managing the property, due diligence, aiming at repayment of principal and interest. He need not carry on a business, but if he does he must try to run it profitably."}, {"url": "https://hklandlaw.wordpress.com/2011/04/06/break-clause-cannot-be-invoked-once-the-landlord-has-elected-to-forfeit-the-lease/", "title": "The effect of forfeiture on lease covenants and break rights", "date": "2011-04-06", "type": "case-note", "topics": ["forfeiture", "break-clause", "leases", "election", "re-entry"], "cases": [{"name": "Prime Aspect Ltd v Chan Wan Hung", "citation": "[2011] HKEC 391", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Having elected to forfeit by re-entry or writ, a landlord can no longer rely on the lease's covenants, including a break right. Serving a possession writ for unpaid rent and then purporting to break the term was therefore ineffective."}, {"url": "https://hklandlaw.wordpress.com/2011/04/05/failure-to-leave-when-a-licence-is-revoked-is-trespass/", "title": "Failure to leave when a licence is revoked is trespass", "date": "2011-04-05", "type": "case-note", "topics": ["licences", "revocation", "trespass", "possession", "remedies"], "cases": [{"name": "Thompson v Park", "citation": "[1944] KB 408", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Revocation ends the right to be there even if it breaks the contract, so an occupier who stays becomes a trespasser. A headmaster allowed to share school premises trespassed by remaining and forcing his way back in after permission was withdrawn."}, {"url": "https://hklandlaw.wordpress.com/2011/04/04/is-a-building-that-interferes-with-tv-or-radio-reception-an-actionable-nuisance/", "title": "Is a building that interferes with TV or radio reception an actionable nuisance", "date": "2011-04-04", "type": "case-note", "topics": ["nuisance", "standing-to-sue", "prescription", "right-to-light", "planning"], "cases": [{"name": "Hunter v Canary Wharf Ltd", "citation": "(1998) 30 HLR 409", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Only those with an interest in the land can sue in private nuisance, so family members cannot. Building on your own land is no nuisance merely because it spoils a neighbour's reception; no such right arises by prescription, and planning law governs."}, {"url": "https://hklandlaw.wordpress.com/2011/04/02/calculation-of-loss-of-income-for-purposes-of-disturbance-payment-under-the-railways-ordinance/", "title": "Calculation of loss of income for purposes of 'disturbance payment' under the Railways Ordinance", "date": "2011-04-02", "type": "case-note", "topics": ["compulsory-acquisition", "compensation", "disturbance-payment", "valuation", "land-tribunal"], "cases": [{"name": "Lingrade Development Ltd v Secretary for the Environment", "citation": "[2011] HKEC 307", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Railways Ordinance (Cap 519)"], "summary": "Compensation for delay caused by statutory occupation was measured by comparing the prices actually obtained with those obtainable but for the delay, adjusted by New Territories indices. Lord Hoffmann NPJ preferred that to the developer's own forecasts as firmer and more realistic."}, {"url": "https://hklandlaw.wordpress.com/2011/04/01/implied-long-stop-date-in-agreement-for-the-sale-of-a-small-house/", "title": "Implied long-stop date in agreement for the sale of a Small House", "date": "2011-04-01", "type": "case-note", "topics": ["sale-of-land", "conditional-contracts", "implied-terms", "completion", "damages"], "cases": [{"name": "Wong On Na v Harbour Well Development Ltd", "citation": "[2002] HKEC 2", "court": "CFI", "jurisdiction": "HK"}, {"name": "Johnson v Humphrey", "citation": "[1946] 1 All ER 460", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "No long-stop date is implied into a conditional agreement whose whole premise is uncertainty and waiting for the condition. Completion depended on a certificate of compliance outside the seller's control; damages ran on the falling market price at the hearing date."}, {"url": "https://hklandlaw.wordpress.com/2011/03/31/easement-not-abandoned-where-owners-tenant-blocked-door/", "title": "Easement not abandoned where owner's tenant blocked door", "date": "2011-03-31", "type": "case-note", "topics": ["easements", "abandonment", "right-of-way", "common-parts", "non-user"], "cases": [{"name": "Wong Kwan Yee v Incorporated Owners of Diamond Mansion", "citation": "[2011] HKEC 315", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Abandonment turns on intention and is not lightly inferred from mere non-user. Forty years of using a doorway from the lobby outweighed a comparatively short interruption after the owner's tenant blocked it in 2004, so the right survived."}, {"url": "https://hklandlaw.wordpress.com/2011/03/30/implied-obligation-to-give-reasonable-time-to-comply-with-split-cheques-stipulation/", "title": "Implied obligation to give reasonable time to comply with 'split cheques' stipulation", "date": "2011-03-30", "type": "case-note", "topics": ["sale-of-land", "completion", "time-of-the-essence", "implied-terms", "rescission"], "cases": [{"name": "Kensland Realty Ltd v Whale View Investment Ltd", "citation": "[2002] 1 HKLRD 87", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Sellers must give buyers reasonable notice of split cheque particulars, and cannot insist on time being of the essence when their own lateness caused the default. The buyer could rescind, and completing within a reasonable time after the deadline sufficed."}, {"url": "https://hklandlaw.wordpress.com/2011/03/29/claim-under-proprietary-estoppel-and-constructive-trust-fathers-assurances-to-daughter/", "title": "Claim under proprietary estoppel and constructive trust: father's assurances to daughter", "date": "2011-03-29", "type": "case-note", "topics": ["proprietary-estoppel", "common-intention-constructive-trust", "assurances", "detrimental-reliance", "donatio-mortis-causa"], "cases": [{"name": "Chan Gordon v Lee Wai Hing", "citation": "[2011] HKEC 300", "court": null, "jurisdiction": "HK"}, {"name": "Pennington v Waine", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "A father's promise that his daughter would always have a rent-free home read as an assurance of ownership. Handing over much of her income and paying repairs and legal costs was sufficient detriment; imperfect gift and resulting trust claims failed."}, {"url": "https://hklandlaw.wordpress.com/2011/03/28/undue-influence-when-guarantee-signed-without-providing-relevant-information/", "title": "Undue influence when guarantee signed without providing relevant information", "date": "2011-03-28", "type": "case-note", "topics": ["undue-influence", "sureties", "guarantees", "independent-advice", "constructive-notice"], "cases": [{"name": "Royal Bank of Scotland plc v Etridge (No 2)", "citation": "[2002] 2 AC 773", "court": "HL", "jurisdiction": "EN"}, {"name": "Royal Bank of Scotland plc v Chandra", "citation": "[2010] EWHC 105 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Lenders must follow the Etridge steps, supplying information about the debtor's finances and allowing real time for independent advice. A wife told of the guarantee only while travelling to sign it had her second guarantee set aside; the bank had constructive notice."}, {"url": "https://hklandlaw.wordpress.com/2011/03/26/priority-as-between-unregistered-instrument-and-a-subsequent-registered-instrument/", "title": "Priority as between unregistered instrument and a subsequent registered instrument", "date": "2011-03-26", "type": "case-note", "topics": ["land-registration", "priority", "notice", "good-faith", "bona-fide-purchaser"], "cases": [{"name": "Kwok Siu Lau v Kan Yang Che", "citation": "(1913) 8 HKLR 52", "court": "other", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3", "Land Registration Ordinance s.3(2)", "Land Registration Ordinance s.4"], "summary": "A registrable instrument left unregistered loses to a later purchaser for value in good faith who registers, even one who knew of it. Good faith under the statute is distinct from equitable notice, so knowledge alone is not bad faith."}, {"url": "https://hklandlaw.wordpress.com/2011/03/25/good-faith-and-section-31-lro/", "title": "Good faith and section 3(1) LRO", "date": "2011-03-25", "type": "case-note", "topics": ["land-registration", "priority-of-interests", "unregistered-interests", "good-faith", "options-to-purchase"], "cases": [{"name": "Keep Point Development Ltd v Chan Yi Yim v Full Country Development", "citation": "[2000] 2 HKLRD 145", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3(1)", "Land Registration Ordinance s.3(2)"], "summary": "Priority under the registration statute turns on the register, not on the later purchaser's honesty; unregistered options lost out regardless of what that purchaser knew or intended."}, {"url": "https://hklandlaw.wordpress.com/2011/03/24/effect-of-acquisition-of-land-without-notice-of-a-restrictive-covenant/", "title": "Effect of acquisition of land without notice of a restrictive covenant", "date": "2011-03-24", "type": "case-note", "topics": ["restrictive-covenants", "bona-fide-purchaser", "doctrine-of-notice", "equitable-interests", "running-of-burden"], "cases": [{"name": "Wilkes v Spooner", "citation": "[1911] 2 KB 473", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Once land reaches a purchaser for value with no notice, the covenant's burden is destroyed permanently. A later taker who does know of the covenant still takes free of it."}, {"url": "https://hklandlaw.wordpress.com/2011/03/23/effectiveness-of-evidence-to-show-that-an-assignment-was-intended-to-have-some-other-effect/", "title": "Effectiveness of evidence to show that an assignment was intended to have some other effect", "date": "2011-03-23", "type": "case-note", "topics": ["assignment", "parol-evidence-rule", "resulting-trust", "estoppel-by-registration", "bona-fide-purchaser"], "cases": [{"name": "Tsang Chuen v Li Po Kwai", "citation": "[1932] AC 715", "court": "PC", "jurisdiction": "HK"}], "statutes": [], "summary": "An assignor who signed an outright transfer could not lead evidence recasting it as a mere family allocation. Any resulting trust yielded to purchasers without notice, and registration estopped him from contradicting the recorded deal."}, {"url": "https://hklandlaw.wordpress.com/2011/03/22/does-seller-have-good-title-where-the-buyer-has-notice-of-a-later-equitable-interest/", "title": "Does seller have good title where the buyer has notice of a later equitable interest", "date": "2011-03-22", "type": "case-note", "topics": ["good-title", "equitable-interests", "resulting-trust", "notice", "sale-and-purchase-agreement"], "cases": [{"name": "Lam Sau-Wah v Tam Chi Hung", "citation": "[2001] 2 HKLRD 104", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Even ranking ahead of a trust claimant, the buyer could not be forced to complete: with an appeal pending nobody could say who was entitled to the outstanding money, so the vendor could not show he could convey cleanly."}, {"url": "https://hklandlaw.wordpress.com/2011/03/21/competing-equitable-interests-where-the-equities-are-not-equal/", "title": "Competing equitable interests where the equities are not equal", "date": "2011-03-21", "type": "case-note", "topics": ["competing-equities", "priority-of-interests", "equitable-interests", "false-colours", "first-in-time"], "cases": [{"name": "Nu Life International Ltd v Healthy Living Products International Ltd", "citation": "[2008] 2 HKLRD 297", "court": "other", "jurisdiction": "HK"}, {"name": "Freeguard v Royal Bank of Scotland plc", "citation": null, "court": null, "jurisdiction": null}, {"name": "Dixon v Muckleston", "citation": "(1872-73) LR 8 Ch App 155", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "The first-in-time rule for equitable interests gives way where the earlier claim rests on a contrived transaction, or where its holder let someone else appear to the world as unencumbered owner."}, {"url": "https://hklandlaw.wordpress.com/2011/03/19/selling-the-same-property-to-two-different-buyers/", "title": "Selling the same property to two different buyers", "date": "2011-03-19", "type": "case-note", "topics": ["double-sale", "competing-equities", "specific-performance", "first-in-time", "land-registration"], "cases": [{"name": "Chu Kit-Yuk v Country Wide Industrial Ltd", "citation": "[1995] 2 HKLR 162", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance"], "summary": "Both sale contracts generated equitable interests of equal quality, so the earlier buyer won specific performance despite never registering; the disappointed second buyer was left to sue the vendor for damages."}, {"url": "https://hklandlaw.wordpress.com/2011/03/18/effect-of-the-new-territories-leases-extension-ordinance-on-squatters/", "title": "Effect of the New Territories Leases (Extension) Ordinance on squatters", "date": "2011-03-18", "type": "case-note", "topics": ["adverse-possession", "limitation-periods", "new-territories-leases", "lease-extension", "squatters-rights"], "cases": [{"name": "Chan Tin Shi v Li Tin Sung", "citation": "[2006] 1 HKLRD 185", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["New Territories Leases (Extension) Ordinance (Cap. 150) s.6", "Limitation Ordinance"], "summary": "Stretching the term of existing New Territories leases to 2047 was treated as prolonging the same lease rather than granting a fresh one, so the limitation clock never restarted and long-standing squatters kept what they had gained."}, {"url": "https://hklandlaw.wordpress.com/2011/03/17/the-operation-of-the-doctrine-of-encroachment-when-the-tenant-acquires-the-reversion/", "title": "The operation of the doctrine of encroachment when the tenant acquires the reversion", "date": "2011-03-17", "type": "case-note", "topics": ["encroachment", "adverse-possession", "landlord-and-tenant", "merger", "reversion"], "cases": [{"name": "Tower Hamlets LBC v Barrett", "citation": "[2005] EWCA Civ 923", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Land a tenant encroaches on is normally held for the landlord, but tenants who bought the freehold were presumed to buy the encroached strip too, and no merger was presumed since both sides wanted their possession preserved."}, {"url": "https://hklandlaw.wordpress.com/2011/03/16/sellers-duty-to-take-reasonable-care-of-the-property-between-contract-and-completion/", "title": "Seller's duty to take reasonable care of the property between contract and completion", "date": "2011-03-16", "type": "case-note", "topics": ["vendor-purchaser-relationship", "constructive-trust", "duty-of-care", "risk-pending-completion", "conveyancing"], "cases": [{"name": "Clarke v Ramuz", "citation": "[1891] 2 QB 456", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Between exchange and completion a vendor must take reasonable steps to keep the land as it was. One who let a trespasser strip away the topsoil had to compensate the buyer for the loss."}, {"url": "https://hklandlaw.wordpress.com/2011/03/15/assignee-of-a-contract-has-to-give-clear-notice-to-original-vendor/", "title": "Assignee of a contract has to give clear notice to original vendor", "date": "2011-03-15", "type": "case-note", "topics": ["assignment-of-contract", "notice", "vendor-purchaser-relationship", "equitable-assignment", "conveyancing"], "cases": [{"name": "Shaw v Foster", "citation": "(1871-1872) LR 5 HL 321", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Notice hinting only at a possible future assignment, and silent on whether the assignee would shoulder the buyer's obligations, was too vague; the vendor was therefore entitled to convey to the original purchaser instead."}, {"url": "https://hklandlaw.wordpress.com/2011/03/14/vendors-lien-for-balance-of-purchase-price/", "title": "Vendor's lien for balance of purchase price", "date": "2011-03-14", "type": "case-note", "topics": ["vendors-lien", "equitable-lien", "unpaid-purchase-price", "succession", "administration-of-estates"], "cases": [{"name": "Re Birmingham, dec'd", "citation": "[1959] Ch 523", "court": "other", "jurisdiction": "EN"}], "statutes": ["Administration of Estates Act s.35(1) (UK)"], "summary": "The lien for unpaid price bites from the moment of contract, though it is only enforced at completion. A buyer dying beforehand meant the debt fell on the daughter's specific gift, not the residue."}, {"url": "https://hklandlaw.wordpress.com/2011/03/12/party-seeking-to-enforce-a-contract-can-waive-an-orally-agreed-term-that-is-to-his-advantage/", "title": "Party seeking to enforce a contract can waive an orally agreed term that is to his advantage", "date": "2011-03-12", "type": "case-note", "topics": ["memorandum-in-writing", "waiver", "oral-terms", "formalities", "agency"], "cases": [{"name": "North v Loomes", "citation": "[1919] 1 Ch 378", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "A written receipt omitted an oral promise that the buyer pay costs; the seller could simply give up that benefit and still enforce. A solicitor told to finalise an agreed deal has implied authority over the formalities."}, {"url": "https://hklandlaw.wordpress.com/2011/03/11/sale-by-agent-and-purchaser-in-occupation-pending-completion/", "title": "Sale by agent and purchaser in occupation pending completion", "date": "2011-03-11", "type": "case-note", "topics": ["agency", "specific-performance", "occupation-pending-completion", "small-house-policy", "conveyancing"], "cases": [{"name": "Yuen Lai Tui v All occupiers of ground floor of building on Lot No 2352", "citation": "[2006] HKEC 2116", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "An agent's authority to sell land need not be written down. With the purchaser already in occupation and ready to tender the balance, completion was ordered, subject to adjustment if Small House certificates proved unobtainable."}, {"url": "https://hklandlaw.wordpress.com/2011/03/10/parties-to-a-contract-have-an-implied-duty-to-cooperate-in-the-performance-of-contractual-obligations/", "title": "Parties to a contract have an implied duty to cooperate in the performance of contractual obligations", "date": "2011-03-10", "type": "case-note", "topics": ["implied-terms", "duty-to-cooperate", "forfeiture", "relief-from-forfeiture", "landlord-and-tenant"], "cases": [{"name": "Quick Switch Ltd v Shining Star Super Seafood Ltd", "citation": "[2011] HKEC 232", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "A tenant lost its mahjong licence covenant fight but escaped forfeiture: the court granted relief and directed the landlord to hand over the information the tenant needed, recognising a mutual obligation to enable performance."}, {"url": "https://hklandlaw.wordpress.com/2011/03/09/no-contract-where-the-auctioneers-authority-has-been-revoked/", "title": "No contract where the auctioneer's authority has been revoked", "date": "2011-03-09", "type": "case-note", "topics": ["auction-sales", "agency", "actual-authority", "breach-of-warranty-of-authority", "formation-of-contract"], "cases": [{"name": "Hoie Sook Fong v Ismail Halima", "citation": "[2008] HKEC 2213", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Once the owner withdrew the auctioneer's mandate, the fall of the hammer bound nobody and the owner walked away. The auctioneers themselves were exposed to the bidder for warranting an authority they no longer held."}, {"url": "https://hklandlaw.wordpress.com/2011/03/08/rectification/", "title": "Rectification", "date": "2011-03-08", "type": "case-note", "topics": ["rectification", "common-mistake", "contractual-interpretation", "common-intention", "equitable-remedies"], "cases": [{"name": "Chartbrook Ltd v Persimmon Homes Ltd", "citation": "[2009] 1 AC 1101", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Rectification needs a shared, outwardly expressed intention that survives to execution and is then misrecorded by mistake. Chartbrook won on construction anyway, but the Lords said rectification would equally have worked."}, {"url": "https://hklandlaw.wordpress.com/2011/03/07/background-knowledge-and-the-construction-of-contracts/", "title": "Background knowledge and the construction of contracts", "date": "2011-03-07", "type": "case-note", "topics": ["contractual-interpretation", "correction-by-construction", "factual-matrix", "pre-contractual-negotiations", "rectification"], "cases": [{"name": "Chartbrook Ltd v Persimmon Homes Ltd", "citation": "[2009] 1 AC 1101", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Where an obvious slip appears on the face of a document and the cure is plain, construction alone can fix it, read through the eyes of a reasonable person sharing the parties' background. Prior negotiations stay excluded."}, {"url": "https://hklandlaw.wordpress.com/2011/03/05/encroachment-and-lease-renewals/", "title": "Encroachment and lease renewals", "date": "2011-03-05", "type": "case-note", "topics": ["encroachment", "lease-renewal", "adverse-possession", "limitation-periods", "new-territories-leases"], "cases": [{"name": "Chau Ka Chik Tso v Secretary for Justice", "citation": "[2011] HKEC 208", "court": "CA", "jurisdiction": "HK"}, {"name": "Chung Ping Kwan v Lam Island Development Ltd", "citation": "[1997] AC 38", "court": "PC", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance", "New Territories (Renewable Leases) Ordinance"], "summary": "Renewal produced one continuous lease split into two stretches, so the renewed term took subject to rights the tenant had already begun to accrue; the limitation clock ran on rather than restarting."}, {"url": "https://hklandlaw.wordpress.com/2011/03/05/the-basis-of-the-doctrine-of-encroachment/", "title": "The basis of the doctrine of encroachment", "date": "2011-03-05", "type": "case-note", "topics": ["encroachment", "adverse-possession", "estoppel", "limitation-periods", "landlord-and-tenant"], "cases": [{"name": "Chau Ka Chik Tso v Secretary for Justice", "citation": "[2011] HKEC 208", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance"], "summary": "Encroached land is absorbed into the demise. The doctrine works on estoppel-like reasoning: seventy years of Government silence over a fish farm spreading onto state land barred recovery until the lease ended."}, {"url": "https://hklandlaw.wordpress.com/2011/03/04/liability-for-damage-cause-by-faulty-waterproof-roof-membrane/", "title": "Liability for damage caused by faulty waterproof roof membrane", "date": "2011-03-04", "type": "case-note", "topics": ["common-parts", "building-management", "incorporated-owners", "repair-obligations", "multi-storey-buildings"], "cases": [{"name": "Kimberley Assets Management Ltd v Golden Star Overseas Ltd", "citation": "[2011] HKEC 238", "court": "other", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "The Lands Tribunal classified the membrane under the roof surface as a common part, so the Incorporated Owners carried the upkeep burden and answered for water damage inflicted on the flat beneath."}, {"url": "https://hklandlaw.wordpress.com/2011/03/03/adverse-possession-and-intention-to-possess/", "title": "Adverse possession and intention to possess", "date": "2011-03-03", "type": "case-note", "topics": ["adverse-possession", "intention-to-possess", "acknowledgement-of-title", "limitation-periods", "squatters-rights"], "cases": [{"name": "Yu Kit Chiu v Chan Shek Woo", "citation": "[2011] HKEC 244", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "An occupier since 1962 sank his own claim by signing a 1970 tenancy modification in the owner's name, conceding the owner still possessed. Whether hypothetical willingness to pay rent matters was left unsettled."}, {"url": "https://hklandlaw.wordpress.com/2011/03/02/once-there-is-a-valid-contract-the-seller-is-constructive-trustee-of-the-property/", "title": "Once there is a valid contract the seller is constructive trustee of the property", "date": "2011-03-02", "type": "case-note", "topics": ["constructive-trust", "vendor-purchaser-relationship", "passing-of-risk", "vendors-lien", "beneficial-ownership"], "cases": [{"name": "Lysaght v Edwards", "citation": "(1875-76) L.R. 2 Ch.D. 499", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "On contract the beneficial interest moves to the buyer while the vendor keeps bare legal title, a lien for the price, possession and rents, but must avoid deliberate harm and take reasonable care; risk shifts to the buyer."}, {"url": "https://hklandlaw.wordpress.com/2011/03/01/the-rule-against-perpetuities-has-long-been-a-part-of-hong-kong-law/", "title": "The rule against perpetuities has long been a part of Hong Kong law", "date": "2011-03-01", "type": "case-note", "topics": ["rule-against-perpetuities", "leasehold-interests", "chinese-customary-law", "testamentary-gifts", "ancestral-trusts"], "cases": [{"name": "Lau Leung Shi v Lau Po Tsun", "citation": "(1911) 6 HKLR 149", "court": "other", "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance"], "summary": "A China-domiciled testator's gift of Hong Kong leasehold for ancestral sacrifices was struck down as perpetuitous, the rule applying to such leaseholds. That holding must now be read alongside the New Territories Ordinance."}, {"url": "https://hklandlaw.wordpress.com/2011/02/28/can-owner-of-dominant-tenement-use-a-right-of-way-for-the-benefit-of-other-nearby-land/", "title": "Can the owner of a dominant tenement use a right of way for the benefit of other nearby land?", "date": "2011-02-28", "type": "case-note", "topics": ["easements", "right-of-way", "dominant-tenement", "excessive-user", "trespass"], "cases": [{"name": "Peacock v Custins", "citation": "[2002] 1 WLR 1815", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A way granted for one plot serves only that plot. Routing access to neighbouring land the grantee happens to own is trespass, and it makes no difference that the extra traffic is slight."}, {"url": "https://hklandlaw.wordpress.com/2011/02/27/when-is-the-merger-of-a-lease-and-the-reversion-intended/", "title": "When is the merger of a lease and the reversion intended?", "date": "2011-02-27", "type": "case-note", "topics": ["merger", "lease-and-reversion", "mortgages", "equitable-presumptions", "landlord-and-tenant"], "cases": [{"name": "Capital and Counties Bank Ltd v Rhodes", "citation": "[1903] 1 Ch 631", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Merger follows intention, not automatic operation of law. Equity assumes nobody meant to merge where doing so would damage their interests or breach a duty, as with a mortgagee relying on the rent covenant."}, {"url": "https://hklandlaw.wordpress.com/2011/02/26/conduct-required-for-surrender-by-operation-of-law/", "title": "Conduct required for surrender by operation of law", "date": "2011-02-26", "type": "case-note", "topics": ["surrender-by-operation-of-law", "estoppel", "landlord-and-tenant", "termination-of-lease", "unequivocal-conduct"], "cases": [{"name": "Bellcourt Estates Ltd v Adesina", "citation": "[2005] EWCA Civ 208", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Surrender demands behaviour on both sides consistent only with the tenancy being over, making denial inequitable. A landlord who simply did nothing after the tenant left and stopped paying had not accepted a surrender."}, {"url": "https://hklandlaw.wordpress.com/2011/02/25/the-definition-of-common-parts-in-section-2-of-the-building-management-ordinance/", "title": "The definition of \"common parts\" in section 2 of the Building Management Ordinance", "date": "2011-02-25", "type": "case-note", "topics": ["common-parts", "building-management", "statutory-interpretation", "deed-of-mutual-covenant", "exclusive-use"], "cases": [{"name": "Incorporated Owners of Westlands Garden v Oey Chiou Ling", "citation": "[2011] HKEC 254", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.2", "Building Management Ordinance Schedule 1"], "summary": "Two gateways define common parts: anything not set aside for exclusive use, or anything in Schedule 1. The court hinted Schedule 1 items need strong documentary evidence to be carved out; internal partition walls fell outside it."}, {"url": "https://hklandlaw.wordpress.com/2011/02/24/729/", "title": "Ownership of partition walls dividing apartments", "date": "2011-02-24", "type": "case-note", "topics": ["common-parts", "partition-walls", "deed-of-mutual-covenant", "building-management", "contractual-interpretation"], "cases": [{"name": "The Incorporated Owners of Westlands Garden v Oey Chiou Ling and Wong Fung Ling", "citation": "[2011] HKEC 254", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.2"], "summary": "Ownership of dividing walls turns on what the first sale documents and DMC meant in their original setting. Developers would hardly have made every partition common, since that would block later resizing of units."}, {"url": "https://hklandlaw.wordpress.com/2011/02/23/the-rule-against-perpetuities-does-not-apply-to-compensation-paid-on-the-resumption-of-tso-land/", "title": "The rule against perpetuities does not apply to compensation paid on the resumption of Tso land", "date": "2011-02-23", "type": "case-note", "topics": ["rule-against-perpetuities", "tso-and-tong", "chinese-customary-law", "land-resumption", "partition"], "cases": [{"name": "Kan Fat-Tat v Kan Yin-Tat", "citation": "[1987] HKLR 516", "court": "other", "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance s.13"], "summary": "Money paid when the Government resumes Tso land stays Tso property and escapes the perpetuities rule. Partition law does not reach such holdings, and any sale or division needs every member to agree."}, {"url": "https://hklandlaw.wordpress.com/2011/02/22/perfecting-transfer-of-land-to-a-tong/", "title": "Perfecting transfer of land to a tong", "date": "2011-02-22", "type": "case-note", "topics": ["tso-and-tong", "chinese-customary-law", "trusts", "land-registration", "new-territories-land"], "cases": [{"name": "Chu Tak-Hing v Chu Chan Cheung-Ki", "citation": "[1968] HKLR 542", "court": "other", "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance s.15"], "summary": "Conveying into the tong's name, naming a sze lei, and registering both deed and membership lists completes the gift. The land leaves private hands and is held for male descendants of the ancestor for the time being."}, {"url": "https://hklandlaw.wordpress.com/2011/02/21/tso-and-tong-are-not-legal-entities/", "title": "Tso and Tong are not legal entities", "date": "2011-02-21", "type": "case-note", "topics": ["tso-and-tong", "legal-personality", "chinese-customary-law", "beneficial-ownership", "standing-to-sue"], "cases": [{"name": "Tang Yau Yi Tong v Tang Mou Shau Tso", "citation": "[1996] 2 HKLR 212", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Neither a Tso nor a Tong has personality, so nothing can be litigated in its name. Where a donor had acted for a Tso, the benefit belonged to that Tso rather than to his estate."}, {"url": "https://hklandlaw.wordpress.com/2011/02/20/partition-of-tso-lands/", "title": "Partition of Tso lands", "date": "2011-02-20", "type": "case-note", "topics": ["tso-and-tong", "partition", "chinese-customary-law", "rule-against-perpetuities", "new-territories-land"], "cases": [{"name": "Tang Kai-Chung v Tang Chik-Shang", "citation": "[1970] HKLR 276", "court": "other", "jurisdiction": "HK"}], "statutes": ["New Territories Ordinance (Cap 97) s.13"], "summary": "Section 13 obliges courts to apply Chinese custom to New Territories land, so English partition rules and perpetuities have no place. Branches descended from six sons could not force an equal carve-up of Tso land."}, {"url": "https://hklandlaw.wordpress.com/2011/02/19/stack-v-dowden/", "title": "Stack v Dowden", "date": "2011-02-19", "type": "case-note", "topics": ["common-intention-constructive-trust", "joint-ownership", "beneficial-interests", "resulting-trust", "family-home"], "cases": [{"name": "Stack v Dowden", "citation": "[2007] UKHL 17, [2007] 2 AC 432", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Joint legal owners are presumed to hold equally in equity, displaced only in unusual cases. Separate finances and a 65/35 contribution split were unusual enough, giving Stack 35 percent; Lord Neuberger preferred resulting trust reasoning."}, {"url": "https://hklandlaw.wordpress.com/2011/02/18/construction-of-deed-of-easement/", "title": "Construction of deed of easement", "date": "2011-02-18", "type": "case-note", "topics": ["easements", "deed-construction", "factual-matrix", "right-of-way", "scope-of-grant"], "cases": [{"name": "Carpenter v Calico Quays Ltd", "citation": "[2011] EWHC 96", "court": "other", "jurisdiction": "EN"}, {"name": "Investors Compensation Scheme v West Bromwich Building Society", "citation": "[1998] 1 WLR 896", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Words and plans do not exhaust the grant: surrounding circumstances known to both sides count. A right over the Roadway was read to take in the grass verges, which existed and were used when the deed was made."}, {"url": "https://hklandlaw.wordpress.com/2011/02/17/are-non-load-bearing-walls-between-neighbouring-units-common-parts/", "title": "Are non-load-bearing walls between neighbouring units common parts?", "date": "2011-02-17", "type": "case-note", "topics": ["common-parts", "partition-walls", "building-management", "exclusive-use", "land-registration"], "cases": [{"name": "Incorporated Owners of Westlands Garden v Oey Chiou Ling", "citation": "[2010] 5 HKLRD 150", "court": "other", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.2", "Building Management Ordinance s.34I(1)(a)", "Building Management Ordinance Schedule 2 clause 4"], "summary": "The Lands Tribunal treated dividing partition walls as common unless a registered instrument gave exclusive use of the wall itself; a mere right to use the surface was not enough, so demolition was unlawful."}, {"url": "https://hklandlaw.wordpress.com/2011/02/16/construction-of-agreement-to-sell-a-canopy-protruding-from-a-building/", "title": "Construction of agreement to sell a canopy protruding from a building", "date": "2011-02-16", "type": "case-note", "topics": ["contractual-interpretation", "airspace", "exclusive-use", "multi-storey-buildings", "conveyancing"], "cases": [{"name": "Nation Group Development Ltd v New Pacific Properties Ltd", "citation": "[2001] 1 HKLRD 375", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Selling a canopy transfers the entire structure unless words say otherwise, unlike a flat, where exclusive use means the airspace between floor and ceiling. The vendor's surface-only reading found no support in the wording."}, {"url": "https://hklandlaw.wordpress.com/2011/02/15/presumption-of-advancement-in-the-uk/", "title": "Presumption of advancement in the UK", "date": "2011-02-15", "type": "overview", "topics": ["presumption-of-advancement", "resulting-trust", "statutory-reform", "beneficial-ownership"], "cases": [], "statutes": ["Equality Act 2010 s.199"], "summary": "A brief note flagging that United Kingdom legislation is set to do away with the advancement presumption, with no further discussion offered."}, {"url": "https://hklandlaw.wordpress.com/2011/02/15/merger-of-lease-by-operation-of-law/", "title": "Merger of lease by operation of law", "date": "2011-02-15", "type": "case-note", "topics": ["merger", "lease-and-reversion", "easements", "equitable-presumptions", "landlord-and-tenant"], "cases": [{"name": "EDF Energy Networks (EPN) plc v Boh Ltd", "citation": "[2010] 2 P & CR 3", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Capital and Counties Bank Ltd v Rhodes", "citation": "[1903] 1 Ch 631", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Equity leans against merger when it would cut across the tenant's interests. Here merger would have wiped out easements the tenant commercially needed, so lease and reversion stayed distinct."}, {"url": "https://hklandlaw.wordpress.com/2011/02/14/can-you-demolish-a-partition-wall-between-two-flats/", "title": "Can you demolish a partition wall between two flats?", "date": "2011-02-14", "type": "case-note", "topics": ["common-parts", "partition-walls", "deed-of-mutual-covenant", "structural-alteration", "building-management"], "cases": [{"name": "Tam Sze Man v Incorporated Owners of Shan Tsui Court", "citation": "[2011] HKEC 111", "court": "CFI", "jurisdiction": "HK"}, {"name": "Nation Group Development Ltd v New Pacific Properties Ltd", "citation": "[2000] 3 HKCFAR 427", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "Ownership must be spelled out in the DMC and assignment, not deduced from markings on a plan; an assignment gives surfaces and enclosed airspace. Knocking out even a non-load-bearing wall counts as structural alteration."}, {"url": "https://hklandlaw.wordpress.com/2011/02/13/carrying-out-domestic-chores-does-not-prove-a-common-intention/", "title": "Carrying out domestic chores does not prove a common intention", "date": "2011-02-13", "type": "case-note", "topics": ["common-intention-constructive-trust", "detrimental-reliance", "beneficial-interests", "family-home", "domestic-contributions"], "cases": [{"name": "Burns v Burns", "citation": "[1984] Ch 317", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Raising the children, paying household bills and decorating said nothing about who was meant to own the house, so the cohabitant established no beneficial share on those facts."}, {"url": "https://hklandlaw.wordpress.com/2011/02/12/constructive-trust-finding-the-necessary-agreement-in-a-deceitful-excuse/", "title": "Constructive trust: finding the necessary agreement in a deceitful excuse", "date": "2011-02-12", "type": "case-note", "topics": ["common-intention-constructive-trust", "express-agreement", "detrimental-reliance", "family-home", "beneficial-interests"], "cases": [{"name": "Eves v Eves", "citation": "[1975] 1 WLR 1338", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Inventing an age excuse for leaving her off the title betrayed that both had assumed she would share ownership; her heavy renovation work supplied the reliance needed to hold the legal owner to it."}, {"url": "https://hklandlaw.wordpress.com/2011/02/11/common-intention-constructive-trust-2/", "title": "Common intention constructive trust again", "date": "2011-02-11", "type": "case-note", "topics": ["common-intention-constructive-trust", "express-agreement", "direct-contributions", "detrimental-reliance", "beneficial-interests"], "cases": [{"name": "Lloyds Bank plc v Rosset", "citation": "[1991] 1 AC 107", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Only two routes open the door: a spoken bargain acted on to one's detriment, or money paid toward price or mortgage. The wife offered neither, so reliance by itself got her nowhere."}, {"url": "https://hklandlaw.wordpress.com/2011/02/10/common-intention-constructive-trust/", "title": "Common intention constructive trust", "date": "2011-02-10", "type": "case-note", "topics": ["common-intention-constructive-trust", "beneficial-interests", "quantification", "family-home", "formalities"], "cases": [{"name": "Gissing v Gissing", "citation": "[1971] AC 886", "court": "HL", "jurisdiction": "EN"}, {"name": "Pettitt", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "A non-owner must show a shared understanding at acquisition, evidenced by words or conduct, plus real contribution. Shares follow any agreement, or inference from conduct, falling back on equal division where contributions cannot be untangled."}, {"url": "https://hklandlaw.wordpress.com/2011/02/09/when-do-improvement-works-confer-a-proprietary-interest/", "title": "When do improvement works confer a proprietary interest?", "date": "2011-02-09", "type": "overview", "topics": ["improvement-works", "proprietary-interests", "resulting-trust", "presumption-of-advancement", "proprietary-estoppel"], "cases": [{"name": "Pettitt v Pettitt", "citation": "[1970] AC 777", "court": "HL", "jurisdiction": "EN"}, {"name": "Gissing v Gissing", "citation": "[1971] AC 886", "court": "HL", "jurisdiction": "EN"}, {"name": "Lloyds Bank plc v Rosset", "citation": "[1991] 1 AC 107", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Work done on someone else's property buys no share by itself, especially if modest or transient. Courts look to declarations, evidence of intention, conduct and the resulting-trust and advancement presumptions; money may be the answer instead."}, {"url": "https://hklandlaw.wordpress.com/2011/02/08/a-modern-example-of-a-licence-coupled-with-an-interest/", "title": "A modern example of a licence coupled with an interest", "date": "2011-02-08", "type": "case-note", "topics": ["licences", "licence-coupled-with-an-interest", "irrevocability", "third-party-effect", "building-management"], "cases": [{"name": "Incorporated Owners of Kwai Chung Plaza v Giant Earnings Limited", "citation": "[2009] HKEC 536", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "A signboard right given alongside the sale of a shop was treated as attached to that interest, hence unrevokable and good against later buyers, though the declaration oddly tied irrevocability to the licensor's own ownership."}, {"url": "https://hklandlaw.wordpress.com/2011/02/07/contractual-licensee-can-bring-possession-proceedings/", "title": "Contractual licensee can bring possession proceedings", "date": "2011-02-07", "type": "case-note", "topics": ["licences", "possession-proceedings", "trespassers", "remedies", "exclusive-possession"], "cases": [{"name": "Manchester Airport plc v Dutton", "citation": "[2000] QB 133", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["RSC O. 113 r.1"], "summary": "An airport licensed to fell trees, though never in occupation, was allowed to evict protesters already on the land. Laws LJ let the remedy follow the contractual right; Chadwick LJ would have refused."}, {"url": "https://hklandlaw.wordpress.com/2011/02/06/a-contractual-licence-is-not-binding-on-a-third-party/", "title": "A contractual licence is not binding on a third party", "date": "2011-02-06", "type": "case-note", "topics": ["licences", "third-party-effect", "charging-orders", "notice", "remedies"], "cases": [{"name": "Lau Chun Ming v Ma Koon Sik", "citation": "[2006] HKCU 1270", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "A creditor's charging order outranked an earlier licence, which sounds only in damages. Inspecting the property gave the creditor no notice of the unregistered arrangement."}, {"url": "https://hklandlaw.wordpress.com/2011/02/05/contractual-licence-given-by-one-co-habitee-to-another/", "title": "Contractual licence given by one co-habitee to another", "date": "2011-02-05", "type": "case-note", "topics": ["licences", "cohabitation", "implied-terms", "proprietary-estoppel", "occupation-rights"], "cases": [{"name": "David Wong v Li Suk-Bing", "citation": "[1984] HKLR 65", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "A partner and children were held entitled to stay until the children finished full-time education, the court stressing their welfare. Hunter J required ordinary contract ingredients; such an arrangement can emerge later, not only at the outset. Estoppel was rejected."}, {"url": "https://hklandlaw.wordpress.com/2011/02/04/a-contractual-licence-does-not-bind-a-mortgagee/", "title": "A contractual licence does not bind a mortgagee", "date": "2011-02-04", "type": "case-note", "topics": ["licences", "mortgagees", "third-party-effect", "constructive-trust", "proprietary-estoppel"], "cases": [{"name": "Chartered Bank v Wong", "citation": "[1987] HKLR 844", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Occupation permitted until the children's schooling ended was purely personal, unsupported by any trust or estoppel, so the lender enforcing its security took free of it. Whether the bank's knowledge would change matters was doubted."}, {"url": "https://hklandlaw.wordpress.com/2011/02/03/third-parties-are-not-bound-by-a-licence/", "title": "Third parties are not bound by a licence", "date": "2011-02-03", "type": "case-note", "topics": ["licences", "third-party-effect", "proprietary-interests", "easements", "damages"], "cases": [{"name": "King v David Allen and Sons, Billposting, Limited", "citation": "[1916] 2 AC 54", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A billposting right created nothing in the land, so a later tenant could ignore it; the grantor still answered in damages. Exclusivity and fixed terms did not turn it into a lease or easement, nor would recital in later deeds."}, {"url": "https://hklandlaw.wordpress.com/2011/02/02/when-is-a-contractual-licence-irrevocable-is-an-injunction-available-to-restrain-unlawful-revocation/", "title": "When is a contractual licence irrevocable? Is an injunction available to restrain unlawful revocation?", "date": "2011-02-02", "type": "case-note", "topics": ["licences", "revocation", "implied-terms", "injunctions", "contractual-interpretation"], "cases": [{"name": "Winter Garden Theatre (London) Limited v Millenium Productions Limited", "citation": "[1948] AC 173", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Silence about ending a licence does not make it perpetual; the parties' intentions govern and terms may be implied. The theatre licence, though undated and unqualified, was held revocable, with Lord Uthwatt suggesting injunctive relief against wrongful revocation."}, {"url": "https://hklandlaw.wordpress.com/2011/02/01/equitable-remedies-are-available-to-compel-a-licensor-to-honour-a-contractual-licence/", "title": "Equitable remedies are available to compel a licensor to honour a contractual licence", "date": "2011-02-01", "type": "case-note", "topics": ["licences", "specific-performance", "injunctions", "equitable-remedies", "revocation"], "cases": [{"name": "Verrall v Great Yarmouth Borough Council", "citation": "[1981] QB 202", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A council that withdrew a hall booking was ordered to honour it even though the licensee had never entered. No substitute venue existed and free speech was at stake, so money would not do."}, {"url": "https://hklandlaw.wordpress.com/2011/01/31/a-landowner-cannot-grant-a-lease-to-himself/", "title": "A landowner cannot grant a lease to himself", "date": "2011-01-31", "type": "case-note", "topics": ["leases", "creation-of-leases", "landlord-and-tenant", "periodic-tenancy", "conveyancing"], "cases": [{"name": "Rye v Rye", "citation": "[1962] AC 496", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Two brothers owning the freehold tried to create a yearly tenancy in their own favour by word of mouth. Nobody can be their own landlord and tenant, so nothing was created."}, {"url": "https://hklandlaw.wordpress.com/2011/01/30/a-tenants-notice-to-quit-also-determines-sub-tenancies/", "title": "A tenant's notice to quit also determines sub-tenancies", "date": "2011-01-30", "type": "case-note", "topics": ["notice-to-quit", "sub-tenancies", "termination-of-lease", "periodic-tenancy", "landlord-and-tenant"], "cases": [{"name": "Pennell v Payne", "citation": "[1995] QB 192", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Agricultural Holdings Act 1986 (UK)"], "summary": "A head-tenant who serves notice on his landlord destroys everything carved out beneath him. The farm tenant could therefore extinguish his own unlawful sub-lease by quitting."}, {"url": "https://hklandlaw.wordpress.com/2011/01/29/a-periodic-tenants-notice-to-quit-is-not-a-disposition/", "title": "A periodic tenant's notice to quit is not a disposition", "date": "2011-01-29", "type": "case-note", "topics": ["notice-to-quit", "periodic-tenancy", "disposition-of-property", "matrimonial-property", "termination-of-lease"], "cases": [{"name": "Newlon Housing Trust v Alsulaimen", "citation": "[1999] 1 AC 313", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Matrimonial Causes Act s.37(2)(b) (UK)"], "summary": "Quitting simply lets the term run out; nothing is handed over. So the notice escaped the matrimonial legislation aimed at dispositions, the landlord's right to possession flowing from expiry alone."}, {"url": "https://hklandlaw.wordpress.com/2011/01/28/no-disclaimer-of-lease-where-the-tenant-denies-the-landlords-title-to-only-part-of-the-demised-property/", "title": "No disclaimer of lease where the tenant denies the landlord's title to only part of the demised property", "date": "2011-01-28", "type": "case-note", "topics": ["disclaimer-of-title", "forfeiture", "landlord-and-tenant", "denial-of-title", "demised-premises"], "cases": [{"name": "W.G. Clarke Properties Ltd v Dupre Properties Ltd", "citation": "[1992] Ch 297", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Disputing the landlord's title to a courtyard while accepting it for the flat was no repudiation, the courtyard being an inseverable part of one holding. A separately lettable area might have produced a different answer."}, {"url": "https://hklandlaw.wordpress.com/2011/01/27/a-landlords-failure-to-act-can-be-a-derogation-from-grant/", "title": "A landlord's failure to act can be a derogation from grant", "date": "2011-01-27", "type": "case-note", "topics": ["derogation-from-grant", "quiet-enjoyment", "nuisance", "repudiatory-breach", "landlord-and-tenant"], "cases": [{"name": "Chartered Trust plc v Davies", "citation": "(1998) 76 P & CR 396", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Holding lease powers that could have curbed a disruptive neighbouring tenant, the landlord stood by while the shop became unusable. That inaction breached the covenant not to derogate, and repudiated the lease."}, {"url": "https://hklandlaw.wordpress.com/2011/01/26/surrender-by-operation-of-law-requires-unequivocal-conduct-by-the-landlord-and-the-tenant/", "title": "Surrender by operation of law requires unequivocal conduct by the landlord and the tenant", "date": "2011-01-26", "type": "case-note", "topics": ["surrender-by-operation-of-law", "unequivocal-conduct", "termination-of-lease", "estoppel", "landlord-and-tenant"], "cases": [{"name": "Sanctuary Housing Association v Campbell", "citation": "[1999] 1 WLR 1279", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Handing back the keys sufficed even though a violent partner and changed locks left belongings behind; she had done all the landlord asked that she could, and both sides acted unambiguously."}, {"url": "https://hklandlaw.wordpress.com/2011/01/25/the-different-effects-of-notice-to-quit-and-surrender-on-sub-tenants/", "title": "The different effects of notice to quit and surrender on sub-tenants", "date": "2011-01-25", "type": "case-note", "topics": ["notice-to-quit", "surrender", "sub-tenancies", "termination-of-lease", "landlord-and-tenant"], "cases": [{"name": "Barrett v Morgan", "citation": "[2000] 2 AC 264", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Agreeing in advance not to counter-notice does not turn a notice to quit into a surrender. Quitting ends sub-leases because it is the lease running its contemplated course; surrender does not."}, {"url": "https://hklandlaw.wordpress.com/2011/01/24/estoppel-is-the-basis-of-surrender-by-operation-of-law-when-does-payment-of-rent-give-rise-to-a-periodic-tenancy/", "title": "Estoppel is the basis of surrender by operation of law. When does payment of rent give rise to a periodic tenancy?", "date": "2011-01-24", "type": "case-note", "topics": ["surrender-by-operation-of-law", "estoppel", "periodic-tenancy", "acceptance-of-rent", "landlord-and-tenant"], "cases": [{"name": "Mattey Securities Ltd v Ervin", "citation": "(1999) 77 P & CR 160", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Estoppel underpins surrender, which turns on conduct admitting the tenancy is over rather than intention. Rent taken because the old lease still required it created no new periodic tenancy, and ongoing negotiations showed the lease survived."}, {"url": "https://hklandlaw.wordpress.com/2011/01/23/yearly-tenants-have-an-implied-obligation-to-use-the-property-in-a-tenantlike-manner/", "title": "Yearly tenants have an implied obligation to use the property in a tenantlike manner", "date": "2011-01-23", "type": "case-note", "topics": ["implied-covenants", "waste", "tenantlike-user", "periodic-tenancy", "landlord-and-tenant"], "cases": [{"name": "Marsden v Edward Heyes Limited", "citation": "[1927] 2 KB 1", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Knocking through between shop and dwelling to enlarge the trading area changed what the premises were, breaching the yearly tenant's implied duty; the character had to be restored when the tenancy ended."}, {"url": "https://hklandlaw.wordpress.com/2011/01/22/failure-to-make-good-damage-caused-by-removal-of-tenants-fixtures-is-waste/", "title": "Failure to make good damage caused by removal of tenant's fixtures is waste", "date": "2011-01-22", "type": "case-note", "topics": ["waste", "tenants-fixtures", "directors-liability", "repair-obligations", "landlord-and-tenant"], "cases": [{"name": "Mancetter Developments Ltd v Garmanson", "citation": "[1986] QB 212", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Pipes and an extractor fan came out but the holes stayed, which was waste. The director who ordered the stripping was personally liable, though whether covenant and waste can overlap was left open."}, {"url": "https://hklandlaw.wordpress.com/2011/01/21/lease-or-licence-depends-on-the-intention-of-the-parties-not-the-label/", "title": "Lease or licence? Depends on the intention of the parties not the label.", "date": "2011-01-21", "type": "case-note", "topics": ["lease-or-licence", "exclusive-possession", "sham-and-pretence", "rent-control", "landlord-and-tenant"], "cases": [{"name": "A.G. Securities v Vaughan", "citation": "[1990] 1 AC 417", "court": "HL", "jurisdiction": "EN"}, {"name": "Antoniades v Villiers", "citation": "[1990] 1 AC 417", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Rent Acts"], "summary": "Substance beats labels. Strangers signing staggered, differing agreements shared no tenancy; a couple wanting to live together did, the reserved power to move others in being a pretence dodging statutory protection."}, {"url": "https://hklandlaw.wordpress.com/2011/01/21/sale-subject-to-an-unregistered-option-is-the-option-binding-on-the-purchaser/", "title": "Sale 'subject to' an unregistered option. Is the option binding on the purchaser?", "date": "2011-01-21", "type": "case-note", "topics": ["land-registration", "unregistered-interests", "options-to-renew", "constructive-trust", "priority-of-interests"], "cases": [{"name": "Wellmake Investments Ltd v Chan Yiu Tong", "citation": "[1996] 2 HKLR 44", "court": "CA", "jurisdiction": "HK"}, {"name": "Lyus v Prowsa Developments Ltd", "citation": "[1982] 1 WLR 1044", "court": null, "jurisdiction": "EN"}], "statutes": ["Land Registration Ordinance s.3(2)"], "summary": "Words making a sale subject to an unregistered renewal option did not stop the buyer invoking the statute, leaving the tenant's remedy against the seller. Vendors should register options or extract undertakings."}, {"url": "https://hklandlaw.wordpress.com/2011/01/20/failure-to-register-the-right-to-exclusive-use-of-the-roof/", "title": "Failure to register the right to exclusive use of the roof", "date": "2011-01-20", "type": "case-note", "topics": ["land-registration", "exclusive-use", "priority-of-interests", "undivided-shares", "common-parts"], "cases": [{"name": "Fast Forward Ltd v Magicsound Co Ltd", "citation": "[1991] 2 HKLR 529", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3"], "summary": "Exclusive roof rights are registrable. Acquired with undivided shares but never entered on the register, they ranked behind a rival claim in the same industrial building that had been registered."}, {"url": "https://hklandlaw.wordpress.com/2011/01/18/details-on-loan-application-form-as-a-source-of-constructive-notice/", "title": "Details on loan application form as a source of constructive notice", "date": "2011-01-18", "type": "case-note", "topics": ["constructive-notice", "mortgages", "equitable-interests", "duty-to-inquire", "family-home"], "cases": [{"name": "Kingsnorth Finance Co Ltd v Tizard", "citation": "[1986] 1 WLR 783", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A borrower calling himself single while telling the valuer he was separated, plus children about the house, should have prompted inquiry. Skipping it left the lender bound by the wife's interest."}, {"url": "https://hklandlaw.wordpress.com/2011/01/17/lease-or-licence-the-label-might-matter/", "title": "Lease or licence? The label might matter.", "date": "2011-01-17", "type": "case-note", "topics": ["lease-or-licence", "exclusive-possession", "intention-of-parties", "business-tenancies", "landlord-and-tenant"], "cases": [{"name": "National Car Parks Ltd v The Trinity Development Co (Banbury) Ltd", "citation": "[2001] EWCA Civ 1686", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Landlord and Tenant Act 1954 Part II"], "summary": "Exclusive possession remains the test, but where commercial equals with lawyers declare they intend only a licence, that declaration is worth something. The car park agreement was held to confer no exclusive possession."}, {"url": "https://hklandlaw.wordpress.com/2011/01/17/elements-of-proprietary-estoppel/", "title": "Elements of proprietary estoppel", "date": "2011-01-17", "type": "overview", "topics": ["proprietary-estoppel", "detrimental-reliance", "unconscionability", "mistaken-belief", "encouragement"], "cases": [{"name": "Taylors Fashions Ltd v Liverpool Victoria Trustees Co Ltd", "citation": "[1982] QB 133", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Beesly v Hallwood Estates Ltd", "citation": "[1961] Ch 105", "court": "other", "jurisdiction": "EN"}], "statutes": ["Land Charges Act 1925"], "summary": "The claimant must have been encouraged or left in a mistaken belief, acted on it to his cost, and face unconscionable denial. The owner sharing the same legal error does not bar relief, though reliance on the owner is essential."}, {"url": "https://hklandlaw.wordpress.com/2011/01/15/receipt-of-purchase-price-and-delivery-of-possession-are-clearest-possible-acts-of-part-performance/", "title": "Receipt of purchase price and delivery of possession are the clearest possible acts of part performance", "date": "2011-01-15", "type": "case-note", "topics": ["part-performance", "formalities", "equitable-interests", "chinese-customary-law", "land-registration"], "cases": [{"name": "Wu Koon Tai v Wu Yau Loi", "citation": "[1996] 2 HKLR 477", "court": "PC", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "New Territories Ordinance s.13", "Land Registration Ordinance"], "summary": "Taking the money and handing over possession made the unwritten bargain specifically enforceable, and the resulting equity bound volunteers claiming through the seller. Custom cannot displace the statutory registration system."}, {"url": "https://hklandlaw.wordpress.com/2011/01/14/when-subject-to-contract-is-meaningless/", "title": "When 'subject to contract' is meaningless", "date": "2011-01-14", "type": "case-note", "topics": ["subject-to-contract", "formation-of-contract", "intention-to-be-bound", "conduct-of-parties", "landlord-and-tenant"], "cases": [{"name": "Hong Kong Housing Authority v Hung Pui", "citation": "[1987] 3 HKC 495", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "Godfrey J disregarded the formula in a rent-revision acceptance: negotiations were finished with no formality left to perform, and the tenant then paid at the new rate, showing both meant to be bound."}, {"url": "https://hklandlaw.wordpress.com/2011/01/14/options-to-renew-are-void-under-cpo-s-32-unless-registered/", "title": "Options to renew are void under LRO s.3(2) unless registered", "date": "2011-01-14", "type": "case-note", "topics": ["land-registration", "options-to-renew", "unregistered-interests", "short-term-leases", "priority-of-interests"], "cases": [{"name": "Markfaith Investments Ltd v Chiap Hua Flashlights Ltd", "citation": "[1990] 2 HKLR 84", "court": "PC", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance s.3(2)"], "summary": "A renewal option is its own registrable interest, so leaving it off the register makes it void against later purchasers or mortgagees for value. The short-lease exemption covers only the lease itself."}, {"url": "https://hklandlaw.wordpress.com/2011/01/13/the-likelihood-of-an-open-contract-in-hong-kong/", "title": "The likelihood of an 'open contract' in Hong Kong", "date": "2011-01-13", "type": "case-note", "topics": ["contract-formation", "formalities", "open-contract", "sale-of-land", "memorandum"], "cases": [{"name": "Kwan Siu Man Joshua v Yaacov Ozer", "citation": "[1999] 1 HKLRD 216", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "Land Registration Ordinance s.3(2)"], "summary": "Asks whether an open contract, oral agreement on parties, property and price alone, can bind in Hong Kong: Kwan Siu Man shows courts hesitate to find contractual intent while the completion date stays unsettled, and correspondence adding fresh terms cannot double as the statutory memorandum."}, {"url": "https://hklandlaw.wordpress.com/2011/01/12/two-documents-referring-to-the-same-contract-can-be-read-together/", "title": "Two documents referring to the same contract can be read together", "date": "2011-01-12", "type": "case-note", "topics": ["memorandum-in-writing", "formalities", "joinder-of-documents", "agency", "conveyancing"], "cases": [{"name": "Chu Kim-Leung v Wong Suk-Yee", "citation": "[1973] HKLR 102", "court": "other", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "Separate papers each pointing to the same bargain may be joined to make one memorandum. A deposit receipt and the seller's instructions, signed by an authorised agent, together supplied every needed term."}, {"url": "https://hklandlaw.wordpress.com/2011/01/11/when-parol-evidence-can-be-used-to-link-two-documents-to-form-a-cpo-s-3-memorandum/", "title": "When parol evidence can be used to link two documents to form a CPO s.3 memorandum", "date": "2011-01-11", "type": "case-note", "topics": ["memorandum-in-writing", "parol-evidence-rule", "joinder-of-documents", "formalities", "conveyancing"], "cases": [{"name": "Elias v George Sahely & Co (Barbados) Ltd", "citation": "[1983] 1 AC 646", "court": "PC", "jurisdiction": "other"}, {"name": "Timmins v Moreland Street Property Co Ltd", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "If the signed paper gestures, openly or by implication, at another document or dealing, oral evidence may identify it. A signed receipt pointing back to an earlier letter was joined to satisfy the formality."}, {"url": "https://hklandlaw.wordpress.com/2011/01/10/defendants-letter-to-own-bankers-as-cpo-s-3-memorandum/", "title": "Defendant's letter to own bankers as CPO s.3 memorandum", "date": "2011-01-10", "type": "case-note", "topics": ["memorandum-in-writing", "formalities", "agreement-for-lease", "part-performance", "damages"], "cases": [{"name": "Chan Yat v Fung Keong Rubber Manufactory Ltd", "citation": "[1967] HKLR 364", "court": "other", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "Even a letter to one's own bank reciting the agreed terms can serve as the required note. Damages for a broken agreement for lease measure the gap between agreed and market rent; the claimant cannot choose his remedy."}, {"url": "https://hklandlaw.wordpress.com/2011/01/09/lands-tribunal-has-no-jurisdiction-to-determine-the-amount-of-the-management-fee/", "title": "Lands Tribunal has no jurisdiction to determine the amount of the management fee", "date": "2011-01-09", "type": "case-note", "topics": ["building-management", "management-fees", "deed-of-mutual-covenant", "jurisdiction", "declaratory-relief"], "cases": [{"name": "Harvest Top Development Ltd v Incorporated Owners of Harbour View Garden", "citation": "[2011] HKEC 32", "court": "other", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance"], "summary": "Finding that a charge was worked out contrary to the DMC, the tribunal still could not fix the correct figure itself. Deputy Judge Lee held a declaration was the limit of its powers."}, {"url": "https://hklandlaw.wordpress.com/2011/01/08/forfeiture-and-common-law-remedies-can-co-exist/", "title": "Forfeiture and common law remedies can co-exist", "date": "2011-01-08", "type": "case-note", "topics": ["forfeiture", "repudiatory-breach", "damages", "rent-arrears", "landlord-and-tenant"], "cases": [{"name": "Well Century Holdings Ltd v Leung Kam Yu", "citation": "[2003] 2 HKLRD 653", "court": "CA", "jurisdiction": "HK"}], "statutes": ["High Court Ordinance s.21F"], "summary": "A landlord re-entering for arrears could also claim damages, including the shortfall on re-letting, where the statutory route was closed. The court treated the lease contractually, allowing repudiation reasoning alongside forfeiture."}, {"url": "https://hklandlaw.wordpress.com/2011/01/07/frustration-of-a-contract-for-the-sale-of-a-flat/", "title": "Frustration of a contract for the sale of a flat", "date": "2011-01-07", "type": "case-note", "topics": ["frustration", "sale-and-purchase-agreement", "radical-difference", "uncompleted-development", "conveyancing"], "cases": [{"name": "Wong Lai-ying v Chinachem Investment Co Ltd", "citation": "[1980] HKLR 1", "court": "PC", "jurisdiction": "HK"}, {"name": "Davis Contractors v Fareham UDC", "citation": "[1956] AC 696", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "An unforeseen landslip pushed construction far past the agreed schedule and demanded wholly different foundations, making performance radically unlike what was promised, so the flat sale agreements were discharged."}, {"url": "https://hklandlaw.wordpress.com/2011/01/06/the-court-can-grant-relief-from-forfeiture-after-peaceable-re-entry/", "title": "The court can grant relief from forfeiture after peaceable re-entry", "date": "2011-01-06", "type": "case-note", "topics": ["relief-from-forfeiture", "peaceable-re-entry", "chose-in-action", "rent-arrears", "landlord-and-tenant"], "cases": [{"name": "Howard v Fanshawe", "citation": "[1895] 2 Ch 581", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Relief remains open whether the landlord took possession by writ or by simply walking back in. The right to seek it is a chose in action, here passing to a trustee in bankruptcy and then a buyer."}, {"url": "https://hklandlaw.wordpress.com/2011/01/05/forfeiture-of-a-head-lease-also-terminates-sub-leases/", "title": "Forfeiture of a head-lease also terminates sub-leases", "date": "2011-01-05", "type": "case-note", "topics": ["forfeiture", "sub-tenancies", "mesne-profits", "termination-of-lease", "landlord-and-tenant"], "cases": [{"name": "Viscount Chelsea v Hutchinson", "citation": "[1994] 2 EGLR 61", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Great Western Railway v Smith", "citation": "(1875) 2 Ch D 235", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Everything derived from a forfeited head-lease falls with it, so pointing to occupying sub-tenants was no answer; the landlord recovered mesne profits over the whole property from service of the writ."}, {"url": "https://hklandlaw.wordpress.com/2011/01/04/is-breach-of-a-covenant-to-complete-works-by-a-specified-date-capable-of-remedy/", "title": "Is breach of a covenant to complete works by a specified date capable of remedy", "date": "2011-01-04", "type": "case-note", "topics": ["forfeiture", "breach-of-covenant", "capable-of-remedy", "statutory-notice", "landlord-and-tenant"], "cases": [{"name": "Expert Clothing Services & Sales Ltd v Hillgate House Ltd", "citation": "[1986] Ch 340", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.58"], "summary": "The test is whether prompt compliance with the notice plus money would put the landlord right. Missing the completion deadline and failing to disclose a mortgage were both curable on that footing."}, {"url": "https://hklandlaw.wordpress.com/2011/01/03/issue-of-a-rent-demand-is-a-waiver-of-right-to-re-enter/", "title": "Issue of a rent demand is a waiver of right to re-enter", "date": "2011-01-03", "type": "case-note", "topics": ["waiver", "forfeiture", "right-of-re-entry", "rent-demand", "landlord-and-tenant"], "cases": [{"name": "Prudential Enterprises Ltd v PH Shek Ltd", "citation": "[1988] HKLY 573", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Sending a demand, even inadvertently, abandons re-entry for breaches known by then; holding an uncashed cheque does not. A fresh breach occurring afterwards left the landlord free to forfeit."}, {"url": "https://hklandlaw.wordpress.com/2011/01/03/2010-in-review/", "title": "2010 in review", "date": "2011-01-03", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Automated WordPress year-end statistics for the blog, not legal content."}, {"url": "https://hklandlaw.wordpress.com/2011/01/01/when-does-the-cause-of-action-accrue-in-latent-defects-cases/", "title": "When does the cause of action accrue in latent defects cases?", "date": "2011-01-01", "type": "case-note", "topics": ["latent-defects", "limitation-periods", "accrual-of-cause-of-action", "negligence", "economic-loss"], "cases": [{"name": "Bank of East Asia Ltd v Tsien Wui Marble Factory Ltd", "citation": "[2000] 1 HKLRD 268", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance"], "summary": "Time starts once real, measurable physical damage exists, not when anyone could spot it. Litton PJ led that view; Bokhary PJ and Lord Nicholls would have waited until the market knew, over failed granite cladding."}, {"url": "https://hklandlaw.wordpress.com/2010/12/30/liability-for-defective-design-of-buildings/", "title": "Liability for defective design of buildings", "date": "2010-12-30", "type": "case-note", "topics": ["negligence", "pure-economic-loss", "defective-buildings", "limitation-of-actions", "duty-of-care"], "cases": [{"name": "Murphy v Brentwood District Council", "citation": "[1991] 1 AC 398", "court": "HL", "jurisdiction": "EN"}, {"name": "Bank of East Asia Ltd v Tsien Wui Marble Factory Ltd", "citation": "[2000] 1 HKLRD 268", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Builders and designers must take reasonable care against injury and property damage, but purely economic loss from a substandard building is not recoverable. Time runs from real, substantial physical damage producing quantifiable loss, not from discovery."}, {"url": "https://hklandlaw.wordpress.com/2010/12/28/certainty-of-term-2/", "title": "Certainty of term", "date": "2010-12-28", "type": "case-note", "topics": ["leases", "certainty-of-term", "lease-validity", "landlord-and-tenant"], "cases": [{"name": "Lace v Chantler", "citation": "[1944] KB 368", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A valid lease needs a start date and duration ascertainable before it begins. A letting expressed to last for the duration of the war fails that test and cannot take effect as a lease."}, {"url": "https://hklandlaw.wordpress.com/2010/12/27/court-can-order-separate-properties-to-be-sold-as-a-single-lot/", "title": "Court can order separate properties to be sold as a single lot", "date": "2010-12-27", "type": "case-note", "topics": ["co-ownership", "partition", "order-for-sale", "consequential-directions"], "cases": [{"name": "Golden Bay Investment Ltd v Chou Hung", "citation": "[1994] 2 HKC 197", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Partition Ordinance s.6(4)"], "summary": "Although the Ordinance does not let a court merge separate properties, once sale of each is ordered it may direct they be marketed together as one lot to maximise price, using its power to give consequential directions."}, {"url": "https://hklandlaw.wordpress.com/2010/12/26/agreement-in-principle-not-enough-to-sever/", "title": "Agreement in principle not enough to sever", "date": "2010-12-26", "type": "case-note", "topics": ["joint-tenancy", "severance", "mutual-agreement", "course-of-dealing", "co-ownership"], "cases": [{"name": "Gore and Snell v Carpenter", "citation": "(1990) 60 P & CR 456", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Spouses negotiating division of two jointly held houses had only agreed in principle when the husband died. Provisional consensus, without both parties committing themselves, is neither a mutual agreement nor a course of dealing severing the joint tenancy."}, {"url": "https://hklandlaw.wordpress.com/2010/12/22/court-can-order-a-sale-under-the-partition-ordinance-whether-or-not-partition-is-feasible/", "title": "Court can order a sale under the Partition Ordinance whether or not partition is feasible", "date": "2010-12-22", "type": "case-note", "topics": ["co-ownership", "partition", "order-for-sale", "judicial-discretion"], "cases": [{"name": "Pun Jong-Sau v Poon Wong-Kong", "citation": "[1980] HKLR 662", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Partition Ordinance"], "summary": "Defendants argued no sale could be ordered because physical partition was impracticable. Trainer J disagreed: the Ordinance confers a broad discretion to respond as the court thinks fit, so feasibility of partition is no precondition to ordering sale."}, {"url": "https://hklandlaw.wordpress.com/2010/12/21/agreeing-to-make-mutual-wills-can-sever-a-joint-tenancy/", "title": "Agreeing to make mutual wills can sever a joint tenancy", "date": "2010-12-21", "type": "case-note", "topics": ["joint-tenancy", "severance", "mutual-wills", "course-of-dealing", "co-ownership"], "cases": [{"name": "Re Wilford's Estate", "citation": "(1879) LR 11 Ch D 267", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Two sisters holding jointly agreed to make mutual wills leaving the property to the survivor and then to a niece. Each was thereby dealing with her own share, which severed the joint tenancy by conduct."}, {"url": "https://hklandlaw.wordpress.com/2010/12/21/factors-relevant-to-order-for-sale-under-the-partition-ordinance/", "title": "Factors relevant to order for sale under the Partition Ordinance", "date": "2010-12-21", "type": "case-note", "topics": ["co-ownership", "partition", "order-for-sale", "judicial-discretion", "hardship"], "cases": [{"name": "Ip Sau Shu v Sham Lai Hing", "citation": "[2003] 2 HKLRD 916", "court": "CFI", "jurisdiction": "HK"}], "statutes": ["Partition Ordinance s.6(1)"], "summary": "Only those holding a legal or beneficial interest count as parties interested when the court weighs a sale. Relatives without any interest do not qualify, though their situation may bear indirectly through a co-owner's own hardship."}, {"url": "https://hklandlaw.wordpress.com/2010/12/19/the-proper-approach-to-construction-of-a-document/", "title": "The proper approach to construction of a document", "date": "2010-12-19", "type": "case-note", "topics": ["construction-of-documents", "deed-of-mutual-covenant", "contractual-interpretation", "multi-storey-buildings"], "cases": [{"name": "Jumbo King Ltd v Faithful Properties Ltd", "citation": "[1999] 3 HKLRD 757", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Lord Hoffmann NPJ framed construction as asking what a reasonable person would take the parties to mean, reading the instrument whole against its factual and legal background. Silence about utility rooms did not cut down the developer's exclusive commercial rights."}, {"url": "https://hklandlaw.wordpress.com/2010/12/19/a-dmc-need-not-attach-a-right-to-exclusive-use-to-any-particular-shares-in-the-land/", "title": "A DMC need not attach a right to exclusive use to any particular shares in the land", "date": "2010-12-19", "type": "case-note", "topics": ["deed-of-mutual-covenant", "co-ownership", "exclusive-possession", "land-covenants", "undivided-shares"], "cases": [{"name": "Jumbo King Ltd v Faithful Properties Ltd", "citation": "[1999] 3 HKLRD 757", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.41(7)"], "summary": "A deed of mutual covenant need not tie exclusive occupation rights to identified shares; holding some shares suffices. Enforceability rests on the covenant being a land covenant and on tenants in common sharing unity of possession."}, {"url": "https://hklandlaw.wordpress.com/2010/12/18/who-owns-structural-walls-between-two-apartments/", "title": "Who owns structural walls between two apartments?", "date": "2010-12-18", "type": "case-note", "topics": ["common-parts", "deed-of-mutual-covenant", "building-management", "multi-storey-buildings", "co-ownership"], "cases": [{"name": "Central Management Ltd v Light Field Investment Ltd", "citation": "[2010] HKEC 1955", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Building Management Ordinance s.2"], "summary": "Structural walls dividing adjoining flats are common parts, not parcels of the individual units. The Court of Appeal preferred the DMC wording and statutory definition over plan markings, since every owner in the development has a stake."}, {"url": "https://hklandlaw.wordpress.com/2010/12/18/equitable-severance-by-mutual-agreement/", "title": "Equitable severance by mutual agreement", "date": "2010-12-18", "type": "case-note", "topics": ["joint-tenancy", "severance", "mutual-agreement", "course-of-dealing", "co-ownership"], "cases": [{"name": "Burgess v Rawnsley", "citation": "[1975] Ch 429", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Nielson-Jones v Fedden", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.36(2)"], "summary": "An oral bargain that one joint tenant will buy out the other severs in equity even though it cannot be enforced as a contract. Mutual agreement and course of dealing are treated as distinct severance routes."}, {"url": "https://hklandlaw.wordpress.com/2010/12/17/severance-of-an-equitable-joint-tenancy-under-section-362-of-the-law-of-property-act-1925/", "title": "Severance of an equitable joint tenancy under section 36(2) of the Law of Property Act 1925", "date": "2010-12-17", "type": "case-note", "topics": ["joint-tenancy", "severance", "notice-of-severance", "matrimonial-proceedings", "co-ownership"], "cases": [{"name": "Harris v Goddard", "citation": "[1983] 1 WLR 1203", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Re Draper's Conveyance", "citation": "[1969] 1 Ch 486", "court": "other", "jurisdiction": "EN"}, {"name": "Williams v Hensman", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property Act 1925 s.36(2)"], "summary": "A divorce petition asking for some future property order does not sever: statutory notice must show an immediate intention to sever. Drafting distinguished Harris from Draper's Conveyance, and the provision's relevance to Hong Kong is doubtful."}, {"url": "https://hklandlaw.wordpress.com/2010/12/15/public-policy-that-land-is-to-be-freely-alienable/", "title": "Public policy that land is to be freely alienable", "date": "2010-12-15", "type": "case-note", "topics": ["alienability", "new-territories-land", "chinese-customary-law", "tso-and-tong", "order-for-sale"], "cases": [{"name": "Re Man Sam Chung Wui", "citation": "[2010] HKEC 1921", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Rules of the High Court (Cap 4A) Order 85"], "summary": "Land should stay freely alienable, save where Chinese custom dedicates it perpetually to ancestral worship. Absent clear proof of a custom demanding unanimity, a 92 per cent majority of a Wui sufficed to authorise sale of valuable New Territories land."}, {"url": "https://hklandlaw.wordpress.com/2010/12/14/an-express-declaration-as-to-the-nature-of-a-co-ownership-is-conclusive/", "title": "An express declaration as to the nature of a co-ownership is conclusive", "date": "2010-12-14", "type": "case-note", "topics": ["co-ownership", "joint-tenancy", "tenancy-in-common", "express-declaration-of-trust", "severance"], "cases": [{"name": "Goodman v Gallant", "citation": "[1986] 2 WLR 236; [1986] 1 All ER 311", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Where the deed states expressly whether co-owners take as joint tenants or tenants in common, that statement settles the matter. On severance the former joint tenants hold in equal shares unless the conveyance says otherwise, resolving earlier doubt."}, {"url": "https://hklandlaw.wordpress.com/2010/12/14/one-tenant-in-common-cannot-oblige-another-to-contribute-to-the-cost-of-repairs/", "title": "One tenant in common cannot oblige another to contribute to the cost of repairs", "date": "2010-12-14", "type": "case-note", "topics": ["co-ownership", "tenancy-in-common", "contribution", "repairs", "partition"], "cases": [{"name": "Leigh v Dickeson", "citation": "(1884-85) LR 15 QBD 60", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Without agreement, a co-owner who repairs cannot make the other pay a share. Brett MR and Cotton LJ left open recovery where the work answered an obligation owed to a third party, or on a partition."}, {"url": "https://hklandlaw.wordpress.com/2010/12/13/when-will-an-equitable-tenancy-in-common-be-presumed/", "title": "When will an equitable tenancy in common be presumed?", "date": "2010-12-13", "type": "case-note", "topics": ["co-ownership", "tenancy-in-common", "equitable-presumptions", "joint-tenancy", "business-tenancies"], "cases": [{"name": "Malayan Credit Ltd v Jack Chia-MPH Ltd", "citation": "[1986] AC 549", "court": "UKPC", "jurisdiction": "SG"}], "statutes": [], "summary": "Two firms took a legal joint tenancy of offices but divided the space and outgoings unevenly. The Privy Council held the categories attracting a presumed tenancy in common are not closed, and beneficially they held in common."}, {"url": "https://hklandlaw.wordpress.com/2010/12/11/effect-of-assignment-to-husband-and-wife-as-joint-tenants/", "title": "Effect of assignment to husband and wife 'as joint tenants'", "date": "2010-12-11", "type": "case-note", "topics": ["joint-tenancy", "presumption-of-advancement", "matrimonial-property", "resulting-trust", "severance"], "cases": [{"name": "Ho Nga Sheung v Ma Fook Leung", "citation": "[1993] HKEC 37", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "An assignment to spouses expressly as joint tenants presumptively makes them joint tenants at law and in equity. Godfrey J applied the presumption of advancement despite the husband paying the mortgage, so severance yielded equal shares of the proceeds."}, {"url": "https://hklandlaw.wordpress.com/2010/12/11/severance-of-joint-tenancy-must-be-irrevocable-and-a-mere-declaration-is-not-sufficient/", "title": "Severance of joint tenancy: must be irrevocable and a mere declaration is not sufficient", "date": "2010-12-11", "type": "case-note", "topics": ["joint-tenancy", "severance", "unilateral-declaration", "mutual-agreement", "co-ownership"], "cases": [{"name": "Nielson-Jones v Fedden", "citation": "[1975] Ch 222; [1974] 3 WLR 583; [1974] 3 All ER 38", "court": "other", "jurisdiction": "EN"}, {"name": "Burgess v Rawnsley", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Walton J held equitable severance demands a step from which the severing party cannot withdraw. An ambiguous memorandum and the drawing of deposit monies amounted to continuing negotiation, and a unilateral statement of intent, however plain, severs nothing."}, {"url": "https://hklandlaw.wordpress.com/2010/12/11/one-tenant-in-common-can-create-a-non-exclusive-licence-to-occupy-the-co-owned-property/", "title": "One tenant in common can create a non-exclusive licence to occupy the co-owned property", "date": "2010-12-11", "type": "case-note", "topics": ["co-ownership", "tenancy-in-common", "licences", "possession", "estate-administration"], "cases": [{"name": "Chin Lan Hong v Cheung Poh Choo", "citation": "[2005] HKLRD 811", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Administrators holding a one-fifth share allowed an occupier to stay under a non-exclusive licence begun by his father. The Court of Appeal held each co-owner may deal freely with his own share, so the other co-owners could not revoke it."}, {"url": "https://hklandlaw.wordpress.com/2010/12/10/on-partition-tenants-in-common-have-to-contribute-to-the-cost-of-improvements/", "title": "On partition tenants in common have to contribute to the cost of improvements", "date": "2010-12-10", "type": "case-note", "topics": ["co-ownership", "tenancy-in-common", "partition", "improvements", "equitable-accounting"], "cases": [{"name": "Re North", "citation": "[1893] 2 Ch 461", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Where one co-owner funded improvements still reflected in the property's value when partition occurs, the others must recompense him from the sale proceeds. Prior consent is unnecessary, though the parties in Re North had in fact agreed."}, {"url": "https://hklandlaw.wordpress.com/2010/12/09/the-nature-of-a-release-by-one-joint-tenant-to-another/", "title": "The nature of a release by one joint tenant to another", "date": "2010-12-09", "type": "case-note", "topics": ["joint-tenancy", "release", "assignment", "leases", "covenants-against-assignment"], "cases": [{"name": "Burton v Camden LBC", "citation": "[2000] 2 AC 399", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A majority treated one joint tenant's release of a leasehold interest to the other as an assignment, so a covenant restricting assignment bit. Lord Millett dissented, each joint tenant already owning the whole. Liability for rent continued contractually."}, {"url": "https://hklandlaw.wordpress.com/2010/12/08/any-joint-periodic-tenant-can-give-an-effective-notice-to-terminate-the-periodic-tenancy/", "title": "Any joint periodic tenant can give an effective notice to terminate the periodic tenancy", "date": "2010-12-08", "type": "case-note", "topics": ["joint-tenancy", "periodic-tenancies", "notice-to-quit", "leases", "break-clauses"], "cases": [{"name": "Hammersmith and Fulham LBC v Monk", "citation": "[1992] 1 AC 478", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "One joint periodic tenant may serve a valid notice to quit over the others' objection, since nobody is presumed to have bound himself indefinitely. Lord Browne-Wilkinson noted the cost to the other's property rights. Break clauses in fixed terms differ."}, {"url": "https://hklandlaw.wordpress.com/2010/12/08/each-tenant-in-common-is-entitled-to-possession/", "title": "Each tenant in common is entitled to possession", "date": "2010-12-08", "type": "case-note", "topics": ["co-ownership", "tenancy-in-common", "unity-of-possession", "equitable-interests", "occupation-rights"], "cases": [{"name": "Bull v Bull", "citation": "[1955] 1 QB 234", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Every tenant in common may possess and use the whole land and none can be ejected by the others. The rule protects equitable as well as legal co-owners, so a son holding legal title could not evict his mother."}, {"url": "https://hklandlaw.wordpress.com/2010/12/07/cpo-s-16-continuous-and-apparent-easements/", "title": "CPO s.16: continuous and apparent easements", "date": "2010-12-07", "type": "case-note", "topics": ["easements", "implied-grant", "continuous-and-apparent", "diversity-of-occupation", "conveyancing"], "cases": [{"name": "Long v Gowlett", "citation": "[1923] 2 Ch 177", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16", "Conveyancing Act 1881 s.6"], "summary": "Where a quasi-easement was continuous and apparent when the grant was made, no earlier diversity of ownership or occupation is required. A downstream mill owner's claim failed because mere beneficial user was neither continuous nor apparent."}, {"url": "https://hklandlaw.wordpress.com/2010/12/06/cpo-s-16-and-continuous-and-apparent-easements/", "title": "CPO s.16 and continuous and apparent easements", "date": "2010-12-06", "type": "case-note", "topics": ["easements", "implied-grant", "continuous-and-apparent", "diversity-of-occupation", "quasi-easements"], "cases": [{"name": "P & S Platt Ltd v Crouch", "citation": "[2003] EWCA 1110", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Re Ellenborough Park", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "Selling a hotel without express grant still carried mooring and fishing rights enjoyed during common ownership, because they were continuous and apparent. A comment adds that the right must also be capable of forming the subject matter of a grant."}, {"url": "https://hklandlaw.wordpress.com/2010/12/03/cpo-s-16-no-need-for-diversity-of-occupation-where-the-easement-is-continuous-and-apparent/", "title": "CPO s 16: no need for diversity of occupation where the easement is continuous and apparent", "date": "2010-12-03", "type": "case-note", "topics": ["easements", "implied-grant", "continuous-and-apparent", "rights-of-way", "diversity-of-occupation"], "cases": [{"name": "Loyal Luck Trading Ltd v Tam Chun Wah", "citation": "[2008] 4 HKLRD 681", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "Yuen Long land used as a lorry park had a road running over it. Despite common ownership and occupation beforehand, a right of way was implied into both the 1994 mortgage and the 2000 assignment as continuous and apparent."}, {"url": "https://hklandlaw.wordpress.com/2010/12/02/cpo-s-16-requires-separate-ownership-or-occupation-prior-to-the-grant/", "title": "CPO s.16 requires separate ownership or occupation prior to the grant", "date": "2010-12-02", "type": "case-note", "topics": ["easements", "implied-grant", "diversity-of-occupation", "compulsory-purchase", "wheeldon-v-burrows"], "cases": [{"name": "Sovmots Investments Ltd v Secretary of State for the Environment", "citation": "[1979] AC 144", "court": "HL", "jurisdiction": "EN"}, {"name": "Wheeldon v Burrows", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.16"], "summary": "The section presupposes earlier separate ownership or occupation of the two tenements, and both it and Wheeldon v Burrows reach only voluntary conveyances. Ancillary support and service rights therefore did not pass on a compulsory acquisition of flats."}, {"url": "https://hklandlaw.wordpress.com/2010/12/01/unconscionable-mortgage-terms-will-be-struck-down/", "title": "Unconscionable mortgage terms will be struck down", "date": "2010-12-01", "type": "case-note", "topics": ["mortgages", "unconscionability", "equity-of-redemption", "inequality-of-bargaining-power", "index-linked-loans"], "cases": [{"name": "Multiservice Bookbinding Ltd v Marden", "citation": "[1979] Ch 84", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Equity strikes down unconscionable mortgage terms but tolerates merely unreasonable ones. A Swiss franc uplift clause survived despite heavy currency movement against the borrower, there being no sharp practice and no inequality of bargaining power."}, {"url": "https://hklandlaw.wordpress.com/2010/12/01/receivers-are-subject-to-equitable-duties-when-exercising-the-power-of-sale/", "title": "Receivers are subject to equitable duties when exercising the power of sale", "date": "2010-12-01", "type": "case-note", "topics": ["mortgages", "receivers", "power-of-sale", "equitable-duties", "subsequent-encumbrancers"], "cases": [{"name": "Downsview Nominees Ltd v First City Corp Ltd", "citation": "[1993] 2 WLR 86", "court": "UKPC", "jurisdiction": "other"}], "statutes": [], "summary": "Lord Templeman held a selling receiver owes equitable duties of good faith and proper purpose to the mortgagor and later encumbrancers, not a general negligence duty. Improper motive breaches those duties and sounds in compensation for later debenture holders."}, {"url": "https://hklandlaw.wordpress.com/2010/11/30/duty-of-care-to-mortgagee-and-guarantor/", "title": "Duty of care to mortgagee and guarantor", "date": "2010-11-30", "type": "case-note", "topics": ["mortgages", "receivers", "power-of-sale", "duty-of-care", "guarantors"], "cases": [{"name": "Standard Chartered Bank Ltd v Walker", "citation": "[1982] 1 WLR 1410", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A receiver selling under the security must take reasonable steps to obtain the best price reasonably obtainable, owing that duty to mortgagor and guarantor alike. A mortgagee who intervenes or directs the sale may itself be liable, remedied by an equitable credit."}, {"url": "https://hklandlaw.wordpress.com/2010/11/29/sale-by-a-mortgagee-to-a-connected-company/", "title": "Sale by a mortgagee to a connected company", "date": "2010-11-29", "type": "case-note", "topics": ["mortgages", "power-of-sale", "self-dealing", "best-price", "laches"], "cases": [{"name": "Tse Kwong Lam v Wong Chit Sen", "citation": "[1983] 1 WLR 1349", "court": "UKPC", "jurisdiction": "HK"}], "statutes": [], "summary": "Selling to a company connected with the mortgagee is permitted, but the seller carries a particularly heavy burden of showing good faith and best endeavours. Delay by the borrower cost him rescission, leaving damages measured by the shortfall in price."}, {"url": "https://hklandlaw.wordpress.com/2010/11/26/a-mortgagee-owes-the-mortgagor-a-duty-of-care/", "title": "A mortgagee owes the mortgagor a duty of care", "date": "2010-11-26", "type": "case-note", "topics": ["mortgages", "power-of-sale", "duty-of-care", "true-market-value", "damages"], "cases": [{"name": "Cuckmere Brick Co Ltd v Mutual Finance Ltd", "citation": "[1971] Ch 949", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A selling mortgagee must act in good faith and take reasonable precautions to realise the property's true market value when it decides to sell. Advertising permission for 35 houses while suppressing the more valuable flats consent sounded in damages."}, {"url": "https://hklandlaw.wordpress.com/2010/11/25/mortgagees-can-choose-when-to-sell/", "title": "Mortgagees can choose when to sell", "date": "2010-11-25", "type": "case-note", "topics": ["mortgages", "power-of-sale", "sureties", "timing-of-sale", "duty-of-care"], "cases": [{"name": "China and South Sea Bank Ltd v Tan Soon Gin (George Tan)", "citation": "[1990] 1 AC 536", "court": "UKPC", "jurisdiction": "HK"}], "statutes": [], "summary": "A bank held shares securing a HK$30m facility and delayed selling while their value collapsed. Lord Templeman held the creditor decides in its own interest whether and when to sell, so the surety's liability stood undiminished."}, {"url": "https://hklandlaw.wordpress.com/2010/11/24/collateral-advantages-and-clogs-on-the-equity-of-redemption/", "title": "Collateral advantages and clogs on the equity of redemption", "date": "2010-11-24", "type": "case-note", "topics": ["mortgages", "equity-of-redemption", "clogs-and-fetters", "collateral-advantages", "unconscionability"], "cases": [{"name": "Kreglinger v New Patagonia Meat and Cold Storage Co Ltd", "citation": "[1914] AC 25", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Lord Parker held equity no longer forbids collateral advantages outright, striking them only where unfair and unconscionable, penal so as to clog redemption, or repugnant to the right to redeem. A five-year first refusal over sheepskins survived early repayment."}, {"url": "https://hklandlaw.wordpress.com/2010/11/22/an-agreement-for-lease-is-as-good-as-a-lease-the-inability-to-enforce-the-agreement-as-between-the-landlord-and-an-assignee-of-the-lease/", "title": "An agreement for lease is as good as a lease? The inability to enforce the agreement as between the landlord and an assignee of the lease.", "date": "2010-11-22", "type": "case-note", "topics": ["agreement-for-lease", "privity-of-estate", "assignment-of-leases", "specific-performance", "leasehold-covenants"], "cases": [{"name": "Purchase v Lichfield Brewery Co", "citation": "[1915] 1 KB 184", "court": "other", "jurisdiction": "EN"}, {"name": "Walsh v Lonsdale", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Where the tenant's status rests only on a right to specific performance, an assignee who never took a vested term or possession has neither privity of contract nor of estate. Lush J held the rent covenant was accordingly unenforceable against him."}, {"url": "https://hklandlaw.wordpress.com/2010/11/22/solus-agreement-does-it-touch-and-concern-land/", "title": "Solus agreement: does it touch and concern land?", "date": "2010-11-22", "type": "case-note", "topics": ["leasehold-covenants", "touch-and-concern", "solus-agreements", "assignment-of-reversion", "running-of-benefit"], "cases": [{"name": "Caerns Motor Services Ltd v Texaco Ltd", "citation": "[1994] 1 WLR 1249", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.31", "Law of Property Act 1925 s.141"], "summary": "A tie obliging a filling station to sell only the landlord's fuel governed how the premises were used rather than conferring a personal benefit. Judge Paul Baker held it touched and concerned the land, so its benefit passed to a successor landlord."}, {"url": "https://hklandlaw.wordpress.com/2010/11/19/white-v-bijou-mansions-cpo-s-26/", "title": "White v Bijou Mansions: CPO s.26", "date": "2010-11-19", "type": "case-note", "topics": ["restrictive-covenants", "building-schemes", "third-party-enforcement", "land-covenants", "construction-of-documents"], "cases": [{"name": "White v Bijou Mansions Ltd", "citation": "[1938] Ch 351", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.26", "Law of Property Act 1925 s.56"], "summary": "A neighbour could not enforce a residential-user covenant. No building scheme was proved over the estate, and the statutory route failed because the covenant was not made with his plot's owner. Greene MR required him to fall within its scope and benefit."}, {"url": "https://hklandlaw.wordpress.com/2010/11/19/spencers-case-the-burden-of-positive-covenants-can-pass-to-assignees-of-a-lease/", "title": "Spencer's case: the burden of positive covenants can pass to assignees of a lease", "date": "2010-11-19", "type": "case-note", "topics": ["leasehold-covenants", "positive-covenants", "touch-and-concern", "assignment-of-leases", "running-of-burden"], "cases": [{"name": "Spencer's Case", "citation": "77 ER 72", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "A lease obliged the tenant to build a wall and was assigned twice over. The decision shows the burden of leasehold covenants, positive ones included, passes to assignees provided the covenant touches and concerns the demised land."}, {"url": "https://hklandlaw.wordpress.com/2010/11/17/does-the-benefit-of-a-guarantee-pass-on-an-assignment-of-the-reversion/", "title": "Does the benefit of a guarantee pass on an assignment of the reversion?", "date": "2010-11-17", "type": "case-note", "topics": ["leasehold-covenants", "touch-and-concern", "guarantees", "assignment-of-reversion", "sureties"], "cases": [{"name": "P & A Swift Investments v Combined English Stores Group plc", "citation": "[1989] AC 632", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A surety covenant touches and concerns the land, so its benefit runs to an assignee of the reversion. Lord Oliver's test asks whether the benefit is tied to the reversion, affects user or value, and is not expressed as personal."}, {"url": "https://hklandlaw.wordpress.com/2010/11/16/austerberry-confirmed/", "title": "Austerberry confirmed", "date": "2010-11-16", "type": "case-note", "topics": ["freehold-covenants", "positive-covenants", "running-of-burden", "restrictive-covenants", "privity-of-contract"], "cases": [{"name": "Rhone v Stephens", "citation": "[1994] 2 AC 310", "court": "HL", "jurisdiction": "EN"}, {"name": "Austerberry v Oldham Corporation", "citation": null, "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Lord Templeman refused to disturb Austerberry: outside landlord and tenant, benefit may run at law but burden does not. Equity will not compel performance of a positive obligation by a successor, since that would contradict the rule against binding non-parties."}, {"url": "https://hklandlaw.wordpress.com/2010/11/15/the-burden-of-positive-covenants-does-not-run-with-the-land/", "title": "The burden of positive covenants does not run with the land", "date": "2010-11-15", "type": "case-note", "topics": ["freehold-covenants", "positive-covenants", "running-of-burden", "restrictive-covenants", "successors-in-title"], "cases": [{"name": "Austerberry v Oldham Corporation", "citation": "(1885) LR 29 Ch D 750", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Tulk v Moxhay", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "At common law no covenant burden, positive or negative, passes with the land. Owners of a road had promised to maintain it, yet the corporation taking the land was bound by nothing. Equity's exception reaches only restrictive covenants."}, {"url": "https://hklandlaw.wordpress.com/2010/11/12/covenants-that-touch-and-concern-land/", "title": "Covenants that touch and concern land", "date": "2010-11-12", "type": "case-note", "topics": ["leasehold-covenants", "touch-and-concern", "personal-covenants", "security-deposits", "assignment-of-reversion"], "cases": [{"name": "Hua Chiao Commercial Bank Ltd v Chiaphua Industries Ltd", "citation": "[1987] 2 WLR 179", "court": "UKPC", "jurisdiction": "HK"}], "statutes": [], "summary": "A landlord's undertaking to return a security deposit was personal and did not bind a successor. The test asks whether the covenant refers directly to the land, or affects landlord or tenant in that normal capacity."}, {"url": "https://hklandlaw.wordpress.com/2010/11/11/cpo-s-39-and-the-annexation-of-the-benefit-of-covenants/", "title": "CPO s.39 and the annexation of the benefit of covenants", "date": "2010-11-11", "type": "case-note", "topics": ["restrictive-covenants", "statutory-annexation", "running-of-benefit", "successors-in-title", "land-covenants"], "cases": [{"name": "Federated Homes Ltd v Mill Lodge Properties Ltd", "citation": "[1980] 1 WLR 594", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.39", "Law of Property Act 1925 s.78"], "summary": "Brightman LJ held that once a covenant restricting user touches and concerns the covenantee's land, the statute annexes its benefit automatically. Annexation attaches to every part of that land, dispensing with express assignment when parcels are sold separately."}, {"url": "https://hklandlaw.wordpress.com/2010/11/10/does-cpo-s-41-apply-to-building-schemes/", "title": "Does CPO s.41 apply to building schemes?", "date": "2010-11-10", "type": "case-note", "topics": ["building-schemes", "restrictive-covenants", "land-covenants", "statutory-interpretation", "local-law-of-the-scheme"], "cases": [{"name": "Sky Heart Ltd v Lee Hysan Co Ltd", "citation": "[1999] 1 HKLRD 100", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.41", "Conveyancing and Property Ordinance s.41(2)(c)"], "summary": "Scheme covenants often omit words benefiting the covenantee's land, and by the later sales the covenantee may retain none. Lord Hoffmann nonetheless held the section must have been meant to cover building schemes and made the wording fit."}, {"url": "https://hklandlaw.wordpress.com/2010/11/10/cpo-s-41and-the-common-law-equitable-rules-on-covenants/", "title": "CPO s.41 and the common law / equitable rules on covenants", "date": "2010-11-10", "type": "case-note", "topics": ["land-covenants", "statutory-codification", "restrictive-covenants", "running-of-covenants", "statutory-interpretation"], "cases": [{"name": "Sky Heart Ltd v Lee Hysan Co Ltd", "citation": "[1999] 1 HKLRD 100", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.41(1)", "Conveyancing and Property Ordinance s.41(2)", "Conveyancing and Property Ordinance s.41(3)"], "summary": "Lord Hoffmann treated the section as a partial code: a covenant meeting its conditions runs regardless of any rule of law or equity, yet covenants falling outside it may still run under the older common law and equitable doctrines."}, {"url": "https://hklandlaw.wordpress.com/2010/11/10/building-schemes/", "title": "Building schemes", "date": "2010-11-10", "type": "case-note", "topics": ["building-schemes", "restrictive-covenants", "mutual-enforceability", "common-vendor", "common-intention"], "cases": [{"name": "Sky Heart Ltd v Lee Hysan Co Ltd", "citation": "[1999] 1 HKLRD 100", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Where a common vendor lays out plots for a general development and promotes a scheme, purchasers share an interest in preserving its integrity and an equity of mutual enforcement can arise. Everything turns on the first buyers' common intention."}, {"url": "https://hklandlaw.wordpress.com/2010/11/09/is-the-naming-right-an-easement/", "title": "Is the naming right an easement?", "date": "2010-11-09", "type": "overview", "topics": ["easements", "naming-rights", "land-covenants", "dominant-tenement", "co-ownership"], "cases": [{"name": "Lamaya Ltd v Supreme Honour Development Ltd", "citation": "[1991] 1 HKC 198", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "The court analysed a shareholder's right to rename a building as a land covenant. The author asks whether an easement analysis would work instead, binding co-owners, but doubts it because there is no separation of ownership between them."}, {"url": "https://hklandlaw.wordpress.com/2010/11/09/the-significance-of-an-assignment-subject-to-the-dmc/", "title": "The significance of an assignment 'subject to' the DMC", "date": "2010-11-09", "type": "case-note", "topics": ["deed-of-mutual-covenant", "land-covenants", "constructive-trust", "successors-in-title", "notice"], "cases": [{"name": "Lamaya Ltd v Supreme Honour Development Ltd", "citation": "[1991] 1 HKC 198", "court": "CA", "jurisdiction": "HK"}, {"name": "Lyus v Prowsa Developments Ltd", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.41"], "summary": "Counsel argued that taking 'subject to and with the benefit of' a deed of mutual covenant created a contractual nexus independent of statute. The court disagreed: the phrase merely gave notice, unlike Lyus. The author thinks it signals intended adherence."}, {"url": "https://hklandlaw.wordpress.com/2010/11/09/naming-rights-which-covenants-pass-under-cpo-s-41/", "title": "Naming rights: which covenants pass under CPO s.41?", "date": "2010-11-09", "type": "case-note", "topics": ["land-covenants", "naming-rights", "deed-of-mutual-covenant", "touch-and-concern", "successors-in-title"], "cases": [{"name": "Lamaya Ltd v Supreme Honour Development Ltd", "citation": "[1991] 1 HKC 198", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.41(2)", "Conveyancing and Property Ordinance s.41(3)", "Conveyancing and Property Ordinance s.41(2)(c)"], "summary": "Only covenants relating to the land and benefiting the covenantee's land pass under the section. A right to rename the whole building resembles sponsorship, its value unconnected to exclusive occupation of any floor, so it did not qualify."}, {"url": "https://hklandlaw.wordpress.com/2010/11/08/proprietary-and-promissory-estoppel-recent-academic-commentary-on-luo-xing-juan-angela-v-estate-of-hui-shui-see-willy/", "title": "Proprietary and promissory estoppel: recent academic commentary on Luo Xing Juan Angela v Estate of Hui Shui See Willy", "date": "2010-11-08", "type": "overview", "topics": ["promissory-estoppel", "proprietary-estoppel", "constructive-trust", "family-home", "cause-of-action-estoppel"], "cases": [{"name": "Luo Xing Juan Angela v Estate of Hui Shui See Willy, deceased", "citation": null, "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Two commentaries fault the Court of Final Appeal. Low says proprietary estoppel reasoning was imported into a promissory estoppel claim; Lee and Ho object that dropping the need for a pre-existing legal relationship lets promissory estoppel found a claim."}, {"url": "https://hklandlaw.wordpress.com/2010/11/08/promissory-estoppel-and-proprietary-estoppel-both-needed/", "title": "Promissory estoppel and proprietary estoppel. Both needed?", "date": "2010-11-08", "type": "case-note", "topics": ["promissory-estoppel", "proprietary-estoppel", "building-management", "possession", "reliance"], "cases": [{"name": "Bestkey Development Ltd v Incorporated Owners of Fine Mansion", "citation": "[1999] 2 HKLRD 662", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Occupants of a management office resisted the developer's successor by pleading both estoppels: promissory on sales-brochure representations about on-site management, proprietary on twenty years of upkeep. Liu JA stressed that only proprietary estoppel supports attack rather than defence."}, {"url": "https://hklandlaw.wordpress.com/2010/11/06/did-a-management-agreement-create-a-lease/", "title": "Did a management agreement create a lease?", "date": "2010-11-06", "type": "case-note", "topics": ["leases", "licences", "exclusive-possession", "management-agreements", "landlord-and-tenant"], "cases": [{"name": "Yip v Wong Shun", "citation": "[2002] HKEC 505", "court": "CFI", "jurisdiction": "HK"}], "statutes": [], "summary": "A manager of commercial premises claimed a tenancy. The court found the owner had reserved such wide rights of possession that exclusive possession was negatived, so the management agreement conferred no lease."}, {"url": "https://hklandlaw.wordpress.com/2010/11/06/easements-and-the-ouster-principle/", "title": "Easements and the ouster principle", "date": "2010-11-06", "type": "overview", "topics": ["easements", "ouster-principle", "car-parking", "exclusive-possession", "adverse-possession"], "cases": [{"name": "Copeland v Greenhalf", "citation": "[1952] Ch 488", "court": "other", "jurisdiction": "EN"}, {"name": "Batchelor v Marlow", "citation": "[2001] EWCA Civ 1051", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Both claims to park on strips of land foundered on ouster. Since every easement interferes somewhat with the servient owner's enjoyment, the author, following Hill-Smith, would confine the objection to claims amounting to unrestricted use of the land."}, {"url": "https://hklandlaw.wordpress.com/2010/11/05/is-the-right-to-park-a-car-capable-of-being-an-easement/", "title": "Is the right to park a car capable of being an easement?", "date": "2010-11-05", "type": "case-note", "topics": ["easements", "car-parking", "ouster-principle", "exclusive-possession", "servient-tenement"], "cases": [{"name": "Moncrieff v Jamieson", "citation": "[2007] UKHL 42", "court": "HL", "jurisdiction": "other"}], "statutes": [], "summary": "The House of Lords accepted parking as a possible easement. Lord Scott separated exclusive use from exclusive possession, allowing the former where the servient owner keeps control; Lord Neuberger preferred asking what proportion of the servient land is occupied."}, {"url": "https://hklandlaw.wordpress.com/2010/11/04/acquiring-easements-by-long-use-the-doctrine-of-lost-modern-grant-in-hong-kong/", "title": "Acquiring easements by long use: the doctrine of lost modern grant in Hong Kong", "date": "2010-11-04", "type": "overview", "topics": ["easements", "prescription", "lost-modern-grant", "leasehold-land", "long-user"], "cases": [{"name": "China Field Ltd v Appeal Tribunal (Buildings) (No 2)", "citation": "[2009] HKEC 1765", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Prescription Act 1832"], "summary": "Of the three English prescription routes, lost modern grant suits Hong Kong best, twenty years' user raising a presumed grant. The Court of Final Appeal rejected the English confinement to fee simple land, allowing prescription between leaseholds under a common landlord."}, {"url": "https://hklandlaw.wordpress.com/2010/11/03/proprietary-estoppel-constructive-trust-and-co-habiting-couples/", "title": "Proprietary estoppel, constructive trust and co-habiting couples", "date": "2010-11-03", "type": "overview", "topics": ["proprietary-estoppel", "constructive-trust", "cohabitation", "beneficial-interests", "common-intention"], "cases": [{"name": "Oxley v Hiscock", "citation": "[2005] Fam 211", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Where an unmarried couple buy a home vested in one name, the court may infer intentions from their life together or proceed by estoppel. Chadwick LJ saw no practical difference in result between the constructive trust and estoppel analyses."}, {"url": "https://hklandlaw.wordpress.com/2010/11/02/willingness-to-pay-rent-is-fatal-to-adverse-possession/", "title": "Willingness to pay rent is fatal to adverse possession", "date": "2010-11-02", "type": "case-note", "topics": ["adverse-possession", "animus-possidendi", "limitation-of-actions", "squatters", "possession-as-of-right"], "cases": [{"name": "Wong Tak Yue v Kung Kwok Wai", "citation": "[1998] 1 HKLRD 241", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "A squatter who would have paid rent had the owners asked was, per Li CJ, treating himself as holding under a lawful title. Occupation as of right rather than as of wrong negatives the intention to possess."}, {"url": "https://hklandlaw.wordpress.com/2010/11/02/adverse-possession-enclosure-is-strong-evidence-of-possession-and-intention-to-possess/", "title": "Adverse possession: enclosure is strong evidence of possession and intention to possess", "date": "2010-11-02", "type": "case-note", "topics": ["adverse-possession", "animus-possidendi", "enclosure", "licences", "factual-possession"], "cases": [{"name": "Ho Hang-Wan v Ma Ting-Cheung", "citation": "[1990] 1 HKLR 649", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Hunter JA held unequivocal evidence of exclusive physical possession, such as fencing, necessarily establishes the intention to possess. The case has proved more influential for its other holding, that a licence ends on the licensor's death without notice."}, {"url": "https://hklandlaw.wordpress.com/2010/11/01/proprietary-estoppel-and-constructive-trust-and-the-double-assurance-aspect-of-proprietary-estoppel-in-contractual-settings/", "title": "Proprietary estoppel and constructive trust and the 'double assurance' aspect of proprietary estoppel in contractual settings", "date": "2010-11-01", "type": "case-note", "topics": ["proprietary-estoppel", "constructive-trust", "formalities", "unconscionability", "double-assurance"], "cases": [{"name": "Kinane v Mackie-Conteh", "citation": "[2005] EWCA Civ 45; [2005] WL 62273", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2(1)", "Law of Property (Miscellaneous Provisions) Act 1989 s.2(5)"], "summary": "An estoppel may rest on a second assurance that the promisor will not take the formality point. Arden LJ located the claim in conduct rather than the void agreement; Neuberger LJ saw agreement or shared understanding as what converts estoppel into constructive trust."}, {"url": "https://hklandlaw.wordpress.com/2010/10/30/adverse-possession-and-the-new-territories-leases-extension-ordinnace/", "title": "Adverse possession and the New Territories Leases (Extension) Ordinance", "date": "2010-10-30", "type": "case-note", "topics": ["adverse-possession", "new-territories-land", "statutory-interpretation", "leasehold-extension", "squatters"], "cases": [{"name": "Chan Tin Shun v Li Tin Shung", "citation": "[2006] HKEC 15", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["New Territories Leases (Extension) Ordinance (Cap 150) s.6"], "summary": "Did the statutory continuation to 2047 prolong existing leases or grant fresh ones that would revive owners' rights of recovery? Lord Hoffmann NPJ refused a reading that would wipe out every squatter's title in the New Territories; the leases were merely extended."}, {"url": "https://hklandlaw.wordpress.com/2010/10/29/adverse-possession-and-options-to-renew/", "title": "Adverse possession and options to renew", "date": "2010-10-29", "type": "case-note", "topics": ["adverse-possession", "limitation", "leases", "options-to-renew", "crown-leases"], "cases": [{"name": "Chung Ping Kwan v Lam Island Development Company Ltd", "citation": "[1996] 2 HKLR 315", "court": "UKPC", "jurisdiction": "HK"}], "statutes": ["New Territories (Renewable Crown Leases) Ordinance (Cap 152)", "Limitation Ordinance s.7(2)", "Limitation Ordinance s.8(1)", "Limitation Ordinance s.17"], "summary": "Renewing a lease under an option in the original lease does not restart limitation against a squatter: the Privy Council looked to substance, treating the renewed term as continuing pre-existing rights, so time ran from the original dispossession and lessees cannot sleep on their rights."}, {"url": "https://hklandlaw.wordpress.com/2010/10/27/adverse-possession-and-the-basic-law/", "title": "Adverse possession and the Basic law", "date": "2010-10-27", "type": "case-note", "topics": ["adverse-possession", "basic-law", "property-rights", "limitation-of-actions", "constitutional-challenge"], "cases": [{"name": "Harvest Good Development Ltd v Secretary for Justice", "citation": "[2007] HKEC 1272", "court": "CFI", "jurisdiction": "HK"}, {"name": "Harvest Good Development Ltd v Secretary for Justice", "citation": "[2008] HKEC 301", "court": "other", "jurisdiction": "HK"}, {"name": "JA Pye (Oxford) Ltd v United Kingdom", "citation": null, "court": "other", "jurisdiction": "other"}], "statutes": ["Limitation Ordinance s.7(2)", "Limitation Ordinance s.17", "Basic Law art 6", "Basic Law art 105"], "summary": "Hartmann J held that losing possessory title by limitation is no expropriation by the state, so the statutory scheme sits consistently with the constitutional property guarantees, however harshly it can operate. Leave to appeal was refused as the point came too late."}, {"url": "https://hklandlaw.wordpress.com/2010/10/27/does-the-benefit-of-a-right-to-rename-a-building-pass-to-a-covenantee%e2%80%99s-successors-in-title/", "title": "Does the benefit of a right to rename a building pass to a covenantee's successors in title?", "date": "2010-10-27", "type": "case-note", "topics": ["land-covenants", "naming-rights", "running-of-benefit", "successors-in-title", "precedent"], "cases": [{"name": "Congleton Corporation v Pattison", "citation": "(1808) 10 East 130", "court": "other", "jurisdiction": "EN"}, {"name": "Lamaya Ltd v Supreme Honour Development Ltd", "citation": "[1991] 1 HKC 198", "court": "CA", "jurisdiction": "HK"}, {"name": "Pak Fah Yeow Investment (Hong Kong) Co Ltd v Proper Invest Group Ltd", "citation": "[2009] HKEC 341", "court": "CA", "jurisdiction": "HK"}, {"name": "Union Insurance Society of Canton Ltd v Hongkong Land Co Ltd", "citation": "HCA 386/1977", "court": "other", "jurisdiction": "HK"}, {"name": "Grant v Edmondson", "citation": "[1931] 1 Ch 1", "court": "other", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.41(2)", "Conveyancing and Property Ordinance s.41(2)(c)"], "summary": "A covenant must bear on the mode of occupation or itself affect land value to pass. The Court of Appeal thought the arguments for letting naming rights run had force, yet considered itself bound by Lamaya, producing a gap between reasoning and result."}, {"url": "https://hklandlaw.wordpress.com/2010/10/26/the-relationship-between-the-assurance-and-the-detriment-in-proprietary-estoppel/", "title": "The relationship between the assurance and the detriment in proprietary estoppel", "date": "2010-10-26", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "detrimental-reliance", "unconscionability", "testamentary-promises"], "cases": [{"name": "Gillett v Holt", "citation": "[2001] Ch 210", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Thorner v Curtis", "citation": "[2007] EWHC 2242 (Ch)", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Which element carries the weight, the assurance or the reliance? Dixon reads Gillett as preventing a testator from resiling on a long-repeated promise, while the sparser assurances in Thorner suggest detrimental reliance and unconscionability matter most."}, {"url": "https://hklandlaw.wordpress.com/2010/10/26/luo-xing-juan-v-estate-of-hui-shui-see-common-intention-constructive-trust-and-promissory-estoppel/", "title": "Luo Xing Juan v Estate of Hui Shui See: common intention constructive trust and promissory estoppel", "date": "2010-10-26", "type": "case-note", "topics": ["common-intention-constructive-trust", "promissory-estoppel", "corporate-veil", "family-home", "equitable-remedies"], "cases": [{"name": "Luo Xing Juan v Estate of Hui Shui See", "citation": "(2009) 12 HKCFAR 1", "court": "CFA", "jurisdiction": "HK"}, {"name": "Re Schuppan", "citation": "[1997] 1 BCLC 256", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Because the flat belonged to a company, the couple's shared intention could not fasten a trust on that separate owner, shareholders having no equitable interest in its assets. The deceased's clear promise of 35 per cent instead grounded promissory estoppel relief."}, {"url": "https://hklandlaw.wordpress.com/2010/10/25/contractual-licence-coupled-with-an-equity/", "title": "Contractual licence coupled with an equity", "date": "2010-10-25", "type": "case-note", "topics": ["contractual-licences", "constructive-trust", "third-party-purchasers", "notice", "occupation-rights"], "cases": [{"name": "Binions v Evans", "citation": "[1972] Ch 359", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "A widow allowed to occupy a cottage for life was threatened with eviction after the estate sold subject to her rights. Lord Denning MR imposed a constructive trust on buyers with notice who paid less, an exception to licences not binding third parties."}, {"url": "https://hklandlaw.wordpress.com/2010/10/25/proprietary-estoppel-and-future-rights/", "title": "Proprietary estoppel and future rights", "date": "2010-10-25", "type": "case-note", "topics": ["proprietary-estoppel", "constructive-trust", "testamentary-promises", "detrimental-reliance", "future-interests"], "cases": [{"name": "Re Basham", "citation": "[1986] 1 WLR 1498", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Nugee QC held the claimant's belief need not concern an existing right: expectation of something to be given in future generates a species of constructive trust. Years of unpaid work and forgone chances sufficed after the promisor died intestate."}, {"url": "https://hklandlaw.wordpress.com/2010/10/23/proprietary-estoppel-as-a-substitute-for-part-performance/", "title": "Proprietary estoppel as a substitute for part performance?", "date": "2010-10-23", "type": "overview", "topics": ["proprietary-estoppel", "part-performance", "formalities", "constructive-trust", "restitution"], "cases": [{"name": "Yaxley v Gotts", "citation": "[2000] Ch 162", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Cobbe v Yeoman's Row Management Ltd", "citation": "[2008] UKHL 55", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2(1)", "Law of Property (Miscellaneous Provisions) Act 1989 s.2(5)"], "summary": "Once land contracts must be wholly in one signed writing there is no contract for part performance to support. The statute saves constructive trusts but not estoppel, and estoppel cannot help a seller suing for price; restitution may fill the gap."}, {"url": "https://hklandlaw.wordpress.com/2010/10/23/aggregating-periods-of-adverse-possession/", "title": "Aggregating periods of adverse possession", "date": "2010-10-23", "type": "case-note", "topics": ["adverse-possession", "aggregation", "successive-squatters", "continuity-of-possession", "limitation-of-actions"], "cases": [{"name": "Allen v Matthews", "citation": "[2007] 2 P & CR 21", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Lawrence Collins LJ held one occupier need not hold throughout: successive squatters' periods may be added so long as possession stays unbroken. On the facts, use from 1987 passed to another occupier who let to his son in 1998."}, {"url": "https://hklandlaw.wordpress.com/2010/10/22/no-aggregation-of-periods-of-adverse-possession-unless-they-are-continuous/", "title": "No aggregation of periods of adverse possession unless they are continuous", "date": "2010-10-22", "type": "case-note", "topics": ["adverse-possession", "aggregation", "continuity-of-possession", "limitation-of-actions", "successive-squatters"], "cases": [{"name": "Wong Kar Sue v Sun Hung Kai Properties Ltd", "citation": "[2006] HKEC 412", "court": "other", "jurisdiction": "HK"}], "statutes": ["Limitation Ordinance s.13(2)"], "summary": "Possession running from 1979 by a woman, then her husband, then her executors was properly added together. Statute resets the clock where land falls out of adverse possession before the right accrues, so any interruption destroys aggregation."}, {"url": "https://hklandlaw.wordpress.com/2010/10/20/adverse-possession-and-the-right-to-private-property/", "title": "Adverse possession and the right to private property", "date": "2010-10-20", "type": "overview", "topics": ["adverse-possession", "human-rights", "property-rights", "land-registration", "limitation-of-actions"], "cases": [{"name": "JA Pye (Oxford) Ltd v Graham", "citation": "[2003] 1 AC 419", "court": "HL", "jurisdiction": "EN"}, {"name": "JA Pye (Oxford) Ltd v United Kingdom", "citation": "(2008) 46 EHRR 45", "court": "other", "jurisdiction": "other"}], "statutes": ["Limitation Act 1980 s.15", "Land Registration Act 1925", "Land Registration Act 2002", "European Convention on Human Rights Protocol 1 art 1"], "summary": "Is limitation legalised theft? Strasbourg treated limitation rules affecting land as serving the general interest and as controlling use rather than depriving an owner of possessions. The author argues registered systems justify stricter requirements than unregistered ones."}, {"url": "https://hklandlaw.wordpress.com/2010/10/19/adverse-possession-get-on-the-housing-ladder-for-free/", "title": "Adverse possession: get on the housing ladder for free!", "date": "2010-10-19", "type": "case-note", "topics": ["adverse-possession", "animus-possidendi", "factual-possession", "limitation-of-actions", "dispossession"], "cases": [{"name": "Buckinghamshire County Council v Moran", "citation": "[1990] Ch 623", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Powell v McFarlane", "citation": "(1979) 38 P & CR 452", "court": "other", "jurisdiction": "EN"}], "statutes": ["Limitation Ordinance (Cap 347) s.7(1)", "Limitation Ordinance (Cap 347) s.7(2)", "Limitation Ordinance (Cap 347) s.8(1)", "Limitation Ordinance (Cap 347) s.13(1)", "Limitation Ordinance (Cap 347) s.13(2)", "Limitation Ordinance (Cap 347) s.17", "Limitation Act 1980"], "summary": "A claimant must show factual possession plus an intention to exclude everyone, including the owner, so far as reasonably practicable. Only the squatter's intention counts, so conceding he might leave if the council needed the land for widening did not defeat him."}, {"url": "https://hklandlaw.wordpress.com/2010/10/18/hope-is-not-enough-for-proprietary-estoppel/", "title": "Hope is not enough for proprietary estoppel", "date": "2010-10-18", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "assurance", "detrimental-reliance", "land-exchange"], "cases": [{"name": "Attorney-General of Hong Kong v Humphreys Estate (Queen's Gardens) Ltd", "citation": "[1987] HKLR 427", "court": "UKPC", "jurisdiction": "HK"}], "statutes": [], "summary": "The Government spent heavily hoping the developer would not pull out of a subject-to-contract exchange. Without an encouraged belief that withdrawal would not occur, no estoppel arose; only unforeseeable circumstances could turn such negotiations into a binding obligation."}, {"url": "https://hklandlaw.wordpress.com/2010/10/18/can-equity-intervene-to-prevent-a-contractual-licence-from-being-revoked/", "title": "Can equity intervene to prevent a contractual licence from being revoked?", "date": "2010-10-18", "type": "case-note", "topics": ["contractual-licences", "revocation", "specific-performance", "proprietary-estoppel", "injunctions"], "cases": [{"name": "Hover Base Investments Ltd v Best Concept Management Ltd", "citation": "[2005] HKEC 776", "court": "CA", "jurisdiction": "HK"}, {"name": "Winter Garden Theatre (London) Ltd v Millennium Productions Ltd", "citation": "[1948] AC 173", "court": "HL", "jurisdiction": "EN"}, {"name": "Winter v Brockwell", "citation": "(1807) 8 East 308", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Free revocability yields in three ways: contract may restrict it, with equity enjoining wrongful revocation where the bargain is specifically enforceable; a licence acted upon is usually irrevocable; and estoppel may bar revocation. A riding-school manager had spent in reliance."}, {"url": "https://hklandlaw.wordpress.com/2010/10/15/unconscionability-and-a-broad-approach-to-proprietary-estoppel/", "title": "Unconscionability and a broad approach to proprietary estoppel", "date": "2010-10-15", "type": "case-note", "topics": ["proprietary-estoppel", "unconscionability", "detrimental-reliance", "assurance", "testamentary-promises"], "cases": [{"name": "Gillett v Holt", "citation": "[2000] 3 WLR 815", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Luo Xing Juan v Estate of Hui Shui See", "citation": "(2009) 12 HKCFAR 1", "court": "CFA", "jurisdiction": "HK"}], "statutes": [], "summary": "Robert Walker LJ warned against dividing the doctrine into watertight compartments, unconscionability running through every element. Knowing a will can be changed does not preclude reliance, and detriment need not be financial provided it is substantial."}, {"url": "https://hklandlaw.wordpress.com/2010/10/15/equity-will-not-assist-a-licensor-to-wrongfully-terminate-a-licence-agreement/", "title": "Equity will not assist a licensor to wrongfully terminate a licence agreement", "date": "2010-10-15", "type": "case-note", "topics": ["contractual-licences", "revocation", "injunctions", "interlocutory-relief", "building-contracts"], "cases": [{"name": "Hounslow London Borough Council v Twickenham Garden Developments Ltd", "citation": "[1970] 3 WLR 538", "court": "other", "jurisdiction": "EN"}, {"name": "Anstalt Nybro v Hong Kong Resort Co Ltd", "citation": "[1978] HKLR 414", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Megarry J declined an interlocutory injunction to expel contractors from a site while the licensor's right to terminate remained unresolved. Equity will not lend its aid to a party who may be breaking his own contract."}, {"url": "https://hklandlaw.wordpress.com/2010/10/13/financial-and-investment-services-for-asia-ltd-v-baik-wha-international-trading-co-ltd/", "title": "Financial and Investment Services for Asia Ltd v Baik Wha International Trading Co Ltd", "date": "2010-10-13", "type": "case-note", "topics": ["priority-of-interests", "equitable-interests", "land-registration", "mortgages", "subrogation"], "cases": [{"name": "Financial and Investment Services for Asia Ltd v Baik Wha International Trading Co Ltd", "citation": "[1985] HKLR 103", "court": "other", "jurisdiction": "HK"}], "statutes": ["Land Registration Ordinance"], "summary": "Hunter J held a refinancier stepped into the priority of the lender it paid off. That unregistered, unwritten equity outranked a later registered charge on the principle that where equities are equal the earlier prevails."}, {"url": "https://hklandlaw.wordpress.com/2010/10/12/certainty-of-assurance-and-of-property-in-proprietary-estoppel/", "title": "Certainty of assurance and of property in proprietary estoppel", "date": "2010-10-12", "type": "case-note", "topics": ["proprietary-estoppel", "assurance", "certainty-of-subject-matter", "testamentary-promises", "reliance"], "cases": [{"name": "Thorner v Major", "citation": "[2009] UKHL 18", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "An assurance need not be clear, precise and unambiguous; it suffices that a reasonable recipient would take it seriously. The subject matter may shift over time, identified in concept at the outset and fixed in extent when the equity crystallises on death."}, {"url": "https://hklandlaw.wordpress.com/2010/10/11/when-should-proprietary-estoppel-give-rise-to-a-proprietary-interest-in-land/", "title": "When should proprietary estoppel give rise to a proprietary interest in land?", "date": "2010-10-11", "type": "overview", "topics": ["proprietary-estoppel", "remedies", "proprietary-interests", "reliance", "third-party-effect"], "cases": [{"name": "Yaxley v Gotts", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Drawing on Bright and McFarlane, the post argues a proprietary award should follow only where needed to protect reasonable reliance, otherwise personal relief. Proprietary relief fits where third parties must be bound, occupation is long, or another interest was surrendered."}, {"url": "https://hklandlaw.wordpress.com/2010/10/09/the-effect-of-a-sale-subject-to-an-existing-contract/", "title": "The effect of a sale 'subject to' an existing contract", "date": "2010-10-09", "type": "case-note", "topics": ["constructive-trust", "subject-to-clauses", "mortgagee-sale", "third-party-purchasers", "notice"], "cases": [{"name": "Lyus v Prowsa Developments Ltd", "citation": "[1982] 1 WLR 1044", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "A buyer from a mortgagee took expressly subject to an earlier sale contract, and the court imposed a constructive trust reflecting the parties' shared intention behind that clause. The author stresses the result is fact-sensitive; other courts have declined to follow it."}, {"url": "https://hklandlaw.wordpress.com/2010/10/09/a-disciplined-approach-to-proprietary-estoppel/", "title": "A disciplined approach to proprietary estoppel", "date": "2010-10-09", "type": "case-note", "topics": ["proprietary-estoppel", "subject-to-contract", "formalities", "unjust-enrichment", "commercial-certainty"], "cases": [{"name": "Cobbe v Yeoman's Row Management Ltd", "citation": "[2008] 1 WLR 1752", "court": "HL", "jurisdiction": "EN"}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2"], "summary": "The House of Lords demanded clarity about what is denied and what interest is claimed: a confident expectation, not speculation. Subject-to-contract dealings rarely found an estoppel, and Lord Walker cautioned against loose equitable intervention in commerce; quantum meruit may answer instead."}, {"url": "https://hklandlaw.wordpress.com/2010/10/07/world-food-fair-in-the-court-of-appeal-part-performance/", "title": "World Food Fair in the Court of Appeal: Part Performance", "date": "2010-10-07", "type": "case-note", "topics": ["part-performance", "formalities", "agreement-for-lease", "concluded-contract", "landlord-and-tenant"], "cases": [{"name": "World Food Fair Ltd v Hong Kong Island Development Ltd", "citation": "[2005] HKLRD 665", "court": "CA", "jurisdiction": "HK"}, {"name": "World Food Fair Ltd v Hong Kong Island Development Ltd", "citation": "[2007] 1 HKLRD 498", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "The Court of Appeal treated paying a deposit and entering into possession as sufficient acts of part performance. The Court of Final Appeal allowed the appeal on another footing, holding no contract had ever been concluded, so part performance never arose."}, {"url": "https://hklandlaw.wordpress.com/2010/10/06/occupation-of-the-property-as-a-source-of-constructive-notice/", "title": "Occupation of the property as a source of constructive notice", "date": "2010-10-06", "type": "case-note", "topics": ["constructive-notice", "occupation", "resulting-trust", "bona-fide-purchaser", "beneficial-interests"], "cases": [{"name": "Wong Chim-Ying v Cheng Kam-Wing", "citation": "[1991] 2 HKLR 253", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A husband who paid for a flat vested in his wife stayed in occupation. Clough JA held notice of occupation is notice of the occupier's rights, so a buyer aware of his presence who never enquired took subject to his resulting-trust interest."}, {"url": "https://hklandlaw.wordpress.com/2010/10/06/subject-to-contract-and-proprietary-estoppel/", "title": "'Subject to contract' and proprietary estoppel", "date": "2010-10-06", "type": "overview", "topics": ["subject-to-contract", "proprietary-estoppel", "formalities", "memorandum", "reliance"], "cases": [], "statutes": ["Conveyancing and Property Ordinance s.3"], "summary": "Noting an article by J E Adams, the post explains that the label does double duty: it stops the documents amounting to a statutory memorandum and simultaneously negatives the representation and reliance an estoppel would need."}, {"url": "https://hklandlaw.wordpress.com/2010/10/06/constructive-notice-when-is-a-purchaser-or-mortgagee-put-on-enquiry/", "title": "Constructive notice: when is a purchaser or mortgagee put on enquiry?", "date": "2010-10-06", "type": "case-note", "topics": ["constructive-notice", "duty-to-enquire", "mortgages", "undervalue-transactions", "beneficial-interests"], "cases": [{"name": "HKCB Finance Ltd v Yuen Yi Wan", "citation": "[2006] HKEC 230", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "Tang JA held a wife had an arguable case that a gross undervalue in the transaction put the lender on enquiry as to her interest, since such prices often signal fraud. Inspection might then have revealed an occupier with a contribution-based claim."}, {"url": "https://hklandlaw.wordpress.com/2010/10/05/the-title-deeds-as-a-source-of-constructive-notice/", "title": "The title deeds as a source of constructive notice", "date": "2010-10-05", "type": "case-note", "topics": ["constructive-notice", "title-investigation", "breach-of-trust", "good-root-of-title", "bona-fide-purchaser"], "cases": [{"name": "Sun Sek Haw v Au So Kum", "citation": "[1999] 3 HKLRD 12", "court": "CA", "jurisdiction": "HK"}], "statutes": [], "summary": "A gratuitous transfer between administrators in the chain of title revealed a breach of trust. The test being what a prudent conveyancing solicitor's enquiries would have shown, the deeds fixed the buyers with notice and they escaped the purchase."}, {"url": "https://hklandlaw.wordpress.com/2010/10/04/constructive-notice/", "title": "Constructive notice", "date": "2010-10-04", "type": "overview", "topics": ["constructive-notice", "bona-fide-purchaser", "occupation", "inspection-of-land", "equitable-interests"], "cases": [{"name": "Hunt v Luck", "citation": "[1902] 1 Ch 428", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Equity protects the good faith purchaser of a legal estate without notice. Notice may be actual or constructive, the latter covering what reasonable inspection of land and title would reveal. Knowing the vendor is out of possession compels enquiry of the occupier."}, {"url": "https://hklandlaw.wordpress.com/2010/10/02/good-faith/", "title": "Good faith", "date": "2010-10-02", "type": "overview", "topics": ["good-faith", "bona-fide-purchaser", "notice", "land-registration", "priority-of-interests"], "cases": [{"name": "Midland Bank Trust Co Ltd v Green (No 1)", "citation": "[1980] Ch 590; [1981] AC 513", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Land Registration Ordinance s.3(2)"], "summary": "Good faith matters twice over: in defeating equitable interests and in the statutory voiding of unregistered dealings. Lord Wilberforce tied it closely to genuinely honest absence of notice while insisting equity keeps its hold on the purchaser's conscience."}, {"url": "https://hklandlaw.wordpress.com/2010/09/29/equitys-darling-and-good-faith/", "title": "Equity's darling and good faith", "date": "2010-09-29", "type": "case-note", "topics": ["bona-fide-purchaser", "good-faith", "constructive-notice", "duty-to-enquire", "equitable-interests"], "cases": [{"name": "Cheung Pik Wan v Tong Sau Ping", "citation": "[1986] HKLR 921", "court": "other", "jurisdiction": "HK"}], "statutes": [], "summary": "Transferees of the legal title failed the good faith requirement: they never asked why the owner had handed the deeds to the first defendant and never inspected the premises. The transfer to them was accordingly set aside."}, {"url": "https://hklandlaw.wordpress.com/2010/09/28/when-do-leases-have-to-be-by-deed/", "title": "When do leases have to be by deed?", "date": "2010-09-28", "type": "overview", "topics": ["leases", "formalities", "deeds", "short-leases", "landlord-and-tenant"], "cases": [{"name": "Long v Tower Hamlets London Borough Council", "citation": "[1998] Ch 197", "court": "other", "jurisdiction": "EN"}, {"name": "World Food Fair Ltd v Hong Kong Island Development Ltd", "citation": "[2005] 1 HKLRD 665", "court": "CA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.4(1)", "Conveyancing and Property Ordinance s.4(2)(d)", "Conveyancing and Property Ordinance s.6(2)", "Law of Property Act 1925 s.54(2)"], "summary": "A deed is normally required, but a term of three years or less taking effect in possession at the best rent without a premium escapes that. Possession must start at once: a three-week gap cost the tenant a legal lease."}, {"url": "https://hklandlaw.wordpress.com/2010/09/27/banner-homes-group-plc-v-luff-developments-ltd/", "title": "Banner Homes Group plc v Luff Developments Ltd", "date": "2010-09-27", "type": "case-note", "topics": ["constructive-trust", "pallant-v-morgan-equity", "joint-ventures", "unconscionability", "pre-acquisition-agreements"], "cases": [{"name": "Banner Homes Group plc v Luff Developments Ltd", "citation": "[2000] Ch 372", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Pallant v Morgan", "citation": null, "court": null, "jurisdiction": "EN"}, {"name": "Yaxley v Gotts", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Chadwick LJ set out the equity: an arrangement before acquisition, no notice of withdrawal, and reliance that benefits the buyer or harms the other. Because the claimant held off competing, half the acquiring company's shares were held on constructive trust."}, {"url": "https://hklandlaw.wordpress.com/2010/09/27/yaxley-v-gotts/", "title": "Yaxley v Gotts", "date": "2010-09-27", "type": "case-note", "topics": ["constructive-trust", "proprietary-estoppel", "formalities", "informal-agreements", "public-policy"], "cases": [{"name": "Yaxley v Gotts", "citation": "[2000] Ch 162", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Law of Property (Miscellaneous Provisions) Act 1989 s.2(1)", "Law of Property (Miscellaneous Provisions) Act 1989 s.2(5)"], "summary": "Letting estoppel rescue an oral land bargain would undercut the policy behind the writing requirement. The Court of Appeal instead used the statutory saving for constructive trusts to honour the arrangement, though the registered owner was not party to it."}, {"url": "https://hklandlaw.wordpress.com/2010/09/27/part-performance-the-constructive-trust-and-proprietary-estoppel/", "title": "Part performance, the constructive trust and proprietary estoppel", "date": "2010-09-27", "type": "overview", "topics": ["part-performance", "constructive-trust", "proprietary-estoppel", "formalities", "detrimental-reliance"], "cases": [{"name": "Yaxley v Gotts", "citation": "[2000] Ch 162", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Banner Homes Group plc v Luff Developments Ltd", "citation": "[2000] Ch 372", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)"], "summary": "Compares three equitable routes rescuing informally made land agreements: part performance, common intention constructive trust, and proprietary estoppel. Notes each demands detrimental reliance, and that estoppel relief is calibrated to the minimum needed to satisfy the equity."}, {"url": "https://hklandlaw.wordpress.com/2010/09/25/part-performance-steadman-v-steadman/", "title": "Part performance: Steadman v Steadman", "date": "2010-09-25", "type": "overview", "topics": ["part-performance", "formalities", "oral-contracts", "specific-performance"], "cases": [{"name": "Steadman v Steadman", "citation": "[1976] AC 536", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "Conveyancing and Property Ordinance s.3(2)"], "summary": "Explains how the Lords relaxed part performance: acts need only show, on balance, that some contract existed, examined alongside the alleged agreement rather than proving it alone. The post calls the resulting doctrine an uneasy compromise serving justice."}, {"url": "https://hklandlaw.wordpress.com/2010/09/24/reading-two-documents-together-to-form-a-memorandum-satisfying-cpo-s-3/", "title": "Reading two documents together to form a memorandum satisfying CPO, s.3", "date": "2010-09-24", "type": "case-note", "topics": ["formalities", "memorandum-in-writing", "joinder-of-documents", "land-contracts"], "cases": [{"name": "Timmins v Moreland Street Property Co Ltd", "citation": "[1958] Ch 110", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3"], "summary": "Two writings can together form the statutory memorandum only where the signed one refers to another document or transaction, linking them without oral evidence. A cheque bearing no such reference could not be joined with the receipt."}, {"url": "https://hklandlaw.wordpress.com/2010/09/24/the-legal-effect-of-a-provisional-agreement/", "title": "The legal effect of a provisional agreement", "date": "2010-09-24", "type": "overview", "topics": ["provisional-agreement", "land-contracts", "specific-performance", "open-contract"], "cases": [{"name": "Man Sun Finance (International) Corp v Lee Ming Ching Stephen", "citation": "[1993] 1 HKC 113", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "Hong Kong provisional sale agreements bind immediately once signed, enforceable on their express terms and, where gaps remain, as an open contract. Where price, completion and possession are settled, specific performance is available; back-out clauses raise separate questions."}, {"url": "https://hklandlaw.wordpress.com/2010/09/23/happy-mid-autumn-festival/", "title": "Happy Mid-Autumn Festival", "date": "2010-09-23", "type": "announcement", "topics": [], "cases": [], "statutes": [], "summary": "Holiday greetings to readers, noting a planned Science Museum visit."}, {"url": "https://hklandlaw.wordpress.com/2010/09/22/the-rule-in-walsh-v-lonsdale/", "title": "The rule in Walsh v Lonsdale", "date": "2010-09-22", "type": "case-note", "topics": ["equitable-lease", "agreement-for-lease", "specific-performance", "formalities"], "cases": [{"name": "Walsh v Lonsdale", "citation": "(1882) LR 21 Ch.D. 9", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "An agreement to grant or transfer a land interest takes effect in equity where specific performance would be granted, so a tenant under an unexecuted agreement for lease holds on the same terms equity would enforce."}, {"url": "https://hklandlaw.wordpress.com/2010/09/22/the-essential-elements-of-a-memorandum-satisfying-section-3-of-the-cpo/", "title": "The essential elements of a memorandum satisfying section 3 of the CPO", "date": "2010-09-22", "type": "overview", "topics": ["formalities", "memorandum-in-writing", "subject-to-contract", "land-contracts"], "cases": [{"name": "Tiverton Estates Ltd v Wearwell Ltd", "citation": "[1975] Ch 146", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.3(1)", "Conveyancing and Property Ordinance s.6(2)"], "summary": "A section 3 memorandum must both record the agreed terms and admit that a contract exists, signed by the party charged. Letters headed subject to contract fail because they deny, rather than acknowledge, any concluded bargain."}, {"url": "https://hklandlaw.wordpress.com/2010/09/21/is-there-a-valid-contract/", "title": "Is there a valid contract?", "date": "2010-09-21", "type": "overview", "topics": ["contract-formation", "essential-terms", "agreement-for-lease", "formalities"], "cases": [{"name": "World Food Fair Ltd v Hong Kong Island Development Ltd", "citation": "[2007] 1 HKLRD 498", "court": "CFA", "jurisdiction": "HK"}], "statutes": ["Conveyancing and Property Ordinance s.3"], "summary": "Before formality questions arise there must be a concluded bargain: parties, property, and for a lease the commencement date, duration and rent. Unsettled start date, rent-free period and renewal length meant no contract despite the tenant's reliance."}, {"url": "https://hklandlaw.wordpress.com/2010/09/20/is-there-such-a-thing-as-an-irremediable-breach-of-covenant-akici-v-lr-butlin/", "title": "Is there such a thing as an irremediable breach of covenant? Akici v LR Butlin", "date": "2010-09-20", "type": "case-note", "topics": ["forfeiture", "breach-of-covenant", "irremediable-breach", "leases"], "cases": [{"name": "Akici v LR Butlin", "citation": "[2005] EWCA Civ 1296", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Rugby School (Governors) v Tannahill", "citation": null, "court": null, "jurisdiction": null}, {"name": "Scala House & District Property Co Ltd v Forbes", "citation": null, "court": null, "jurisdiction": null}], "statutes": ["Conveyancing and Property Ordinance s.58"], "summary": "Neuberger LJ treated almost every covenant breach as capable of remedy, dismissing the Scala House reasoning as demonstrably fallacious, while accepting that a genuinely irremediable breach needs no remedy requirement in the statutory notice."}, {"url": "https://hklandlaw.wordpress.com/2010/09/20/trying-to-be-too-clever/", "title": "Trying to be too clever?", "date": "2010-09-20", "type": "case-note", "topics": ["sub-letting", "breach-of-covenant", "substance-over-form", "leases"], "cases": [{"name": "Scala House & District Property Co Ltd v Forbes", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "A restaurant management agreement was characterised as a sub-letting, breaching the covenant. Courts look at what an arrangement actually creates rather than its label, so clever drafting cannot disguise the grant of a subsidiary interest."}, {"url": "https://hklandlaw.wordpress.com/2010/09/20/breach-of-covenant-against-sub-letting-cannot-be-remedied-scala-house-district-property-co-ltd-v-forbes/", "title": "Breach of covenant against sub-letting cannot be remedied: Scala House & District Property Co Ltd v Forbes", "date": "2010-09-20", "type": "case-note", "topics": ["sub-letting", "breach-of-covenant", "forfeiture", "relief-from-forfeiture", "irremediable-breach"], "cases": [{"name": "Scala House & District Property Co Ltd v Forbes", "citation": "[1973] 3 WLR 14", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.58"], "summary": "Creating an unlawful sub-lease is a completed fact that a later surrender cannot undo, so the breach is irremediable and the notice need allow no time to cure. Relief from forfeiture nevertheless remained available and was granted."}, {"url": "https://hklandlaw.wordpress.com/2010/09/20/breaches-of-covenant-that-are-incapable-of-remedy-rugby-school-governors-v-tannahill-1935-1-kb-87/", "title": "Breaches of covenant that are incapable of remedy: Rugby School (Governors) v Tannahill [1935] 1 KB 87", "date": "2010-09-20", "type": "case-note", "topics": ["forfeiture", "irremediable-breach", "breach-of-covenant", "immoral-user", "leases"], "cases": [{"name": "Rugby School (Governors) v Tannahill", "citation": "[1935] 1 KB 87", "court": "EWCA", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.58", "Law of Property Act 1925 s.146"], "summary": "Immoral user as a brothel left a lasting stigma on the landlord's reversion, so stopping the conduct could not cure it. Such a breach is incapable of remedy and the forfeiture notice need not demand one."}, {"url": "https://hklandlaw.wordpress.com/2010/09/19/the-doctrine-of-frustration-and-leases-national-carriers-ltd-v-panalpina-northern-ltd/", "title": "The doctrine of frustration and leases: National Carriers Ltd v Panalpina (Northern) Ltd", "date": "2010-09-19", "type": "case-note", "topics": ["frustration", "leases", "estate-in-land", "risk-allocation"], "cases": [{"name": "Leighton's Investment Trust Ltd v Cricklewood Property and Investment Trust Ltd", "citation": "[1943] KB 49", "court": "EWCA", "jurisdiction": "EN"}, {"name": "National Carriers Ltd v Panalpina (Northern) Ltd", "citation": "[1981] AC 675", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "The Lords accepted that frustration can in principle apply to a lease, since creating an estate does not exclude it, but closing a warehouse access road for twenty months of a ten-year term fell well short."}, {"url": "https://hklandlaw.wordpress.com/2010/09/18/certainty-of-term/", "title": "Certainty of term", "date": "2010-09-18", "type": "case-note", "topics": ["certainty-of-term", "leases", "term-of-years", "void-leases"], "cases": [{"name": "Ashburn Anstalt v Arnold", "citation": "[1989] Ch 1", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Prudential Assurance Co Ltd v London Residuary Body", "citation": "[1992] 2 AC 386", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Discusses when a lease term is sufficiently certain, noting the view that an occupier's power to leave can supply certainty provided the determining event is objectively identifiable, an approach later disapproved in Prudential Assurance."}, {"url": "https://hklandlaw.wordpress.com/2010/09/18/rent-is-not-an-essential-element-of-lease-ashburn-anstalt-v-arnold/", "title": "Rent is not an essential element of a lease: Ashburn-Anstalt v Arnold", "date": "2010-09-18", "type": "case-note", "topics": ["leases", "rent", "lease-essentials", "exclusive-possession"], "cases": [{"name": "Ashburn Anstalt v Arnold", "citation": "[1989] Ch 1", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Rent is not a necessary ingredient of a lease. The Court of Appeal read Lord Templeman's earlier remarks as not making rent essential, correcting the misreading that had grown up around them."}, {"url": "https://hklandlaw.wordpress.com/2010/09/17/the-purely-contractual-lease-bruton-v-london-and-quadrant-housing-trust-2000-1-ac-406/", "title": "The purely contractual lease: Bruton v London and Quadrant Housing Trust [2000] 1 AC 406", "date": "2010-09-17", "type": "case-note", "topics": ["leases", "non-proprietary-lease", "exclusive-possession", "tenure", "licences"], "cases": [{"name": "Bruton v London & Quadrant Housing Trust", "citation": "[2000] 1 AC 406", "court": "HL", "jurisdiction": "EN"}, {"name": "Milmo v Carreras", "citation": "[1946] KB 306", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Street v Mountford", "citation": null, "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "A grantor without any estate can still create a lease binding between the parties, because the relationship rests on exclusive possession for a term rather than tenure or a reversion. Its forfeiture consequences remain unsettled."}, {"url": "https://hklandlaw.wordpress.com/2010/09/15/the-contractual-aspects-of-the-lease/", "title": "The contractual aspects of the lease", "date": "2010-09-15", "type": "overview", "topics": ["leases", "contract-and-property", "frustration", "certainty-of-term", "non-proprietary-lease"], "cases": [{"name": "Prudential Assurance Co Ltd v London Residuary Body", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "National Carriers Ltd v Panalpina (Northern) Ltd", "citation": "[1981] 2 WLR 45", "court": "HL", "jurisdiction": "EN"}, {"name": "Bruton v London & Quadrant Housing Trust", "citation": null, "court": "HL", "jurisdiction": "EN"}, {"name": "Street v Mountford", "citation": null, "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Surveys the pull between lease-as-contract and lease-as-estate: terms must be definite and ascertainable, frustration nonetheless applies, and Bruton shows a lease can rest on contractual elements alone without the grantor holding any estate."}, {"url": "https://hklandlaw.wordpress.com/2010/09/14/leases-must-be-for-a-term-that-is-certain-prudential-assurance-co-ltd-v-london-residuary-body/", "title": "Leases must be for a term that is certain: Prudential Assurance Co Ltd v London Residuary Body", "date": "2010-09-14", "type": "case-note", "topics": ["certainty-of-term", "leases", "void-leases", "term-of-years"], "cases": [{"name": "Say v Smith", "citation": "(1563) Plowd. 269", "court": "other", "jurisdiction": "EN"}, {"name": "Lace v Chantler", "citation": "[1944] KB 368", "court": "other", "jurisdiction": "EN"}, {"name": "Prudential Assurance Co Ltd v London Residuary Body", "citation": "[1992] 2 AC 386", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Reaffirms that a lease needs a maximum duration fixed at the outset; a term lasting only until the land was needed for a future purpose was void. Lord Browne-Wilkinson applied the ancient technical rule while doubting its rationale."}, {"url": "https://hklandlaw.wordpress.com/2010/09/14/exclusive-possession/", "title": "Exclusive possession", "date": "2010-09-14", "type": "overview", "topics": ["exclusive-possession", "lease-licence-distinction", "possession", "leases"], "cases": [{"name": "Marcroft Wagons Ltd v Smith", "citation": "[1951] 2 KB 496", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Explains exclusive possession as the hallmark of a tenancy: the occupier must intend to control the space and be able to exclude the owner. Service occupiers and family members may merely extend the owner's own possession."}, {"url": "https://hklandlaw.wordpress.com/2010/09/13/lam-man-yuen-v-lucky-apartments-1964-hklr-689/", "title": "Lam Man-Yuen v Lucky Apartments [1964] HKLR 689", "date": "2010-09-13", "type": "case-note", "topics": ["lease-licence-distinction", "exclusive-possession", "lodger", "licences"], "cases": [{"name": "Lam Man-Yuen v Lucky Apartments", "citation": "[1964] HKLR 689", "court": null, "jurisdiction": "HK"}], "statutes": [], "summary": "The occupier was held a lodger, not a tenant, because the proprietors kept substantial control: staff changed the bed linen, brought tea and water, and had to admit residents returning after midnight. The court decided with hesitation."}, {"url": "https://hklandlaw.wordpress.com/2010/09/13/street-v-mountford-1985-ac-809/", "title": "Street v Mountford [1985] AC 809", "date": "2010-09-13", "type": "case-note", "topics": ["lease-licence-distinction", "exclusive-possession", "certainty-of-term", "substance-over-form"], "cases": [{"name": "Street v Mountford", "citation": "[1985] AC 809", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Rent Act"], "summary": "A grant of exclusive possession for a term is a tenancy whatever the parties call it. Labelling an agreement a licence cannot displace its legal character or strip an occupier of statutory protection."}, {"url": "https://hklandlaw.wordpress.com/2010/09/13/applying-the-law-on-fixtures-to-everyday-household-items/", "title": "Applying the law on fixtures to everyday household items", "date": "2010-09-13", "type": "case-note", "topics": ["fixtures", "degree-of-annexation", "purpose-of-annexation", "chattels"], "cases": [{"name": "Botham v TSB Bank plc", "citation": "[1996] E.G. 149", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Applies the annexation tests to light fittings, bathroom accessories and kitchen appliances, finding them hard to use consistently. Suggests instead presuming such items stay personal property unless removing them would be unreasonable."}, {"url": "https://hklandlaw.wordpress.com/2010/09/12/is-a-boat-on-a-river-a-fixture/", "title": "Is a boat on a river a fixture?", "date": "2010-09-12", "type": "case-note", "topics": ["fixtures", "chattels", "annexation", "houseboats"], "cases": [{"name": "Chelsea Yacht & Boat Co Ltd v Pope", "citation": "[2000] 1 WLR 1941", "court": "EWCA", "jurisdiction": "EN"}, {"name": "Elitestone", "citation": null, "court": null, "jurisdiction": null}], "statutes": [], "summary": "A houseboat moored and plugged into riverbank services stays a chattel: the connections come apart easily and a vessel that floats then settles on the bed is not annexed. Tuckey LJ called the conclusion common sense."}, {"url": "https://hklandlaw.wordpress.com/2010/09/11/how-the-law-of-fixtures-developed/", "title": "How the law of fixtures developed", "date": "2010-09-11", "type": "overview", "topics": ["fixtures", "degree-of-annexation", "purpose-of-annexation", "intention", "chattels"], "cases": [{"name": "Hellawell v Eastwood", "citation": "(1851) 6 Ex 285, 155 E.R. 554", "court": "other", "jurisdiction": "EN"}, {"name": "Holland v Hodgson", "citation": null, "court": null, "jurisdiction": null}, {"name": "Wood v Hewett", "citation": "(1846) 8 Q.B. 913, 115 ER 1118", "court": "other", "jurisdiction": "EN"}, {"name": "Lancaster v Eve", "citation": "(1859) 5 CB(NS) 717, 141 ER 288", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Traces fixtures doctrine from a purely physical attachment inquiry to a three-part test. Hellawell v Eastwood added purpose of annexation, arguably merging two separate questions, while the annexor's intention appeared later as a judicial convenience."}, {"url": "https://hklandlaw.wordpress.com/2010/09/11/berkley-v-poulett-1977-1-eglr-86/", "title": "Berkley v Poulett [1977] 1 EGLR 86", "date": "2010-09-11", "type": "case-note", "topics": ["fixtures", "purpose-of-annexation", "degree-of-annexation", "chattels"], "cases": [{"name": "Berkley v Poulett", "citation": "[1977] 1 EGLR 86", "court": "EWCA", "jurisdiction": "EN"}], "statutes": [], "summary": "Pictures set into panelling, a marble statue on its plinth and a sundial were all chattels. The majority treated purpose of annexation as dominant, Scarman LJ stressing that each case turns on its own facts."}, {"url": "https://hklandlaw.wordpress.com/2010/09/11/leigh-v-taylor-1902-ac-157/", "title": "Leigh v Taylor [1902] AC 157", "date": "2010-09-11", "type": "case-note", "topics": ["fixtures", "purpose-of-annexation", "chattels", "works-of-art"], "cases": [{"name": "Leigh v Taylor", "citation": "[1902] AC 157", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Tapestries fastened to a wall remained chattels. Purpose of annexation decided the case: they were put up to be enjoyed as works of art and could be taken down without harming the building."}, {"url": "https://hklandlaw.wordpress.com/2010/09/11/holland-v-hodgson-1871-72-l-r-7-c-p-328/", "title": "Holland v Hodgson (1871 - 72) L.R. 7 C.P. 328", "date": "2010-09-11", "type": "case-note", "topics": ["fixtures", "degree-of-annexation", "purpose-of-annexation", "chattels"], "cases": [{"name": "Holland v Hodgson", "citation": "(1871-72) L.R. 7 C.P. 328", "court": "other", "jurisdiction": "EN"}], "statutes": [], "summary": "Looms nailed to a mill floor were fixtures even though easily lifted, because they were attached to serve the building's use as a mill. Fixture status turns on degree and purpose of annexation, a question of fact."}, {"url": "https://hklandlaw.wordpress.com/2010/09/09/what-is-property/", "title": "What is 'property'?", "date": "2010-09-09", "type": "overview", "topics": ["concept-of-property", "right-to-exclude", "ownership", "expropriation"], "cases": [{"name": "Bradford Corporation v Pickles", "citation": "[1895] AC 587", "court": null, "jurisdiction": "EN"}], "statutes": [], "summary": "Explores what makes a resource property: security against arbitrary state removal, a power to exclude, and control over use. Argues propertiness is a matter of degree, and traces the shift from absolute to socially qualified ownership."}, {"url": "https://hklandlaw.wordpress.com/2010/09/08/the-distinction-between-proprietary-and-non-proprietary-interests-in-land/", "title": "The distinction between proprietary and non-proprietary interests in land", "date": "2010-09-08", "type": "overview", "topics": ["proprietary-interests", "licences", "binding-successors", "leases"], "cases": [{"name": "National Provincial Bank Ltd v Ainsworth", "citation": "[1965] AC 1175", "court": "HL", "jurisdiction": "EN"}], "statutes": [], "summary": "Sets out why the proprietary label matters: only such rights bind successors. Ainsworth's criteria require an interest that is definable, identifiable by third parties, capable of assumption by them, and reasonably permanent, which licences lack."}, {"url": "https://hklandlaw.wordpress.com/2010/09/07/estates-in-land/", "title": "Estates in land", "date": "2010-09-07", "type": "overview", "topics": ["estates-in-land", "fee-simple", "leasehold", "government-lease", "legal-estates"], "cases": [{"name": "Street v Mountford", "citation": "[1985] AC 809", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Conveyancing and Property Ordinance s.2", "Basic Law Article 7", "Basic Law Articles 120-123", "Joint Declaration Annex III"], "summary": "Estates slice land ownership by time. Hong Kong has almost no fee simple: the government holds the land and grants leases, with pre-handover grants continuing but expiring no later than 30 June 2047."}, {"url": "https://hklandlaw.wordpress.com/2010/09/04/what-is-land-law/", "title": "What is land law?", "date": "2010-09-04", "type": "overview", "topics": ["land-law-scope", "proprietary-interests", "estates-in-land", "conveyancing", "land-registration"], "cases": [{"name": "National Provincial Bank v Ainsworth", "citation": "[1965] AC 1175", "court": "HL", "jurisdiction": "EN"}], "statutes": ["Land Registration Ordinance", "Land Titles Ordinance"], "summary": "Introduces the subject: land law allocates rights over immovable property, manages competing interests in the same plot and their priority, and prescribes conveyancing formalities. Ownership is conceived as a bundle of rights, an estate, rather than of the soil."}];